using namespace std;
typedef vector<ll> vec;
typedef vector<vec> mat;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;

    string T;
    vec balls(2*N, -1);
    vec ans;
    ll idx;
    for (ll i = 0; i <= N; i++) {
        cout << "? ";
        for (ll j = i; j < i + N; j++) {
            cout << j << " ";
        }
        cout << endl;
        cin >> T;
        if (T == "-1") {
            return 0;
        } else if (T == "Red") {
            ans.push_back(1);
        } else {
            ans.push_back(0);
        }

        if (i > 0 && ans[i-1] != ans[i]) {
            balls[i-1] = ans[i-1];
            balls[i+N-1] = ans[i];
            idx = i;
            break;
        }
    }

    ll target = 0;
    Rep (i, N+1) {
        cout << "? ";
        Rep (j, N-1) {
            cout << idx + j << " ";
        }
        cout << target << endl;

        cin >> T;
        if (T == "-1") {
            return 0;
        } else if (T == "Red") {
            ans.push_back(1);
        } else {
            ans.push_back(0);
        }
        balls[target] = ans.back();
        target++;
        if (target == idx) target = idx + N - 1;
    }

    vec query;
    ll cntr = 0, cntb = 0;
    for (ll i = 0; i < 2*N; i++) {
        if (idx <= i && i < idx + N) continue;
        if (balls[i] == 1 && cntr < (N-1)/2) {
            query.push_back(i);
            cntr++;
        } else if (balls[i] == 0 && cntb < (N-1)/2) {
            query.push_back(i);
            cntb++;
        }
    }

    for (ll i = idx; i < idx + N - 1; i++) {
        cout << "? ";
        for (auto e : query) {
            cout << e << " ";
        }
        cout << i << endl;
        cin >> T;
        if (T == "-1") {
            return 0;
        } else if (T == "Red") {
            ans.push_back(1);
        } else {
            ans.push_back(0);
        }
        balls[i] = ans.back();
    }

    cout << "! ";
    Rep (i, 2*N) {
        if (balls[i] == 1) {
            cout << 'R';
        } else {
            cout << 'B';
        }
    }
    cout << endl;
    return 0;
}

