	if(r - l == 1) return l;
	const int m = (l + r) / 2;
	rep(i, m, r) swap(ball[i], ball2[i]);
	const bool ret = output();
	rep(i, m, r) swap(ball[i], ball2[i]);

	if(ret ^ init){
