    vector<string> ans(2*N);

    string prev=query(0,N);
    int lb=0;
    int ub=N;
    while(ub-lb>1){
        int mid=(lb+ub)/2;
        if(query(0,N-mid,2*N-mid,2*N)==prev) lb=mid;
        else ub=mid;
    }
    int i=ub;

    int tar=-1;
    for(int j=N-i;j<2*N-i;j++){
        ans[j]=query(0,N-i,2*N-i+1,2*N,j);
        if(ans[j]==prev){
            tar=j;
        }
    }

    for(int j=0;j<N-i;j++){
        ans[j]=query3(N-i,2*N-i,j,tar);
    }
    for(int j=2*N-i;j<2*N;j++){
        ans[j]=query3(N-i,2*N-i,j,tar);
    }
    cout<<"! ";
    for(int i=0;i<2*N;i++){
        cout<<ans[i][0];
    }
    cout<<endl;

    return 0;
}

