		cout << endl << flush;
		string result;
		cin >> result;
		if(result != last_result){
			if(result != "Red"){ swap(order[i], order[i + n]); }
			swap(order[i], order[n - 1]);
			swap(order[n], order[i + n]);
			break;
		}
	}
	vector<int> solution(2 * n, -1);
	solution[order[n - 1]] = 0; // Red
	solution[order[n]]     = 1; // Blue
	for(int i = n + 1; i < 2 * n; ++i){
		cout << "?";
		for(int j = 0; j + 1 < n; ++j){ cout << " " << order[j] + 1; }
		cout << " " << order[i] + 1 << endl << flush;
		string result;
		cin >> result;
		if(result == "-1"){ return -1; }
		if(result == "Red"){
			solution[order[i]] = 0;
		}else{
			solution[order[i]] = 1;
		}
	}
	for(int i = n - 2; i >= 0; --i){
		cout << "?";
		for(int j = n + 1; j < 2 * n; ++j){ cout << " " << order[j] + 1; }
		cout << " " << order[i] + 1 << endl << flush;
		string result;
		cin >> result;
		if(result == "-1"){ return -1; }
		if(result == "Red"){
			solution[order[i]] = 0;
		}else{
			solution[order[i]] = 1;
		}
	}
	cout << "! ";
	for(const auto c : solution){
		cout << "RB"[c];
	}
	cout << endl;
	return 0;
}

