// constexpr ptrdiff_t operator ""_td(unsigned long long n) { return n; }

constexpr int red = -1;
constexpr int blue = +1;

using namespace std::literals;

int query(std::deque<size_t> const& q) {
  static int nq = 0;
  if (++nq > 210) abort();
  printf("?");
  for (size_t i = 0; i < q.size(); ++i)
    printf(" %zu", q[i]+1);
  printf("\n");
  fflush(stdout);

  char buf[8];
  scanf("%s", buf);
  if (buf == "Red"s) return red;
  if (buf == "Blue"s) return blue;
  if (buf[0] == 'R') return red;
  if (buf[0] == 'B') return blue;
  return 0;
}

void next(size_t& i, size_t n) {
  n += n;
  if (++i == n) i = 0;
}

void answer(std::vector<int> const& res) {
  printf("! ");
  for (size_t i = 0; i < res.size(); ++i) {
    printf("%c", ((res[i] == red)? 'R': 'B'));
  }
  puts("");
  fflush(stdout);
}

int main() {
  size_t n;
  scanf("%zu", &n);

  std::vector<int> res(n+n);
  std::deque<size_t> q;

  if (n == 1) {
    q.push_back(0);
    res[0] = query(q);
    q.pop_back();
    q.push_back(1);
    res[1] = query(q);
    answer(res);
    return 0;
  }

  std::mt19937 rsk(0315);
  std::uniform_int_distribution<size_t> neko(0, n+n-1);
  size_t i = neko(rsk);
  for (size_t j = 0; j < n; ++j) {
    q.push_back(i);
    next(i, n);
  }

  int last = query(q);
  if (i >= n+n) i -= n;
  while (true) {
    q.pop_front();
    q.push_back(i);
    int cur = query(q);
    if (last != cur) break;
    next(i, n);
  }

  // fprintf(stderr, "[%zu]: %d\n", (i+n)%(n+n), last);
  // fprintf(stderr, "[%zu]: %d\n", i, -last);

  res[(i+n)%(n+n)] = last;
  res[i] = -last;

  next(i, n);
  while (res[i] == 0) {
    q.pop_back();
    q.push_back(i);
    res[i] = query(q);
    next(i, n);
  }
  q.clear();
  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == blue) {
      q.push_back(i);
      if (q.size() == n/2) break;
    }
  }
  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == red) {
      q.push_back(i);
      if (q.size() == n-1) break;
    }
  }

  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == 0) {
      q.push_back(i);
      res[i] = query(q);
      q.pop_back();
    }
  }
  answer(res);
}

