int main() {
	int n;
	scanf("%d", &n);
	vector<int> v(n);
	iota(v.begin(), v.end(), 0);
	int init = ask(v);
	int lo = 0, hi = n - 1;
	while (lo < hi) {
		int m = (lo + hi + 1) >> 1;
		iota(v.begin(), v.end(), m);
		int t = ask(v);
		if (t == init) lo = m;
		else hi = m - 1;
	}
	int m = lo;
	// m+1..m+n-1 have equal R,B.
	iota(v.begin(), v.end(), m + 1);
	vector<int> ans(2 * n, -1);
	for (int i = 0; i < 2 * n; ++i) {
		if (i < m + 1 || i >= m + n) {
			v.back() = i;
			ans[i] = ask(v);
		}
	}
	int c = 0;
	for (int i = 0; i < 2 * n; ++i)
		if (ans[i] == 0 && c < n / 2) v[c++] = i;
	for (int i = 0; i < 2 * n; ++i)
		if (ans[i] == 1 && c < n - 1) v[c++] = i;
	for (int i = m + 1; i < m + n; ++i) {
		v.back() = i;
		ans[i] = ask(v);
	}
	printf("! ");
	for (int i = 0; i < 2 * n; ++i) printf("%c", "BR"[ans[i]]);
	printf("\n");
	fflush(stdout);
}

