int n;
vector<int> query;
int ans[200];
int last = -1;
int ct = 0;
bool done = false;
int getverdict(){
    ct++;
    string s;
    cin >> s;
    if (s == "Red") return 0;
    else return 1;
}
vector<int> guaranteed;
vector<int> red;
vector<int> blue;
int iscurg[200];
void check(int x){
    cout << "? ";
    for (int i = x; i < n+x; i++){
        cout << query[i] << " ";
    }
    cout << endl;
    int verdict = getverdict();
    if (last != -1 && verdict != last){
        done = true;
        ans[query[x+n-1]] = verdict;
        ans[query[x-1]] = last;
        for (int i = x; i < n+x-1; i++){
            guaranteed.push_back(query[i]);
            iscurg[query[i]] = true;
        }
    }
    last = verdict;
}
int getAnswer(int x){
    cout << "? ";
    for (auto k : guaranteed) cout << k << " ";
    cout << x;
    cout << endl;
    int verdict = getverdict();
    if (verdict == 0 && (int)red.size() < n/2) red.push_back(x);
    if (verdict == 1 && (int)blue.size() < n/2) blue.push_back(x);
    return verdict;
}
int main(){
    srand(23234);
    memset(ans,-1,sizeof(ans));
    cin >> n;
    for (int i = 1; i <= 2*n; i++) query.push_back(i);
    random_shuffle(query.begin(),query.end());
    for (int i = 0; i <= n && !done; i++){
        check(i);
    }
    for (int i = 1; i <= 2*n; i++){
        if (ans[i] == -1 && !iscurg[i]){
            //printf("checking %d\n",i);
            ans[i] = getAnswer(i);
        }
    }
    guaranteed.clear();
    for (auto x : red) guaranteed.push_back(x);
    for (auto x : blue) guaranteed.push_back(x);
    for (int i = 1; i <= 2*n; i++){
        if (ans[i] == -1){
            //printf("checking %d\n",i);
            ans[i] = getAnswer(i);
        }
    }
    cout << "! ";
    for (int i = 1; i <= 2*n; i++){
        if (ans[i] == 0) cout << 'R';
        else cout << 'B';
    }
    cout << endl;
    //printf("%d queries used.",ct);
    return 0;
}

#include <iostream>
#include <bits/stdc++.h>
#define mp make_pair
#define pb push_back
using namespace std;
using ll = long long int;
bool query(vector<int> q){
    cout<<"? ";
    for(const auto &x : q){
        cout<<x<<" ";
    }
    cout<<endl;
    string ans;
    cin>>ans;
    return ans=="Red";
}
vector<int> makevector(int l,int r){
    vector<int> ans(r-l+1);
    for(int i=0;i<ans.size();i++){
        ans[i]=i+l;
    }
    return ans;
}
void solve(){
    int n;
    cin>>n;
    vector<int> ans(2*n+1, -1);//1 - red, 0 - blue;
    vector<int> red, blue;
    int g,r;
    for(int i=2, prev = query(makevector(1,n));i<=n;i++){
        vector<int> q = makevector(i,n+i-1);
        if(prev!=query(q)){
            ans[i-1]=(prev==1);
            ans[n+i-1] = (prev==0);
            g=i, r=n+i-2;
            break;
        }
    }
    for(int i=1;i<=2*n;i++){
        if(i>=g && i<=r){
            continue;
        }
        vector<int> q = makevector(g,r);
        q.pb(i);
        ans[i] = query(q);
        if(ans[i]){
            red.pb(i);
        }
        else{
            blue.pb(i);
        }
    }
    vector<int> base;
    for(int i=0;i<n/2;i++){
        base.pb(red[i]);
        base.pb(blue[i]);
    }
    for(int i=g;i<=r;i++){
        base.pb(i);
        ans[i] = query(base);
        base.pop_back();
    }
    cout<<"! ";
    for(int i=1;i<=2*n;i++){
        cout<<(ans[i] ? "R" : "B");
    }
    cout<<endl;
}
int main() {
    ios_base::sync_with_stdio(false);
    solve();
}

