class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int ans = 0, N;
  vector<Int> B, R;
  Solver() {}
  void input() {
    cin >> N;
  }
  void solve() {
    set<Int> found;
    rep(tc, 210){
      if(int(R.size()) == N)break;
      /*
      cerr << "Red: ";
      FOR(r, R){
        cerr << r << " ";
      }
      cerr <<endl;
      cerr << "Blue: ";
      FOR(r, B){
        cerr << r << " ";
