       */
      vi baseQ;
      rep(i, B.size()){
        baseQ.push_back(B[i]);
        baseQ.push_back(R[i]);
        if(Int(baseQ.size() + 1) == Int(N))break;
      }

      string lastResult;
      deque<Int> Q;
      rep(i, 2*N){
        if(found.count(i))continue;
        Q.push_back(i);
        if(Int(baseQ.size() + Q.size()) < N)continue;
        Int last = -1;
        if(Int(baseQ.size() + Q.size()) > N) {
          last = Q.front();
          Q.pop_front();
        }

        cout << "?";
