        if(lastResult == ""){
          lastResult = result;
          continue;
        }
        if(result != lastResult){
          if(result == "Blue"){
            found.insert(i);
            found.insert(last);
            B.push_back(i);
            R.push_back(last);
            goto NEXT;
          }
          else if(result == "Red"){
            found.insert(i);
            found.insert(last);
            R.push_back(i);
            B.push_back(last);
            goto NEXT;
          }else{
            return;
          }
        }
      }
      NEXT:;
    }
  }
  void output() {
