class Xorshift
{
private:
    uint32_t x, y, z, w;
public:
    Xorshift(uint32_t seed=88675123, int32_t loop=50){
        x = 123456789;
        y = 362436069;
        z = 521288629;
        w = seed;
        while(--loop >= 0){
            (*this)();
        }
    }
    uint32_t operator()(){
        uint32_t t=(x^(x<<11));
        x=y; y=z; z=w;
        return w=(w^(w>>19))^(t^(t>>8));
    }
    uint32_t operator()(uint32_t size){
        return (*this)() % size;
    }
    uint64_t get64(){
        uint64_t a = (*this)();
        uint64_t b = (*this)();
        return (a << 32) | b;
    }
    uint64_t get64(uint64_t size){
        return get64() % size;
    }
    template <class T>
    void shuffle(vector<T>& v){
        uint32_t n = v.size();
        for(uint32_t i=0; i<n-1; ++i){
            uint32_t j = (*this)(n-i) + i;
            swap(v[i], v[j]);
        }
    }
};
Xorshift xorshift;

bool query(const vector<int>& v, int n)
{
    cout << '?';
    for(int i=0; i<n; ++i)
        cout << ' ' << (v[i] + 1);
    cout << endl;

    string s;
    cin >> s;
    return s == "Red";
}

int main()
{
    int n;
    cin >> n;

    vector<int> v(2*n);
    for(int i=0; i<2*n; ++i)
        v[i] = i;

    vector<bool> isRed(2*n, false);
    for(;;){
        xorshift.shuffle(v);
        bool a = query(v, n);
        swap(v[0], v[n]);
        swap(v[1], v[n+1]);
        swap(v[2], v[n+2]);
        swap(v[3], v[n+3]);
        bool b = query(v, n);
        if(a != b){
            if(b){
                swap(v[0], v[n]);
                swap(v[1], v[n+1]);
                swap(v[2], v[n+2]);
                swap(v[3], v[n+3]);
            }

            for(int i=0; ; ++i){
                swap(v[i], v[n+i]);
                if(!query(v, n)){
                    swap(v[i], v[n+i]);
                    swap(v[0], v[i]);
                    swap(v[n], v[n+i]);
                    break;
                }
            }

            isRed[v[0]] = true;
            break;
        }
    }

    for(int i=1; i<n; ++i){
        swap(v[i], v[n]);
        if(!query(v, n))
            isRed[v[n]] = true;
        swap(v[i], v[n]);
    }
    for(int i=n+1; i<2*n; ++i){
        swap(v[0], v[i]);
        if(query(v, n))
            isRed[v[0]] = true;
        swap(v[0], v[i]);
    }

    cout << "! ";
    for(int i=0; i<2*n; ++i){
        if(isRed[i])
            cout << 'R';
        else
            cout << 'B';
    }
    cout << endl;

    return 0;
}

