void askFinish(ll x)
{
    ll l = x;
    ll r = x+n-2;
    for (ll i=1; i<=2*n; i++)
    {
        if (!(l<=i && i<=r))
        {
            ll ans = askllerval(l, r, i);
            Ans[i] = ans;
        }
    }

    l = x + n;
    r = x - 2;
    for (ll i=1; i<=2*n; i++)
    {
        if (!(l<=i || i<=r) && Ans[i] == 0)
        {
            ll ans = askllerval(l, r, i);
            Ans[i] = ans;
        }
    }

    prllAns();
}

