	return t == "Blue";
}

void answer(vector<int> v) {
	cout << "! ";
	for (int b : v) {
		cout << (b ? 'B' : 'R');
	}
	cout << endl;
}

void rec(vector<int>& ans, int l, int r, vector<int> fix) {
	if (l == r) return;
	vector<int> v = fix;
	REP(i, l + 1, r - 1) {
		v.push_back(i);
	}

	v.push_back(l);
	bool a = query(v);
	v.pop_back();
	v.push_back(r - 1);
	bool b = query(v);
	v.pop_back();

	if (a == b) {
		ans[l % M] = ans[(r - 1) % M] = !a;
	} else {
		ans[l % M] = a;
		ans[(r - 1) % M] = b;
	}
	fix.push_back(l);
	fix.push_back(r - 1);
	rec(ans, l + 1, r - 1, fix);
}

bool cat(int i) {
	vector<int> v;
	REP(k, i, N + i) {
		v.push_back(k);
	}
	return query(v);
}

