	bool ref = cat(lo);
	while (hi - lo > 1) {
		int mid = (lo + hi) / 2;
		if (cat(mid) == ref) {
			lo = mid;
		} else {
			hi = mid;
		}
	}

	{
		int a = lo;
		int b = lo + N;
		ans[a] = ref;
		ans[b] = !ref;

		vector<int> fix = { a, b };
		rec(ans, a + 1, a + N, fix);
		rec(ans, b + 1, b + N, fix);
	}
	answer(ans);

	return 0;
}

