string f(int offset, int n) {
    string response;
    cout << "? ";
    for (int i = offset; i < offset + n; i++) {
        cout << i + 1 << ' ';
    }
    cout << endl;

    cin >> response;
    return response;
}

string jump_val(int given_pos, int jump, int n) {
    string response;
    cout << "? " << given_pos + 1 << ' ';
    for (int i = 0; i < jump; i++) {
        cout << i + 1 << ' ';
    }
    for (int i = jump + n + 1; i < 2 * n; i++) {
        cout << i + 1 << ' ';
    }
    cout << endl;

    cin >> response;
    return response;
}

string inside_val(int given_pos, int inside, int n) {
    string response;
    cout << "? " << given_pos + 1 << ' ';
    for (int i = inside + 1; i < inside + n; i++) {
        cout << i + 1 << ' ';
    }
    cout << endl;

    cin >> response;
    return response;
}

int main() {
    int n;
    cin >> n;

    string to_search = f(0, n);
    string balls(2 * n, 'R');

    int left = 0, right = n - 1, middle, val = 0;
    while (left <= right) {
        middle = left + (right - left) / 2;
        if (f(middle, n) == to_search) {
            val = middle;
            left = middle + 1;
        }
        else {
            right = middle - 1;
        }
    }

    if (to_search[0] == 'R') {
        balls[val] = 'R';
        balls[val + n] = 'B';
    }
    else {
        balls[val] = 'B';
        balls[val + n] = 'R';
    }

    for (int i = 0; i < val; i++) {
        balls[i] = inside_val(i, val, n)[0];
    }
    for (int i = val + 1; i < val + n; i++) {
        balls[i] = jump_val(i, val, n)[0];
    }
    for (int i = val + n + 1; i < 2 * n; i++) {
        balls[i] = inside_val(i, val, n)[0];
    }

    cout << "! " << balls << endl;
    return 0;
}

