}

void generate(int v[], int n, int x) {
    for (int i = 0; i < n; i ++) {
        v[i] = x + i + 1;
    }
}

int binary_search(char first_color, int n) {
    int left = 0, right = n;
    int v[n];
    while (left <= right) {
        int mid = (left + right) / 2;
        generate(v, n, mid);
        char color = ask(v, n);
        if (color == '-')   return -1;
        if (first_color != color) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return right + 1;
}

