	cin >> n;
	ans = vector<char>(n * 2, 'U');
	vi initary(n);
	Loop(i, n) initary[i] = i;
	init = ask(initary);
	int p = lower_bsearch(0, n, { -1 }, evalfunc);
	equal_ary.resize(n - 1);
	Loop1(i, n - 1) {
		equal_ary[i - 1] = p + i;
	}
	ans[p] = init;
	ans[p + n] = rev(init);
	if (n >= 3) {
		solve_others();
		solve_self();
	}
	cout << "! ";
	Loop(i, n * 2) {
		cout << ans[i];
	}
	cout << endl;
}

