using namespace std;

const int N=220;

int n,qlist[N];

char rd[10],ans[N];

bool inl[N];

void query(int u){
	int l=u,r=u+n-1;
	printf("? ");
	for(int i=l;i<=r;i++){
		printf("%d%c",i," \n"[i==r]);
	}
	fflush(stdout);
}

void querylist(){
	printf("? ");
	for(int i=1;i<=n;i++){
		printf("%d%c",qlist[i]," \n"[i==n]);
	}
	fflush(stdout);
}

void answer(){
	printf("! %s\n",ans+1);fflush(stdout);
	exit(0);
}

void work(int u){
	int poss=1;
	for(int i=1;i<=n;i++){
		qlist[i]=u-1+i;
	}
	for(int i=1;i<=n;i++){
		if(ans[qlist[i]]==ans[u]){
			poss=i;break;
		}
	}
	for(int i=2;i<=n;i++){
		inl[qlist[i]]=1;
	}
	swap(qlist[poss],qlist[1]);
	for(int i=1;i<=(n<<1);i++){
		if(ans[i]^'U'||inl[i]){
			continue;
		}
		qlist[1]=i;
		querylist();
		scanf(" %s",rd);
		ans[i]=rd[0];
	}
	int pos[2][N]={0,0},cnt[2]={0,0};
	for(int i=1;i<=(n<<1);i++){
		if(ans[i]^'U'){
			if(ans[i]=='R'){
				pos[0][++cnt[0]]=i;
			}
			else{
				pos[1][++cnt[1]]=i;
			}
		}
	}
	memset(inl,0,sizeof inl);
	int cntq=1;
	for(int i=1;i<=(n>>1);i++){
		qlist[++cntq]=pos[0][i];
		inl[pos[0][i]]=1;
		qlist[++cntq]=pos[1][i];
		inl[pos[1][i]]=1;
	}
	for(int i=1;i<=(n<<1);i++){
		if(ans[i]^'U'||inl[i]){
			continue;
		}
		qlist[1]=i;
		querylist();
		scanf(" %s",rd);
		ans[i]=rd[0];
	}
	answer();
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=(n<<1);i++){
		ans[i]='U';
	}
	int lc=0,rc=0,l=1,r=n+1;
	query(1);
	scanf(" %s",rd);
	if(rd[0]=='B'){
		lc=1;
	}
	else{
		rc=1;
	}
	while(l+1<r){
		int mid=(l+r)>>1;
		query(mid);
		scanf(" %s",rd);
		int col=(rd[0]=='B'?1:0);
		if(rc^col){
			l=mid;
		}
		else{
			r=mid;
		}
		if(l>r){
			swap(l,r);swap(lc,rc);
		}
	}
	work(l);
	answer();
	return 0;
}

