ll n;
void go(int i){
  string s = "? ";
  for(int j=0;j<n;j++) s += to_string(i+j) + (j!=n-1?" ":"");
  std::cout << s << "\n" << std::flush;
}

int main(int argc, char const *argv[]) {
  std::cin >> n;
  string s="?", t, r;
  ll L = 1, R= n+1, l = 0;

  go(1);
  string FIRST;
  std::cin >> FIRST;

  while(R-L>1){
    ll mid = (L+R)/2;
    go(mid);
    std::cin >> t;
    if(t==FIRST) L = mid;
    else R = mid;
  }
  ll m = R;

  string c ="?";
  for(int i=m;i<=m+n-2;i++) c += " ", c+=to_string(i);
  // m~m+n-1は等しい、m-1とm+nが異なる
  set<ll> red, blue;
  for(int i=1;i<=2*n;i++){
    if(i>=m&&i<=m+n-2) continue;
    std::cout << c << " " << i << "\n" << std::flush;
    std::cin >> r;
    l++;
    if(r=="Red") red.insert(i);
    else blue.insert(i);
  }
  c = "?";
  auto itr = red.begin();
  re(i, n/2){
    c += " ";
    c += to_string((*itr));
  }
  itr = blue.begin();
  re(i, n/2){
    c += " ";
    c += to_string((*itr));
  }

  for(int i=m;i<=m+n-2;i++){
    std::cout << c << " " << i << "\n" << std::flush;
    std::cin >> r;
    l++;
    if(r=="Red") red.insert(i);
    else blue.insert(i);
  }
  string ans="! ";
  for(int i=1;i<=2*n;i++){
    if(red.find(i)!=red.end()) ans+="R";
    else ans+="B";
  }
  std::cout << ans << "\n" << std::flush;
  return 0;
}

