int N;
bool ans[99];

vector<int> make_vector(const int& st, const int sz){
    int pos = st;
    if((pos %= (2 * N)) < 0)pos += (2 * N);
    vector<int> res(sz);
    rep(i, sz){
        res[i] = pos;
        if(++pos >= (2 * N))pos -= (2 * N);
    }
    return res;
}

bool inquire(const vector<int>& vec){
    cout << "?";
    for(const int &x : vec)cout << " " << x + 1;
    cout << endl;
    string s;
    cin >> s;
    if(s == "-1")exit(0);
    return s == "Blue";
}

void answer(){
    cout << "! ";
    rep(i, 2 * N)cout << (ans[i] ? "B" : "R");
    cout << endl;
}

// solve
int main(){

    cin >> N;

    bool fir_blue = inquire(make_vector(0, N));
    int lb = 0, ub = N;
    while(ub - lb > 1){
        int md = (lb + ub) / 2;
        (fir_blue == inquire(make_vector(md, N)) ? lb : ub) = md;
    }

    ans[lb] = fir_blue;
    ans[lb + N] = !fir_blue;
    vector<int> use = make_vector(ub, N - 1);

    rep(i, 0, lb - 1){
        use.push_back(i);
        ans[i] = inquire(use);
        use.pop_back();
    }

    rep(i, ub + N, 2 * N - 1){
        use.push_back(i);
        ans[i] = inquire(use);
        use.pop_back();
    }

    use = make_vector(ub + N, N - 1);
    rep(i, ub, lb + N - 1){
        use.push_back(i);
        ans[i] = inquire(use);
        use.pop_back();
    }

    answer();

}

