ll n;
void go(int i){
  string s = "? ";
  for(int j=0;j<n;j++) s += to_string(i+j) + (j!=n-1?" ":"");
  std::cout << s << "\n" << std::flush;
}

string make(int i){
  string s = "? ";
  for(int j=0;j<n-1;j++) s += to_string(i+j) + (j!=n-1?" ":"");
  return s;
}

int main(int argc, char const *argv[]) {
  std::cin >> n;
  string s="?", t;
  ll L = 1, R = n+1;
  go(1);
  string FIRST;
  std::cin >> FIRST;

  while(R-L>1){
    ll mid = (L+R)/2;
    go(mid);
    std::cin >> t;
    if(t==FIRST) L = mid;
    else R = mid;
  }
  std::cout << R << '\n';
  string x = make(R);

  vll ans(n+1, 0);
  vll r, b;
  for(int i=1;i<R;i++){
    string y = x + to_string(i);
    std::cout << y << "\n" << std::flush;
    std::cin >> t;
    if(t=="Red") r.push_back(i), ans[i] = 1;
    else b.push_back(i), ans[i] = 0;
  }
  for(int i=R+n-1;i<=2*n;i++){
    string y = x + to_string(i);
    std::cout << y << "\n" << std::flush;
    std::cin >> t;
    if(t=="Red") r.push_back(i), ans[i] = 1;
    else b.push_back(i), ans[i] = 0;
  }
  string z = "? ";
  for(int i=0;i<n/2;i++) z += to_string(r[i]) + " ";
  for(int i=0;i<n/2;i++) z += to_string(b[i]) + " ";

  // mid
  for(int i=R;i<R+n-1;i++){
    string tmp = z + to_string(i);
    std::cout << tmp << "\n" << std::flush;
    std::cin >> t;
    if(t=="Red") ans[i] = 1;
  }
  string ret = "! ";
  for(int i=1;i<=2*n;i++) {
    ret += (ans[i]?"R":"B");
    if(i!=2*n) ret += " ";
  }
  std::cout << ret << "\n" << std::flush;
  return 0;
}

