int main() {
//    freopen("in.txt","r", stdin);
//    cout << fixed << setprecision(15);
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int n;
    cin >> n;

    const string R = "Red";
    const string B = "Blue";

    map<string, string> opp = {{R,B},{B,R}};

    vector<string> ans(2 * n + 1);

    string fst = get(1, n);
    int l = 1;
    int r = n + 1;
    while (r-l > 1) {
        int mid = (l+r) / 2;
        if (get(mid, mid + n - 1) != fst)
            r = mid;
        else
            l = mid;
    }

    ans[l] = fst;
    ans[l + n] = opp[fst];

    for (int i = 1; i <= 2 * n; ++i) {
        if (ans[i] == "") {
            if (i < l || i > l + n) {
                if (get(l + 1, l + n - 1, i) == fst)
                    ans[i] = fst;
                else
                    ans[i] = opp[fst];
            } else {
                if (get(l, l + n, i) != fst)
                    ans[i] = fst;
                else
                    ans[i] = opp[fst];
            }
        }
    }
    cout << "! ";
    for (int i = 1; i <= 2 * n; ++i)
        cout << ans[i][0];
    cout << endl;
}

