int main(){
    int N;
    cin >> N;
    vector<bool> arr = vector<bool>(N * 2, false);
    for(int i = 0; i < N; i++){
        arr[i] = true;
    }
    int left = query(arr);
    int low = 0, high = N; // (low, high]
    while(low + 1 < high){
        int mid = (low + high) / 2;
        arr = vector<bool>(N * 2, false);
        for(int i = 0; i < N - mid; i++){
            arr[i] = true;
        }
        for(int i = 0; i < mid; i++){
            arr[i + N] = true;
        }
        int ret = query(arr);
        if(ret == left){
            low = mid;
        }else{
            high = mid;
        }
    }
    vector<int> ans(N * 2, -1);
    arr = vector<bool>(N * 2, false);
    for(int i = 0; i < N - high; i++){
        arr[i] = true;
    }
    for(int i = 0; i < high - 1; i++){
        arr[i + N] = true;
    }
    for(int i = N - high; i < N; i++){
        arr[i] = true;
        ans[i] = query(arr);
        arr[i] = false;
    }
    for(int i = high - 1; i < N; i++){
        arr[i + N] = true;
        ans[i + N] = query(arr);
        arr[i + N] = false;
    }
    bool red = false, blue = false;
    arr = vector<bool>(N * 2, false);
    for(int i = N - high; i < N; i++){
        if(ans[i] == 0 && !red){
            red = true;
            continue;
        }else if(ans[i] == 1 && !blue){
            blue = true;
            continue;
        }
        arr[i] = true;
    }
    for(int i = high - 1; i < N; i++){
        if(ans[i + N] == 0 && !red){
            red = true;
            continue;
        }else if(ans[i + N] == 1 && !blue){
            blue = true;
            continue;
        }
        arr[i + N] = true;
    }

    for(int i = 0; i < N - high; i++){
        arr[i] = true;
        ans[i] = query(arr);
        arr[i] = false;
    }
    for(int i = 0; i < high - 1; i++){
        arr[i + N] = true;
        ans[i + N] = query(arr);
        arr[i + N] = false;
    }
    answer(ans);
}

