ll askllerval(ll l, ll r, ll x)
{
    if (r>2*n)
        r-=2*n;
    V.clear();
    if (r<l)
    {
        for (ll i = l; i <= 2*n; i++)
            V.push_back(i);
        for (ll i = 1; i <= r; i++)
            V.push_back(i);
    }
    else
    {
        for (ll i = l; i <= r; i++)
            V.push_back(i);
    }
    if (x!=-1)
        V.push_back(x);
    ll ans = ask();
    return ans;
}

void prllAns()
{
    cout<<"! ";
    for (ll i=1; i<=2*n; i++)
    {
        if (Ans[i] == 0)
            cout<<"R";
        else
            cout<<"B";
    }
    cout.flush();
    exit(0);
}

void askFinish(ll x)
{
    ll l = x;
    ll r = x+n-2;
    if (r > 2*n)
    {
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i || i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i && i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }

    l = x + n;
    r = x + 2*n - 2;
    if (l <= 2*n)
    {
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i || i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        l -= 2*n;
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i && i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }

    prllAns();
}

