    cin>>n;

    if (n==1)
    {
        V.push_back(1);
        Ans[1] = ask();
        V.clear();
        V.push_back(2);
        Ans[2] = ask();
        prllAns();
        return 0;
    }

    ll last = -1;
    for (ll i=1; i<=2*n; i++)
    {
        ll ans = askllerval(i, i+n-1, -1);
        if (last != -1 &&  ans != last)
        {
            askFinish(i);
            return 0;
        }
        last = ans;
    }
    assert(false);
    return 0;
}

