vector <int> getEqual(){
	vector <int> all;
	for(int i = 1; i <= n + n; ++i)
		all.push_back(i);
	random_shuffle(all.begin(), all.end());

	vector <int> Left, Right;
	for(int i = 0; i < n + n; ++i)
		if(i < n)	Left.push_back(all[i]);
		else	Right.push_back(all[i]);

	if(!ask(Left))
		swap(Left, Right);

	random_shuffle(Left.begin(), Left.end());
	random_shuffle(Right.begin(), Right.end());	

	vector <int> tmp = Left;
	while(true){
		for(int i = 0; i < n; ++i)
			if(tmp[i] == Left.back()){
				swap(tmp[i], tmp[n - 1]);
				tmp.pop_back();
				break;
			}

		tmp.push_back(Right.back());
		if(!ask(tmp)){
			tmp.pop_back();
			tmp.push_back(Left.back());

			r = Left.back(), b = Right.back();
			return tmp;
		}

		Left.pop_back();
		Right.pop_back();

	}

	assert(false);
}

vector <int> getRest(vector <int> in){
	vector <bool> is(n + n + 1, false);
	for(auto v: in)
		is[v] = true;

	vector <int> ret;
	for(int i = 1; i <= n + n; ++i)
		if(!is[i])
			ret.push_back(i);
	return ret;
}

vector <int> change(vector <int> a, int x, int y){
	for(auto &v: a)
		if(v == x){
			v = y;
			break;
		}

	return a;
}

