string ask(vector<int> &v){
    cout << "? ";
    for(int i = 0; i < n; i++){
        cout << v[i] << " ";
    }
    fflush(stdout);

    string res;
    cin >> res;
    return res;
}

int findPos(vector<int>&asking){
    for(int i = 0; i < n; i++){
        asking[i] = i+1;
    }

    string firstHalf=ask(asking);

    int st=1;
    int dr=n;
    int pos = -1;
    while(st <= dr){
        int mij = (st+dr)/2;
        asking.clear();
        for(int i = 0; i < n; i++){
            asking[i] = mij + i+1;
        }
        string res = ask(asking);
        if(res != firstHalf){
            pos = mij;
            dr = mij-1;
        } else {
            st = mij+1;
        }
    }

    if(firstHalf=="Red"){
        sol[pos]='R';
        sol[pos+n]='B';
    } else {
        sol[pos]='B';
        sol[pos+n]='R';
    }

    return pos;
}

void getOutside(int pos,vector<int>&outside){
    for(int i=1;i<pos;i++){
        outside.push_back(i);
    }
    for(int i=pos+n+1;i<=2*n;i++){
        outside.push_back(i);
    }

    int cntRed=0;
    int cntBlue=0;
    for(int i=0;i<(int)outside.size();i++){
        if(sol[outside[i]]=='R'){
            cntRed++;
        } else {
            cntBlue++;
        }
    }

    for(int i=0;i<(int)outside.size();i++){
        if(cntBlue>cntRed && sol[outside[i]]=='B'){
            outside.erase(outside.begin()+i);
            break;
        }
        if(cntRed>cntBlue && sol[outside[i]]=='R'){
            outside.erase(outside.begin()+i);
            break;
        }
    }
}

