    t.resize(2*n+1);
    t[0] = ' ';
    int rc = 0, bc = 0;
    for(int i = 1; i <= 2*n; i++){
        if(rc == n)
            t[i] = 'B', bc++;
        else if(bc == n)
            t[i] = 'R', rc++;
        else{
            if(randint(0, 1))
                t[i] = 'R', rc++;
            else
                t[i] = 'B', bc++;
        }
    }
    assert(rc == bc);
}

bool run(){
    sa = 0;
    assert(q.size() == n);
    printf("?");
    for(int i: q){
        assert(i > 0 && i <= 2*n);
        printf(" %d", i);
        sa += t[i] == 'R';
    }
    printf("\n"); fflush(stdout);
    q.clear();

#ifdef DEBUG
    str[0] = (sa > n/2) ? 'R' : 'B';
#else
    scanf("%s", str);
#endif

    assert(str[0] != '-');
    cnt++;
    return str[0] == 'R';
}

void getans(int i){
    if(~ans[i]) return;
    for(int j = 0; j < n; j++)
        q.push_back(i+j);
    ans[i] = run();
}

int main(){

    memset(a, -1, sizeof a);
    memset(ans, -1, sizeof ans);

#ifdef DEBUG
    gen();
#else
    scanf("%d", &n);
#endif

    if(n == 1){
        printf("? 1\n");
        fflush(stdout);
        scanf("%s", str);
        printf("! %c %c\n", str[0], (str[0] == 'R') ? 'B': 'R');
        fflush(stdout);
        return 0;
    }

    while(1){

        int i = randint(2, n+1);
        getans(i);
        getans(i-1);

        if(ans[i] != ans[i-1]){
            //printf("found\n");
            a[i-1] = ans[i-1];
            a[i+n-1] = ans[i];
            s[ans[i-1]].push_back(i-1);
            s[ans[i]].push_back(i+n-1);

            //now solve the rest
            for(int j = 1; j <= 2*n; j++){
                if(j < i-1 || j > i+n-1){

                    q.push_back(j);
                    for(int k = i; k < i+n-1; k++)
                        q.push_back(k);

                    a[j] = run();
                    s[a[j]].push_back(j);
                }
            }
            break;
        }
    }

    for(int i = 1; i <= 2*n; i++){
        if(a[i] == -1){
            q.push_back(i);
            for(int j = 0; j < n/2; j++)
                q.push_back(s[0][j]), q.push_back(s[1][j]);

            a[i] = run();
            s[a[i]].push_back(i);
        }
    }

    printf("! ");
    for(int i = 1; i <= 2*n; i++){
        assert(~a[i]);
        printf("%c", a[i] ? 'R' : 'B');
    }
    printf("\n"); fflush(stdout);

#ifdef DEBUG
    cout << ' ' << t << '\n';
    print(cnt);
    assert(cnt <= 210);
#endif

    return 0;
}

