                stage++;
                target = en;
            }
        } else if (stage == 1) {
            if (cnt < N) {
                cout << "?";
                for (int j = target-N+1; j < target; j++) {
                    cout << " " << j+1;
                }
                cnt++;
                cout << " " << (target+cnt)%(2*N)+1 << endl;
                string s; cin >> s;
