                if (s[0] == ho) ans[(target+cnt)%(2*N)] = ho;
                else ans[(target+cnt)%(2*N)] = ge;
            }
            if (cnt == 2*N) break;
        }
    }
    cout << "! ";
    rep(i,2*N) cout << ans[i]; 
    cout << endl;
}

