int main() {
	int N;
	cin >> N;
	if (N == 1) {
		cout << "? 1" << endl;
		int t = check();
		if (t == 0) {
			cout << "! RB" << endl;
		}
		else {
			cout << "! BR" << endl;
		}
		return 0;
	}
	vector<int> decide;
	set<int> undecide;
	for (int i = 1; i <= 2 * N; i++) {
		undecide.insert(i);
	}
	string ans;
	ans.resize(2 * N, '?');
	decide.reserve(2 * N);
	while (1) {
		if (N - decide.size() == 1) {
			for (int it : undecide) {
				vector<int> out(N);
				for (int j = 0; j < decide.size(); j++) {
					out[N - 1 - j] = decide[j];
				}
				out[0] = it;
				sort(out.begin(), out.end());
				cout << "? ";
				for (int o = 0; o < N; o++) {
					cout << out[o];
					if (o == N - 1) {
						cout << endl;
					}
					else {
						cout << " ";
					}
				}
				ans[it-1] = (check() == 0 ? 'R' : 'B');
			}
			cout <<"! " <<  ans << endl;
			return 0;
		}
		vector<int> ren(N, -1);
		for (int i = 0; i < N - decide.size() / 2; i++) {

			vector<int> out(N);
			for (int j = 0; j < decide.size(); j++) {
				out[N - 1 - j] = decide[j];
			}
			for (int j = 0; j < N - decide.size(); j++) {
				auto it = undecide.begin();
				advance(it, i + j);
				out[j] = *it;
			}
			sort(out.begin(), out.end());
			cout << "? ";
			for (int o = 0; o < N; o++) {
				cout << out[o];
				if (o == N - 1) {
					cout << endl;
				}
				else {
					cout << " ";
				}
			}
			ren[i] = check();
		}
		int RtB = -1;
		int BtR = -1;
		int before = -1;
		int after = -1;
		bool checkered = false;
		for (int i = 0; i < N; i++) {
			if (ren[i] == -1)continue;
			after = ren[i];
			if (before == -1) {
				before = after;
			}
			else {
				if (after != before) {
					if (before == 0) {
						if (RtB != -1)checkered = true;
						RtB = i;
					}
					else {
						if (BtR != -1)checkered = true;
						BtR = i;
					}
					if (RtB != -1 && BtR != -1) {
						checkered = true;
					}
				}
				before = after;
			}
		}
		if (checkered) {
			for (int i = 0; i < N; i++) {
				if (ren[i] == -1)continue;
				ans[i] = (ren[i] == 0 ? 'R' : 'B');
			}
			cout << "! " << ans << ":" << endl;
			return 0;
		}
		else {
			if (RtB != -1) {
				auto it = undecide.find(RtB);
				advance(it, N - decide.size());
				decide.push_back(RtB);
				ans[RtB - 1] = 'R';
				decide.push_back(*it);
				ans[*it - 1] = 'B';
				undecide.erase(*it);
				undecide.erase(RtB);
			}
			if (BtR != -1) {
				auto it = undecide.find(BtR);
				advance(it, N - decide.size());
				decide.push_back(BtR);
				ans[BtR - 1] = 'B';
				decide.push_back(*it);
				ans[*it - 1] = 'R';
				undecide.erase(*it);
				undecide.erase(BtR);
			}
			//cout << ans << endl;
		}
	}
	return 0;
}

