int main() {
    int N;
    cin >> N;
    // Find first
    deque<int> a;
    deque<int> b;
    for (int i = 0; i < N; i++) {
        a.push_back(i);
        b.push_back(N + i);
    }

    int r = ask(a);

    if (r < 0) {
        swap(a, b);
    }
    int lstpop;
    int lstadd;
    int rr;
    do {
        lstpop = a.back();
        lstadd = b.front();
        b.push_back(a.back());
        a.pop_back();
        a.push_back(b.front());
        b.pop_front();
         rr = ask(a);
    } while (rr > 0);

    res[lstadd] = -1;
    res[lstpop] = +1;

    auto c = a;

    c.pop_back(); // c is neutral

    for (int i = 0; i < N; i++) {
        if (res[i]==0) {
            auto t = c;
            t.push_back(i);
            int r = ask(t);
            res[i] = r;
        }
    }

    report(N);


}

