    cout << endl;
    string ans;
    cin >> ans;
    return ans == "Red" ? RED : BLUE;
}

int main() {
    int N;
    cin >> N;
    vector<int> v(N), u1(N - 1), u2(N - 1), ans(2 * N);
    int L, R;

    for (int j = 0; j < N; j++) v[j] = j;
    L = query(v);
    R = -L;

    // query logN times 
    int i = BinSearch<int>(-1, N, [&](int k) {
        for(int j = 0; j < N; j++) v[j] = j + k;
        return query(v) == R;
    });
    for(int j = 0; j < N; j++) {
        u1[j] = i + j;
        u2[j] = (i + N + j) % (2 * N);
    }
    // query 2N times
    for(int k = 0; k < 2 * N; k++) {
        for (int j = 0; j < N - 1; j++) {
            v[j] = (i <= k && k < i + N) ? u2[j] : u1[j];
        }
        v[N - 1] = k;
        ans[k] = query(v);
    }
    cout << "! ";
    for(int x : ans) cout << (x == RED ? "R" : "B");
    cout << endl;
    return 0;
}

