int main() {
	int n;
	cin >> n;

	bool normal = true;

	auto ask = [&](set<int> const & se) {
		cout << "?";
		inc(i, 2 * n) {
			if((se.count(i) == 1) == normal) { cout << " " << i + 1; }
		}
		cout << endl;
		string s;
		cin >> s;
		return s[0];
	};
	auto type1 = [&](int p) {
		set<int> se;
		inc(i, n) { se.insert(i < p ? i + n : i); }
		return ask(se);
	};
	auto type2 = [&](int p, int L) {
		set<int> se;
		inc(i, n) {
			if(i == L) { continue; }
			if(i == p) { se.insert(i); }
			se.insert(i + n);
		}
		return ask(se);
	};
	auto type3 = [&](int p, int L) {
		set<int> se;
		inc(i, n) {
			if(i == L) { continue; }
			if(i == p) { se.insert(i + n); }
			se.insert(i);
		}
		return ask(se);
	};

	// ----

	if(type1(0) != 'R') { normal = false; }

	int L = 0, H = n;
	while(H - L > 1) {
		int M = (L + H) / 2;
		(type1(M) == 'R' ? L : H) = M;
	}

	auto ans = string(2 * n, '@');
	ans[L + 0] = 'R';
	ans[L + n] = 'B';
	inc(i, n) {
		if(i == L) { continue; }
		ans[i + 0] = type2(i, L);
		ans[i + n] = type3(i, L);
	}

	if(! normal) {
		inc(i, n) { swap(ans[i], ans[i + n]); }
	}

	cout << "! " << ans << endl;

	return 0;
}

