int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> ans(n * 2, -1);

  vector<int> leftHalf;
  for (int i = 0; i < n; i++)
    leftHalf.push_back(i);

  // ask 1 -> n
  int leftHalfColor = ask(leftHalf);
  int rightHalfColor = leftHalfColor ^ 1;

  // find when left color turns to right color
  int res = 0, low = 1, high = n - 1;
  vector<int> save;
  for (int i = 0; i < n; i++)
    save.push_back(i + n);
  while (low <= high)
  {
    int mid = (low + high) / 2;
    vector<int> a;
    for (int i = 0; i < n; i++)
      if (i < mid) a.push_back(i);
      else a.push_back(i + n);
    if (ask(a) == rightHalfColor)
    {
      res = mid;
      low = mid + 1;
      save = a;
    }
    else high = mid - 1;
  }

  ans[res] = leftHalfColor;
  ans[res + n] = rightHalfColor;

  // a contains [0, res) and [res + n, 2n)
  vector<int> a = save;
  for (int i = res + 1; i < res + n; i++)
  {
    a[res] = i;
    if (ask(a) == rightHalfColor) ans[i] = rightHalfColor;
    else ans[i] = leftHalfColor;
  }

  // add n/2 0s and n/2 1s
  vector<int> b;
  int cnt[2] = {0};
  for (int i = res; i <= res + n; i++)
    if (cnt[ans[i]] < n / 2)
    {
      b.push_back(i);
      cnt[ans[i]]++;
    }

  b.push_back(-1);
  for (int i = 0; i < n * 2; i++)
    if (ans[i] < 0)
    {
      b.back() = i;
      ans[i] = ask(b);
    }

  cout << "! ";
  for (int i = 0; i < n * 2; i++)
    cout << (ans[i] ? 'B' : 'R');
  cout << endl;
  cout.flush();
}

