}

int main() {
  mt19937 random(chrono::steady_clock::now().time_since_epoch().count());

  int n = ReadN();
  if (DEBUG) {
    cout << "n: " << n << endl;
  }

  vector<int> xs(2 * n);
  for (int i = 0; i < 2 * n; i++) {
    xs[i] = i;
  }
  shuffle(xs.begin(), xs.end(), random);
  vector<int> rs(n), bs(n);
  for (int i = 0; i < n; i++) {
    rs[i] = xs[i];
    bs[i] = xs[n + i];
  }
  string s0 = Query(rs);
  if (s0 == "Blue") swap(rs, bs);

  vector<char> ans(2 * n, '.');

  for (int k = 0; k < n; k++) {
    swap(rs[k], bs[k]);
    string s = Query(rs);
    if (s == "Blue") {
      ans[rs[k]] = 'B';
      ans[bs[k]] = 'R';
      swap(rs, bs);
      break;
    }
  }

  vector<int> r_points(2 * n, 4);
  vector<int> b_points(2 * n, 4);

  while (true) {
    auto is_end_fn = [&]() {
      int r_count = 0;
      int b_count = 0;
      for (int r : rs) {
        if (ans[r] == 'R') r_count++;
        if (ans[r] == 'B') b_count++;
      }
      if (r_count == n / 2 + 1) {
        for (int r : rs) {
          if (ans[r] == '.') ans[r] = 'B';
        }
        for (int b : bs) {
          if (ans[b] == '.') ans[b] = 'R';
        }
        return true;
      }
      if (b_count == n / 2) {
        for (int r : rs) {
          if (ans[r] == '.') ans[r] = 'R';
        }
        for (int b : bs) {
          if (ans[b] == '.') ans[b] = 'B';
        }
        return true;
      }

      for (char c : ans) {
        if (c == '.') return false;
      }
      return true;
    };
    if (is_end_fn()) {
      cout << "! ";
      for (char c : ans) {
        cout << c;
      }
      cout << endl;
      return 0;
    }


    vector<int> ris;
    for (int i = 0; i < n; i++) {
      if (ans[rs[i]] == '.') {
        for (int k = 0; k < r_points[rs[i]]; k++) {
          ris.push_back(i);
        }
      }
    }
    shuffle(ris.begin(), ris.end(), random);
    int ri = ris[0];

    vector<int> bis;
    for (int i = 0; i < n; i++) {
      if (ans[bs[i]] == '.') {
        for (int k = 0; k < b_points[bs[i]]; k++) {
          bis.push_back(i);
        }
      }
    }
    shuffle(bis.begin(), bis.end(), random);
    int bi = bis[0];

    swap(rs[ri], bs[bi]);
    string s = Query(rs);
    if (s == "Blue") {
      ans[rs[ri]] = 'B';
      ans[bs[bi]] = 'R';
      swap(rs, bs);
    } else {
      r_points[bs[ri]] = max(r_points[bs[ri]] / 2, 1);
      b_points[bs[ri]] = min(b_points[bs[ri]] * 2, 16);

      b_points[rs[ri]] = max(b_points[rs[ri]] / 2, 1);
      r_points[rs[ri]] = min(r_points[rs[ri]] * 2, 16);
    }
  }
}

