int64 query(const vector<int64>& v) { // Red -> 0 , Blue -> 1
  cout << "? ";
  REP(i, v.size()) {
    cout << v[i]+1 << " ";
  }
  cout << endl;
  string s;
  cin >> s;
  return s == "Red" ? 0 : 1;
}

int main(void){
  int64 N;
  cin >> N;
  vector<int64> res(2*N, -1);
  int64 fir = 0;
  vector<int64> q;
  REP(i, N) {
    q.push_back(i);
  }
  fir = query(q);
  vector<int64> base;
  int64 l, r;
  FOR(i, 1, N+1) {
    q = vector<int64>();
    FOR(j, i, i+N) {
      q.push_back(j);
    }
    int64 ret = query(q);
//    cout << fir << " " << ret << endl;
    if (ret != fir) {
      res[i-1] = fir;
      res[i+N-1] = 1-fir;
      FOR(j, i, i+N-1) {
        base.push_back(j);
      }
      l = i; r = i+N-1;
      break;
    }
  }
//  REP(i, 2*N) cout << res[i] << " ";
//  cout << endl;

//  cout << l << " " << r << endl;
  REP(i, 2*N) {
    if (res[i] == -1 && !(l <= i && i < r)) {
      base.push_back(i);
      res[i] = query(base);
      base.pop_back();
    }
  }
  int64 cnt[2] = {};
  base = vector<int64>();
  REP(i, 2*N) {
    if (res[i] == -1) continue;
    if (cnt[res[i]] < (N-1)/2) {
      base.push_back(i);
      cnt[res[i]]++;
    }
  }
  FOR(i, l, r) {
    base.push_back(i);
    res[i] = query(base);
    base.pop_back();
  }
  cout << "! ";
  REP(i, res.size()) {
    cout << (res[i] ? 'B' : 'R');
  }
  cout << endl;
}

