pair<int, int> first() {
    int pre = -1;
    for (int i : range(N + 1)) {
        vector<int> q;
        for (int j : range(N)) {
            q.push_back(i + j);
        }
        int cur = query(q);
        if (pre != -1 && pre != cur) {
            return {i, cur};
        }
        pre = cur;
    }
    assert(false);
    return {0, 0};
}

