    ret[pos + N - 1] = col;
    ret[pos - 1]     = 1 - col;
    {
        // [use](col)
        vector<int> use, target;
        for (int i : range(N * 2)) {
            if (lb <= i && i < ub - 1) {
                use.push_back(i);
            }
            if (i < lb || ub <= i) {
                target.push_back(i);
            }
        }
        for (auto p : target) {
            vector<int> check = use;
            check.push_back(p);
            ret[p] = query(check);
        }
