const int N = 102;

int q = 0, n;
bool query(vector<int> v)
{
    q++;
    cout << "? ";
    for (int i = 0; i < v.size(); i++)
        cout << v[i] << " ";
    cout << endl;
    string res;
    cin >> res;
    return (res[0] == 'R');
}

bool query(int x)
{
    vector<int> v;
    for (int i = 0; i < n; i++)
        v.PB(x + i);
    return query(v);
}

int pos, ans[N + N];
int val, l, r, m;

int main()
{
    cin >> n;
    val = query(1);
    l = 1;
    r = n + 1;
    for (int i = 8; i >= 0; i--)
    {
        m = (l + r) / 2;
        if (query(m) == val)
            l = m;
        else
            r = m;
    }
    //cout << l << " : " << r << endl;
    pos = r;

    ans[pos - 1] = val;
    ans[pos + n] = !ans[pos + n];
    vector<int> x;
    for (int i = pos; i < pos + n - 1; i++)
        x.PB(i);

    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n && i >= pos - 1)
            continue;
        x.PB(i);
        ans[i] = query(x);
        x.pop_back();
    }
    x.clear();

    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n - 1 && i >= pos)
            continue;
        if (ans[i] == 0 && x.size() < (n - 1) / 2)
            x.PB(i);
    }
    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n - 1 && i >= pos)
            continue;
        if (ans[i] == 1 && x.size() < (n - 1))
            x.PB(i);
    }

    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n - 1 && i >= pos)
        {
            x.PB(i);
            ans[i] = query(x);
            x.pop_back();
        }
    }

    cout << "! ";

    for (int i = 1; i <= n + n; i++)
        if (ans[i])
            cout << "R";
        else
            cout << "B";
    cout << endl;

    return 0;
}

