const int N = 2000;
int n, vis[N], f[N], c[N];
int read() {
    char s[10];
    scanf("%s", s);
    return s[0] == 'R' ? 1: -1;
}
int query(int pos) {
    if (vis[pos] == 1) return f[pos];
    vis[pos] = 1;
    printf("?");
    for (int i = pos; i < pos + n; i ++) {
        printf(" %d", i);
    }
    printf("\n");
    fflush(stdout);
    return f[pos] = read();
}
int main() {
    scanf("%d", &n);
    int lef = 1, rig = n + 1;
    while (rig - lef > 1) {
        int mid = (lef + rig) >> 1;
        if (query(mid) != query(lef)) {
            rig = mid;
        } else {
            lef = mid;
        }
    }
    if (query(rig) == 1) c[rig + n - 1] = 1;
    else c[rig + n - 1] = -1;
    if (query(lef) == 1) c[lef] = 1;
    else c[lef] = -1;
    for (int i = 1; i <= 2 * n; i ++) {
        if (c[i]) continue;
        if (i < lef || i > rig + n - 1) {
            printf("?");
            for (int j = rig; j < rig + n - 1; j ++) printf(" %d", j);
            printf(" %d\n", i); fflush(stdout);
            if (read() == query(rig)) c[i] = c[rig + n - 1]; else c[i] = - c[rig + n - 1]; 
        }
    }
    int v = -1;
    for (int j = 1; j < lef; j ++) v = j;
    for (int j = lef + n; j <= 2 * n; j ++) v = j;
    for (int i = 1; i <= 2 * n; i ++) {
        if (c[i]) continue;
        if (i >= lef && i <= rig + n - 1) {
            printf("?");
            for (int j = 1; j < lef; j ++) if (j != v) printf(" %d", j);
            for (int j = lef + n; j <= 2 * n; j ++) if (j != v) printf(" %d", j);
            printf(" %d\n", i); fflush(stdout);
            if (read() == - query(lef)) c[i] = c[v]; else c[i] = - c[v]; 
        }
    }
    printf("! ");
    for (int i = 1; i <= 2 * n; i ++) printf("%c", c[i] == 1 ? 'R' : 'B');
    printf("\n");
    fflush(stdout);
}

