#include <iostream>
#include <vector>
#include <numeric>
using namespace std;
using uint = unsigned int;
using ull = unsigned long long;

bool ask(const vector<uint>& index) {
	cout << "?" << " ";
	for(uint i=0; i<index.size(); i++) {
		cout << index[i] + 1 << " ";
	}
	cout << endl;
	string ans;
	cin >> ans;
	cout << flush;

	if(ans == "-1") {
		exit(-1);
	}
	return (ans == "Red");
}

int main() {

	uint N;
	cin >> N;

	uint low = 0;
	uint high = N;
	vector<uint> id(N);
	iota(id.begin(), id.end(), 0);
	bool low_c = ask(id);
	bool high_c = !low_c;
	uint mid = (low + high) / 2;

	while(low < high) {
		mid = (low + high) / 2;
		iota(id.begin(), id.end(), mid);
		bool mid_c = ask(id);

		if (mid_c == high_c) {
			high = mid;
		} else {
			low = mid + 1;
		}
	}

	uint dpoint = low;
	// cout << "dpoint : " << dpoint << endl;
	vector<uint> ball_color(N * 2);
	ball_color[dpoint-1] = low_c;
	ball_color[dpoint+N-1] = high_c;

	// cout << "outer part 1" << endl;
	iota(id.begin(), id.end()-1, dpoint);
	for(uint i=0; i<dpoint-1; i++) {
		id[N-1] = i;
		ball_color[i] = ask(id);
	}

	// cout << "outer part 2" << endl;
	for(uint i=dpoint+N; i<2*N; i++) {
		id[N-1] = i;
		ball_color[i] = ask(id);
	}

	// cout << "inner part" << endl;
	iota(id.begin(), id.begin()+dpoint-1, 0);
	iota(id.begin()+dpoint-1, id.end()-1, dpoint+N);
	for(uint i=dpoint; i<dpoint+N-1; i++) {
		id[N-1] = i;
		ball_color[i] = ask(id);
	}

	for(uint i=0; i<N*2; i++) {
		char color = ball_color[i] ? 'R' : 'B';
		cout << color;
	}

	return 0;
}

