int main() {
    int N;
    cin >> N;
    // Find first
    deque<int> a;
    deque<int> b;
    for (int i = 0; i < N; i++) {
        a.push_back(i);
        b.push_back(N + i);
    }

    int r = ask(a);

    if (r < 0) {
        swap(a, b);
    }
    int lstpop;
    int lstadd;
    int rr;
    do {
        lstpop = a.front();
        lstadd = b.front();
        b.pop_front();
        b.push_back(lstpop);
        a.pop_front();
        a.push_back(lstadd);
        rr = ask(a) ;
    } while (rr > 0);

    res[lstadd] = -1;
    res[lstpop] = +1;

    auto c = a;

    c.pop_back(); // c is neutral

    auto d = b;
    d.pop_back();

    for (int i = 0; i < 2*N; i++) {
        if (res[i] == 0 && count(c.begin(), c.end(), i) == 0) {
            auto t = c;
            t.push_back(i);
            int r = ask(t);
            res[i] = r;
        }
    }

    for (int i = 0; i < 2*N; i++) {
        if (res[i] == 0 && count(d.begin(), d.end(), i) == 0) {
            auto t = d;
            t.push_back(i);
            int r = ask(t);
            res[i] = r;
        }
    }


    report(N);


}

