		bool now=que(a);
		if(now!=pre)r=m;
		else l=m;
		for(int i=0;i<=m;i++)swap(a[i],b[i]);
	}
	if(pre)ans[a[q]-1]=1;
	else ans[b[q]-1]=1;
	q=r;
	for(int i=0;i<n;i++){
		if(i==q)continue;
		swap(a[q],b[i]);
		if((pre==que(a))==(pre==true))ans[a[q]-1]=1;
		swap(a[q],b[i]);
	}
	for(int i=0;i<n;i++){
		if(i==q)continue;
		swap(b[q],a[i]);
		if((pre==que(b))==(pre==true))ans[b[q]-1]=1;
		swap(b[q],a[i]);
	}
	flush(cout);
	cout<<"! ";
	for(int i=0;i<n*2;i++){
		if(ans[i])cout<<'R';
		else cout<<'B';
	}
	cout<<endl;
	flush(cout);
}

