  cin >> N;
  char bl = ask(0, 1);
  char br = bl == 'R' ? 'B' : 'R';
  int l = 0;
  int r = N;
  while (l + 1 < r) {
    int mid = (l + r) / 2;
    char b = ask(mid, mid+1);
    if (b == bl) l = mid;
    else         r = mid;
  }
  char res[2*N+1];
  res[2*N] = 0;
  for (int i = 0; i < 2*N; i++) {
    if (i == l)          res[i] = bl;
    else if (i == l + N) res[i] = br;
    else if (i < l)      res[i] = ask(i, l+1);
    else if (i < l + N)  res[i] = ask(i, l+1 + N);
    else                 res[i] = ask(i, l+1);
  }
  cout << "! " << string(res) << endl;
  return 0;
}

