signed main() {
    cin >> n;
    Int red = n, blue = 0;
    bool rev = false;
    {
        vector<Int> a(n);
        REP(i, n) a[i] = i;
        rev = !query(a);
    }
    if (rev) swap(red, blue);

    auto check = [&](int mid) -> bool {
        vector<Int> a;
        REP(i, mid) a.push_back(i);
        REPI(i, n + mid, 2 * n) a.push_back(i);
        return query(a);
    };
    Int prv = -1;
    while (abs(red - blue) > 1) {
        Int mid = (red + blue) / 2;
        (check(mid) ? red : blue) = mid;
    }

    vector<Int> a;
    Int x = red - rev;
    REP(i, x) a.push_back(i);
    REPI(i, n + x + 1, 2 * n) a.push_back(i);
    vector<Int> ans(2 * n, -1);
    vector<Int> b;
    Int r_num = 0, b_num = 0;
    assert(a.size() == n - 1);
    REP(i, 2 * n) {
