const i64 MOD = 1e9 + 7;
const i64 INF = i64(1e18) + 7;

int n;

uint32_t xorshift(){
    static uint32_t x = 123456789;
    static uint32_t y = 362436069;
    static uint32_t z = 521288629;
    static uint32_t w = 88675123;
    uint32_t t;
    t = x ^ (x<<11);
    x = y; y = z; z = w;
    w ^= t ^ (t>>8) ^ (w>>19);
    return w % (2 * n);
}

template <typename T>
bool print(T& v){
    cout << "?";
    for(auto& x : v)
        cout << " " << x + 1;
    cout << endl;
    string s;
    cin >> s;
    return s == "Red";
};

signed main(){

    cin >> n;
    vector<int> ans(2 * n, -1);

    set<int> ss;
    int nex, nex2;

    while(1){
        set<int> s;
        while(s.size() < n)
            s.emplace(xorshift());
        bool res = print(s);
        if(res == false){
            set<int> t;
            for(int i = 0; i < 2 * n; ++i)
                if(s.find(i) == s.end())
                    t.emplace(i);
            s = move(t);
        }

        nex2 = *s.begin();
        while(s.find(nex2) != s.end())
            nex2 = xorshift();

        nex = *s.begin();

        // swap
        s.erase(nex);
        s.emplace(nex2);
        if(print(s) == false){
            s.emplace(nex);
            s.erase(nex2);
            ss = move(s);
            break;
        }
    }

    ans[nex] = 1;
    ans[nex2] = 0;

    set<int> s_not;
    for(auto& x : ss)
        if(x != nex)
            s_not.emplace(x);

    while(!s_not.empty()){
        int to = *s_not.begin();
        ss.erase(to);
        ss.emplace(nex2);
        bool res = print(ss);
        ss.emplace(to);
        ss.erase(nex2);
        s_not.erase(to);
        ans[to] = !res;
    }

    set<int> t_not;
    for(int i = 0; i < 2 * n; ++i)
        if(ss.find(i) == ss.end() && i != nex2)
            t_not.emplace(i);

    while(!t_not.empty()){
        int to = *t_not.begin();
        ss.emplace(to);
        ss.erase(nex);
        bool res = print(ss);
        ss.erase(to);
        ss.emplace(nex);
        t_not.erase(to);
        ans[to] = res;
    }
    cout << "! ";
    for(int i = 0; i < 2 * n; ++i){
        assert(ans[i] != -1);
        cout << (ans[i] ? "R" : "B");
    }
    cout << endl;
}

