int main() {
	int N; cin >> N;
	int p;

	{
		V<int> vec;
		rep(i, N) {
			vec.pb(i);
		}
		p = ask(vec);
	}

	int lo = 0, hi = N;
	while (hi - lo > 1) {
		int m = (lo + hi) / 2;
		V<int> vec;
		rep(i, N) vec.pb(m + i);
		int res = ask(vec);
		if (res == p) {
			lo = m;
