			vec.pb(i);
			//not [l-1,l+N-1] 
			for (int j = 0; j < l-1; ++j) {
				vec.pb(j);
			}
			for (int j = l + N; j < N * 2; ++j) {
				vec.pb(j);
			}
		}
		bool t = ask(vec);
		if (t) {
			col[i] = 1;
		} else {
			col[i] = 0;
