int main()
{
    int n;
    cin >> n;

    vector<int> v(2*n);
    for(int i=0; i<2*n; ++i)
        v[i] = i;

    vector<bool> isRed(2*n, false);
    if(!query(v, n))
        reverse(v.begin(), v.end());
    for(;;){
        swap(v[0], v[n]);
        if(!query(v, n)){
            swap(v[0], v[n]);
            isRed[v[0]] = true;
            break;
        }

        swap(v[0], v[n]);
        rotate(v.begin(), v.begin() + 1, v.begin() + n);
        rotate(v.begin() + n, v.begin() + n + 1, v.end());
    }

    for(int i=1; i<n; ++i){
        swap(v[i], v[n]);
        if(!query(v, n))
            isRed[v[n]] = true;
        swap(v[i], v[n]);
    }
    for(int i=n+1; i<2*n; ++i){
        swap(v[0], v[i]);
        if(query(v, n))
            isRed[v[0]] = true;
        swap(v[0], v[i]);
    }

    cout << "! ";
    for(int i=0; i<2*n; ++i){
        if(isRed[i])
