		swap(a[q],b[i]);
		bool now=que(a);
		if(now)ans[a[q]-1]=1;
		swap(a[q],b[i]);
	}
	for(int i=0;i<n;i++){
		if(i==q)continue;
		swap(b[q],a[i]);
		bool now=que(b);
		if(now)ans[b[q]-1]=1;
		swap(b[q],a[i]);
	}
	flush(cout);
	cout<<"! ";
	for(int i=0;i<n*2;i++){
		if(ans[i])cout<<'R';
		else cout<<'B';
	}
	cout<<endl;
	flush(cout);
}

