int mid_search(int l,int r,int val){
    if (l>=r-1) {return r;}
    int md=(l+r)>>1;
    vector<int> tmp;
    tmp.clear();
    for (int i=1;i<=n;++i){
        tmp.push_back(i+n*(i<=md));
    }
    if (check(tmp)!=val) return mid_search(l,md,val);
    else return mid_search(md,r,val);
}

int main(){
    cin>>n;
    vector<int> tmp;
    tmp.clear();
    for (int i=1;i<=n;++i) tmp.push_back(i);
    int u=check(tmp);
    int k=mid_search(0,n,u);
    int ans[207];
    for (int i=1;i<=2*n;++i){
        if (i<k||i>=n+k){
            vector<int> tmp;
            tmp.clear();
            for (int i=1;i<=n;++i){
                if (i==k) continue;
                tmp.push_back(i+n*(i<=k));
            }
            tmp.push_back(i);
            ans[i]=query(tmp);
        }
        else{
            vector<int> tmp;
            tmp.clear();
            for (int i=1;i<=n;++i){
                if (i==k) continue;
                tmp.push_back(i+n*(i>k));
            }
            tmp.push_back(i);
            ans[i]=query(tmp);
        }
    }
    cout<<"! ";
    for (int i=1;i<=2*n;++i){
        if (ans[i]) cout<<"R";
        else cout<<"B";
    }
    return 0; 
}

