int main() {

    ll n; cin >> n;

    if (n == 1) {
        cout << "? 1" << endl;
        string s; cin >> s;
        cout << (s[0] == 'R' ? "! RB" : "! BR") << endl;
        return 0;
    }

    string ans(n * 2, ' ');

    ll a = 1;   string ar = ask_seq(n, 1);
    ll b = n+1; string br = ar[0] == 'R' ? "Blue" : "Red";
    while (b - a > 1) {
        ll c = (b + a) / 2;
        string cr = ask_seq(n, c);
        (cr == ar ? a : b) = c;
    }
    ans[a-1]   = ar[0];
    ans[a+n-1] = br[0];

    vector<ll> eqset(n, -1);
    RANGE(i, b, b+n-2) eqset[i-b] = (i-1) % (n*2) + 1;

    RANGE(i, 0, n*2-1) {
        eqset.back() = -1;
        if (i == a-1 || i == a+n-1) continue;
        if (find(ALL_OF(eqset), i+1) == eqset.end()) {
            eqset.back() = i+1;
            ans[i] = ask(eqset)[0];
        }
    }

    vector<ll> reds, blues, neqset;
    eqset.back() = -1;
    RANGE(i, 1, n*2) {
        if (find(ALL_OF(eqset), i) >= eqset.end() - 1) {
            (ans[i-1] == 'R' ? reds : blues).push_back(i);
        }
    }
    REP(i, n/2) {
        neqset.push_back(reds[i]);
        neqset.push_back(blues[i]);
    }
    neqset.push_back(-1);
    DUMPALL(neqset);

    REP(j, n-1) {
        ll i = eqset[j];
        neqset.back() = i;
        ans[i-1] = ask(neqset)[0];
    }

    cout << "! " << ans << endl;

}

