  for (int i = 0; i < l - n; i++) {
    vector<int> q2 = query;
    q2.push_back(rest[i]);
    int c = quest(q2);
    ok.emplace_back(rest[i], c);
    use[rest[i] - 1] = true;
  }
  for (int i = l + 1; i < rest.size(); i++) {
    vector<int> q2 = query;
    q2.push_back(rest[i]);
    int c = quest(q2);
    ok.emplace_back(rest[i], c);
    use[rest[i] - 1] = true;
  }
  ok.emplace_back(rest[l], 1 - c);
  ok.emplace_back(rest[l - n], c);
  use[rest[l] - 1] = true;
  use[rest[l - n] - 1] = true;
  rest.erase(rest.begin() + l);
  rest.erase(rest.begin() + l - n);
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cin >> n;
  use.resize(2 * n);
  for (int i = 0; i < 2 * n; i++) rest.push_back(i + 1);
  while (ok.size() < n / 2 * 2) {
    solve();
  }
  vector<int> query;
  int c[2] = {0};
  for (int i = 0; i < ok.size(); i++) {
    if (c[ok[i].second] < n / 2) {
      query.push_back(ok[i].first);
      c[ok[i].second]++;
    }
  }
  for (int i = 0; i < 2 * n; i++) {
    if (use[i]) continue;
    vector<int> q2 = query;
    q2.push_back(i + 1);
    int c = quest(q2);
    ok.emplace_back(i + 1, c);
  }
  vector<char> ans(2 * n, '0');
  for (int i = 0; i < ok.size(); i++) {
    ans[ok[i].first - 1] = ok[i].second ? 'R' : 'B';
  }
  int rcnt = 0;
  for (int i = 0; i < n; i++) if (ans[i] == 'R') rcnt++;
  if (rcnt != n) {
    exit(1);
  }
  cout << "! ";
  for (int i = 0; i < 2 * n; i++) cout << ans[i];
  cout << endl;

  return 0;
}

