  ans[ok+N] = conq[ng];
  vector<ll> same;
  for(ll i = ok + 1; i < ok + N; i++){
    same.pb(i);
  }
  rep(i, N){
    ll s = (ok + N + i) % (2 * N);
    if(ans[s] != 0) continue;
    ans[s] = ques(same, s);
  }
  vector<ll> blue, red;
  rep(i, 2 * N){
    if(ans[i] == 0) continue;
    if(ans[i] == 1) blue.pb(i);
    else red.pb(i);
  }
  same.resize(0);
  rep(i, N/2){
    same.pb(red[i]);
    same.pb(blue[i]);
  }
  rep(i, 2 * N){
    if(ans[i] != 0) continue;
    ans[i] = ques(same, i);
  }
  cout << "! ";
  rep(i, 2 * N){
    if(ans[i] == 1) cout << "B";
    else cout << "R";
  }
  cout << endl;

}


