struct InteractiveProblem {
	const int N;
	const int MAX_Q = 210;
	int q;
	vector<int> is_red;
	bool to_server;
	InteractiveProblem(int n, bool to_server) :N(n), q(0), is_red(2 * N), to_server(to_server) {
		random_device rd;
		mt19937 mt(rd());
		set<int> st;
		while (st.size() < N)
			st.emplace(mt() % (2 * N));
		for (auto i : st) {
			is_red[i] = true;
		}
	}
	bool question(vector<int> A) {
		if (to_server) {
			cout << "?";
			rep(i, 0, A.size())
				cout << " " << A[i] + 1;
			cout << endl;
			string res; cin >> res;
			assert(res != "-1");
			return res == "Red";
		}
		else {
			assert(q < MAX_Q);
			q++;

			int cnt = 0;
			for (auto i : A) {
				if (is_red[i])
					cnt++;
			}
			dump(cnt);
			return cnt >= N / 2 + 1;
		}
	}
	void judge(vector<int> ans) {
		if (to_server)return;
		int correct = 0;
		rep(i, 0, 2 * N) {
			if (ans[i] == -1)continue;
			dump(ans[i] == 1, is_red[i]);
			if (ans[i] == is_red[i])correct++;
		}
		dump(correct);
	}
};

void sim() {
	int N = 99;
	InteractiveProblem IP(N, false);

	auto f = [&](int x) {
		dump(x);
		vector<int> A(N);
		rep(i, 0, N) {
			A[i] = (i + x) % (2 * N);
		}
		bool ret = IP.question(A);
		dump(ret);
		return ret;
	};
	auto bisectionMethod = [&](int ng, int ok) {
		while (ng + 1 < ok) {
			int m = (ng + ok) / 2;
			if (f(m))
				ok = m;
			else
				ng = m;
		}
		return ok;
	};

	vector<int> A(N);
	iota(all(A), 0);
	bool res = IP.question(A);
	dump(res);
	int l = 0, r = N;
	if (res) {
		l = N, r = 2 * N;
	}
	dump(l, r);
	auto x = bisectionMethod(l, r);
	dump(x);
	dump(f(x - 1));
	dump(f(x));

	int l1 = x, r1 = x + N - 1;

	vector<int> a(2 * N, -1);

	rep(i, 0, N - 1) {
		A[i] = (l1 + i) % (2 * N);
	}
	rep(i, 0, N + 2) {
		int x = (r1 + i) % (2 * N);
		A.back() = x;
		a[x] = IP.question(A);
	}
	dump(a);

	A.clear();
	int red = 0, blue = 0;
	rep(i, 0, 2 * N) {
		if (a[i] == -1)continue;
		if (red < N / 2 && a[i]) {
			A.push_back(i); red++;
		}
		if (blue < N / 2 && !a[i]) {
			A.push_back(i); blue++;
		}
	}
	IP.judge(a);

	rep(i, 0, 2 * N) {
		if (a[i] != -1)continue;
		A.back() = i;
		a[i] = IP.question(A);
	}
	dump(a);

	IP.judge(a);
}

