	auto bisectionMethod = [&](int ng, int ok) {
		while (ng + 1 < ok) {
			int m = (ng + ok) / 2;
			if (f(m))
				ok = m;
			else
				ng = m;
		}
		return ok;
	};

	vector<int> A(N);
	iota(all(A), 0);
	bool res = IP.question(A);
	dump(res);
	int l = 0, r = N;
	if (res) {
		l = N, r = 2 * N;
	}
	dump(l, r);
	auto x = bisectionMethod(l, r);
	dump(x);
	dump(f(x - 1));
	dump(f(x));

	int l1 = x, r1 = x + N - 1;

	vector<int> a(2 * N, -1);

	rep(i, 0, N - 1) {
		A[i] = (l1 + i) % (2 * N);
	}
	rep(i, 0, N + 2) {
		int x = (r1 + i) % (2 * N);
		A.back() = x;
		a[x] = IP.question(A);
	}
	dump(a);

	A.clear();
	int red = 0, blue = 0;
	rep(i, 0, 2 * N) {
		if (a[i] == -1)continue;
		if (red < N / 2 && a[i]) {
			A.push_back(i); red++;
		}
		if (blue < N / 2 && !a[i]) {
			A.push_back(i); blue++;
		}
	}
	IP.judge(a);
	A.push_back(-1);

	rep(i, 0, 2 * N) {
		if (a[i] != -1)continue;
		A.back() = i;
		a[i] = IP.question(A);
	}
	dump(a);

	IP.judge(a);

	cout << "! ";
	rep(i, 0, 2 * N) {
		cout << (a[i] == 1 ? "R" : "B");
	}
	cout << endl;

	return 0;
}

