bool query(ll a, ll b, ll c = 0, ll d = 0, ll e = 0, ll f = 0){
  vector<ll> v(0);
  FOR(i, a, b){
    v.pb(i);
  }
  FOR(i, c, d){
    v.pb(i);
  }
  FOR(i, e, f){
    v.pb(i);
  }
  return query(v);
}

int main(){

  ll n = in();

  bool base = query(0, n);

  ll lb = 0, ub = n;
  while(ub - lb > 1){
    ll md = (lb + ub) / 2;
    if(query(0, n - md, n, n + md) != base){
      ub = md;
    } else {
      lb = md;
    }
  }

  vector<bool> ans(2 * n);
  FOR(i, n-ub, n){
    ans[i] = query(0, n-ub, n, n+lb, i, i+1);
  }
  FOR(i, n+lb, 2 * n){
    ans[i] = query(0, n-ub, n, n+lb, i, i+1);
  }
  FOR(i, 0, n-ub){
    ans[i] = query(n-lb, n, n+ub, 2*n, i, i+1);
  }
  FOR(i, n, n +lb){
    ans[i] = query(n-lb, n, n+ub, 2*n, i, i+1);
  }

  printf("! ");
  REP(i, 2*n){
    if(ans[i]){
      printf("R");
    } else {
      printf("B");
    }
  }
  printf("\n");

  return 0;
}

