inline int read()
{
    int x=0,f=1;char ch=getchar();
    while(ch<'0' || ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0' && ch<='9')x=x*10+ch-'0',ch=getchar();
    return x*f;
}
int stack[20];
inline void write(int x)
{
	if(x<0){putchar('-');x=-x;}
    if(!x){putchar('0');return;}
    int top=0;
    while(x)stack[++top]=x%10,x/=10;
    while(top)putchar(stack[top--]+'0');
}
inline void pr1(int x){write(x),putchar(' ');}
inline void pr2(int x){write(x),puts("");}
char ss[5],cnt[210];
int n,id[110];
inline int getid(int st)
{
	if(id[st])return id[st];
	printf("?");
	for(int i=0;i<n;i++)printf(" %d",st+i);puts("");
	fflush(stdout);
	scanf("%s",ss+1);
	if(ss[1]=='R')id[st]=1;
	else id[st]=2;
	return id[st];
}
int top,sta[110],uf;
inline void solve(int p,int pd)
{
	printf("? %d",p);
	if(pd==1)for(int i=1;i<n;i++)printf(" %d",uf+i);
	else for(int i=1;i<=top;i++)printf(" %d",sta[i]);puts("");
	fflush(stdout);
	scanf("%s",ss+1);
	cnt[p]=ss[1];
}
int main()
{
    //freopen("a.in","r",stdin);
	//freopen("a.out","w",stdout);
	n=read();
	getid(1),id[n+1]=3-id[1];
	if(n==1)
	{
		if(id[1]==1)printf("! RB\n");
		else printf("! BR\n");
	}
	else
	{
		int l=1,r=n;
		while(l<=r)
		{
			int mid=l+r>>1;
			if(getid(mid)!=id[1])r=mid-1;
			else
			{
				if(id[1]==getid(mid+1))l=mid+1;
				else {uf=mid;break;}
			}
		}
		int nr=(n-1)/2,nb=nr;
		for(int i=1;i<=uf;i++)
		{
			solve(i,1);
			if(cnt[i]=='R' && nr)sta[++top]=i,nr--;
			if(cnt[i]=='B' && nb)sta[++top]=i,nb--;
		}
		for(int i=uf+n;i<=2*n;i++)
		{
			solve(i,1);
			if(cnt[i]=='R' && nr)sta[++top]=i,nr--;
			if(cnt[i]=='B' && nb)sta[++top]=i,nb--;
		}
		for(int i=uf+1;i<uf+n;i++)solve(i,2);
		printf("! ");
		for(int i=1;i<=2*n;i++)printf("%c",cnt[i]);
		puts("");
	}fflush(stdout);
	return 0;
}

