bool ask(vector<int> A){
  sort(A.begin(),A.end());
  Assert(unique(A.begin(),A.end())==A.end());
  cout<<"?";
  for(auto &I:A){
    Assert(I>=0 && I<2*N);
    cout<<" "<<I+1;
  }
  cout<<endl;
  string ret;
  cin>>ret;
  Assert(ret!="-1");
  return ret=="Red";
}

