    bool ret=ask_line(i);
    if(ret!=ls){idx=i; break;}
  }
  //Assert(idx!=-1);
  vector<bool> ans(2*N,false);
  ans[idx-1]=ls;
  ans[idx+N-1]=!ls;
  for(int i=0;i<2*N;i++){
