void solve() {
    int n;
    cin >> n;

    vector<char> ans(n * 2 + 1, '*');

    string q;
    function<bool(int)> ask = [&](int m) {
        cout << "? ";
        FOR(i, m, m + n) cout << i << (i == m + n - 1 ? EOL : ' ');
        cout << flush;
        cin >> q;
        return "Blue" == q;
    };

    int left = 0;
    int right = n + 1;
    while (abs(right - left) > 1) {
        int m = (left + right) / 2;
        if (ask(m)) {
            left = m;
        } else {
            right = m;
        }
    }

    cout << "? ";
    FOR(i, left, left + n) cout << i << (i == left + n - 1 ? EOL : ' ');
    cout << flush;
    cin >> q;

    if (q == "Red") {
        ans[left] = 'R';
    } else {
        ans[left] = 'B';
    }

    FOR(i, 1, left) {
        cout << "? " << i << " ";
        FOR(j, left + 1, left + n) cout << j << (j == left + n - 1 ? EOL : ' ');
        cout << flush;
        cin >> q;
        if (q == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }

    FOR(i, left + n, n * 2 + 1) {
        cout << "? " << i << " ";
        FOR(j, left + 1, left + n) cout << j << (j == left + n - 1 ? EOL : ' ');
        cout << flush;
        cin >> q;
        if (q == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }

    FOR(i, left + 1, left + n) {
        cout << "? " << i << " ";
        int c = 1;
        FOR(j, 1, left) {
            c++;
            cout << j << (c == n ? EOL : ' ');
        }
        FOR(j, left + n + 1, n * 2 + 1) {
            c++;
            cout << j << (c == n ? EOL : ' ');
        }
        cout << flush;
        cin >> q;
        if (q == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }
    cout << "! ";
    REP1(i, n * 2) cout << ans[i];
    cout << EOL << flush;
}

