	cin >> n;
	vector<int> a(2 * n, -1);
	srand(time(NULL));
	vector<int> p(2 * n, 0);
	for (int i = 0; i < 2 * n; ++i) p[i] = i;
	vector<int> b;
	while (true) {
		random_shuffle(all(p));
		string ans1 = query(p, p[n - 1]);
		string ans2 = query(p, p[n]);
		if (ans1 != ans2) {
			for (int i = 0; i + 1 < n; ++i) {
	            b.pb(p[i]);	
				a[p[i]] = 2;
     		}
			break;
		}
	}
	int sum0 = 0;
	int sum1 = 0;

	for (int i = 0; i < 2 * n; ++i) {
	    if (a[i] != -1) {
		    continue;
		}
		string ans = query(b, i);
		if (ans == "Red") {
		   a[i] = 1;
		   ++sum1;
		} else {
		   a[i] = 0;
		   ++sum0;
		}
	}
	vector<int> d;
	for (int i = 0; i < 2 * n; ++i) {
	   if (d.size() == (n - 1) / 2) break;
	   if (a[i] == 0) d.pb(i);
	}
	for (int i = 0; i < 2 * n; ++i) {
	   if (d.size() == (n - 1)) break;
	   if (a[i] == 1) d.pb(i);
	}
	for (int i = 0; i < 2 * n; ++i) {
	    if (a[i] != 2) {
		    continue;
		}
		string ans = query(d, i);
		if (ans == "Red") {
		   a[i] = 1;
		   ++sum1;
		} else {
		   a[i] = 0;
		   ++sum0;
		}
		if (sum0 == n) {
		    for (int j = 0; j < 2 * n; ++j) {
			    if (a[j] == -1 ||  a[j] == 2) a[j] = 1;
			}
			break;
		}
		if (sum1 == n) {
		    for (int j = 0; j < 2 * n; ++j) {
			    if (a[j] == -1 ||   a[j] == 2) a[j] = 0;
			}
			break;
		}
	}

	string ans = "! ";
	for (int i = 0; i < 2 * n; ++i) {
	   if (a[i] == 1) ans += 'R';
	   if (a[i] == 0) ans += 'B';
	}
	cout << ans << endl;	
    return 0;
}

