#include <bits/stdc++.h>
using namespace std;

int ask[205], ans[205], n, n2;

int qq() {
  cout << "?";
  for(int i = 0 ; i < n ; ++i) cout << ' ' << ask[i] + 1;
  cout << endl;
  string s; cin >> s;
  return s[0] == 'R' ? 1 : -1;
}
int q(int x) {
  for(int i = x, j = 0 ; j < n ; i = (i + 1) % n2, j++) {
    ask[j] = i;
  }
  return qq();
}

void init() {
  cin >> n;
  n2 = n * 2;
}
void solve() {
  int pre = q(0), tt;
  for(int i = 1 ; i < n2 ; ++i) {
    if(q(i) != pre) {
      tt = i; break;
    }
  }
  for(int i = 0 ; i < n - 1 ; ++i) ask[i] = tt + i;
  for(int i = 0 ; i < n2 ; ++i) {
    if((i >= tt && i - tt <= n - 1) || (i < tt && tt - i >= n + 1)) continue;
    ask[n - 1] = i;
    ans[i] = qq();
  }
  int ca = 0, cb = 0, k = 0;
  for(int i = 0 ; i < n2 ; ++i) {
    if(ans[i] == 1 && ca < (n - 1) / 2) ask[k++] = i, ca++;
    if(ans[i] == -1 && cb < (n - 1) / 2) ask[k++] = i, cb++;
  }
  assert(k == n - 1);
  for(int i = tt, j = 0 ; j < n - 1 ; i = (i + 1) % n2, j++) {
    ask[n - 1] = i;
    ans[i] = qq();
  }
  cout << "! ";
  for(int i = 0 ; i < n2 ; ++i) cout << (ans[i] == 1 ? 'R' : 'B');
  cout << endl;
}

int main() {
  init();
  solve();
}

