int n;
int query_range(int start) {
  vector<int> q;
  for (int i = 0; i < n; i++) q.push_back(start + i);
  return query(q);
}

int main() {
  scanf("%d", &n);
  vector<int> result(2 * n, -1);
  int last = -1;
  vector<int> base;
  vector<int> base2;
  {
    int lcolor = query_range(0), lpos = 0;
    int rcolor = 1 - lcolor, rpos = n;
    int low = 1, high = n - 1;
    while (low <= high) {
      int mid = (low + high) / 2;
      int mcolor = query_range(mid);
      if (mcolor == lcolor) {
        lpos = mid;
        low = mid + 1;
      } else {
        rpos = mid;
        high = mid - 1;
      }
    }

    int L = lpos, R = rpos + n - 1;
    result[L] = lcolor;
    result[R] = rcolor;
    for (int j = 0; j < 2 * n; j++) {
      if (j == L || j == R) continue;
      if (j > L && j < R) base.push_back(j);
      else base2.push_back(j);
    }
  }
  for (int i = 0; i < 2 * n; i++) {
    if (result[i] != -1) continue;
    vector<int> qset;
    if (binary_search(base.begin(), base.end(), i)) {
      qset = base2;
      qset.push_back(i);
      result[i] = query(qset);
