void solve(){
  cin >> N;
  ll ok = 0, ng = N;
  vector<ll> conq(N+1, 0);
  while(ng - ok > 1){
    ll mid = (ok + ng) / 2;
    if(conq[ok] == 0){
      conq[ok] = question(ok);
    }
    if(conq[ng] == 0){
      conq[ng] = question(ng);
    }
    if(conq[mid] == 0){
      conq[mid] = question(mid);
    }
    if(conq[ok] == conq[mid]){
      ok = mid;
    }else{
      ng = mid;
    }
  }
  vector<ll> ans(2 * N, 0);
  ans[ok] = conq[ok];
  ans[ok+N] = conq[ng];
  vector<ll> same;
  for(ll i = ok + 1; i < ok + N; i++){
    same.pb(i);
  }
  rep(i, N){
    ll s = (ok + N + i) % (2 * N);
    if(ans[s] != 0) continue;
    ans[s] = ques(same, s);
  }
  vector<ll> blue, red;
  rep(i, 2 * N){
    if(ans[i] == 0) continue;
    if(ans[i] == 1) blue.pb(i);
    else red.pb(i);
  }
  same.resize(0);
  rep(i, N/2){
    same.pb(red[i]);
    same.pb(blue[i]);
  }
  rep(i, 2 * N){
    if(ans[i] != 0) continue;
    ans[i] = ques(same, i);
  }
  cout << "! ";
  rep(i, 2 * N){
    if(ans[i] == 1) cout << "B";
    else cout << "R";
  }
  cout << endl;

}


