auto make_v(size_t a,Ts... ts){
  return std::vector<decltype(make_v<T>(ts...))>(a,make_v<T>(ts...));
}

bool query(std::vector<int> && q) {
	cout << "? ";
	for(auto v: q) cout << v << " ";
	cout << endl;

	std::string t; cin >> t;
	if(t == "-1") std::abort();
	return (t == "Red");
}

std::vector<int> get_segment(int s, int len, int i, int j) {
	std::vector<int> q;
	for(int k = s; k < s + len; k++) {
		if(i != j and k == i) continue;

		q.push_back(k + 1);
	}
	if(i != j) q.push_back(j + 1);
	return q;
}

char c(bool f) {
	return (f ? 'R' : 'B');
}

int main() {
	int n; scanf("%d", &n);

	bool now = query(get_segment(0, n, 0, 0));

	int L = 0, R = n; // [L, R)
	while(std::abs(L - R)) {
		int mid = (L + R) >> 1;

		auto ret = query(get_segment(mid + 1, n, 0, 0));
		if(now == ret) L = mid;
		else R = mid;
	}

	now = !now;
	int bound = L;
	// [bound, bound + n) != [bound + 1, bound + n + 1)
	// [bound, bound + n) == now

	std::string ans(2 * n, '?');
	for(int i = 0; i < 2 * n; i++) {
		if(bound + 1 <= i and i < bound + n) {
			auto ret = query(get_segment(bound + 1, n, i, bound));

			ans[i] = (now == ret ? c(!now) : c(now));
		} else {
			auto ret = query(get_segment(bound + 1, n, bound + n, i));

			ans[i] = (now == ret ? c(now) : c(!now));
		}
	}

	cout << "! " << ans << endl;
	return 0;
}

