	{
		std::vector<int> tmp(N);
		std::iota(tmp.begin(), tmp.end(), 0);
		begin_red = query(tmp);
	}
	int change{1};
	for (; change <= N; change++)
	{
		std::vector<int> tmp(N);
		std::iota(tmp.begin(), tmp.end(), change);
		if (query(tmp) != begin_red) break;
	}
	std::vector<int> key(N);
	std::iota(key.begin(), key.end() - 1, change);
	std::string ans(2 * N, '$');
	for (int i{}; i < 2 * N; i++)
	{
		if (change <= i && i < change + N) continue;
		key.back() = i;
		if (query(key)) ans[i] = 'R';
		else ans[i] = 'B';
	}
	std::iota(key.begin(), key.begin() + change - 1, 0);
	std::iota(key.begin() + change - 1, key.end() - 1, change + N);
	for (int i{change}; i < change + N; i++)
	{
		key.back() = i;
		if (query(key)) ans[i] = 'R';
		else ans[i] = 'B';
	}

