int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int N; cin >> N;

  vector<char> ans(2*N, 0);
  set<int> exacts;
  bool prev_rb;
  int back;
  auto prev_i = 0;
  int i = 1;
  auto request = [&](int f) {
    auto reqlist = exacts;
    int i = f;
    auto back = i;
    while (reqlist.size() < N) {
      if (exacts.count(i) > 0) {
        i = (i+1)%(2*N);
        continue;
      }
      reqlist.insert(i);
      if (ans[i] != 0)
        back = i;
      i = (i+1)%(2*N);
    }
    cout << "? ";
    for (auto r : reqlist)
      cout << r+1 << " ";
    cout << endl;

    std::string s; cin>>s;
    return make_pair(s == "Red", back);
  };
  auto p = request(0);
  prev_rb = p.first;
  int cnt = 0;
  bool init = true;
  while (cnt < 2*N) {
    if (ans[i] != 0) {
      i = (i+1)%(2*N);
      continue;
    }
    auto p = request(i);
    auto rb = p.first;
    auto back = p.second;
    if (init) {
      init = false;
    } else if (rb != prev_rb) {
      if (exacts.size() <= N-3) {
        exacts.insert(prev_i);
        exacts.insert(back);
      }
      ans[prev_i] = rb ? 'B' : 'R';
      ans[back] = rb ? 'R' : 'B';
      if (i != back) {
        auto p = request(i);
        rb = p.first;
        back = p.second;
      } else {
        init = true;
      }
      cnt += 2;
    }
    prev_rb = rb;
    prev_i = i;
    i = (i+1)%(2*N);
  }
  cout << "! ";
  for (auto c : ans)
    cout << c;
  cout << endl;

  return 0;
}

