class Task{
public:
    void solve(istream& in, ostream& out){
        int N;
        int pre = -1;
        in>>N;
        vc<string> ans(2*N, "*"), f = {"Red", "Blue"};
        vc<int> rs, bs, vec;
        FOR(l, 1, N+2){
            out<<'?';
            REP(i, N) out<<' '<<l+i;
            out<<endl;
            string res;
            in>>res;
            if(pre==-1){
                if(res=="Red") pre = 0;
                else pre = 1;
            }else if(res!=f[pre]){
                ans[l-2] = f[pre];
                ans[l+N-2] = f[pre^1];
                // [l, l+N-1]
                FOR(r, l+N, 2*N+1){
                    out<<'?';
                    REP(i, N-1) out<<' '<<l+i;
                    out<<' '<<r;
                    out<<endl;
                    string now;
                    in>>now;
                    if(now==f[pre]) ans[r-1] = f[pre];
                    else ans[r-1] = f[pre^1];
                }
                for(int ll=l-2;0<ll;--ll){
                    out<<'?';
                    REP(i, N-1) out<<' '<<l+i;
                    out<<' '<<ll;
                    out<<endl;
                    string now;
                    in>>now;
                    if(now==f[pre]) ans[ll-1] = f[pre];
                    else ans[ll-1] = f[pre^1];
                }
                REP(i, 2*N){
                    if(ans[i]=="Red") rs.pb(i+1);
                    else if(ans[i]=="Blue") bs.pb(i+1);
                    else vec.pb(i+1);
                }
                REP(i, LEN(vec)){
                    out<<'?';
                    REP(j, N/2) out<<' '<<rs[j];
                    REP(j, N/2) out<<' '<<bs[j];
                    out<<' '<<vec[i];
                    out<<endl;
                    string now;
                    in>>now;
                    if(now=="Red") ans[vec[i]-1] = "Red";
                    else ans[vec[i]-1] = "Blue";
                }
                out<<"! ";
                REP(i, 2*N) out<<ans[i][0];
                out<<endl;
                return;
            }
        }
    }
};

int main(){
    istream& in(cin);
    ostream& out(cout);
    ios_base::sync_with_stdio(false);
    in.tie(nullptr), out.tie(nullptr);
    Task solver;
    solver.solve(in, out);
    return 0;
}

