    rep(i,0,n)printf("%d ",a[i]);
    puts(""); fflush(stdout);
    string s; cin>>s;
    return s[0]=='R';
}

int main(){
    scanf("%d",&n);
    rep(i,0,2*n)ans+='?';
    vector<int> a(n); iota(ALL(a),1);
    bool f=ask(a); int lb=1,rb=n+1;
    while(rb-lb>1){
        int mid=(lb+rb)/2; iota(ALL(a),mid);
        if(ask(a)!=f)rb=mid; else lb=mid;
    }
    vector<int> b(n-1); iota(ALL(b),rb);
    rep(i,1,2*n+1){
        if(i<b[0]||i>b.back()){
            vector<int> c=b; c.push_back(i);
            if(ask(c))ans[i-1]='R';
            else ans[i-1]='B';
        }
    }
    int rcnt=0,bcnt=0; a.clear();
    rep(i,0,2*n){
        if(ans[i]=='R'&&rcnt<n/2){
            a.push_back(i+1); rcnt++;
        }
        if(ans[i]=='B'&&bcnt<n/2){
            a.push_back(i+1); bcnt++;
        }
    }
    rep(i,rb,rb+n-1){
        vector<int> c=a; c.push_back(i+1);
        if(ask(c))ans[i]='R'; else ans[i]='B';
    }
    cout<<"! "<<ans<<endl; fflush(stdout);
    return 0;
}

