void sub(int n,int l){
	int r=l+n-1;

	string ans(n*2,'?');
	rep(i,n*2){
		if(i<l||r<=i){
			vi a{i};
			rng(j,l,r)
				a.pb(j);
			ans[i]=askraw(a);
