using namespace std;

typedef long long ll;

int n;

string Ask(const vector<int> a) {
  string s = "?";
  for (int x : a) {
    s += " " + to_string(x);
  }
  cout << s << endl;
  cout.flush();
  string result;
  cin >> result;
  return result;
}

string GetColor(int p) {
  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    a[i] = p + i + 1;
  }
  return Ask(a);
}

string Other(string color) {
  if (color == "Red") return "Blue";
  return "Red";
}

string AskColor(int left, int what, int to) {
  vector<int> a;
  for (int i = 0; i < n; ++i) {
    if (left + i == what) continue;
    a.push_back(left + i + 1);
  }
  a.push_back(to + 1);
  return Ask(a);
}

int main()
{
  cin >> n;

  string leftColor = GetColor(0);

  int l = 0; int r = n;
  while (r - l > 1) {
    int m = (l + r) / 2;
    string curColor = GetColor(m);
    if (curColor != leftColor) {
      r = m;
    } else {
      l = m;
    }
  }

  string result(2 * n, ' ');
  result[l] = leftColor[0];
  r = l + n;
  result[r] = Other(leftColor)[0];

  for (int i = 0; i < 2 * n; ++i) {
    if (i == l || i == r) continue;
    string curColor;
    if (i < l || i > r) {
      curColor = AskColor(l, l, i);
    } else {
      curColor = Other(AskColor(l, i, r));
    }
    result[i] = curColor[0];
  }

  cout << "! " + result << endl;
  cout.flush();

  return 0;
}

