			else {
				if (ans[i] == '#') tot++;
				ans[i] = 'B';
				if (ans[(i + N) % (2 * N)] == '#') tot++;
				ans[(i + N) % (2 * N)] = 'R';
			}
			if (N - 1 < tot) return;
		}
		pre = res;
	}
