typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)

ll binary_search(
    ll lo, ll hi, function<bool(ll)> is_ok,
    bool maximize
){
    while(lo < hi){
        if(maximize){
            const ll mid = (lo + hi + 1) / 2;
            if(is_ok(mid)){
                lo = mid;
            }else{
                hi = mid - 1;
            }
        }else{
            const ll mid = (lo + hi) / 2;
            if(is_ok(mid)){
                hi = mid;
            }else{
                lo = mid + 1;
            }
        }
    }
    return lo;
}


ll ask(vector<ll>& a){
    cout << "? ";
    REP(i, a.size()){
        cout << a.at(i) + 1;
        if(i + 1 < a.size()){
            cout << ' ';
        }
    }
    cout << endl << flush;
    string s;
    cin >> s;
    if(s == "Red"){
        return 0;
    }else if(s == "Blue"){
        return 1;
    }else{
        exit(0);
    }
}

int main(){
    ll n;
    cin >> n;

    vector<ll> tmp(n);
    REP(i, n){ tmp.at(i) = i; }
    ll col0 = ask(tmp);

    ll pos = binary_search(
        1, n,
        [&](ll mid) -> bool {
            vector<ll> tmp(n);
            REP(i, n){ tmp.at(i) = mid + i; }
            ll col = ask(tmp);
            return col != col0;
        },
        false
    );

    vector<ll> ans(2 * n, -1);
    ans.at(pos - 1) = col0;
    ans.at(pos + n - 1) = 1 - col0;

    vector<ll> tmp1, tmp2;
    REP(i, 2 * n){
        if(i == pos - 1 || i == pos + n - 1){
            continue;
        }else if(pos - 1 < i && i < pos + n - 1){
            tmp1.push_back(i);
        }else{
            tmp2.push_back(i);
        }
    }
    tmp1.push_back(-1);
    tmp2.push_back(-1);

    REP(i, 2 * n){
        if(ans.at(i) != -1){
            continue;
        }
        if(i < pos - 1 || pos + n - 1 < i){
            tmp1.back() = i;
            ans.at(i) = ask(tmp1);
        }else{
            tmp2.back() = i;
            ans.at(i) = ask(tmp2);
        }
    }

    cout << "! ";
    REP(i, 2 * n){
        if(ans.at(i) == 0){
            cout << 'R';
        }else{
            cout << 'B';
        }
    }
    cout << endl << flush;

    return 0;
}

