int main(int argc, char *argv[]) {
	int n;
	cin >> n;
	vector<int> res(2 * n, 0);
	int last = 0;
	int now = 0;
	int start = 0;
	while (last * now >= 0) {
		last = now;
		vector<int> q;
		for (int i = 0; i < n; i++) {
			q.push_back((start + i) % (2 * n));
		}
		now = f(q);
		start++;
	}
	start--;
	start--;
	if (start < 0)
		start += n + n;
	int end = (start + n) % (2 * n);
	if (last == 1) {
		res[start] = 1;
		res[end] = -1;
	}
	else {
		res[start] = -1;
		res[end] = 1;
	}

	for (int i = (start + 1) % (2 * n); i != end; i = (i + 1) % (2 * n)) {
		vector<int> q;
		for (int j = (start + 1) % (2 * n); j != end; j = (j + 1) % (2 * n)) {
			if (j == i) continue;
			q.push_back(j);
		}
		q.push_back(start);
		q.push_back(end);
		now = f(q);
		if (now == 1)
			res[i] = -1;
		else
			res[i] = 1;
	}
	vector<int> q;
	for (int i = (start + 1) % (2 * n); i != end; i = (i + 1) % (2 * n)) {
		q.push_back(i);
	}
	for (int i = (end + 1) % (2 * n); i != start; i = (i + 1) % (2 * n)) {
		q.push_back(i);
		now = f(q);
		if (now == 1)
			res[i] = 1;
		else
			res[i] = -1;
		q.pop_back();
	}
	cout << "! ";
	for (auto r : res) {
		if (r == 1) 
			cout << "R";
		else
			cout << "B";
	}
	cout << endl << flush;
}

