int main(){

  int n; cin >> n;
  cout << "? ";
  string color;
  for(int i = 0; i < n; i++) {
    if(i != n - 1) cout << i + 1 << " ";
    else cout << i + 1 << endl;
  }

  cin >> color;

  // i まで残す
  set<int> st;
  for(int i = 0; i < n; i++) {
    cout << "? ";
    for(int j = 0; j < n; j++) {
      int out;
      if(j <= i) out = j + 1;
      else out = j + 1 + n;
      if(j == n - 1) cout << out << endl;
      else cout << out << " ";
    }
    string nxt; cin >> nxt;

    if(nxt == color) {
      for(int k = 0; k < i; k++) st.insert(k);
      for(int k = i + 1; k < n; k++) st.insert(k + n);
      break;
    }
  }

  vector<char> ans(2*n, 'x');

  for(int i = 0; i < 2 * n; i++) {
    if(st.find(i) != st.end()) {
      cout << "? ";
      for(auto hoge : st) cout << hoge + 1 << " ";
      cout << i + 1 << endl;
      string c; cin >> c;
      ans[i] = c[0];
    }
  }

  set<int> st2;
  int r = 0;
  int b = 0;
  for(int i = 0; i < 2 * n; i++) {
    if(ans[i] == 'x') continue;
    if(ans[i] == 'R') {
      if(r != (n - 1) / 2) {
        r++;
        st2.insert(i);
      }
    }
    if(ans[i] == 'B') {
      if(b != (n - 1) / 2) {
        b++;
        st2.insert(i);
      }
    }  
  }

  for(int i = 0; i < 2 * n; i++) {
    if(ans[i] != 'x') continue;
    cout << "? ";
    for(auto hoge : st2) {
      cout << hoge + 1 << " ";
    }
    cout << i + 1 << endl;
    string c; cin >> c;
    ans[i] = c[0];
  }

  cout << "! ";
  for(int i = 0; i < 2 * n; i++) {
    if(i == 2 * n - 1) cout << ans[i] << endl;
    else cout << ans[i] << " ";
  }

  return 0;
}

