int main(){
    int N;
    cin >> N;
    vector<int> A(N), ans(2*N, -1);
    for(int i=0; i<N; i++) A[i] = i;
    int col = ask(A);

    int ok = N-1, ng = -1;
    while(ok-ng>1){
        int mid = (ok+ng)/2;
        for(int i=0; i<N; i++) A[i] = (i<=mid ? i+N : i);
        int col2 = ask(A);
        (col != col2 ? ok : ng) = mid;
    }
    vector<int> A0, A1;
    for(int i=0; i<N; i++){
        if(i == ok) continue;
        if(i<ok){
            A0.push_back(i+N);
            A1.push_back(i);
        }else{
            A0.push_back(i);
            A1.push_back(i+N);
        }
    }
    ans[ok] = col;
    ans[ok+N] = 1-col;
    for(int a : A0){
        A1.push_back(a);
        int c = ask(A1);
        ans[a] = c;
        A1.pop_back();
    }
    for(int a : A1){
        A0.push_back(a);
        int c = ask(A0);
        ans[a] = c;
        A0.pop_back();
    }

    cout << "!";
    string BR = "BR";
    for(int i=0; i<2*N; i++) cout << " " << BR[ans[i]];
    cout << endl;
    return 0;
}

