void solve() {
  vector<int> query;
  for (int i = 0; i < n; i++) query.push_back(rest[i]);
  int c = quest(query);
  int l = n, r = rest.size();
  while (r - l > 1) {
    query.clear();
    int m = (r + l) / 2;
    for (int i = m - 1; i >= m - n; i--) query.push_back(rest[i]);
    int c2 = quest(query);
    if (c == c2) {
      l = m;
    } else {
      r = m;
    }
  }
  ok.emplace_back(rest[l], 1 - c);
  ok.emplace_back(rest[l - n], c);
  rest.erase(rest.begin() + l);
  rest.erase(rest.begin() + l - n);
}

