    {
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i || i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        l -= 2*n;
