      if (i > 1 && ans[i] != ans[i - 1]) {
         int l = i, r = i + n - 2;  
         if (ans[i]) res[i - 1] = 0, res[i + n - 1] = 1;
         else res[i - 1] = 1, res[i + n - 1] = 0;
         cur.clear ();
         for (int k = l; k <= r; k ++) cur.pb (k); 
