void solve(int N){
    vi a(N*2); rep(i,N*2) a[i] = i;

    set<int> unk;
    rep(i,N*2) unk.insert(i);
    map<int,int> deja;

    int lo=0, loF = ask(a,lo,lo+N);
    int hi=N, hiF = (loF=='R')?'B':'R';

    while (lo+1 < hi) {
        int mi = (lo+hi)/2;
        int miF = ask(a,mi,mi+N);
        if (loF == miF){
            lo = mi;
        } else {
            hi = mi;
        }
    }

    deja[lo] = loF; unk.erase(lo);
    deja[hi] = hiF; unk.erase(hi);

    for(int i=0; i<lo; ++i){
        a[lo] = i;
        deja[i] = ask(a,lo,lo+N);
        unk.erase(i);
    }
    for(int i=lo+N+1; i<N*2; ++i){
        a[lo] = i;
        deja[i] = ask(a,lo,lo+N);
        unk.erase(i);
    }

    a.assign(N,-1);
    int H=(N-1)/2, ac=0, bc=0, i=0;
    for (auto& p: deja){
        if (ac==H && bc==H) break;
        switch (p.second){
            case 'R':
                if (ac<H) {
                    a[i++] = p.first;
                    ++ac;
                }
                break;
            case 'B':
                if (bc<H) {
                    a[i++] = p.first;
                    ++bc;
                }
                break;
        }
    }
    assert(i==N-1);

    for (int n: unk){
        a[N-1] = n;
        deja[n] = ask(a,0,N);
    }

    vi pat(N*2, '?');
    rep(i,2*N){
        pat[i] = deja[i];
    }
    ans(pat);
}

int main() {
    int N; cin >> N;
    solve(N);
    return 0;
}

