void solve()
{
	cin >> N;
	string colors(2*N, 'R');

	ll ok = 0, ng = N;
	vll q(N);
	REP(i, N) q[i] = i;
	char okColor = QuestionAndAnswer(q);
	char ngColor = (okColor=='R') ? 'B' : 'R';

	while (std::abs(ok - ng) > 1){
		ll mid = (ok + ng)/2;

		REP(i, N) q[i] = mid+i;
		char color = QuestionAndAnswer(q);

		if (color == okColor) ok = mid;
		else ng = mid;
	}
	ll K = ok;

	colors[K] = okColor;
	colors[K+N] = ngColor;


	REP(i, N-1) q[i+1] = i+K+1;

	REPS(i, 0, K-1){
		q[0] = i;
		char color = QuestionAndAnswer(q);
		colors[i] = color;
	}
	REPS(i, K+N+1, 2*N-1){
		q[0] = i;
		char color = QuestionAndAnswer(q);
		colors[i] = color;
	}

	ll count=1;
	REPS(i, 0, K-1){
		q[count] = i; count++;
	}
	REPS(i, K+N+1, 2*N-1){
		q[count] = i; count++;
	}

	REPS(i, K+1, K+N-1){
		q[0] = i;
		char color = QuestionAndAnswer(q);
		colors[i] = color;
	}

	cout << "! " << colors << flush;
}

