map<i_i, int> mp;

int query(int l, int r) {
    auto lr = i_i(l, r);
    if (mp.count(lr)) return mp[lr];
    vector<int> a(r - l);
    rep(i, r - l) a[i] = l + i;
    return mp[lr] = query(a);
}

int main() {
    int N; cin >> N;
    int l = 0, r = N;
    while (r - l > 1) {
        int m = (l + r) / 2;
        int x = query(l, l + N);
        int y = query(r, r + N);
        int z = query(m, m + N);
        if (z == x) l = m;
        if (z == y) r = m;
    }
    vector<int> ans(N * 2);
    rep(i, N * 2) {
        vector<int> a;
        if (l + 1 <= i && i < l + N) {
            for (int i = 0; i < l; i++) a.pb(i);
            for (int i = r + N; i < N * 2; i++) a.pb(i);
        }
        else {
            for (int i = l + 1; i < l + N; i++) a.pb(i);
        }
        a.pb(i);
        ans[i] = query(a);
    }
    string s(N * 2, ' ');
    rep(i, N * 2) s[i] = "RB"[ans[i]];
    cout << "! " << s << endl;
}

