int main() {
    int N;
    cin >> N;
    // Find first
    deque<int> a;
    deque<int> b;
    for (int i = 0; i < N; i++) {
        a.push_back(i);
        b.push_back(N + i);
    }

    int r = ask(a);

    if (r < 0) {
        swap(a, b);
    }
    int lstpop;
    int lstadd;
    int rr;
    do {
        lstpop = a.front();
        lstadd = b.front();
