        a.push_back(lstadd);
        rr = ask(a) ;
    } while (rr > 0);

    res[lstadd] = -1;
    res[lstpop] = +1;

    auto c = a;

    c.pop_back(); // c is neutral

    for (int i = 0; i < N; i++) {
        if (res[i] == 0) {
            auto t = c;
            t.push_back(i);
            int r = ask(t);
            res[i] = r;
        }
    }

    report(N);


}

