int main() {
	int N; cin >> N;
	int p;

	{
		V<int> vec;
		rep(i, N) {
			vec.pb(i);
		}
		p = ask(vec);
	}

	int lo = 0, hi = N;
	while (hi - lo > 1) {
		int m = (lo + hi) / 2;
		V<int> vec;
		rep(i, N) vec.pb(m + i);
		int res = ask(vec);
		if (res == p) {
			lo = m;
		} else {
			hi = m;
		}
	}
	int l = hi;

	//(l,l+N-2)
	V<int> col(N * 2, -1);

	rep(i, N * 2) {
		V<int> vec;
		if (i < l || i >= l + N) {
			vec.pb(i);
			for (int j = l; j < l + N - 1; ++j) {
				vec.pb(j);
			}
		} else {
			vec.pb(i);
			//not [l-1,l+N-1] 
			for (int j = 0; j < l-1; ++j) {
				vec.pb(j);
			}
			for (int j = l + N; j < N * 2; ++j) {
				vec.pb(j);
			}
		}
		bool t = ask(vec);
		if (t) {
			col[i] = 1;
		} else {
			col[i] = 0;
		}
	}

	dump(col);
	answer(col);

	return 0;
}

