    unsigned long idx{0}, r{N}, c{1}, t{0UL + query()};
    while(idx + 1 < r){
        auto m = (idx + r) / 2;
        iota(ask.begin(), ask.end(), m);
        ((res[m] = 0UL + query()) == t ? idx : r) = m;
        ++c;
    }
    if(212 < c + 2 * N)abort();
    ans[idx] = res[idx];
    ans[N + idx] = res[idx + 1];
    for(unsigned long i = 0; i < idx; ++i){
