int main() {
  int n;
  scanf("%d", &n);
  vector<int> result(2 * n, -1);
  for (;;) {
    int last = -1;
    vector<int> base;
    vector<int> base2;
    for (int i = 0; i <= n; i++) {
      vector<int> cur;
      for (int j = 0; j < n; j++) cur.push_back(i + j);
      int res = query(cur);
      if (last != -1 && last != res) {
        int L = i - 1, R = i + n - 1;
        result[L] = last;
        result[R] = res;
        for (int j = 0; j < 2 * n; j++) {
          if (j == L || j == R) continue;
          if (j > L && j < R) base.push_back(j);
          else base2.push_back(j);
        }
        break;
      }
      last = res;
    }
    for (int i = 0; i < 2 * n; i++) {
      if (result[i] != -1) continue;
      vector<int> qset;
      if (binary_search(base.begin(), base.end(), i)) {
        qset = base2;
        qset.push_back(i);
        result[i] = query(qset);
      } else {
        qset = base;
        qset.push_back(i);
        result[i] = query(qset);
      }
    }
  }
  string ans="! ";
  for (int i = 0; i < 2 * n; i++) if (result[i] == 0) ans.push_back('R'); else ans.push_back('B');
  printf("%s\n", ans.c_str());
  return 0;
}

