            goto NEXT;
          }
          if(result == "Red"){
            found.insert(i);
            found.insert(last);
            R.push_back(i);
            B.push_back(last);
            goto NEXT;
          }
        }
      }
      NEXT:;
    }
  }
  void output() {
    map<Int, char> M;
    FOR(r, R)M[r] = 'R';
    FOR(r, B)M[r] = 'B';
    cout << "! ";
    rep(i, N*2){
      cout << M[i];
    }
    cout <<endl;
  }
};

