char recieve_color() {
    string s; cin >> s;
    if(s == "-1") exit(1);
    return (s == "Red" ? 'R' : 'B');
}

void answer_query(string ans) {
    cout << "! " << ans << endl;
}

int main() {
    int N; cin >> N;
    string ans(2*N+1, '?');

    const char NIL = '?';

    send_query1(1, 1+N);
    char L = recieve_color();
    send_query1(N+1, N+1+N);
    char R = recieve_color();
    if(L == R) R = 'B' ^ 'R' ^ L;

    int ub = N+1, lb = 1;
    while(ub - lb > 1) {
        int mid = (ub + lb) / 2;
        send_query1(mid, mid+N);
        char P = recieve_color();
        if(P == L) lb = mid;
        else ub = mid;
    }

    {
        int i = ub;
        // i-1 番目は pre の色
        // i+N-1 番目は cur の色
        ans[i-1] = L;
        ans[i+N-1] = R;

        // [i, i+N-2] に青と赤が (N-1)/2 ずつ含まれる
        vector<int> vec;
        for(int j=i; j<=i+N-2; j++) vec.emplace_back(j);

        for(int j=1; j<=2*N; j++) {
            if(ans[j] != NIL) continue;
            if(i <= j and j <= i+N-2) continue;
            send_query2(vec, j);
            ans[j] = recieve_color();
        }

        int target = (N - 1) / 2;
        vector<int> red, blue;
        for(int j=1; j<=2*N; j++) {
            if(ans[j] == 'R' and red.size() < target) red.emplace_back(j);
            if(ans[j] == 'B' and blue.size() < target) blue.emplace_back(j);
        }

        for(int j=1; j<=2*N; j++) {
            if(ans[j] != NIL) continue;
            send_query3(red, blue, j);
            ans[j] = recieve_color();
        }
    }
    answer_query(ans.substr(1));
    return 0;
}

