        assert(A.size() == N);
        std::cout << "?";
        for (const int e : A) { std::cout << " " << e + 1; }
        std::cout << std::endl;
        const auto rep = read<std::string>();
        assert(rep != "-1");
        return (rep == "Blue" ? 1 : 0);
    };
    auto answer = [&](const std::vector<int>& Ans) {
        assert(Ans.size() == 2 * N);
        std::cout << "! ";
        for (const int e : Ans) { std::cout << (e == 0 ? 'R' : 'B'); }
        std::cout << std::endl;
    };
    std::vector<int> ren(2 * N);
    std::vector<int> ans(2 * N, -1);
    std::deque<int> A;
    int r = -1, b = -1;
    for (int i = 0; i < 2 * N; i++) {
        if (A.empty()) {
            for (int j = 0; j < N; j++) { A.push_back(j); }
        }
        ren[i] = ask(A);
        A.pop_front();
        A.push_back((i + N) % (2 * N));
        if (i > 0 and ren[i - 1] != ren[i]) {
            (ren[i - 1] == 0 ? r : b) = i - 1;
            (ren[i - 1] == 0 ? b : r) = (i - 1 + N) % (2 * N);
            break;
        }
    }
    assert(r != -1 and b != -1);
    if (r == -1 and b == -1) {
        (ren[0] == 0 ? r : b) = 0;
        (ren[0] == 0 ? b : r) = N;
    }
    std::vector<int> L, R;
    for (int i = (r + 1) % (2 * N); i != b; (i += 1) %= (2 * N)) { L.push_back(i); }
    for (int i = (b + 1) % (2 * N); i != r; (i += 1) %= (2 * N)) { R.push_back(i); }
    SHOW(r, b);
    ans[r] = 0, ans[b] = 1;
    SHOW(L, R);
    for (const int e : L) {
        std::deque<int> a{r, b};
        for (const int e2 : L) {
            if (e2 == e) { continue; }
            a.push_back(e2);
        }
        const int blue = ask(a);
        ans[e]         = 1 - blue;
    }
    for (const int e : R) {
        std::deque<int> a{r, b};
        for (const int e2 : R) {
            if (e2 == e) { continue; }
            a.push_back(e2);
        }
        const int blue = ask(a);
        ans[e]         = 1 - blue;
    }
    SHOW(ans);
    answer(ans);
    return 0;
}

