    l=1,r=n+1;
    while(l<r-1){
        int mid=(l+r)/2;
        vec v;
        rep2(i,mid,mid+n-1)v.pb(i);
        bool now=ask(v);
        if(now!=defo)r=mid;
        else l=mid;
    }
    rep2(i,l,r)st.pb(i);
    r=l+n-2;
    rep2(i,1,n*2){
        if(l<=i&&i<=r)continue;
        vec now=st;
        now.pb(i);
        ans[i]=ask(now);
    }
    bool red=0,blue=0;
    vec w;
    rep2(i,1,n*2){
        if(l<=i&&i<=r)continue;
        if(ans[i]==1){
            if(red) w.pb(i);
            red=1;
        }
        else{
            if(blue)w.pb(i);
            blue=1;
        }
    }
    rep2(i,l,r){
        vec ww=w;
        ww.pb(i);
        ans[i]=ask(ww);
    }
    cout<<"! ";
    rep2(i,1,n*2){
        cout<<(ans[i]?"R":"B");
    }
    cout<<endl;
    cout.flush();
    return 0;
}

