void solve() {
	int N; cin >> N;
	if (N == 1) {
		cout << "?" << " ";
		cout << 1 << endl;
		string S; cin >> S;
		if (S == "Red") {
			ans[1] = 'R';
			ans[2] = 'B';
		}
		else {
			ans[1] = 'B';
			ans[2] = 'R';
		}
		cout << "!" << " ";
		FOR(i, 1, 2 * N + 1) {
			cout << ans[i];
			if (i == 2 * N)cout << endl;
		}
		return;
	}
	int l = 1, r = N;
	string pre;
	bool ok = false;
	question(l, r);
	cin >> pre;
	while (!ok) {
		l++, r++;
		question(l, r);
		string now; cin >> now;
		if (pre != now) {
			ok = true;
			break;
		}
	}
	r--;
	FOR(i, 1, l) {
		question2(l, r, i);
		string now; cin >> now;
		if (now == "Red") {
			ans[i] = 'R';
		}
		else {
			ans[i] = 'B';
		}
	}
	FOR(i, r+1, 2*N+1) {
		question2(l, r, i);
		string now; cin >> now;
		if (now == "Red") {
			ans[i] = 'R';
		}
		else {
			ans[i] = 'B';
		}
	}
	vector<int>q;
	int remR = N/2, remB = N/2;
	FOR(i,1, 2 * N+1) {
		if (ans[i] == 'R'&&remR>0) {
			q.push_back(i); remR--;
		}
		else if (ans[i] == 'B'&&remB > 0) {
			q.push_back(i); remB--;
		}
	}
	FOR(i, l, r + 1) {
		cout << "?" << " ";
		REP(i, N-1) {
			cout << q[i] << " ";
		}
		cout << i << endl;
		string now; cin >> now;
		if (now == "Red") {
			ans[i] = 'R';
		}
		else {
			ans[i] = 'B';
		}
	}
	cout << "!" << " ";
	FOR(i, 1, 2 * N + 1) {
		cout << ans[i];
		if (i == 2 * N)cout << endl;
	}
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

