string ask3(int j, int p, int n) {
	cout << "? " << j << " ";
	for (int i = p + 1; i < p + n; i++) {
		cout << i << " ";
	}
	cout << "\n";
	cout.flush();
	string ans;
	cin >> ans;
	string res = (ans == "Red") ? "R":"B";
	return res;
}

int bs(int l, int r, int n) {
	int ans;
	int x = ask(l, n);
	while (l <= r) {
		int m = (l + r) / 2;
		int y = ask(m, n);
		if (x == y) {
			ans = m;
			l = m + 1;
		} else {
			r = m - 1;
		}
 	}
	return ans;
}

