int Debug = 1;

string str;

string Interaction(vector<int> vec) {
	if (Debug == 1) {
		cout << "?";
		for (int i = 0; i < vec.size(); i++) cout << " " << vec[i];
		cout << endl;

		string ret; cin >> ret;
		return ret;
	}
	if (Debug == 2) {
		int v1 = 0, v2 = 0;
		for (int i = 0; i < vec.size(); i++) {
			if (str[vec[i] - 1] == 'R') v1++;
			else v2++;
		}
		if (v1 > v2) return "Red";
		return "Blue";
	}
}

void destroy() {
	for (int i = 0; i < 1000000000; i++) cout << i << endl;
}

string getranged(int cl, int cr) {
	vector<int> vec;
	for (int i = cl; i <= cr; i++) vec.push_back(i);
	return Interaction(vec);
}

string solve(int N) {
	// 変曲点を探す
	string A1 = getranged(1, N); int critical = 0;
	for (int i = 7; i >= 0; i--) {
		int I = min(N + 1, critical + (1 << i));
		string A2 = getranged(I, I + N - 1);
		if (A1 == A2) { critical += (1 << i); }
	}

	// 変曲点から各ボールの色を求める
	vector<int> vec1, vec2;
	for (int i = 1; i <= 2 * N; i++) {
		if (critical + 1 <= i && i <= critical + N - 1) vec1.push_back(i);
		else if (i != critical && i != critical + N) vec2.push_back(i);
	}

	string ans = "";
	for (int i = 1; i <= 2 * N; i++) {
		if (critical + 1 <= i && i <= critical + N - 1) {
			vector<int> E = vec2; E.push_back(i);
			string V = Interaction(E); assert(V != "-1");
			if (V == "Blue") ans += "B";
			else ans += "R";
		}
		else {
			vector<int> E = vec1; E.push_back(i);
			string V = Interaction(E); assert(V != "-1");
			if (V == "Blue") ans += "B";
			else ans += "R";
		}
	}
	return ans;
}

int main() {
	int N;
	if (Debug == 1) cin >> N;
	if (Debug == 2) cin >> N >> str;

	string P = solve(N);
	cout << "! " << P << endl;
	return 0;
}

