int main(int argc, char* argv[])
{
    int n;
    scanf("%d", &n);

    vector<int> a(n);
    int i;
    for(i=0; i<n; i++) {
        a[i]=i;
    }
    int ret0=ask(n, a);
    if(ret0==99) {
        return 99;
    }

    int l=0, r=n;
    while(r-l>1) {
        int m=(l+r)/2;
        for(i=0; i<n; i++) {
            if(i<n-m) a[i]=i;
            else      a[i]=i+n;
        }
        int ret=ask(n, a);
        if(ret0==99) {
            return 99;
        }
        if(ret==ret0) {
            l=m;
        }
        else {
            r=m;
        }
    }

    for(i=0; i<n; i++) {
        if(i<n-l) a[i]=i;
        else      a[i]=i+n;
    }
    int ss=n-l-1;

    vector<int> ans(n*2,-1);
    ans[n-l-1]=ret0;
    ans[n*2-l-1]=1-ret0;
    for(i=1; i<n; i++) {
        a[ss]=ss+i;
        int ret1=ask(n, a);
        if(ret1==ret0) {
            ans[ss+i]=ret0;
        }
        else {
            ans[ss+i]=1-ret0;
        }
        a[ss]=ss;
    }

    for(i=0; i<n; i++) {
        a[i]=ss+i;
    }
    for(i=0; i<n*2; i++) {
        if(ans[i]<0) {
            a[ss]=i;
            int ret1=ask(n, a);
            if(ret1==ret0) {
                ans[i]=ret0;
            }
            else {
                ans[i]=1-ret0;
            }
        }
        a[ss]=ss;
    }

    printf("! ");
    for(i=0; i<n*2; i++) {
        if(ans[i]==1) {
            printf("R");
        }
        else if(ans[i]==0) {
            printf("B");
        }
        else {
            printf("?");
        }
    }
    printf("\n");

    return 0;
}

