int main()
{
    scanf("%d",&n);
    a=Q1(1,n);
    b=3-a;
    go(1,a);
    go(n+n,b);
    int left=1,right=n+1;
    while (left+1<right) {
        int mid=(left+right)>>1;
        int c=Q1(mid,mid+n-1);
        if (a==c) left=mid;
        else right=mid;
    }
    for (int i=right;i<=left+n-1;++i) vec.push_back(i);
    for (int i=2;i<right;++i) {
        vec.push_back(i);
        go(i,Q2());
