int main() {
    int64_t N;
    cin >> N;

    int64_t first = 1, second = 1 + N;
    vector<int64_t> q(N);
    iota(q.begin(), q.end(), 1);
    string first_str = query(q);
    while (second - first != 1) {
        int64_t mid = (first + second) / 2;
        iota(q.begin(), q.end(), mid);
        string curr = query(q);
        (curr == first_str ? first = mid : second = mid);
    }

    int64_t change_index = second;

    //change_indexからN - 1個はB, Rが半々
    //そこ+1を問えば+1部分が特定可能
    q.clear();
    for (int64_t i = change_index; i < change_index + N - 1; i++) {
        q.push_back(i);
    }

    string ans;
    for (int64_t i = 0; i < 2 * N; i++) {
        ans.push_back('?');
    }

    for (int64_t i = 1; i <= 2 * N; i++) {
        if (change_index <= i && i < change_index + N - 1) {
            continue;
        }

        q.push_back(i);
        string T = query(q);
        q.pop_back();

        ans[i - 1] = (T == "Red" ? 'R' : 'B');
    }

    //確定したところからR, Bが半々の質問を構成して残りを問う
    q.clear();
    int64_t r_num = (N - 1) / 2, b_num = (N - 1) / 2;
    for (int64_t i = 0; i < 2 * N; i++) {
        if (ans[i] == 'R' && r_num > 0) {
            q.push_back(i + 1);
            r_num--;
        } else if (ans[i] == 'B' && b_num > 0) {
            q.push_back(i + 1);
            b_num--;
        }
    }

    for (int64_t i = change_index; i < change_index + N - 1; i++) {
        q.push_back(i);
        string T = query(q);
        q.pop_back();
        ans[i - 1] = (T == "Red" ? 'R' : 'B');
    }

    cout << "! " << ans << endl;
}

