int L, R;

void step1_binarySearch() {
	set<int> qL, qR, qM;
	for (int i = 0; i < n; i++) {
		qL.insert(i);
		qR.insert(i + n);
	}
	char colorL = query(qL);
	char colorR = (colorL == 'R' ? 'B' : 'R');
	char colorM;
	//assert(colorL != colorR);
	L = 0, R = n;
	int M;
	while (L + 1 < R) {
		M = (L + R) / 2;
		//cerr << L << " " << M << " " << R << "\n";
		for (int i = 0; i < n; i++) {
			qM.insert(i + M);
		}
		colorM = query(qM);
		if (colorL == colorM) {
			L = M;
			qL = qM;
			colorL = colorM;
		} else {
			R = M;
			qR = qM;
			colorR = colorM;
		}
		qM.clear();
	}
	R = L + n;
	res[L] = colorL;
	res[R] = colorR;
}

int red, blue;

void step2() {
	red = blue = (n - 1) / 2;
	set<int> q;
	for (int i = L + 1; i < R; i++) {
		q.insert(i);
	}
	for (int i = 0; i < n2; i++) {
		if (i < L or i > R) {
			if (red == 0) {
				res[i] = 'B';
				continue;
			}
			if (blue == 0) {
				res[i] = 'R';
				continue;
			}
			q.insert(i);
			(res[i] = query(q)) == 'R' ? red-- : blue--;
			q.erase(i);
		}
	}
}

void step3() {
	red = blue = (n - 1) / 2;
	set<int> q;
	for (int i = 0; i < n2; i++) {
		if (i < L or i > R) {
			q.insert(i);
		}
	}
	for (int i = L + 1; i < R; i++) {
		if (red == 0) {
			res[i] = 'B';
			continue;
		}
		if (blue == 0) {
			res[i] = 'R';
			continue;
		}
		q.insert(i);
		(res[i] = query(q)) == 'R' ? red-- : blue--;
		q.erase(i);
	}
}

