    string res(n * 2, ' ');

    out(1, n);
    string base;
    cin >> base;
    // base = get();
    int lo = 1, hi = n + 1, mid;
    while(lo + 1 < hi){
    	mid = lo + (hi - lo) / 2;
    	out(mid, n);
    	string cur;
    	cin >> cur;
    	// cur = get();
    	if(cur == base)
