V rng(int l, int r) {
  int n = r - l + 1;
  V res(n);
  rep(i, n) res[i] = l + i;
  return res;
}


int main() {
  int n; cin >> n;

  cout << "? " << rng(1, n) << endl;
  string s; cin >> s;
  assert(s != "-1");
  int x = (s == "Red" ? 0 : 1);

  int l = -1;
  rep2(i, 1, n+1) {
    cout << "? " << rng(i+1, i+n) << endl;
    string s; cin >> s;
    assert(s != "-1");
    int y = (s == "Red" ? 0 : 1);
    if (x != y) {
      l = i;
      break;
    }
  }

  V ans(2*n+1, -1);
  ans[l] = x;
  ans[l+n] = x^1;

  rep2(i, 1, 2*n+1) {
    if (i == l || i == l+n) continue;
    if (i < l || n+l < i) cout << "? " << rng(l+1, l+n-1) << i << endl;
    else cout << "? " << rng(1, l-1) << rng(l+n+1, 2*n) << i << endl;
    string s; cin >> s;
    assert(s != "-1");
    int y = (s == "Red" ? 0 : 1);
    ans[i] = y;
  }

  cout << "! ";
  rep(i, 2*n) cout << (ans[i+1] == 0 ? 'R' : 'B');
  cout << endl;
  return 0;
}

