    if(s != t) ng = mid; else ok = mid;
  }

  // ok で 50 以上
  // ng で 50 未満
  // ok + 1 == ng
  // =>
  // ng で 49

  for(int i = 0; i < ng; i++) swap(a[i], a[i+n]);
  // a[ng-1] == !s, a[ng-1 + n] == s

  set<int> ss;
  for(int i = 0; i < n; i++) ss.insert(i);
