  }

  // 一つずつAで置き換えて行く
  int baseIndex = -1;
  int vvQueryIndex = -1;
  REP(n,rA.size()) {
    vv[queryCounter][RB.size()+n] = rA[n];
    int color = query();
    if(color == -1) {
      vv[queryCounter] = vv[queryCounter-1];
      continue;
    } else { // 青から赤に変わった
      baseIndex = n + RB.size();
      vvQueryIndex = queryCounter-2;
      break;
    }
  }

  color[vv[queryCounter-1][baseIndex]] = 1;
  color[vv[queryCounter-2][baseIndex]] = -1;

  cerr << "確定" << endl;
  cerr << baseIndex << endl;
  for(int v : vv[queryCounter-1]) {
    cerr << v << " ";
  }
  cerr << endl;

  bool baseVecUsed[MAX_N];
  memset(baseVecUsed, 0, sizeof(baseVecUsed));
  for(int v : vv[vvQueryIndex]) {
    baseVecUsed[v] = true;
  }

  // vvに含まれていない色を確定させて行く
  FOR(n,1,2*N+1) {
    if(color[n] == 0 && !baseVecUsed[n]) {
      vv[queryCounter] = vv[vvQueryIndex];
      vv[queryCounter][baseIndex] = n;
      color[n] = query();
    }
  }

  cerr << "OK" << endl;
  FOR(n,1,2*N+1) {
    cerr << color[n] << " ";
  }
  cerr << endl;

  int ccc = 0;
  int ci = 0;
  FOR(n,1,2*N+1) {
    if(color[n] == 1) {
      ccc = color[n];
      ci = n;
      break;
    }
  }

  REP(n,N) {
    vv[queryCounter] = vv[vvQueryIndex];
    int old = vv[queryCounter][n];
    vv[queryCounter][n] = ci;
    if(ccc == query()) {
      color[old] = -1;
    } else {
      color[old] = 1;
    }
  }

  writeAns();

  return 0;
}

