i64 bin(i64 l, i64 r) {
    if (l == r) {
        return l;
    }
    if (l + 1 == r) {
        char c = queryz(l);
        if (c == 'B') {
            return l;
        }
        else {
            return r;
        }
    }

    i64 t = (l + r) / 2;
    char c = queryz(t);
    if (c == 'R') {
        return bin(t, r);
    }
    else {
        return bin(l, t);
    }
}


