      cur.ppb ();    
   }
   cur.clear ();
   int red = n / 2, blue = n / 2;
   for (int j = 1; j <= n + n; j ++) {
      if (res[j] != -1) {
         if (res[j] && red > 0) red --, cur.pb (j);
