		a[n-1]=x;
		auto t1=Query(a);
		a[n-1]=y;
		auto t2=Query(a);
		if(t1!=t2) break;
	}
	for(int i=0;i<2*n;i++) if(!b[i]&&i!=x){
		a[n-1]=i;
		res[i]=Query(a)[0];
	}
	int I=0;
	for(int i=0;i<2*n;i++) if(!b[i]&&i!=x&&i!=y) a[I++]=i;
	for(int i=0;i<2*n;i++) if(b[i]||i==x){
		a[n-1]=i;
		res[i]=Query(a)[0];
	}
	Answer(res);
}

