ll n, Ans[205];
vector<ll> V;

ll ask()
{
    string ans;
    cout<<"? ";
    for (auto i : V)
        cout<<i<<" ";
    cout<<'\n';
    cout.flush();
    cin>>ans;
    if (ans == "-1")
        exit(0);
    return ans == "Blue";
}

ll askCircular(ll x)
{
    V.clear();
    for (ll i=x; i<=x+n-1; i++)
        V.push_back(i);
    ll ans = ask();
    return ans;
}

ll askllerval(ll l, ll r, ll x)
{
    V.clear();
    if (r<l)
    {
        for (ll i = l; i <= 2*n; i++)
            V.push_back(i);
        for (ll i = 1; i <= r; i++)
            V.push_back(i);
    }
    else
    {
        for (ll i = l; i <= r; i++)
            V.push_back(i);
    }
    V.push_back(x);
    ll ans = ask();
    return ans;
}

void prllAns()
{
    cout<<"! ";
    for (ll i=1; i<=2*n; i++)
    {
        if (Ans[i] == 0)
            cout<<"R";
        else
            cout<<"B";
    }
    cout.flush();
    exit(0);
}

void askFinish(ll x)
{
    ll l = x;
    ll r = x+n-2;
    if (r > 2*n)
    {
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i || i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i && i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }

    l = x + n;
    r = x + 2*n - 2;
    if (l <= 2*n)
    {
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i || i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        l -= 2*n;
        r -= 2*n;
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i && i<=r) && Ans[i] == 0)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }

    prllAns();
}

int main()
{
    //freopen("input.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    cin>>n;

    if (n==1)
    {
        V.push_back(1);
        Ans[1] = ask();
        V.clear();
        V.push_back(2);
        Ans[2] = ask();
        prllAns();
        return 0;
    }

    ll last = -1;
    for (ll i=1; i<=2*n; i++)
    {
        ll ans = askCircular(i);
        if (last != -1 &&  ans != last)
        {
            askFinish(i);
            return 0;
        }
        last = ans;
    }
    assert(false);
    return 0;
}

