	for(int i = 0; i < n; i++) {
		q[i] = true;
	}

	bool initial = ask_blue(q);
	int lo = 0, hi = n;

	while(hi - lo > 1) {
		int mid = (lo + hi) / 2;
		fill(q.begin(), q.end(), false);
		for(int i = 0; i < n - mid; i++) {
			q[i] = true;
		}
		for(int i = 0; i < mid; i++) {
			q[n + i] = true;
		}
		bool ans = ask_blue(q);
		if(initial != ans) {
			hi = mid;
		} else {
			lo = mid;
		}
	}

	dbg(lo);

	vector<bool> main_color(2 * n, false);
	int x = n - hi;
	int y = lo;

	main_color[x] = true;
	main_color[y] = false;

	fill(q.begin(), q.end(), false);
	for(int i = 0; i < x; i++) {
		q[i] = true;
	}
	for(int i = 0; i < y; i++) {
		q[n + i] = true;
	}

	for(int i = x + 1; i < n; i++) {
		q[i] = true;
		bool ans = ask_blue(q);
		main_color[i] = (initial == ans);
		q[i] = false;
	}

	for(int i = y + 1; i < n; i++) {
		q[n + i] = true;
		bool ans = ask_blue(q);
		main_color[n + i] = (initial == ans);
		q[n + i] = false;
	}

	q[x] = q[y] = true;

	for(int i = 0; i < x; i++) {
		q[i] = false;
		bool ans = ask_blue(q);
		main_color[i] = (initial != ans);
		q[i] = true;
	}

	for(int i = 0; i < y; i++) {
		q[n + i] = false;
		bool ans = ask_blue(q);
		main_color[n + i] = (initial != ans);
		q[n + i] = true;
	}

