signed main(){
	int n;
	cin >> n;
	string ans;
	for(int i = 0;i < n * 2;i++) ans += '?';
	vector<int> q;
	for(int i = 0;i < n;i++) q.push_back(i);
	bool isR = ask(q);
	int r = 0,b = n;
	if(!isR) swap(r,b);
	while(abs(r - b) > 1){
		int mid = (r + b) / 2;
		for(int i = 0;i < n;i++) q[i] = mid + i;
		if(ask(q)) r = mid;
		else b = mid;
	}
	if(r < b){
		ans[r] = 'R';
		ans[r + n] = 'B';
	}else{
		ans[b] = 'B';
		ans[b + n] = 'R';
	}
	int ma = max(b,r);
	for(int i = 0;i < n * 2;i++){
		q.clear();
		if(ma <= i && i < ma + n - 1){
			for(int j = -1;j < n;j++){
				if(ma + j != i) q.push_back(ma + j);
			}
			ans[i] = (ask(q) ? 'B' : 'R');
		}else{
			for(int j = 0;j < n - 1;j++){
				q.push_back(ma + j);
			}
			q.push_back(i);
			ans[i] = (ask(q) ? 'R' : 'B');
		}
	}
	cout << "! " << ans << endl;
}

