int ask_range(int a) {
  set<int> q;
  REP(i, 0, n) q.insert((a + i) % (2 * n));
  return ask(q);
}

int main(void) {
  cin >> n;
  init(n);
  int f0 = ask_range(0);
  int lo = 0;
  int hi = n;
  while (hi - lo > 1) {
    int mid = (hi + lo) / 2;
    if (ask_range(mid) == f0) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  // lo is f0, lo + n is -f0.
  VI ans(2 * n);
  ans[lo] = f0;
  ans[lo + n] = -f0;
  REP(i, 0, n - 1) {
    int x = (lo + n + 1 + i) % (2 * n);
    set<int> a;
    // [lo + 1, lo + n - 1]
    REP(j, 0, n - 1) a.insert((lo + 1 + j) % (2 * n));
    a.insert(x);
    ans[x] = ask(a);
  }
  REP(i, 0, n - 1) {
    set<int> a;
    int x = (lo + 1 + i) % (2 * n);
    // [lo + n + 1, lo + 2 * n - 1]
    REP(j, 0, n - 1) a.insert((lo + n + 1 + j) % (2 * n));
    a.insert(x);
    ans[x] = ask(a);
  }
  cout << "! ";
  REP(i, 0, 2 * n) {
    cout << (ans[i] == 1 ? 'R' : 'B');
  }
  cout << endl;
}

