        static int Q = 0;
        Q++;
        assert(Q <= 210);
        assert(A.size() == N);
        std::cout << "?";
        for (const int e : A) { std::cout << " " << e + 1; }
        std::cout << std::endl;
        const auto rep = read<std::string>();
        assert(rep != "-1");
        return (rep == "Blue" ? 1 : 0);
    };
    auto answer = [&](const std::vector<int>& Ans) {
        assert(Ans.size() == 2 * N);
        std::cout << "! ";
        for (const int e : Ans) { std::cout << (e == 0 ? 'R' : 'B'); }
        std::cout << std::endl;
    };
    std::vector<int> ren(2 * N, -1);
    std::vector<int> ans(2 * N, -1);
    auto hoge = [&](const int i) -> int {
        if (ren[i] != -1) { return ren[i]; }
        std::vector<int> A;
        for (int j = 0; j < N; j++) { A.push_back((i + j) % (2 * N)); }
        return ren[i] = ask(A);
    };

    int inf = -1, sup = N;
    int r = -1, b = -1;
    while (sup - inf > 1) {
        const int mid                      = (inf + sup) / 2;
        (hoge(mid) == hoge(0) ? inf : sup) = mid;
    }
    (ren[inf] == 0 ? r : b) = inf;
    (ren[inf] == 0 ? b : r) = inf + N;
    assert(r != -1 and b != -1);
    std::vector<int> L, R;
    for (int i = (r + 1) % (2 * N); i != b; (i += 1) %= (2 * N)) { L.push_back(i); }
    for (int i = (b + 1) % (2 * N); i != r; (i += 1) %= (2 * N)) { R.push_back(i); }
    SHOW(r, b);
    ans[r] = 0, ans[b] = 1;
    SHOW(L, R);
    for (const int e : L) {
        std::vector<int> a{r, b};
        for (const int e2 : L) {
            if (e2 == e) { continue; }
            a.push_back(e2);
        }
        const int blue = ask(a);
        ans[e]         = 1 - blue;
    }
    for (const int e : R) {
        std::vector<int> a{r, b};
        for (const int e2 : R) {
            if (e2 == e) { continue; }
            a.push_back(e2);
        }
        const int blue = ask(a);
        ans[e]         = 1 - blue;
    }
    SHOW(ans);
    answer(ans);
    return 0;
}

