      vv[queryCounter] = vv[vvQueryIndex];
      vv[queryCounter][baseIndex] = n;
      color[n] = query();
    }
  }

  cerr << "OK" << endl;
  FOR(n,1,2*N+1) {
    cerr << color[n] << " ";
  }
  cerr << endl;

  int ccc = 0;
  int ci = 0;
  FOR(n,1,2*N+1) {
    if(color[n] == 1) {
      ccc = color[n];
      ci = n;
      break;
    }
  }

  REP(n,N) {
    vv[queryCounter] = vv[vvQueryIndex];
    int old = vv[queryCounter][n];
    vv[queryCounter][n] = ci;
    if(ccc == query()) {
      color[old] = -1;
    } else {
      color[old] = 1;
    }
  }

  writeAns();

  return 0;
}

