int ask(int st) {

    cout << "? ";
    for (int i = 0; i < n; ++i) {
        cout << st + i << " ";
    }
    cout << endl;
    string ans;
    cin >> ans;
    if (ans == "Red") return 0;
    return 1;

}

int ask_array(int *v) {

    cout << "? ";
    for (int i = 0; i < n; ++i) {
        cout << v[i] << " ";
    }
    cout << endl;
    string ans;
    cin >> ans;
    if (ans == "Red") return 0;
    return 1;

}

void bin_search(int st, int dr, int val) {

    if (st > dr) return;
    if (st == dr) {
        if (ask(st) == val) {
            pos = max(pos, st);
            return;
        }
    }
    int mij = (st + dr) / 2;
    if (ask(mij) == val) {
        pos = max(pos, mij);
        bin_search(mij + 1, dr, val);
    } else {
        bin_search(st, mij - 1, val);
    }

}

int main() {

    // 0 -> rosu
    // 1 -> albastru

    std::ios::sync_with_stdio(false);
    cin >> n;
    int x = ask(1);
    bin_search(1, n, x);

    a[pos] = x;

    for (int i = 1; i < pos; ++i) {
        for (int j = 0; j < n - 1; ++j) {
            v[j] = pos + j + 1;
        }
        v[n - 1] = i;
        a[i] = ask_array(v);
    }

    for (int j = 0; j < n - 1; ++j) {
        v[j] = pos + j + 1;
    }

    for (int i = pos + n; i <= 2 * n; ++i) {
        v[n - 1] = i;
        a[i] = ask_array(v);
    }
    int index = 0;
    for (int j = 1; j < pos; ++j) {
        v[index] = j;
        index ++;
    }
    for (int j = pos + n + 1; j <= 2 * n; ++j) {
        v[index] = j;
        index ++;
    }

    for (int i = pos + 1; i <= pos + n; ++i) {
        v[n - 1] = i;
        a[i] = ask_array(v);
    }

    cout << "! ";
    for (int i = 1; i <= 2 * n; ++i) {
        if (a[i] == 0) cout << "R";
        else cout << "B";
    }
    cout << endl;

    return 0;
}

