inline void Solve () {
   cin >> n;
   vector <int> cur;
   cur.clear ();
   memset (res, -1, sizeof res);
   if (n == 1) {
      cur.pb (1);
      if (ask (cur)) res[1] = 1, res[2] = 0;
      else res[1] = 0, res[2] = 1;
      cout << "! ";
      for (int i = 1; i <= 2; i ++) cout << (res[i] ? "R" : "B");
      exit (0);
   }
   int L = 2, R = n + 1, i = -1;
   vector <int> q1, q2;
   for (int i = 1; i <= n; i ++) q1.pb (i);
   bool t = ask (q1);
   q1.clear ();
   while (L <= R) {
      int mid = L + R >> 1;
      q1.clear ();
      q2.clear ();
      for (int j = mid; j < mid + n; j ++) q1.pb (j);
      bool r1 = ask (q1);
      if (r1 != t) {
         i = mid;
         R = mid - 1;
      }
      else {
         L = mid + 1;
      }
   }
   ans[i] = (t ^ 1);
   ans[i - 1] = t;     
   assert (i != -1);
   int l = i, r = i + n - 2;  
   if (ans[i]) res[i - 1] = 0, res[i + n - 1] = 1;
   else res[i - 1] = 1, res[i + n - 1] = 0;
   cur.clear ();
   for (int k = l; k <= r; k ++) cur.pb (k); 
   for (int j = 1; j < l - 1; j ++) {
      cur.pb (j);
      if (ask (cur)) res[j] = 1;
      else res[j] = 0;
      cur.ppb ();    
   }
   for (int j = r + 2; j <= 2 * n; j ++) {
      cur.pb (j);
      if (ask (cur)) res[j] = 1;
      else res[j] = 0;
      cur.ppb ();    
   }
   cur.clear ();
   int red = n / 2, blue = n / 2;
   for (int j = 1; j <= n + n; j ++) {
      if (res[j] != -1) {
         if (res[j] && red > 0) red --, cur.pb (j);
         if (!res[j] && blue > 0) blue --, cur.pb (j);  
      }
   }
   for (int j = l; j <= r; j ++) {
      cur.pb (j);
      if (ask (cur)) res[j] = 1;
      else res[j] = 0;
      cur.ppb ();        
   }
   cout << "! ";
   for (int j = 1; j <= n + n; j ++) cout << (res[j] ? "R" : "B");
   fflush (stdout);
}

