        }
        for (int b : bs) {
          if (ans[b] == '.') ans[b] = 'R';
        }
        return true;
      }
      if (b_count == n / 2) {
        for (int r : rs) {
          if (ans[r] == '.') ans[r] = 'R';
        }
        for (int b : bs) {
          if (ans[b] == '.') ans[b] = 'B';
        }
