inline char query(int l, int r, int x = 0) {
  printf("?");
  for (int i = l; i != r + 1; i = i % (2 * N) + 1)
    printf(" %d", i);
  if (x != 0) printf(" %d", x);
  std::cout << std::endl;
  static char s[10];
  scanf("%s", s + 1);
  return s[1];
}

int main() {
  scanf("%d", &N);
  char base = query(1, N);
  int lbound = 2, rbound = N + 1, ans = 0;
  while (lbound <= rbound) {
    int mid = (lbound + rbound) >> 1;
    if (query(mid, mid + N - 1) == base) lbound = mid + 1;
    else {
      rbound = mid - 1;
      ans = mid;
    }
  }
  for (int i = 1; i <= 2 * N; ++i) {
    if (ans <= i && i < ans + N - 1)
      Ans[i] = query((ans + N - 1) % (2 * N) + 1, ans - 2 == 0 ? 2 * N : ans - 2, i);
    else
      Ans[i] = query((ans - 1) % (2 * N) + 1, (ans + N - 3) % (2 * N) + 1, i);
  }
  printf("! %s", Ans + 1);
  std::cout << std::endl;
  return 0;
}

