int gcd(int a, int b){
    if (a == 0 && b == 0) return 0;
    if (a < 0) a = a*(-1);
    if (b < 0) b = b*(-1);
    if (a == 0) return b;
    if (b == 0) return a;
    int c;
    if (a > b) swap(a, b);
    while (b % a > 0){
        c = b % a;
        b = a;
        a = c;
    }
    return a;
}

