int main() {
    cin >> n;
    char ans[2*n+1];
    int lb = 1, ub = n+1;
    char L = query(1), R = query(n+1);
    while (ub - lb > 1) {
        int m = (lb + ub) / 2;
        char r = query(m);
        if (r == L) lb = m;
        else ub = m;
    }
    vector<int> q_in, q_out;
    for (int i = 1; i <= 2*n; i++)
        if (lb < i && i < lb + n) q_in.push_back(i);
        else if (i < lb || lb + n < i) q_out.push_back(i);
    ans[lb] = L; ans [lb + n] = R;
    cerr << q_in.size() << " " << q_out.size() << " size" << endl;
    q_in.push_back(-1);
    q_out.push_back(-1);
    for (int i = 1; i <= 2*n; i++) {
        if (i < lb || lb + n < i) {
            q_in.back() = i;
            ans[i] = query(q_in);
        } else if (lb < i && i < lb + n) {
            q_out.back() = i;
            ans[i] = query(q_out);
        }
    }
    cout << "! ";
