void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;

	vector<int> V;
	MINUS(A);
	FOR(i,2*N) C[i]=2;
	/*
	FOR(i,2*N) V.push_back(i);
	random_shuffle(ALL(V));
	ZERO(A);
	FOR(i,N) A[V[i]]=1;
	FOR(i,2*N) cout<<A[i];
	cout<<endl;
	*/

	vector<int> B;
	FOR(i,N) B.push_back(i);
	int pre=ask(B);
	int pov,a,b;
	for(i=N-1;i>=0;i--) {
		B.clear();
		FOR(x,i) B.push_back(x);
		FOR(x,N-i) B.push_back(2*N-1-x);
		sort(ALL(B));
		y=ask(B);
		if(y!=pre) {
			C[i]=pre;
			C[N+i]=y;
			a=pre,b=y;
			pov=i;
			break;
		}
	}


	for(i=pov+1;i<N+pov;i++) {
		B.clear();
		FOR(x,pov) B.push_back(x);
		FOR(x,N-pov-1) B.push_back(2*N-x);
		B.push_back(i);
		sort(ALL(B));
		y=ask(B);
		if(a==y) C[i]=C[pov];
		else C[i]=C[N+pov];


	}

	/*
	FOR(i,2*N) cout<<A[i];
	cout<<endl;
	FOR(i,2*N) cout<<C[i];
	cout<<endl;
	*/
	vector<int> NC;
	a=0,b=0;
	for(i=pov;i<=N+pov;i++) {
		if(C[i]==1) {
			if(a<N/2) {
				a++;
				NC.push_back(i);
			}
		}
		else {
			if(b<N/2) {
				b++;
				NC.push_back(i);
			}
		}
	}
	assert(NC.size()==N-1);
	FOR(i,2*N) {
		if(i>=pov && i<=N+pov) continue;
		B=NC;
		B.push_back(i);
		sort(ALL(B));
		C[i]=ask(B);
	}

	ans();

	FOR(i,2*N) cout<<A[i];
	cout<<endl;
	FOR(i,2*N) cout<<C[i];
	cout<<endl;


}


