int main() {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    cin >> n;

    int l = 0, r = n - 1;
    vector<int> vec(n); iota(vec.begin(), vec.end(), 0);
    bool val0 = query(vec);
    while (l < r) {
        int mid = (l + r + 1) >> 1;
        iota(vec.begin(), vec.end(), mid);
        bool val = query(vec);
        if (val != val0) r = mid - 1;
        else l = mid;
    }

    vector<bool> ans(n << 1);
    vector<int> base(n - 1);
    iota(base.begin(), base.end(), l + 1);
    for (int i = 0; i < (n << 1); ++i) if (i <= l || i >= l + n) {
        vector<int> tmp = base; tmp.emplace_back(i);
        ans[i] = query(tmp);
    }

    base.clear();
    for (int i = 0; i < (n << 1); ++i) if (i <= l || i >= l + n) {
        if (ans[i] && sz(base) < ( (n - 1) >> 1) ) base.emplace_back(i);
    }

    for (int i = 0; i < (n << 1); ++i) if (i <= l || i >= l + n) {
        if (!ans[i] && sz(base) < n - 1) base.emplace_back(i);
    }

    for (int i = l + 1; i < l + n; ++i) {
        vector<int> tmp = base; tmp.emplace_back(i);
        ans[i] = query(tmp);
    }

    cout << "! ";
    for (auto i : ans) cout << (i ? 'R' : 'B');
    cout << '\n'; cout.flush();

    return 0;
}

