            F.insert(F.end(), C0.begin(), C0.end());
            R = C1;
            B = C3;
        }
        if (a0=="Blue" && a1=="Blue")
        {
            //  F+C0+C1 = Red, F+C0+C3 = Blue, F+C2+C3 = Blue, F+C2+C1 = Blue
            F.insert(F.end(), C0.begin(), C0.end());
            R = C1;
            B = C3;
        }
    }

    //  0: red, 1: blue, 2: in F, 3: not in F
    vector<int> A(2*N, 3);
    for (int f: F)
        A[f] = 2;
    A[R[0]] = 0;
    A[B[0]] = 1;

    vector<int> iF;
    for (int i=0; i<2*N; i++)
        if (A[i]==3)
            iF.push_back(i);

    for (int i=0; i<2*N; i++)
        if (A[i]==2 ||  A[i]==3)
        {
            vector<int> Q = A[i]==2 ? iF : F;
            Q.push_back(i);
            A[i] = query(Q)=="Red" ? 0 : 1;
        }

    string ans;
    for (int a: A)
        ans += a==0 ? "R" : "B";
    cout<<"! "<<ans<<endl;
}

