int askInterval(int l, int r, int x)
{
    V.clear();
    if (r<l)
    {
        for (int i = l; i <= 2*n; i++)
            V.push_back(i);
        for (int i = 1; i <= r; i++)
            V.push_back(i);
    }
    else
