            V.push_back(i);
    }
    V.push_back(x);
    int ans = ask();
    return ans;
}

void askFinish(int x)
{
    int l = x;
    int r = x+n-2;
    for (int i=1; i<=2*n; i++)
    {
        if (!(l<=i && i<=r))
        {
            int ans = askInterval(l, r, i);
            Ans[i] = ans;
