int n;
vector<int> rest;
vector<pair<int, int>> ok;
vector<int> query;

int quest(vector<int> &c) {
  cout << "?";
  for (int i = 0; i < n; i++) cout << " " << c[i];
  cout << endl;
  string q;
  cin >> q;
  if (q == "Red") return true;
  if (q == "Blue") return false;
  exit(1);
  return true;
}

void solve() {
  vector<int> query;
  for (int i = 0; i < n; i++) query.push_back(rest[i]);
  int c = quest(query);
  int l = n, r = rest.size();
  while (r - l > 1) {
    query.clear();
    int m = (r + l) / 2;
    for (int i = m - 1; i >= m - n; i--) query.push_back(rest[i]);
    int c2 = quest(query);
    if (c == c2) {
      l = m;
    } else {
      r = m;
    }
  }
  ok.emplace_back(rest[l], 1 - c);
  ok.emplace_back(rest[l - n], c);
  rest.erase(rest.begin() + l);
  rest.erase(rest.begin() + l - n);
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cin >> n;
  for (int i = 0; i < 2 * n; i++) rest.push_back(i + 1);
  while (ok.size() < n) {
    solve();
  }
  vector<int> query;
  int c[2] = {0};
  for (int i = 0; i < ok.size(); i++) {
    if (c[ok[i].second] < n / 2) {
      query.push_back(ok[i].first);
      c[ok[i].second]++;
    }
  }
  for (int i = 0; i < rest.size(); i++) {
    vector<int> q2 = query;
    q2.push_back(rest[i]);
    int c = quest(q2);
    ok.emplace_back(rest[i], c);
  }
  vector<char> ans(2 * n);
  for (int i = 0; i < ok.size(); i++) {
    ans[ok[i].first - 1] = ok[i].second ? 'R' : 'B';
  }
  cout << "! ";
  for (int i = 0; i < 2 * n; i++) cout << ans[i];
  cout << endl;

  return 0;
}

