void solve() {
  int n; cin >> n;

  string ans;
  ans.resize(2*n, 'x');
  const int red = 0, blue = 1;
  vi pos(2, -1);
  int know;
  vector<P> hist;
  hist.push_back(P(n+1, -1));
  hist.push_back(P(1, -1));

  while (1) {
    int idx = hist.back().first;
    int &color = hist.back().second;
    cout << '?';
    rep(i,n) cout << ' ' << idx+i;
    cout << endl;

    string t; cin >> t;
    if (t == "Red") {
      color = red;
    } else if (t == "Blue") {
      color = blue;
    } else {
      return;
    }

    if (hist.size() == 2) {
      hist.front().second = 1-color;
      pos[1-color] = n+1;
    }

    if (abs(idx-pos[1-color]) == 1) {
      if (idx < pos[1-color]) {
        know = idx;
        ans[idx-1] = color == red ? 'R' : 'B';
        ans[idx-1+n] = 1-color == red ? 'R' : 'B';
      } else {
        know = pos[1-color];
        ans[pos[1-color]-1] = 1-color == red ? 'R' : 'B';
        ans[pos[1-color]-1+n] = color == red ? 'R' : 'B';
      }
      break;
    }

    pos[color] = idx;
    hist.push_back(P((idx+pos[1-color])/2, -1));
  }

  Graph question(2, vi(n-1));
  rep(i,n-1) {
    question[0][i] = know+i+1;
    question[1][i] = know+n+i+1;
    if (question[1][i] > 2*n) question[1][i] -= 2*n;
  }

  rep(i,2) {
    for (auto p : question[i]) {
      cout << '?' << ' ' << know << ' ' << know+n;
      for (auto q : question[i]) {
        if (p != q) cout << ' ' << q;
      }
      cout << endl;

      string t; cin >> t;
      if (t == "Red") {
        ans[p-1] = 'B';
      } else if (t == "Blue") {
        ans[p-1] = 'R';
      } else {
        return;
      }
    }
  }

  cout << "! " << ans << endl;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(12);
  solve();
  return 0;
}

