#define rep(i,n) REP((i),0,(n))
using ll = long long;

int N;

bool isRed(const vector<int>& v) {
    assert(v.size() == N);
    cout << "?";
    for (auto num : v)cout << " " << (num + 1);
    cout << endl;

    string s;
    cin >> s;
    return s == "Red";
}

bool isChange(const int idx, const bool base) {
    vector<int> v;
    rep(i, N)v.push_back(idx + i);
    return isRed(v) != base;
}

int changeIdx(const bool base, vector<int>& v) {
    int l = 0, r = N;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        (isChange(mid, base) ? r : l) = mid;
    }
    while (isChange(l, base))l--;
    return l + 1;
}

int main()
{
    cin >> N;
    vector<int> v;
    rep(i, N)v.push_back(i);

    bool baseRed = isRed(v);
    const int change = changeIdx(baseRed, v);

    vector<int> res(2 * N, -1);
    vector<int> normal, next;
    rep(i, N - 1)normal.push_back(i + change);

    rep(i, change) {
        normal.push_back(i);
        res[i] = isRed(normal) ? 1 : 0;
        normal.pop_back();
    }
    REP(i, change + N, 2 * N) {
        normal.push_back(i);
        res[i] = isRed(normal) ? 1 : 0;
        normal.pop_back();
    }

    int bcnt = (N - 1) / 2;
    int rcnt = (N - 1) / 2;
    rep(i, 2 * N) {
        if (res[i] == 0) {
            if (bcnt <= 0)continue;
            bcnt--;
            next.push_back(i);
        }
        if (res[i] == 1) {
            if (rcnt <= 0)continue;
            rcnt--;
            next.push_back(i);
        }
    }
    assert(next.size() == N - 1);
    rep(i, 2 * N)if (res[i] == -1) {
        next.push_back(i);
        res[i] = isRed(next) ? 1 : 0;
        next.pop_back();
    }
    cout << "! ";
    for (bool isred : res) {
        cout << (isred ? "R" : "B");
    }
    cout << endl;
    return 0;
}

