	INIT;

	VAR(int, n);

	std::string ans(n * 2, '~');

	V<int> a(n);
	std::iota(ALL(a), 0);

	std::string first = query(a);
	V<int> b;
	int p = n;
	while (true) {
		int from = a.back();
		a.pop_back();
		int to = p;
		b.emplace_back(p++);
		std::string res = query(a, b);
		if (first == res) continue;

		ans[from] = first[0];
		ans[to] = res[0];

		b.pop_back();
		std::set<int> used;
		for (auto& x : a) used.emplace(x);
		for (auto& x : b) used.emplace(x);
		REP(i, n * 2) {
			if (used.count(i)) continue;
			if (ans[i] != '~') continue;

			b.emplace_back(i);
			res = query(a, b);
			ans[i] = res[0];
			b.pop_back();
		}
		break;
	}

	int cnt[2] = {};
	a.resize(0);
	REP(i, n * 2) {
		if (ans[i] == 'R' && cnt[0] < n / 2) a.emplace_back(i), ++cnt[0];
		if (ans[i] == 'B' && cnt[1] < n / 2) a.emplace_back(i), ++cnt[1];
	}

	REP(i, n * 2) {
		if (ans[i] != '~') continue;
		a.emplace_back(i);
		std::string res = query(a);
		ans[i] = res[0];
		a.pop_back();
	}

	end(ans);

	return 0;
}

