void check(int x){
    cout << "? ";
    for (int i = x; i < n+x; i++){
        cout << i << " ";
    }
    cout << endl;
    int verdict = getverdict();
    if (last != -1 && verdict != last){
        done = true;
        ans[x+n-1] = verdict;
        ans[x-1] = last;
        for (int i = x; i < n+x-1; i++){
            guaranteed.push_back(i);
            iscurg[i] = true;
        }
    }
    last = verdict;
}
int getAnswer(int x){
    cout << "? ";
    for (auto k : guaranteed) cout << k << " ";
    cout << x;
    cout << endl;
    int verdict = getverdict();
    if (verdict == 0 && (int)red.size() < n/2) red.push_back(x);
    if (verdict == 1 && (int)blue.size() < n/2) blue.push_back(x);
    return verdict;
}
