int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int N; cin >> N;

  vector<char> ans(2*N, 0);
  set<int> exacts;
  set<int> cands;
  for (int i = 0; i < 2*N; i++)
    cands.insert(i);

  auto request = [&](int f) -> tuple<bool, int, int> {
    auto list = exacts;
    auto it = cands.begin();
    for (int i = 0; i < f; i++)
      ++it;
    auto front = *it;
    auto back = *it;
    for (; list.size() < N; it = (++it == cands.end() ? cands.begin() : it)) {
      list.insert(*it);
      back = *it;
    }

    cout << "? ";
    for (auto a : list)
      cout << a << " ";
    cout << endl;

    string s; cin>>s;
    return make_tuple(s == "Red", front, back);
  };

  while (not cands.empty()) {
    auto p = request(0);
    bool prev_rb = get<0>(p);
    int prev_front = get<1>(p);
    int i = 1;
    while (true) {
      auto p = request(i);
      bool rb = get<0>(p);
      int front = get<1>(p);
      int back = get<2>(p);
      if (rb != prev_rb) {
        ans[prev_front] = rb ? 'B' : 'R';
        ans[back] = rb ? 'R' : 'B';
        if (exacts.size() <= N - 3) {
          exacts.insert(prev_front);
          exacts.insert(back);
        }
        cands.erase(prev_front);
        cands.erase(back);
        break;
      }
      prev_front = front;
      prev_rb = rb;
    }
  }

  cout << "! ";
  for (auto c : ans)
    cout << c;
  cout << endl;

  return 0;
}

