int main(){
    int N;
    cin>>N;

    vector<int> reds,blues;
    vector<int> v;
    rep(i,N) v.push_back(i);
    int lef=query(v);
    int rig=3-lef;
    int ok=N,ng=0;
    while(abs(ok-ng)>1){
        int mid=(ok+ng)/2;
        vector<int> v;
        rep(i,N) v.push_back(mid+i);
