    v.clear();
    for(int i=0;i<N-1;i++) v.push_back(ok+i);

    for(int i=0;i<2*N;i++){
        if(ng<=i&&i<=ng+N) continue;
        v.push_back(i);
        int c=query(v);
        if(c==1) reds.push_back(i);
        else blues.push_back(i);
        v.pop_back();
    }

    v.clear();
    for(int i=0;i<N/2;i++){
        v.push_back(reds[i]);
        v.push_back(blues[i]);
    }
    for(int i=ng+1;i<ng+N;i++){
        v.push_back(i);
