        if(c==1) reds.push_back(i);
        else blues.push_back(i);
        v.pop_back();
    }

    string ans(2*N,'p');
    rep(i,N){
        ans[reds[i]]='R';
        ans[blues[i]]='B';
    }
    cout<<"! "<<ans<<endl;

  return 0;
}

