char solve(int x, int l, int r) {
    char ret = ' ';
    if(l <= x && x <= r) {
        vector<int> v;
        FOR(i, l, r + 1) {
            if(i == x) continue;
            else v.pb(i);
        }
        cout << "? ";
        cout << v << endl;
        string str;
        cin >> str;
        if(str == "Red") ret = 'B';
        else ret = 'R';
    } else {
        vector<int> v;
        v.pb(x);
        FOR(i, l + 1, r) v.pb(i);
        cout << "? ";
        cout << v << endl;
        string str;
        cin >> str;
        ret = str[0];
    }
    return ret;
}

