int main(int argc, char* argv[]){
  if(argc==2){
    debug = true;
    ans_debug = string(argv[1]);
  }

  int n;
  cin>>n;

  if(n==1) {
    bool r = ask({0});
    if(r) cout << "! RB";
    else cout << "! BR";
    cout << endl;
    return 0;
  }

  int RED = 1;
  int BLK = 0;
  int UK = -1;
  vector<int> ans(2*n, UK);
  // find half set
  vector<int> h1,h2;

  auto f = [&](int i) {
    vector<int> cand;
    rep(j,n) cand.pb(i+j);
    return ask(cand);
  };

  int l=0, r=n;
  bool il = f(0);
  bool ir = !il;
  while(r-l>1) {
    int m = (l+r)/2;
    bool im = f(m);
    if(il == im) l = m;
    else r = m;
  }

  rep(i,n-1) h1.pb(l+i+1);

  rep(i,n-1) h2.pb((n+r+i)%(2*n));

  ans[l] = (il ? RED : BLK);
  ans[n+l] = (il ? BLK : RED);

  rep(i,2*n) if(ans[i] == UK){
    bool use_h1 = true;
    for(auto x : h1) if(x == i) use_h1 = false;
    vector<int> q = (use_h1) ? h1 : h2;
    q.pb(i);
    bool rep = ask(q);
    ans[i] = rep ? RED : BLK;
  }

  cout << "! ";
  rep(i,2*n) cout << (ans[i] == RED ? "R" : "B");
  cout << endl;

  return 0;
}

