int main(){
    int n;
    cin >> n;
    string prev = query(1, n + 1);
    vector<char> ans(2 * n + 1, 'N');
    int l, r;

    for (int i = 2; i <= n + 1; i++){
        string res = query(i, i + n);
        if (prev == res)
            continue;
        l = i;
        r = i + n - 1;
        ans[i - 1] = query_to_ans(prev);
        ans[i + n - 1] = query_to_ans(res);
        break;
    }

    for (int i = 1; i <= 2 * n; i++){
        if (i == l){
            i = r - 1;
            continue;
        }
        if (ans[i] != 'N')
            continue;

        string res = query(l, r, i);
        ans[i] = query_to_ans(res);
    }

    for (int i = 1; i <= 2 * n; i++){
        if (ans[i] == 'N')
            continue;

        if (ans[i] == 'B' and B.size() < n / 2)
            B.push_back(i);
        else if (ans[i] == 'R' and R.size() < n / 2)
            R.push_back(i);
    }

    for (int i = l; i < r; i++){
        string res = query_br(B, R, i);
        ans[i] = query_to_ans(res);
    }

    cout << "! ";
    for (int i = 1; i <= 2 * n; i++)
        cout << ans[i];
    cout << endl;
}

