/*!* [binsearch] *!*/
/*+* 二分探索 *+*/
// judge を満たすような下限を求める
// l:[X] 定義域外部の上限
// r:[X] 定義域外部の下限
// judge:[X -> bool] X を評価する関数
// lower:[bool] falseにすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X>
X BinSearch(X l, X r, function<bool(X)> judge, bool lower = true, X eps = 1) {
    while (r - l > eps) {
        X m = (r + l) / 2;
        if (judge(m) == lower) {
            r = m;
        } else {
            l = m;
        }
    }
    return lower ? r : l;
}

const int RED = 1, BLUE = -1;

int query(vector<int> &q) {
    cout << "?";
    for(int x : q) cout << " " << x + 1;
    cout << endl;
    string ans;
    cin >> ans;
    return ans == "Red" ? RED : BLUE;
}

int main() {
    int N;
    cin >> N;
    vector<int> v(N), u1(N - 1), u2(N - 1), ans(2 * N);
    int L, R;

    for (int j = 0; j < N; j++) v[j] = j;
    L = query(v);
    R = -L;

    // query logN times 
    int i = BinSearch<int>(-1, N, [&](int k) {
        for(int j = 0; j < N; j++) v[j] = j + k;
        return query(v) == L;
    }, false);

    for(int j = 0; j < N; j++) {
        u1[j] = i + j;
        u2[j] = (i + N + j) % (2 * N);
    }
    // query 2N times
    for(int k = 0; k < 2 * N; k++) {
        for (int j = 0; j < N - 1; j++) {
            v[j] = (i <= k && k < i + N) ? u2[j] : u1[j];
        }
        v[N - 1] = k;
        ans[k] = query(v);
    }
    cout << "! ";
    for(int x : ans) cout << (x == RED ? "R" : "B");
    cout << endl;
    return 0;
}

