    r = n + 1;
    while (l + 1 < r)
    {
        m = (l + r) / 2;
        if (query(m) == val)
            l = m;
        else
            r = m;
    }
    //cout << l << " : " << r << endl;
    pos = r;

    ans[pos - 1] = val;
    ans[pos + n] = !ans[pos + n];
    vector<int> x;
    for (int i = pos; i < pos + n - 1; i++)
        x.PB(i);

    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n && i >= pos - 1)
            continue;
        x.PB(i);
        ans[i] = query(x);
        x.pop_back();
    }
    x.clear();

    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n - 1 && i >= pos)
            continue;
        if (ans[i] == 0 && x.size() < (n - 1) / 2)
            x.PB(i);
    }
    for (int i = 1; i <= n + n; i++)
    {
        if (i < pos + n - 1 && i >= pos)
            continue;
        if (ans[i] == 1 && x.size() < (n - 1))
            x.PB(i);
    }

    for (int i = 1; i <= n + n; i++)
