int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);
    int N; cin >> N;
    int type = query2(N, 1);
    int lo = 1, hi = N + 1;
    while (abs(lo - hi) > 1) {
        int mid = (lo + hi) / 2;
        if (query2(N, mid) == type) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    vector<int> even(N - 1); iota(begin(even), end(even), hi);
    vector<int> even2;
    for (int i = 1; i <= 2 * N; i++) {
        if (i < lo || hi + N - 1 < i) even2.push_back(i);
    }
    vector<int> ans(2 * N);
    for (int i = 1; i <= 2 * N; i++) {
        if (find(begin(even), end(even), i) == end(even)) {
            even.push_back(i);
            ans[i - 1] = query(even);
            even.pop_back();
        } else {
            even2.push_back(i);
            ans[i - 1] = query(even2);
            even2.pop_back();
        }
    }
    answer(ans);
    return 0;
}

