        v[i] = i;

    vector<bool> isRed(2*n, false);
    for(;;){
        xorshift.shuffle(v);
        bool a = query(v, n);
        swap(v[0], v[n]);
        bool b = query(v, n);
        if(a != b){
            if(a)
                swap(v[0], v[n]);
            isRed[v[0]] = true;
            break;
        }
    }

    for(int i=1; i<n; ++i){
        swap(v[i], v[n]);
        if(!query(v, n))
            isRed[v[n]] = true;
        swap(v[i], v[n]);
    }
    for(int i=n+1; i<2*n; ++i){
        swap(v[0], v[i]);
        if(query(v, n))
            isRed[v[0]] = true;
        swap(v[0], v[i]);
