        string val_left = askSegment(left);
        string val_right = askSegment(right);

        while (right - left > 1) {
            int mid = (left + right) / 2;
            string res = askSegment(mid);

            if (res == val_left) {
                left = mid;
            } else {
                right = mid;
            }
