  if (buf[0] == 'B') return blue;
  assert(false);
  return 0;
}

void next(size_t& i, size_t n) {
  n += n;
  if (++i == n) i = 0;
}

void answer(std::vector<int> const& res) {
  printf("! ");
  for (size_t i = 0; i < res.size(); ++i) {
    printf("%c", ((res[i] == red)? 'R': 'B'));
  }
  puts("");
  fflush(stdout);
}

int main() {
  size_t n;
  scanf("%zu", &n);

  std::vector<int> res(n+n);
  std::deque<size_t> q;

  if (n == 1) {
    q.push_back(0);
    res[0] = query(q);
    q.pop_back();
    q.push_back(1);
    res[1] = query(q);
    answer(res);
    return 0;
  }

  std::mt19937 rsk(0315);
  std::uniform_int_distribution<size_t> neko(0, n+n-1);
  size_t i = neko(rsk);
  for (size_t j = 0; j < n; ++j) {
    q.push_back(i);
    next(i, n);
  }

  int last = query(q);
  if (i >= n+n) i -= n;
  while (true) {
    q.pop_front();
    q.push_back(i);
    int cur = query(q);
    if (last != cur) break;
    next(i, n);
  }

  // fprintf(stderr, "[%zu]: %d\n", (i+n)%(n+n), last);
  // fprintf(stderr, "[%zu]: %d\n", i, -last);

  res[(i+n)%(n+n)] = last;
  res[i] = -last;

  next(i, n);
  while (res[i] == 0) {
    q.pop_back();
    q.push_back(i);
    res[i] = query(q);
    next(i, n);
  }
  q.clear();
  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == blue) {
      q.push_back(i);
      if (q.size() == n/2) break;
    }
  }
  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == red) {
      q.push_back(i);
      if (q.size() == n-1) break;
    }
  }
  assert(q.size() == n);

  for (size_t i = 0; i < n+n; ++i) {
    if (res[i] == 0) {
      q.push_back(i);
      res[i] = query(q);
      q.pop_back();
    }
  }
  answer(res);
  int bal = 0;
  for (auto r: res) {
    assert(r != 0);
    bal += r;
  }
  assert(bal == 0);
}

