    int n, c, x, l, r, m, i, j;
    vector <int> v, w;

    scanf("%d", &n);

    for (i = 1; i <= n * 2; i++) v.push_back(i);

    for (i = 0; i < n; i++) w.push_back(v[i]);
    c = ask(w);

    l = 0, r = n, m = (l + r) / 2;

    while (r - l > 1) {
        vector <int> z;

        for (i = m; i < m + n; i++) z.push_back(v[i]);

