	while(std::abs(L - R)) {
		int mid = (L + R) >> 1;

		auto ret = query(get_segment(mid, n, 0, 0));
		if(now == ret) L = mid;
		else R = mid;
	}

	// 1
	int bound = (query(get_segment(L, n, 0, 0)) != now ? L - 1 : L); count++;
	// [bound, bound + n) != [bound + 1, bound + n + 1)
	// [bound, bound + n) == now

