void solve(int l, char l_color, char r_color) {
    vector<char> ans(2 * N, '.');
    ans[l] = l_color;
    ans[(l + N) % (2 * N)] = r_color;
    FOR(i, 1, N) {
        cout << "?"
             << " " << l + 1 << " " << (l + N) % (2 * N) + 1;
        FOR(j, 1, N) {
            if (i == j) continue;
            cout << " " << (l + j) % (2 * N) + 1;
        }
        cout << endl;
        string T;
        cin >> T;
        if (T == "Red") {
            ans[(l + i) % (2 * N)] = 'B';
        } else {
            ans[(l + i) % (2 * N)] = 'R';
        }
    }
    // 中のN-1個を使ってほかを探す
    FOR(i, 0, 2 * N) {
        if (ans[i] != '.') continue;
        cout << "?";
        FOR(j, 1, N) {
            cout << " " << (l + j) % (2 * N) + 1;
        }
        cout << " " << i + 1;
        cout << endl;
        string T;
        cin >> T;
        ans[i] = (T == "Red" ? 'R' : 'B');
    }
    cout << "!";
    for (auto c : ans) cout << c;
    cout << endl;
}

