    x = n;
    for (i = 1; i < n; i++) {
        vector <int> z;

        for (j = i; j < i + n; j++) z.push_back(v[j]);

        if (ask(z) != c) {
            x = i;
            break;
        }
    }

    ans[x - 1] = c;
    ans[x + n - 1] = 1 - c;

    for (i = x; i < x + n - 1; i++) {
        vector <int> z;

        for (j = x - 1; j <= x + n - 1; j++) {
            if (j == i) continue;
            z.push_back(v[j]);
