int main(){

    memset(a, -1, sizeof a);

    scanf("%d", &n);
    if(n == 1){
        printf("? 1\n");
        fflush(stdout);
        scanf("%s", str);
        printf("! %c %c\n", str[0], (str[0] == 'R') ? 'B': 'R');
        fflush(stdout);
