        ans[i] = (str[0] == 'R');

        if(i > 1 && ans[i] != ans[i-1]){
            //printf("found\n");
            a[i-1] = ans[i-1];
            a[i+n-1] = ans[i];
            s[ans[i-1]].push_back(i-1);
            s[ans[i]].push_back(i+n-1);

            //now solve the rest
            for(int j = 1; j <= 2*n; j++){
                if(j < i-1 || j > i+n-1){

                    printf("? %d", j);
                    for(int k = i; k < i+n-1; k++)
