vector<int> get_range(int l, int r) {
    vector<int> res;
    rep(i, l, r) {
        res.push_back(i);
    }
    return res;
}

int main()
{
    //freopen("a.in", "r", stdin);
    //freopen("a.out", "w", stdout);
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.precision(20);
    //ll TL = 10.95 * CLOCKS_PER_SEC;
    //clock_t time = clock();
    int n;
    cin >> n;
    if (n == 1) {
        vector<int> ans(n * 2, 0);
        rep(i, 0, n * 2) {
            ans[i] = ask({i});
        }
        answer(ans);
    }
    int segm[n + 1];
    rep(i, 0, n) {
        segm[i] = ask(get_range(i, i + n));
    }
    segm[n] = -segm[0];
    vector<int> ans(n * 2, 0);
    int L, R;
    rep(i, 0, n) {
        if (segm[i] != segm[i + 1]) {
            if (segm[i] == 1 && segm[i + 1] == -1) {
                ans[i] = 1;
                ans[i + n] = -1;
            } else {
                ans[i] = -1;
                ans[i + n] = 1;
            }
            L = i; R = i + n;
            break;
        }
    }
    vector<int> pos1, pos2;
    rep(i, 0, n * 2) {
        if (i < L || i > R) {
            pos1.push_back(i);
        } else if (i > L && i < R) {
            pos2.push_back(i);
        }
    }
    rep(i, 0, n * 2) {
        if (i == L || i == R) {
            continue;
        }
        if (i < L || i > R) {
            pos2.push_back(i);
            ans[i] = ask(pos2);
            pos2.pop_back();
        } else {
            pos1.push_back(i);
            ans[i] = ask(pos1);
            pos1.pop_back();
        }
    }
    answer(ans);
    return 0;
}

