int cnt;
int query(const VI &v) {
    assert((int)v.size() == N);
    REP (i, v.size()) REP (j, i) assert(v[i] != v[j]);
    REP (i, v.size()) assert(0 <= v[i] && v[i] < N*2);

    printf("?");
    REP (i, v.size()) printf(" %d", v[i] + 1);
    puts("");
    fflush(stdout);

#ifdef MYTEST
    cnt++;
    eprintf("cnt %d\n", cnt);
    int b = 0, r = 0;
    EACH (e, v) {
	if (S[*e] == 'R') r++;
	else b++;
    }
    assert(r + b == N);
    return b > r;
#else
    static char buf[111];
    scanf("%s", buf);
    assert(*buf != '-');
    return *buf == 'B';
#endif
}

int range_query(int s) {
    VI v;
    REP (i, N) v.push_back(s+i);
    return query(v);
}

void MAIN() {
    init();
    memset(A, -1, sizeof A);

    scanf("%d", &N);

    int c = range_query(0);

    // q[0] == c;
    // q[N] == 1-c;
    int lo = 0, hi = N;
    while (hi - lo > 1) {
	int mid = (lo + hi) / 2;
	int d = range_query(mid);
	if (d == c) lo = mid;
	else hi = mid;
    }

    A[lo] = c;
    A[lo+N] = 1 - c;
    VI v;
    for (int i=lo+1; i<lo+1+N; i++) v.push_back(i);

    REP (i, N*2) {
	if (i < lo || lo+N < i) {
	    v.back() = i;
	    A[i] = query(v);
	}
    }

    v.clear();
    REP (i, N*2) if ((int)v.size() < N/2 && A[i] == 0) v.push_back(i);
    REP (i, N*2) if ((int)v.size() < N-1 && A[i] == 1) v.push_back(i);
    v.push_back(-100);

    REP (i, N*2) {
	if (A[i] == -1) {
	    v.back() = i;
	    A[i] = query(v);
	}
    }

    printf("! ");
    REP (i, N*2) printf("%c", "RB"[A[i]]);
    puts("");
    fflush(stdout);
}


int main() {
    int TC = 1;
