typedef pair <ll,ll>      pl;
typedef tuple <ll,ll,ll>  tl;

int N, lower, upper, maxfr, el, er, rc, bc;
char fr, ans[205];
vector <int> q_para;

char q_range() {
	cout << "?";
	for (int x : q_para) cout << " " << x;
	cout << endl;
	string ret;
	cin >> ret;
	return (ret.compare("Red") == 0 ? 'R' : 'B');
}

int main() {

	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	cin >> N;

	q_para.clear();
	for (int i = 1; i <= N; i++) q_para.push_back(i);
	fr = q_range();

	lower = 1;
	upper = N+1;
	maxfr = 1;

	while (upper - lower > 1) {
		int test = (lower + upper) / 2;
		q_para.clear();
		for (int i = 0; i < N; i++) q_para.push_back(test + i);
		char re = q_range();
		if (fr == re) {
			maxfr = max(maxfr, test);
			lower = test;
		} else upper = test;
	}

	el = maxfr + 1;
	er = maxfr + N - 1;
	q_para.clear();
	for (int i = el; i <= er; i++) q_para.push_back(i);
	for (int i = 1; i <= 2 * N; i++) {
		if (el <= i && i <= er) continue;
		q_para.push_back(i);
		ans[i] = q_range();
		q_para.pop_back();
	}

	q_para.clear();
	rc = (N - 1) / 2;
	bc = (N - 1) / 2;
	for (int i = 1; i <= 2 * N; i++) {
		if (el <= i && i <= er) continue;
		if (ans[i] == 'R' && rc > 0) {
			q_para.push_back(i);
			rc--;
		} else if (ans[i] == 'B' && bc > 0) {
			q_para.push_back(i);
			bc--;
		}
	}

	for (int i = el; i <= er; i++) {
		q_para.push_back(i);
		ans[i] = q_range();
		q_para.pop_back();
	}

	cout << "! ";
	for (int i = 1; i <= 2 * N; i++) {
		cout << ans[i];
	}

    return 0;
}

