  vector<i64> blue(N);
  vector<i64> red(N);
  rep(i,0,N) blue[i] = i + 1;
  rep(i,0,N) red[i] = N + i + 1;

  vector<char> ans(2 * N);

  {
    auto s = query(blue);
    if(s == "Red") {
      swap(blue, red);
    }
  }

  i64 ok = N;
  i64 ng = 0;
  while(ok - ng > 1) {
    i64 mid = (ok + ng) /2;
    rep(i,0,mid) {
      swap(red[i], blue[i]);
    }
    if(query(blue) == "Red") {
