  	bool lst = query(0);
  	RE(i,n){
  		bool nw = query(i);
  		if(nw == lst){
  			lst = nw;
  			continue;
  		}
  		ans[order[i+n-1]] = nw;
  		ans[order[i-1]] = lst;
  		for(int k = i;k < i+n-1;k++){
  			crucial.pb(order[k]);
