  				nsg.pb(order[k]);
  				eh[k] = 2;
  			}
  		}
  		break;
  	}
  	REP(i,2*n){
  		if(!eh[i])continue;
  		if(eh[i] == 2){
  			ans[order[i]] = find(i);
  		}
  		else{
  			ans[order[i]] = find1(i);
