   cur.clear ();
   memset (res, -1, sizeof res);
   if (n == 1) {
      cur.pb (1);
      if (ask (cur)) res[1] = 1, res[2] = 0;
      else res[1] = 0, res[2] = 1;
      cout << "! ";
      for (int i = 1; i <= 2; i ++) cout << (res[i] ? "R" : "B");
      exit (0);
   }
   for (int i = 1; i <= n + 1; i ++) {
      cur.clear ();
      for (int j = i; j <= i + n - 1; j ++) cur.pb (j);
      ans[i] = ask (cur);
      if (i > 1 && ans[i] != ans[i - 1]) {
         int l = i, r = i + n - 2;  
         if (ans[i]) res[i - 1] = 0, res[i + n - 1] = 1;
         else res[i - 1] = 1, res[i + n - 1] = 0;
         cur.clear ();
         for (int k = l; k <= r; k ++) cur.pb (k); 
         for (int j = 1; j < l - 1; j ++) {
            cur.pb (j);
            if (ask (cur)) res[j] = 1;
            else res[j] = 0;
            cur.ppb ();    
         }
         for (int j = r + 2; j <= 2 * n; j ++) {
            cur.pb (j);
            if (ask (cur)) res[j] = 1;
            else res[j] = 0;
            cur.ppb ();    
         }
         cur.clear ();
         int red = n / 2, blue = n / 2;
         for (int i = 1; i <= n + n; i ++) {
            if (res[i] != -1) {
               if (res[i] && red > 0) red --, cur.pb (i);
               if (!res[i] && blue > 0) blue --, cur.pb (i);  
            }
         }
         assert (red == 0 && blue == 0);
         for (int j = l; j <= r; j ++) {
            cur.pb (j);
            if (ask (cur)) res[j] = 1;
            else res[j] = 0;
            cur.ppb ();        
         }
         cout << "! ";
         for (int i = 1; i <= n + n; i ++) cout << (res[i] ? "R" : "B");
         exit (0);
      }              
   }
}

