int find_trans(int N) {
    vi balls(N);
    for (int j=0;j<N;j++) balls[j] = j;
    int left_val = query(balls);

    int left = 0;
    int right = N;

    while (right - left > 1) {
        int mid = (left + right) / 2;
        for (int j=0;j<N;j++) balls[j] = mid+j;
        int cur = query(balls);

        if (cur == left_val) {
            left = mid;
        } else {
            right = mid;
        }
    }
    return right;
}

