pair<int, int> first() {
    int lb = 0, ub = N;
    vector<int> q(N);
    iota(ALL(q), 0);
    int l = query(q);
    iota(ALL(q), N);
    int r = query(q);
    while (abs(ub - lb) > 1) {
        const int mid = (lb + ub) / 2;
        iota(ALL(q), mid);
        int m = query(q);
        if (m == l)
            lb = mid;
        else
            ub = mid;
    }
    return {ub, r};
}

