    auto reqlist = exacts;
    int i = f;
    auto back = i;
    while (reqlist.size() < M) {
      if (sexacts.count(i) > 0) {
        i = (i+1)%(2*M);
        continue;
      }
      reqlist.push_back(i);
      if (ans[i] != 0)
        back = i;
      i = (i+1)%(2*M);
