    std::string s; cin>>s;
    return make_pair(s == "Red", back);
  };
  auto p = request(0);
  prev_rb = p.first;
  int cnt = 0;
  while (cnt < 2*M) {
    if (ans[i] != 0) {
      i = (i+1)%(2*M);
      continue;
    }
    auto p = request(i);
    auto rb = p.first;
