int main(int argc, char* argv[]){
  if(argc==2){
    debug = true;
    ans_debug = string(argv[1]);
  }

  int n;
  cin>>n;

  if(n==1) {
    bool r = ask({0});
    if(r) cout << "! RB";
    else cout << "! BR";
    cout << endl;
    return 0;
  }

  int RED = 1;
  int BLK = 0;
  int UK = -1;
  vector<int> ans(2*n, UK);
  // find half set
  int prev = UK;
  vector<int> h1,h2;

  rep(i,n) {
    vector<int> cand;
    rep(j,n-i) cand.pb(j);
    rep(j,i) cand.pb(n+j);
    bool rep = ask(cand);
    if(prev == UK) prev = rep;
    else if(prev != rep) {
      rep(j,n-i) h1.pb(j);
      rep(j,i-1) h1.pb(n+j);

      rep(j,n-i+1,n) h2.pb(j);
      rep(j,i,n) h2.pb(n+j);
      if(prev && !rep) {
        ans[n-i] = RED;
        ans[n+i-1] = BLK;
      } else {
        ans[n-i] = BLK;
        ans[n+i-1] = RED;
      }
      break;
    }
  }
  if(h1.size() == 0) {
    rep(i,1,n) h1.pb(i);
    rep(i,n-1) h2.pb(i+n);
    ans[0] = (prev ? RED : BLK);
    ans[2*n-1] = (prev ? BLK : RED);
  }

  rep(i,2*n) if(ans[i] == UK){
    bool use_h1 = true;
    for(auto x : h1) if(x == i) use_h1 = false;
    vector<int> q = (use_h1) ? h1 : h2;
    q.pb(i);
    bool rep = ask(q);
    ans[i] = rep ? RED : BLK;
  }

  cout << "! ";
  rep(i,2*n) cout << (ans[i] == RED ? "R" : "B");
  cout << endl;


  return 0;
}

