class EMajorityOfBalls {
public:
    void solve(istream& cin, ostream& cout) {
        int N; cin >> N;
        cout << "?";
        for (int i = 1; i <= N; ++i) cout << ' ' << i;
        cout << endl;
        string Init, Cur; cin >> Init;
        int b = 2;
        while (true) {
            cout << "?";
            for (int i = 0; i < N; ++i) cout << ' ' << b+i;
            cin >> Cur;
            if (Cur != Init) break;
            ++b;
        }

        string Ans(2*N, '?');
        Ans[b-1-1] = Init[0];
        Ans[b+N-1-1] = Cur[0];
        for (int j = 1; j <= 2*N; ++j) {
            if (j <= b || j >= b+N) {
                cout << "? " << j;
                for (int i = 1; i < N; ++i) cout << ' ' << b + i;
                cout << endl;
                cin >> Cur;
                Ans[j - 1] = Cur[0];
            }
        }

        for (int j = b+1; j < b+N; ++j) {
            cout << "? " << j;
            int r = N/2, b = N/2;
            for (int i = 0; i < 2*N; ++i) {
                if (Ans[i] == 'R' && r) {
                    --r;
                    cout << ' ' << i+1;
                } else if (Ans[i] == 'B' && b) {
                    --b;
                    cout << ' ' << i+1;
                }
            }
            cout << endl;
            cin >> Cur;
            Ans[j-1] = Cur[0];
        }

        cout << "! " << Ans;

    }
};



