namespace Problem {
using namespace std;

class Solver {
 public:
  int n;
  Solver(LL n) : n(n){};

  void solve() {
    set<int> a;
    vector<int> b, c;
    for (int i = 1; i <= n; ++i) {
      a.insert(i);
    }
    if (queryR(a)) {
      for (int i = 1; i <= n / 2; ++i) {
        b.push_back(i);
      }
      for (int i = n + 1; i <= n + n / 2; ++i) {
        c.push_back(i);
      }
      if (!checkB(a, b, c)) {
        b.clear();
        c.clear();
        for (int i = n / 2 + 1; i <= n; ++i) {
          b.push_back(i);
        }
        for (int i = n + n / 2 + 1; i <= n + n; ++i) {
          c.push_back(i);
        }
      }
    } else {
      a.clear();
      for (int i = n + 1; i <= n * 2; ++i) {
        a.insert(i);
      }
      for (int i = n + 1; i <= n + n / 2; ++i) {
        b.push_back(i);
      }
      for (int i = 1; i <= n / 2; ++i) {
        c.push_back(i);
      }
      if (!checkB(a, b, c)) {
        b.clear();
        c.clear();
        for (int i = n + n / 2 + 1; i <= n + n; ++i) {
          b.push_back(i);
        }
        for (int i = n / 2 + 1; i <= n; ++i) {
          c.push_back(i);
        }
      }
    }
    while (b.size() > 1) {
      DBG(b, c)
      int sz = b.size() / 2;
      vector<int> B, C;
      for (int i = 0; i < sz; ++i) {
        B.push_back(b[b.size() - 1 - i]);
        C.push_back(c[c.size() - 1 - i]);
      }
      if (checkB(a, B, C)) {
        b = B;
        c = C;
      } else {
        for (int i = 0; i < sz; ++i) {
          b.pop_back();
          c.pop_back();
        }
      }
    }
    DBG(a, b, c)
    vector<int> ans(2 * n + 1, -1);
    ans[b[0]] = 1;
    ans[c[0]] = 0;

    for (auto x : a) {
      if (x == b[0]) continue;
      vector<int> t1 = {x};
      vector<int> t2 = {c[0]};

      if (checkB(a, t1, t2))
        ans[x] = 1;
      else
        ans[x] = 0;
    }

    set<int> a2;
    for (int i = 1; i <= 2 * n; ++i) {
      if (!a.count(i)) a2.insert(i);
    }

    for (auto x : a2) {
      if (x == c[0]) continue;
      vector<int> t1 = {x};
      vector<int> t2 = {b[0]};

      if (!checkB(a2, t1, t2))
        ans[x] = 0;
      else
        ans[x] = 1;
    }

    writeans(ans);
  }

  void writeans(vector<int> ans) {
    cout << "! ";
    for (auto x : ans) {
      if (x == 1) {
        cout << 'R';
      } else {
        cout << "B";
      }
    }
    cout << endl;
    fflush(stdout);
  }
  bool checkB(set<int> x, vector<int> &y, vector<int> &z) {
    for (auto w : y) {
      x.erase(w);
    }
    for (auto w : z) {
      x.insert(w);
    }
    return !queryR(x);
  }

  bool queryR(set<int> &v) {
    cout << "? ";
    for (auto x : v) {
      cout << x << ' ';
    }
    cout << endl;
    fflush(stdout);
    string s;
    cin >> s;
    if (s == "-1") {
      exit(0);
    }
    return s == "Red";
  }
};

