char query_succ(ll start, ll n)
{
    V<ll> q;
    srep (i, start, start+n) q.pb(i);
    return query(q);
}

char query_succ_plusone(ll start, ll idx, ll n)
{
    V<ll> q;
    srep (i, start, start+n-1) q.pb(i);
    q.pb(idx);
    return query(q);
}

char query_base_plusone(const V<ll> &baselist, ll idx, ll n)
{
    V<ll> q = baselist;
    q.pb(idx);
    return query(q);
}

void _main()
{
    ll n; llin(n);

    char init_color = query_succ(0, n);

    ll left = 0;
    ll right = n;
    ll now = (left + right) / 2LL;
    ll border = n;
    for ( ; left <= right; now = (left + right) / 2LL) {
        char color = query_succ(now, n);
        if (init_color == color) {
            left = now + 1;
        }
        else {
            border = min(border, now);
            right = now - 1;
        }
    }

    S char anslist[205] = {};

    rep (idx, n * 2) {
        if (border <= idx && idx < border + n - 1) continue;
        anslist[idx] = query_succ_plusone(border, idx, n);
    }

    V<ll> baselist;
    ll cntr = 0;
    ll cntb = 0;
    rep (idx, n * 2) {
        if (anslist[idx] == 0) continue;
        if (anslist[idx] == 'R' && cntr < n / 2) {
            baselist.pb(idx);
            cntr++;
        }
        if (anslist[idx] == 'B' && cntb < n / 2) {
            baselist.pb(idx);
            cntb++;
        }
        if (cntr == n / 2 && cntb == n / 2) break;
    }

    srep (idx, border, border+n-1) {
        anslist[idx] = query_base_plusone(baselist, idx, n);
    }

    cout << "! ";
    rep (i, n * 2) cout << anslist[i];
    cout << endl << flush;
}

