class DDigitSumReplace {
public:
    void solve() {
        in.setBufSize(1);
        out.autoflush = true;
        int n = in.readInt();

        arri req(n);
        for (int i : range(n)) {
            req[i] = i + 1;
        }
        out.printLine("?", req);
        auto cur = in.readString();
        string answer(2 * n, ' ');
        int l = 0;
        int r = n - 1;
        while (l < r) {
            int mid = (l + r + 1) / 2;
            for (int i : range(n)) {
                req[i] = mid + 1 + i;
            }
            out.printLine("?", req);
            if (in.readString() == cur) {
                l = mid;
            } else {
                r = mid - 1;
            }
        }
        answer[l] = cur[0];
        answer[l + n] = 'R' + 'B' - cur[0];
        for (int i : range(n)) {
            req[i] = l + i + 1;
        }
        for (int i : range(2 * n)) {
            if (i >= l && i <= l + n) {
                continue;
            }
            req[0] = i + 1;
            out.printLine("?", req);
            answer[i] = in.readString()[0];
        }
        int at = 1;
        for (int i : range(2 * n)) {
            if (i < l || i > l + n) {
                req[at++] = i + 1;
            }
        }
        for (int i : range(2 * n)) {
            if (i <= l || i >= l + n) {
                continue;
            }
            req[0] = i + 1;
            out.printLine("?", req);
            answer[i] = in.readString()[0];
        }
        out.printLine("!", answer);
    }
};


