int n;
char buff[10];
int ask1(int p) {
  cout << "? ";
  for (int i = p; i < p + n; ++i) {
    cout << i + 1 << " \n"[i == p + n - 1];
  }
  cout << endl;
  cin >> buff;
  return buff[0] == 'R';
}

vector<int> gs[2];
int ask2(int p, int g) {
  cout << "? " << p + 1 << ' ';
  for (int i : gs[g]) {
    cout << i + 1 << ' ';
  }
  cout << endl;
  cin >> buff;
  return buff[0] == 'R';
}

void solve(std::istream &in, std::ostream &out) {
  in >> n;
  int x = ask1(0);
  int l = -1, r = n;
  while (r - l > 1) {
    int mid = l + r >> 1;
    int y = ask1(mid);
    if (x != y) {
      r = mid;
    } else {
      l = mid;
    }
  }
  for (int i = l + 1; i < l + n; ++i) gs[0].push_back(i);
  for (int i = l + n; i < 2 * n; ++i) gs[1].push_back(i);
  for (int i = 0; i < l; ++i) gs[1].push_back(i);
  vector<int> ans(2 * n);
  ans[l] = 1, ans[l + n] = 0;
  for (int i : gs[0]) ans[i] = ask2(i, 1);
  for (int i : gs[1]) ans[i] = ask2(i, 0);
  out << "! ";
  for (int i = 0; i < 2 * n; ++i) {
    out << (ans[i] ? 'R' : 'B') << ' ';
  }
  out << endl;
}

