    if(s=="Red"){
      cout<<"! RB"<<endl;
    }
    else cout<<"! BR"<<endl;
  }
  ll lb=1,rb=n+1;
  bool a1=ask(make_seq(1));
  bool a2=~a1;
  ll ans[205]={0};
  while(rb-lb>1){
    ll mid=(lb+rb)/2;
    bool f1=ask(make_seq(mid));
    bool f2=ask(make_seq(mid+1));
    if(f1!=f2){
      lb=mid;
      ans[lb]=f1;
      ans[lb+n]=f2;
      break;
    }
    else{
      if(f1==a1) lb=mid;
      else rb=mid;
    }
  }

  vector<ll> non_decide,decide;
  for(int i=1;i<=2*n;i++){
    if(i==lb||i==lb+n) continue;
    if(i<=lb||i>=lb+n) non_decide.push_back(i);
    else decide.push_back(i);
  }


  ll c1=0,c2=0;
  for(int i=0;i<non_decide.size()-1;i++){
    cout<<"? "<<non_decide[i]<<" ";
    for(int j=0;j<n-1;j++) cout<<decide[j]<<(j==n-2?"\n":" ");

    string s;
    cin>>s;
    bool f=(s=="Red");

    if(f){
      ans[non_decide[i]]=1;
      c1++;
    }
    else{
      ans[non_decide[i]]=2;
      c2++;
    }
  }
  int ina=non_decide.size();
  if(c1<c2){
    ans[non_decide[ina-1]]=1;
  }
  else ans[non_decide[ina-1]]=2;

  vector<ll> r,b;
  for(int i=1;i<=2*n;i++){
    if(ans[i]==1) r.push_back(i);
    else if(ans[i]==2) b.push_back(i);
  }
  int d1=0,d2=0;
  int kn=(n-1)/2;
  for(int i=0;i<decide.size()-1;i++){
    cout<<"? "<<decide[i]<<" ";
    for(int j=0;j<kn;j++) cout<<r[j]<<" ";
    for(int j=0;j<kn-1;j++) cout<<b[j]<<" ";
    cout<<b[kn-1]<<endl;

    string s;
    cin>>s;
    if(s=="Red") {
      ans[decide[i]]=1;
      d1++;
    }
    else{
      ans[decide[i]]=2;
      d2++;
    }
  }
  cout<<"! ";
  for(int i=1;i<=2*n;i++){
    if(ans[i]==0){
      if(d1<d2) cout<<"R";
      else cout<<"B";
    }
    else cout<<(ans[i]==1?"R":"B");
  }
  cout<<endl;
}

