  return s[0]=='R';
}

int Query(int l,int r,int p0){
  cout<<"? ";
  if (l<p0&&p0<r){
	for (int i=l;i<p0;++i) cout<<i<<' ';
	for (int i=p0+1;i<=r;++i) cout<<i<<' ';
	cout<<endl;
  }else{
	for (int i=l+1;i<r;++i) cout<<i<<' ';
	cout<<p0<<endl;
  }
  fflush(stdout);
  string s;
  cin>>s;
  return s[0]=='R'^(l<p0&&p0<r);
}

void Two_divide_ans(){
  int l=1,r=n+1,tl=Query(l),tr=Query(r);
