int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    setLength(10);
    read(N);
    fill(lp.c, lp.c + N * 2, 1);
    for (int i = 0; i < N * 2; i++) {
        vector<int> V(N * 2);
        for (int j = 0; j < N * 2; j++) V[j] = (i + j) % (2 * N);
        string T = query(vector<int>(V.begin(), V.begin() + N));
        fill(lp.A[i * 2], lp.A[i * 2] + N * 2, 0);
        fill(lp.A[i * 2 + 1], lp.A[i * 2 + 1] + N * 2, 0);
        if (T == "Blue") {
            for (int j = 0; j < N; j++) lp.A[i * 2][V[j]] = 1;
            lp.b[i * 2] = N / 2;
            for (int j = N; j < N * 2; j++) lp.A[i * 2 + 1][V[j]] = -1;
            lp.b[i * 2 + 1] = -(N / 2 + N % 2);
        } else {
            for (int j = N; j < N * 2; j++) lp.A[i * 2][V[j]] = 1;
            lp.b[i * 2] = N / 2;
            for (int j = 0; j < N; j++) lp.A[i * 2 + 1][V[j]] = -1;
            lp.b[i * 2 + 1] = -(N / 2 + N % 2);
        }
    }
    for (int i = 0; i < N * 2; i++) {
        fill(lp.A[N * 4 + i], lp.A[N * 4 + i] + N * 2, 0);
        lp.A[N * 4 + i][i] = 1;
        lp.b[N * 4 + i] = 1;
    }
    fill(lp.A[N * 6], lp.A[N * 6] + N * 2, 1);
    lp.b[N * 6] = N;
    fill(lp.A[N * 6 + 1], lp.A[N * 6 + 1] + N * 2, -1);
    lp.b[N * 6 + 1] = -N;
    lp.solve(N * 6 + 2, N * 2);
    string ans;
    for (int i = 0; i < N * 2; i++) ans.push_back(lp.x[i] > 0.5 ? 'R' : 'B');
    writeln('!', ans);
    flush();
    return 0;
}

