void ask_conti(int a, int n, int dis){
    cout << '?';
    for(int i = 0; i <= n; i++){
        if((a + i) % (n * 2) != dis) cout << ' ' << (a + i) % (n * 2) + 1;
    }
    cout << endl;
}

int main()
{
    int n;
    cin >> n;
    int right = n - 1, left = 0;
    ask_conti(0, n, n);
    string p, curr;
    cin >> p;
    while(right - left > 1){
        int mid = (right + left) / 2;
        ask_conti(mid, n, mid + n);
        cin >> curr;
        if(p == curr) left = mid;
        else right = mid;
    }
    int f;
    if(n == 1 || p == curr) f = right;
    else f = left;
    char c[202];
    string s;
    for(int i = f; i < f + n; i++){
        ask_conti(f, n, i);
        cin >> s;
        if(s == "Red") c[i] = 'B';
        else c[i] = 'R';
    }
    for(int i = f + n; i < f + n * 2; i++){
        ask_conti(f + n, n, i % (n * 2));
        cin >> s;
        if(s == "Red") c[i % (n * 2)] = 'B';
        else c[i % (n * 2)] = 'R';
    }
    cout << "! ";
    for(int i = 0; i < n * 2; i++) cout << c[i];
    cout << endl;
}

