int solve(int l, int r)
{
	if (l + 1 == r)
		return r;
	int m = (l + r) / 2;
	if (query(m) == val)
		return solve(m, r);
	else
		return solve(l,m);

}

int main()
{
	cin >> n;
	val = query(1);

	pos = solve(1,n+1);

	ans[pos - 1] = val;
	ans[pos + n-1] = !ans[pos - 1];
	vector<int> x;
	for (int i = pos; i < pos + n - 1; i++)
		x.PB(i);

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n && i >= pos - 1)
			continue;
		x.PB(i);
		ans[i] = query(x);
		x.pop_back();
	}
	x.clear();

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n - 1 && i >= pos)
			continue;
		if (ans[i] == 0 && x.size() < (n - 1) / 2)
			x.PB(i);
