	{
		if (i < pos + n - 1 && i >= pos)
			continue;
		if (ans[i] == 1 && x.size() < (n - 1))
			x.PB(i);
	}

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n - 1 && i >= pos)
		{
			x.PB(i);
			ans[i] = query(x);
			x.pop_back();
		}
	}

	cout << "! ";

	for (int i = 1; i <= n + n; i++)
		if (ans[i])
			cout << "R";
		else
			cout << "B";
	cout << endl;

	return 0;
}

