    int a = 0, b = n;
    vector<int> res1(n), res2(n);
    rep(i, n) {
        res1[i] = i + 1;
        res2[i] = i + n + 1;
    }
    string A = query(res1), B = query(res2);
    while(b - a > 1) {
        int mid = (a + b) / 2;
        vector<int> res(n);
        rep(i, n) {
            res[i] = i + mid + 1;
        }
        string C = query(res);
        if(A == C) a = mid;
        if(B == C) b = mid;
    }
    vector<char> ans(2 * n);
