    ans[a + n] = (A == "Red" ? 'B' : 'R');
    vector<int> res(n);
    rep(i, n - 1) {
        res[i] = i + a + 1 + 1;
    }
    rep(i, 2 * n) {
        if(i >= a && i <= a + n) continue;
        auto hoge = res;
        hoge[n] = i;
        string X = query(hoge);
        if(X == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }
    int j = -1;
    rep(i, n - 1) {
        if(j == a - 1) j = a + n + 1;
        else ++j;
        res[i] = j;
    }
    for(int i = a + 1; i <= a + n - 1; ++i) {
