int main() {
	int n; reader(n);
	vector<int> ord;
	FOR(i, n * 2) ord.push_back(i);
	random_shuffle(ord.begin(), ord.end());

	int lcol = askSeq(0, n);
	int l = 0, r = n;
	while (r - l != 1) {
		int md = (l + r) / 2;
		int mdcol = askSeq(md, n);
		if (lcol == mdcol) {
			l = md;
		} else {
			r = md;
		}
	}

	string ans;
	FOR(i, 2 * n) ans.push_back('?');
	ans[l] = "BR"[lcol];
	ans[l + n] = "BR"[1 - lcol];
	FOR(i, 2 * n) {
		if (ans[i] != '?') continue;
		vector<int> x;
