			FOR(i, l) x.push_back(i);
			for (int i = l + n + 1; i < 2 * n; i++) x.push_back(i);
		} else {
			for (int i = l + 1; i < l + n; i++) x.push_back(i);
		}
		int col = ask(x);
		ans[i] = "BR"[col];
	}

