// Fisher–Yates algorithm
// Richard Durstenfeldによる改良版(1964)
template <typename T>
void fisher_yates_inplace(vector<T>& a) {
    int n = a.size();
    for (int i=n-1; i>=0; --i) {
        int j = randint(0, i); // inclusive
        swap(a[j], a[i]);
    }
}

int ask(vi& nums){
    printf("?");
    rep(i, nums.size()){
        printf(" %d", 1+nums[i]);
    }
    printf("\n");
    fflush(stdout);

    string v; cin >> v;

    if (v[0] == '-') return -1;
    return (int)v[0]; // R, B
}

void ans(vi& pat){
    printf("! ");
    rep(i, pat.size()){
        putchar(pat[i]);
    }
    printf("\n");
    fflush(stdout);
}

void solve(int N){
    vi a(N*2); rep(i,N*2) a[i]=i; // iota
    fisher_yates_inplace(a);

    vi b(a.begin()+N, a.end());
    a.resize(N);

    int first = ask(a), second, pix=-1, apicallcount=1;

    set<int> unk;
    rep(i,N*2) unk.insert(i);
    map<int,int> deja;
    rep(i,N){
        swap(a[i], b[i]);
        int second = ask(a); apicallcount++;
        if (second == -1) return;
        if (second == first) continue;
        pix=i;
        deja[a[i]] = second;
        deja[b[i]] = first;
        unk.erase(a[i]);
        unk.erase(b[i]);
        break;
    }
    rep(i,N){
        if (i==pix) continue;
        swap(a[pix], b[i]);
        deja[a[pix]] = ask(a); apicallcount++;
        unk.erase(a[pix]);
    }

    int H=(N-1)/2, ac=0, bc=0, i=0;
    for (auto& p: deja){
        if (ac==H && bc==H) break;
        switch (p.second){
            case 'R':
                if (ac<H) {
                    a[i++] = p.first;
                    ++ac;
                }
                break;
            case 'B':
                if (bc<H) {
                    a[i++] = p.first;
                    ++bc;
                }
                break;
        }
    }
    assert(i==N-1);

    for (int n: unk){
        a[N-1] = n;
        deja[n] = ask(a); apicallcount++;
    }

    vi pat(N*2, '?');
    rep(i,2*N){
        pat[i] = deja[i];
    }
    debug("apicallcount = %d\n", apicallcount);
    ans(pat);
}

int main() {
    int N; cin >> N;
    solve(N);
    return 0;
}

