int main() {
    cout << fixed << setprecision(20);
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);


    ll n;
    cin >> n;

    vl p = range(0, n);
    ll last = ask(p);
    ll index = 0;

    for (ll i = 1; i <= n; ++i) {
        vl pp = range(i, n);
        ll curr = ask(pp);
        if (curr == last) { continue; }
        index = i - 1;
        break;
    }
    vb colors(2 * n, false);
    colors[index] = last;
    colors[index + n] = 1 - last;

    for (ll i = 0; i < 2 * n; ++i) {
        if (i >= index && i <= index + n) { continue; }
        vl q = range(index + 1, n - 1);
        q.pb(i);
        colors[i] = ask(q);
    }

    for (ll i = 0; i < 2 * n; ++i) {
        if (i <= index || i >= index + n) { continue; }
        vl q;
        q.pb(i);
        for (ll xx : range(0, index)) { q.pb(xx); }
        for (ll xx : range(index + n + 1, (n - 1) - index)) { q.pb(xx); }
        colors[i] = ask(q);
    }


    ans(colors);
    print_time();
    return 0;
}

