int L, R;

int Ask(int l, int r)
{
    printf("?");
    for (int i = l; i <= r; i++)
        printf(" %d", i);
    printf("\n"); fflush(stdout);
    string res; cin >> res;
    return res == "Red"? -1: 1;
}

int Ask(int x)
{
    printf("? %d", x);
    for (int i = 1; i <= 2 * n; i++)
        if (i != L && i != R && (L < i && i < R) != (L < x && x < R))
            printf(" %d", i);
    printf("\n"); fflush(stdout);
    string res; cin >> res;
    return res == "Red"? -1: 1;
}

int main()
{
    scanf("%d", &n);
    int prv = Ask(1, n);
    int lef = 2, rig = n;
    while (lef <= rig) {
        int mid = lef + rig >> 1;
        if (Ask(mid, mid + n - 1) == prv) lef = mid + 1;
        else rig = mid - 1;
    }
    lef--;
    L = lef; R = lef + n;
    res[L] = prv; res[R] = -prv;
    for (int i = 1; i <= 2 * n; i++)
        if (i != L && i != R) res[i] = Ask(i);
    printf("! ");
    for (int i = 1; i <= 2 * n; i++)
        printf("%c", res[i] == -1? 'R': 'B');
