int main() {
    int n;
    scanf("%d", &n);

    int first = -1;
    {
        std::deque<int> q;
        for (int i = 1; i <= n; i++) q.push_back(i);
        first = ask(q);
    }

    int l = 1, r = n + 1;
    while (r - l > 1) {
        int k = (l + r) / 2;
        std::deque<int> q;
        for (int i = 0; i < n; i++) q.push_back(k + i);
        int res = ask(q);
        if (res == first) l = k;
        else r = k;
    }

    std::deque<int> q;
    for (int i = 0; i + 1 < n; i++) q.push_back(r + i);

    std::vector<int> ret(2 * n + 1, -1);
    for (int i = 1; i < r; i++) {
        q.push_back(i);
        ret[i] = ask(q) == first;
        q.pop_back();
    }
    for (int i = l + n; i <= 2 * n; i++) {
        q.push_back(i);
        ret[i] = ask(q) == first;
        q.pop_back();
    }

    q.clear();
    int same = 0, diff = 0;
    for (int i = 1; i <= 2 * n; i++) {
        if (ret[i] < 0) continue;
        if (ret[i] && same < n / 2) {
            q.push_back(i);
            same++;
        } else if (!ret[i] && diff < n / 2) {
            q.push_back(i);
            diff++;
        }
    }

    for (int i = r; i < l + n; i++) {
        q.push_back(i);
        ret[i] = ask(q) == first;
        q.pop_back();
    }

    printf("! ");
    char sc = first ? 'R' : 'B', dc = first ? 'B' : 'R';
    for (int i = 1; i <= 2 * n; i++) printf("%c", ret[i] ? sc : dc);
    printf("\n");
    fflush(stdout);

    return 0;
}

