		for (int j = i; j < i + N; j++) {
			vs.push_back(j);
		}
		flag[i] = query(vs);
	}
	flag.push_back(!flag[0]);
	int pos = -1;
	for (int i = 0; i < N; i++) if (flag[i] != flag[i + 1]) {
		pos = i;
