main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    //freopen("input.txt", "r", stdin);
    int n;
    cin >> n;
    int l = 1;
    int r = n + 1;
    string s0 = ask(1, n);
    while(r - l > 1){
        int mid = (r + l) / 2;
        if (s0 == ask(mid, mid + n - 1)) l = mid; else r = mid;
    }
    ans[l] = 0;
    ans[l + n] = 1;
    for (int i = l + 1; i < l + n; i++){
        string t = ask(l, l + n, i);
        if (t == s0) ans[i] = 1; else ans[i] = 0;
    }
    for (int i = 1; i < l; i++){
        string t = ask(l + 1, l + n - 1, -i);
        if (t == s0) ans[i] = 0; else ans[i] = 1;
    }
    for (int i = l + n + 1; i <= n + n; i++){
        string t = ask(l + 1, l + n - 1, -i);
        if (t == s0) ans[i] = 0; else ans[i] = 1;
    }
    if (s0 == "Red"){
        cout << "! ";
