#include <iostream>
#include <vector>
using namespace std;

const int maxN = 100;

int n;
char sol[2*maxN];

string ask(vector<int> &v){
    cout << "? ";
    for(int i = 0; i < n; i++){
        cout << v[i] << " ";
    }
    cout<<endl;

    string res;
    cin >> res;
    return res;
}

int findPos(vector<int>&asking){
    for(int i = 0; i < n; i++){
        asking[i] = i+1;
    }

    string firstHalf=ask(asking);

    int st=1;
    int dr=n;
    int pos = -1;
    while(st <= dr){
        int mij = (st+dr)/2;
        asking.clear();
        for(int i = 0; i < n; i++){
            asking[i] = mij + i+1;
        }
        string res = ask(asking);
        if(res != firstHalf){
            pos = mij;
            dr = mij-1;
        } else {
            st = mij+1;
        }
    }

    if(firstHalf=="Red"){
        sol[pos]='R';
        sol[pos+n]='B';
    } else {
        sol[pos]='B';
        sol[pos+n]='R';
    }

    return pos;
}

void getOutside(int pos,vector<int>&outside){
    for(int i=1;i<pos;i++){
        outside.push_back(i);
    }
    for(int i=pos+n+1;i<=2*n;i++){
        outside.push_back(i);
    }

    int cntRed=0;
    int cntBlue=0;
    for(int i=0;i<(int)outside.size();i++){
        if(sol[outside[i]]=='R'){
            cntRed++;
        } else {
            cntBlue++;
        }
    }

    for(int i=0;i<(int)outside.size();i++){
        if(cntBlue>cntRed && sol[outside[i]]=='B'){
            outside.erase(outside.begin()+i);
            break;
        }
        if(cntRed>cntBlue && sol[outside[i]]=='R'){
            outside.erase(outside.begin()+i);
            break;
        }
    }
}

int main(){
    cin >> n;
    vector<int> asking(n);

    //se schimba intre pos si pos + 1
    //pos e firstHalf, pos+n e nonFirstHalf
    //pos+1 .. pos+n-1

    int pos=findPos(asking);

    for(int i = 1; i < pos; i++){
        asking.clear();
        for(int j = 0; j < n-1; j++){
            asking[j] = pos+j+1;
        }
        asking[n-1]=i;
        string res=ask(asking);
        if(res=="Red"){
            sol[i] = 'R';
        } else {
            sol[i] = 'B';
        }
    }

    for(int i = pos+n+1; i <= 2*n; i++){
        asking.clear();
        for(int j = 0; j < n-1; j++){
            asking[j]=pos+j+1;
        }
        asking[n-1]=i;

        string res=ask(asking);
        if(res=="Red"){
            sol[i] = 'R';
        } else {
            sol[i] = 'B';
        }
    }

    vector<int> outside;
    getOutside(pos,outside);

    asking.clear();
    for(int i=0;i<(int)outside.size();i++){
        asking[i]=outside[i];
    }
    for(int i=pos+1;i<pos+n;i++){
        asking[n-1]=i;
        string res=ask(asking);
        if(res=="Red"){
            sol[i]='R';
        } else {
            sol[i]='B';
        }
    }

    cout<<"! ";
    sol[2*n+1]=0;

    cout<<(sol+1)<<endl;
    fflush(stdout);

    return 0;
}

