//num 何個反対側に行くか
string func(int num){
	output("?");
	rep(i, n-num){
		output(i+1);
	}
	rep(i, num){
		output(n*2-i);
	}
	outendl();
	string res;
	cin >> res;
	return res;
}

int main(){
	cin >> n;
	string first;
	vector<char> ans(2*n+1, ' ');
	output("?");
	rep(i, n){
		output(i+1);
	}
	outendl();
	cin >> first;
	//何個反対側にすると結果が反転するか判定
	int lp = 1;
	int rp = n+1;
	while(lp<rp){
		int mid = (lp + rp) / 2;
		if(func(mid) == first){
			lp = mid + 1;
		}else{
			rp = mid;
		}
	}
	//lpの位置のやつが経典のため
	set<int> selector;
	ans[n*2-lp+1] = first=="Red"?'B':'R';
	rep(i, n-lp){
		selector.emplace(i+1);
	}
	rep(i, lp-1){
		selector.emplace(n*2-i);
	}
	repa(i, n*2+1){
		if(selector.count(i))continue;
		output("?");
		foreach(j, selector)output(j);
		output(i);
		outendl();
		string str;
		cin >> str;
		ans[i] = str[0];
	}
	set<int> s;
	int nr = n / 2;
	int nb = n / 2;
	repa(i, n*2+1){
		if(selector.count(i))continue;
		if(ans[i]=='R'){
			if(nr){
				--nr;
				s.emplace(i);
			}
		}else{
			if(nb){
				--nb;
				s.emplace(i);
			}
		}
	}
	selector = s;
	repa(i, n*2+1){
		if(selector.count(i))continue;
		output("?");
		foreach(j, selector)output(j);
		output(i);
		outendl();
		string str;
		cin >> str;
		ans[i] = str[0];
	}
	cout << "! ";
	repa(i, n*2+1){
		cout << ans[i];
	}
	cout << endl;

	return 0;
}

