void solve(){
	scanf("%d", &n);

	REP(i, 0, n) {
		used[i] = 1;
	}

	int ans_l = ask();

	int l = 0, r = n;
	while(l + 1 < r) {
		int mid = (l + r) >> 1;
		REP(i, 0, 2 * n) {
			used[i] = 0;
			if (i >= mid && i < mid + n) {
				used[i] = 1;
			}
		}
		int cur = ask();
		if (cur == ans_l) {
			l = mid;
		} else {
			r = mid;
		}
	}

	int l_ind = l, r_ind = n + l;
	ans[l_ind] = ans_l;
	ans[r_ind] = 'R' + 'B' - ans_l;

	REP(i, 0, 2 * n) {
		used[i] = 0;
		if (i > l_ind && i < r_ind) {
			used[i] = 1;
		}
	}

	REP(i, 0, 2 * n) {
		if (i < l_ind || i > r_ind) {
			used[i] = 1;
			ans[i] = ask();
			used[i] = 0;
		}
