char ask(int x, int y)
{
	printf("?");
	if (x < y || y + n < x)
	{
		printf(" %d", x);
		for (int i = 1; i <= n - 1; ++i)
			printf(" %d", y + i);
		read_ans();
		return ans[0];
	} 
	else 
	{
		for (int i = 0; i <= n; ++i)
			if (y + i != x)
				printf(" %d", y + i);
		read_ans();
		return ans[0] ^ 'R' ^ 'B';
	}
}

