int main(){
    cin>>n;
    vector<int> red,blue;
    red.clear();
    for (int i=1;i<=n;++i){
        red.push_back(i);
        pos[i]=1, pos[i+n]=-1;
        blue.push_back(i+n);
   }
   if (!query(red)){
       for (auto &c:red){
           pos[c]=-1;
           c+=n;
       }
       for (auto &c:blue){
           pos[c]=1;
           c-=n;
       }
    }
    for (int i=0;i<n;++i){
        pos[red[i]]=-1, pos[blue[i]]=1;
        swap(red[i],blue[i]);
        if (!query(red)){
            red.erase(red.begin()+i);
            blue.erase(blue.begin()+i);
            for (int j=1;j<=2*n;++j){
                vector<int> tmp;
                if (pos[j]==-1){
                    tmp=red;
                }
                else{
                    tmp=blue;
                }
                tmp.push_back(j);
                if (query(tmp)) ans[j]=1;
                else ans[j]=-1;
            }
            cout<<"! ";
            for (int j=1;j<=2*n;++j){
                if (ans[j]>0) cout<<"R";
                else cout<<"B";
            }
            return 0;
        }
    }

}

