int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<int> A(2 * N), ans(2 * N);
    deque<int> D;
    for (int i = 0; i < N; i++) D.push_back(i), A[i] = 1;
    bool prev = query(D);
    for (int i = N; i < 3 * N; i++) {
        D.pop_front();
        A[(i - N) % (2 * N)] = 0;
        A[i % (2 * N)] = 1;
        D.push_back(i % (2 * N));
        bool curr = query(D);
        if (prev != curr) {
            A[i % (2 * N)] = 0;
            ans[i % (2 * N)] = curr ? +1 : -1;
            ans[(i - N) % (2 * N)] = curr ? -1 : +1;
            D.pop_back();
            break;
        }
    }
    for (int i = 0; i < 2 * N; i++) if (A[i] == 0 && ans[i] == 0) {
        D.push_back(i);
        ans[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    D.clear();
    int r = N / 2, b = N / 2;
    for (int i = 0; i < 2 * N; i++) {
        if (ans[i] == +1 && r) D.push_back(i), r--;
        if (ans[i] == -1 && b) D.push_back(i), b--;
    }
    for (int i = 0; i < 2 * N; i++) if (ans[i] == 0) {
        D.push_back(i);
        ans[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    cout << "! ";
    for (int i = 0; i < 2 * N; i++) {
        cout << (ans[i] == +1 ? 'R' : 'B');
    }
    cout << '\n';
    return 0;
}

