  ll N;
  cin>>N;
  mt19937 mt;

  if(N==1){
    string res(2*N,'-');
    rep(i,2*N){
      vector<ll> v(1,i);
      string crt=query(v);
      if(crt=="Red"){
        res[i]='R';
      }else{
        res[i]='B';
      }
    }
    answer(res);
    return 0;
  }

  uniform_int_distribution<> rands(0,N-1);
  vector<bool> used(N,false);
  ll ri=-1,bi=-1;
  while(ri==-1||bi==-1){
    ll i=rands(mt);
    if(used[i])continue;
    vector<ll> qs;
    repl(j,i,i+N)qs.push_back(j);
    string crt=query(qs);
    if(crt=="Red"&&ri==-1){
      ri=i;
    }else if(crt=="Blue"&&bi==-1){
      bi=i;
    }
  }

  ll lb=min(ri,bi),ub=max(ri,bi);
  while(ub-lb>1){
    ll mid=(ub+lb)/2;
    vector<ll> qs;
    repl(j,mid,mid+N)qs.push_back(j);
    string crt=query(qs);
    if(crt=="Red"){
      ri=mid;
    }else{
      bi=mid;
    }
    lb=min(ri,bi); ub=max(ri,bi);
  }
  P r=P(lb+1,lb+N);

  string res(2*N,'-');
  vector<ll> oth;
  ll rcnt=0,bcnt=0;
  rep(i,2*N){
    if(r.fi<=i&&i<r.se)continue;
    vector<ll> v;
    repl(j,r.fi,r.se)v.push_back(j);
    v.push_back(i);
    string crt=query(v);
    if(crt=="Red"){
      res[i]='R';
      if(rcnt<(N-1)/2){
        oth.push_back(i);
        rcnt++;
      }
    }else{
      res[i]='B';
      if(bcnt<(N-1)/2){
        oth.push_back(i);
        bcnt++;
      }
    }
  }

  repl(i,r.fi,r.se){
    vector<ll> v=oth;
    v.push_back(i);
    string crt=query(v);
    if(crt=="Red"){
      res[i]='R';
    }else{
      res[i]='B';
    }
  }

  answer(res);

  return 0;
}

