int main()
{
	cin >> N;
	vector<int> res(N * 2, -1);
	vector<bool> flag(N);
	for (int i = 0; i < N; i++) {
		vector<int> vs;
		for (int j = i; j < i + N; j++) {
			vs.push_back(j);
		}
		flag[i] = query(vs);
	}
	flag.push_back(!flag[0]);
	int pos = -1;
	queue<int> q;
	for (int i = 0; i < N; i++) if (flag[i] != flag[i + 1]) {
		pos = i;
		res[i] = flag[i];
		res[i + N] = flag[i + 1];
		q.push(i);
		q.push(N + i);
	}
	while (!q.empty()) {
		auto id = q.front(); q.pop();
		for (int j = 0; j <= N; j++) if (j <= id && id < N + j) {
			int c1 = 0, c2 = 0;
			for (int k = j; k < N + j; k++) {
				c1 += res[k] == 0;
				c2 += res[k] == 1;
			}
			int c3 = N - c1 - c2;
			if (c3 == 0) continue;
			if (flag[j]) {
