					for (int k = j; k < N + j; k++) if (res[k] == -1) {
						q.push(k);
						res[k] = 1;
					}
				}
			}
			else {
				if (c1 + c3 == (N + 1) / 2) {
					for (int k = j; k < N + j; k++) if (res[k] == -1) {
						q.push(k);
						res[k] = 0;
					}
				}
			}
		}
	}
