#include <iostream>
#include <vector>
#include <set>
using namespace std;

int N;
string get(const vector<int> &v) {
    cout << "?";
    for (auto vi : v) cout << " " << vi+1;
    cout << endl;
    string res;
    cin >> res;
    return res;
}

string get(int f) {
    vector<int> v(N);
    for (int i = 0; i < N; ++i) v[i] = f + i;
    return get(v);
}

void solve() {
    int left = 0, right = N;
    string start = get(left);
    while (right - left > 1) {
        int mid = (left + right) / 2;
        if (get(mid) == start) left = mid;
        else right = mid;
    }

    vector<int> base(N-1);
    for (int i = 0; i < N-1; ++i) base[i] = left + i+1;

    set<int> red, blue;
    string res('U', N*2);
    for (int i = 0; i < N*2; ++i) {
        if (i >= base[0] && i <= base.back()) continue;
        base.push_back(i);
        auto tmp = get(base);
        if (tmp == "Red") {
            res[i] = 'R';
            if (red.size() < N/2) red.insert(i);
        }
        else {
            res[i] = 'B';
            if (blue.size() < N/2) blue.insert(i);
        }
        base.pop_back();
    }

    vector<int> nbase;
    for (auto c : red) nbase.push_back(c);
    for (auto c : blue) nbase.push_back(c);
    for (int i = 0; i < N*2; ++i) {
        if (red.count(i) || blue.count(i)) continue;
        nbase.push_back(i);
        auto tmp = get(nbase);
        if (tmp == "Red") res[i] = 'R';
        else res[i] = 'B';
        nbase.pop_back();
    }
    cout << "! " << res << endl;
}

int main() {
    while (cin >> N) {
        solve();
    }
}

