  s = ask(1);
  if(s == "Red") sx = "Blue";
  else sx = "Red";
  int st = 2;
  int dr = 2 * N - N + 1;
  int ok;
  while(st <= dr) {
    int mij = (st + dr) / 2;
    string a = ask(mij);
    if(a == sx) {
      ok = mij;
      dr = mij - 1;
    } else {
      st = mij + 1;
    }
  }
  ret[ok-1] = s;
  ret[ok+N-1] = sx;
  vi v;
  for(int i=ok;i<ok + N - 1; ++i) {
    v.pb(i);
  }
  for(int i=1;i<=2*N;++i) {
    if(sz(ret[i])) continue;
    if(i >= ok && i < ok + N - 1) continue;
    ret[i] = ask(v, i);
  }
  map<int,int> h;
  v.clear();
  int R = (N-1)/2;
  int B = (N-1)/2;
  for(int i=1;i<=2*N;++i) {
    if(R && ret[i] == "Red") {
      --R;
      v.pb(i);
      h[i]++;
    } else if(B && ret[i] == "Blue") {
      --B;
      v.pb(i);
      h[i]++;
    }
  }
  for(int i=1;i<=2*N;++i) {
    if(sz(ret[i])) continue;
    if(h[i]) continue;
    ret[i] = ask(v, i);
  }
  cout << "! ";
  for(int i=1;i<=2*N;++i) {
    cout << ret[i][0];
  }
  cout << endl;

}

