int n,a[N],b[N];
char s[10];
int R()
{
    fflush(stdout);
    scanf("%s",s);
    if(s[0]=='R') return 1;
    return 2;
}
int ask(int x)
{
    printf("?");
    for(int i=x;i<=x+n-1;i++)
        printf(" %d",i);
    printf("\n");
    return R();
}
int main()
{
    scanf("%d",&n);
    a[1]=ask(1);
    if(n==1)
    {
        if(a[1]==1) printf("! R\n");
        else printf("! B\n");
        return 0;
    }
    int l,r;
    for(int i=2;i<=n+1;i++)
    {
        a[i]=ask(i);
        if(a[i]!=a[i-1])
        {
            if(a[i]==1)
            {
                b[i+n-1]=1;
                b[i-1]=2;
            }
            else
            {
                b[i+n-1]=2;
                b[i-1]=1;
            }
            l=i;r=i+n-2;
            break;
        }
        assert(i!=n+1);
    }
    for(int i=1;i<=2*n;i++)
        if(b[i]==0&&!(i>=l&&i<=r))
    {
        printf("?");
        for(int j=l;j<=r;j++)
        {
            printf(" %d",j);
        }
        printf(" %d\n",i);
        b[i]=R();
    }
    vector<int>v;
    int s1=n/2,s2=n/2;
    for(int i=1;i<=2*n;i++)
        if(b[i]==1&&s1)
    {
        s1--;v.push_back(i);
    }
    else if(b[i]==2&&s2)
    {
        s2--;v.push_back(i);
    }
    assert(s1==0&&s2==0);
    for(int i=1;i<=2*n;i++)
        if(b[i]==0)
        {
            printf("?");
            for(int j=0;j<v.size();j++)
                printf(" %d",v[j]);
            printf(" %d\n",i);
            b[i]=R();
        }
    printf("! ");
    for(int i=1;i<=2*n;i++)
        if(b[i]==1) putchar('R');
    else putchar('B');
    putchar('\n');
}

