    if (T == "Red") {
        ans.push_back(1);
    } else if (T == "Blue") {
        ans.push_back(0);
    }
    return;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;

    vec balls(2*N, -1);
    ll ok = 0, ng = N;
    vec check(N+1, -1);
    vec prepare(2*N, 0);
    Rep (i, N) {
        prepare[i] = 1;
    }

    ask(prepare);

    check[ok] = ans.back();
    check[ng] = 1 - ans.back();

    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        prepare.assign(2*N, 0);
        for (ll i = mid; i < mid + N; i++) {
            prepare[i] = 1;
        }
        ask(prepare);
        check[mid] = ans.back();
        if (check[ok] == check[mid]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }

    balls[ok] = check[ok];
    balls[ok+N] = check[ng];

    for (ll i = 0; i < 2*N; i++) {
        if (ok <= i && i <= ok+N) continue;
        prepare.assign(2*N, 0);
        prepare[i] = 1;
        for (ll j = ok + 1; j <= ok + N - 1; j++) {
            prepare[j] = 1;
        }
        ask(prepare);
        balls[i] = ans.back();
    }

    for (ll i = 0; i < 2*N; i++) {
        if (i <= ok || ok + N <= i) continue;
        prepare.assign(2*N, 0);
        for (ll j = 0; j < 2*N; j++) {
            if (ok <= j && j <= ok+N) continue;
            prepare[j] = 1;
        }
        prepare[i] = 1;
        ask(prepare);
        balls[i] = ans.back();
    }

    cout << "! ";
    Rep (i, 2*N) {
        if (balls[i] == 1) {
            cout << 'R';
        } else {
            cout << 'B';
        }
    }
    cout << endl;
    return 0;
}

