bool query(const vecint& v) {
  cout<<"?";
  for(auto&& e:v) cout<<" "<<e+1;
  cout<<endl;
  string s;
  cin>>s;
  if (s == "-1") exit(-1);
  return s == "Red";
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin>>n;
  vecint v(n);
  iota(ALL(v), 0);
  bool isred = query(v);
  int lt = 0;
  int gt = n;
  while (gt - lt > 1) {
    int mid = (gt + lt) / 2;
    iota(ALL(v), mid);
    if (query(v) == isred) {
      lt = mid;
    } else {
      gt = mid;
    }
  }
  auto clr = [] (bool isred) {
    return isred ? 'R' : 'B';
  };
  string ans(2*n, '.');
  ans[lt] = clr(isred);
  ans[lt+n] = clr(!isred);
  iota(ALL(v), lt);
  REP(i,lt) {
    v[0] = i;
    ans[i] = clr(query(v));
  }
  FOR(i, lt+n+1, 2*n) {
    v[0] = i;
    ans[i] = clr(query(v));
  }
  iota(ALL(v), -1);
  FOR(i,lt+1, n) v[i] += n + 1;
  FOR(i,lt+1, lt+n) {
    v[0] = i;
    ans[i] = clr(query(v));
  }
  cout<<ans<<endl;
  return 0;
}

