class Solution {
public:
	bool query1(int s, int n){
		cout << "? ";
		for(int i=0; i<n; i++)cout << (s + i) % (2 * n) + 1 << " ";
		cout << endl;
		string ret;
		cin >> ret;
		if(ret == "Red")return true;
		return false;
	}

	bool query2(int k, int s, int n){
		cout << "? " << k + 1<< " ";
		for(int i=0; i < n-1; i++)cout << (s + i) % (2 * n) + 1 << " ";
		cout << endl;
		string ret;
		cin >> ret;
		if(ret == "Red")return true;
		return false;
	}

	void solve() {
		int n;
		cin >> n;
		int l = 0, r = n;
		bool c0 = query1(0, n);
		while(r-l > 1){
			int mid = (l+r)/2;
			if(query1(mid, n) == c0)l = mid;
			else r = mid;
		}
		vector<bool> ans(2*n);
		ans[l] = c0;
		ans[(l+n)%(2*n)] = 1-c0;
		for(int i=0; i < n-1; i++){
			ans[(l+n+i+1)%(2*n)] = query2((l+n+i+1)%(2*n), l+1, n);
			ans[(l+1+i)%(2*n)] = query2((l+1+i)%(2*n), l+n+1, n);
		}
		cout << "! ";
		string sans;
		for(int i=0; i<2*n; i++){
			if(ans[i])cout << "R";
			else cout << "B";
		}
		cout << endl;

		return;
	};
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	Solution solution;
	solution.solve();
	return 0;
}

