    }
    else
    {
      cout << endl;
    }
  }
  string S;
  cin >> S;
  assert(S == "Red" || S == "Blue");
  return S == "Red";
}

void answer(vector<bool> const &C)
{
  assert(static_cast<int>(C.size()) == 2 * N);
  cout << "! ";
  for (auto i = 0; i < 2 * N; i++)
  {
    cout << (C[i] ? "R" : "B");
  }
  cout << endl;
}

vector<int> make_vec(int x)
{
  assert(0 <= x && x <= N);
  vector<int> ans;
  for (auto i = 0; i < x; i++)
  {
    ans.push_back(i);
  }
  for (auto i = x; i < N; i++)
  {
    ans.push_back(i + N);
  }
  return ans;
}

int main()
{
  cin >> N;
  vector<bool> C(2 * N);
  bool init_color{flush(make_vec(N))};
  int ng{0}, ok{N};
  while (abs(ok - ng) > 1)
  {
    int t{(ok + ng) / 2};
    bool c{flush(make_vec(t))};
    if (c == init_color)
    {
      ok = t;
    }
    else
    {
      ng = t;
    }
  }
  C[ok - 1] = init_color;
  C[ok - 1 + N] = !init_color;
  vector<int> unit = make_vec(ok);
  auto it{unit.begin()};
  unit.erase(it + ok - 1);
  vector<int> unit2;
  for (auto x : unit)
  {
    unit2.push_back((N + x) % (2 * N));
  }
  // unit2
  for (auto i = 0; i < ok - 1; i++)
  {
    vector<int> X = unit2;
    X.push_back(i);
    C[i] = flush(X);
  }
  for (auto i = ok; i < N; i++)
  {
    vector<int> X = unit2;
    X.push_back(i + N);
    C[i + N] = flush(X);
  }
  // unit
  for (auto i = 0; i < ok - 1; i++)
  {
    vector<int> X = unit;
    X.push_back(i + N);
    C[i + N] = flush(X);
  }
  for (auto i = ok; i < N; i++)
  {
    vector<int> X = unit;
    X.push_back(i);
    C[i] = flush(X);
  }
  answer(C);
}

