        while(s.size() < n)
            s.emplace(xorshift());
        bool res = print(s);
        if(res == false){
            set<int> t;
            for(int i = 0; i < 2 * n; ++i)
                if(s.find(i) == s.end())
                    t.emplace(i);
            s = move(t);
        }

        nex2 = *s.begin();
        while(s.find(nex2) != s.end())
