int ri() {
	int n;
	scanf("%d", &n);
	return n;
}
int main() {
	int n = ri();
	std::vector<int> perm(2 * n);
	std::iota(perm.begin(), perm.end(), 0);
	std::mt19937 rnd(10);
	std::shuffle(perm.begin(), perm.end(), rnd);

	int cnt = 0;
	auto Query = [&] (std::vector<int> a) {
		if (++cnt > 210) {
			system("sleep 1.5");
			exit(0);
		}
		for (auto &i : a) i = perm[i];
		std::sort(a.begin(), a.end());

		std::set<int> uniq;
		for (auto j : a) if (!uniq.insert(j).second || j < 0 || j >= 2 * n || (int) a.size() != n) {
			system("sleep 0.7");
			exit(0);
		}

		std::cout << "?";
		for (auto i : a) std::cout << " " << i + 1;
		std::cout << std::endl;
		fflush(stdout);
		std::string s;
		std::cin >> s;
		if (s == "Red") return true;
		if (s == "Blue") return false;
		while (s != "-1") std::cerr << "x";
		system("sleep 0.2");
		exit(0);
	};

	int ind;
	std::map<int, bool> qans;
	{
		std::vector<int> tmp(n);
		std::iota(tmp.begin(), tmp.end(), 0);
		bool first = Query(tmp);
		int l = 0, r = n;
		while (r - l > 1) {
			int m = l + (r - l) / 2;
			std::vector<int> query(n);
			std::iota(query.begin(), query.end(), m);
			bool cur = Query(query);
			qans[m] = cur;
			if (cur != first) r = m;
			else l = m;
		}
		ind = l;
	}

	std::vector<bool> res(2 * n);
	if (qans[ind]) res[ind] = true, res[ind + n] = false;
	else res[ind] = false, res[ind + n] = true;
	std::vector<int> stable;
	for (int i = ind + 1; i < ind + n; i++) stable.push_back(i);

	for (int i = 0; i < 2 * n; i++) {
		if (i == ind || i == ind + n) continue;
		if (i < ind || i > ind + n) {
			std::vector<int> query = stable;
			query.push_back(i);
			res[i] = Query(query);
		} else {
			std::vector<int> query;
			for (int j = ind; j <= ind + n; j++) if (j != i) query.push_back(j);
			res[i] = !Query(query);
		}
	}
	std::string ans(2 * n, '0');
	for (int i = 0; i < 2 * n; i++) {
		ans[perm[i]] = res[i] ? 'R' : 'G';
	}
	std::cout << "! " << ans << std::endl;


	return 0;
}

