bool askl(int N,int l){
	vector<int>v(N);
	iota(v.begin(),v.end(),l);
	return ask(v);
}
int main(){
	ios::sync_with_stdio(false);

	int N;cin>>N;

	bool zero_red;
	{
		zero_red=askl(N,0);
	}

	int same_l=-1,same_r=-1;

	{
		int ng=0;
		int ok=N;

		while(ng+1!=ok){
			int amid=(ng+ok)/2;
			if(askl(N,amid)==zero_red){
				ng=amid;
			}else{
				ok=amid;
			}
		}
		same_l=ok;
		same_r=ok+N-1;
	}

	vector<int>is_reds(2*N,-1);

	vector<int>red_places,blue_places;
	for(int i=0;i<2*N;++i){
		if(same_l<=i&&i<same_r)continue;
		else{
			vector<int>v(N-1);
			iota(v.begin(),v.end(),same_l);
			v.push_back(i);
			is_reds[i]=ask(v);
			if(is_reds[i]){
				if(red_places.size()<N/2)red_places.push_back(i);
			}else{
				if(blue_places.size()<N/2)blue_places.push_back(i);
			}
		}
	}
	for(int i=0;i<2*N;++i){
		if(same_l<=i&&i<same_r){
			vector<int>v(red_places);
			v.insert(v.end(),blue_places.begin(),blue_places.end());
			v.push_back(i);
			is_reds[i]=ask(v);
		}
	}
	cout<<"! ";
	for(int i=0;i<2*N;++i){
		if(is_reds[i])cout<<"R";
		else cout<<"B";
	}
	cout<<endl;
	return 0;
}

