  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> N;

  // Red: true, Blue: false
  int li = 1, ri = N + 1, mi;
  bool l = ask(li), r = ask(ri);
  while (ri - li > 1) {
    mi = (li + ri) / 2;
    if (ask(mi) == l)
      li = mi;
    else
      ri = mi;
  }

  vector<bool> c(N * 2);
  c[li - 1] = l;
  c[li + N - 1] = r;
  FOR(i, 1, N * 2 + 1) {
    if (i < li || i > li + N) {
