      cout << i << " ";
      FOR(j, li + 1, li + N)
      cout << j << " ";
      cout << "\n";
      cout.flush();
      string T;
      cin >> T;
      c[i - 1] = T == "Red";
    } else if (i > li && i < li + N) {
      cout << "? ";
      FOR(j, li, li + N + 1)
      if (j != i)
        cout << j << " ";
      cout << "\n";
      cout.flush();
      string T;
      cin >> T;
      c[i - 1] = T == "Blue";
    }
  }

  cout << "! ";
  REP(i, N * 2)
  cout << (c[i] ? "R" : "B");
  cout << "\n";
}

