      ccc = color[n];
      ci = n;
      break;
    }
  }

  REP(n,N) {
    vv[queryCounter] = vv[vvQueryIndex];
    int old = vv[queryCounter][n];
    vv[queryCounter][n] = ci;
    if(ccc == query()) {
      color[old] = -1;
    } else {
      color[old] = 1;
    }
  }

  writeAns();

  return 0;
}

