int main() {
    cin >> N;

    if (N == 1) {
        auto tmp = get(0);
        if (tmp == "Red") cout << "RB" << endl;
        else cout << "BR" << endl;
        return 0;
    }

    int left = 0, right = N;
    string start = get(left);
    while (right - left > 1) {
        int mid = (left + right) / 2;
        if (get(mid) == start) left = mid;
        else right = mid;
    }

    vector<int> base(N-1);
    for (int i = 0; i < N-1; ++i) base[i] = left + i+1;

    vector<int> red, blue, nbase;
    string res(N*2, 'U');
    for (int i = 0; i < N*2; ++i) {
        if (i >= base[0] && i <= base.back()) continue;
        base.push_back(i);
        auto tmp = get(base);
        if (tmp == "-1") return 0;
        if (tmp == "Red") {
            res[i] = 'R';
            if (red.size() < N/2) red.push_back(i), nbase.push_back(i);
        }
        else {
            res[i] = 'B';
            if (blue.size() < N/2) blue.push_back(i), nbase.push_back(i);
        }
        base.pop_back();
    }

    for (auto i : base) {
        nbase.push_back(i);
        auto tmp = get(nbase);
        if (tmp == "-1") return 0;
        if (tmp == "Red") res[i] = 'R';
        else res[i] = 'B';
        nbase.pop_back();
    }
    cout << "! " << res << endl;
    return 0;
}

