vector<int> find_null(int ptr) {
    int l = 1; 
    int m; 
    int r = n; 
    while (l + 1 < r) {
        m = (l + r) / 2; 
        if (get(m) == ptr) l = m;
        else r = m;  
    }    
    vector<int> eq;
    for (int i = 0; i < n - 1; ++i) {
        eq.pb(r + i); 
    }
    return eq; 
}

void solve() { 
    cin >> n;
    vector<int> q; 
    for (int i = 1; i <= n; ++i) {
        q.pb(i); 
    }    
    int ptr = ask(q); 
    vector<int> eq = find_null(ptr);
    for (auto v : eq) used[v] = 1; 
    for (int i = 1; i <= 2 * n; ++i) {
        if (!used[i]) {
            eq.pb(i); 
            int t = ask(eq);
            if (t == 0) {
                ans[i] = 'R'; 
            }  else {
                ans[i] = 'B'; 
            }
            eq.pop_back(); 
        }
    }
    vector<int> ms;
    int R = 0;
    int B = 0; 
    for (int i = 1; i <= 2 * n; ++i) {
        if (!used[i]) {
            if (ans[i] == 'R') {
                if (R != (n - 1) / 2) {
                    ++R; 
                    ms.pb(i); 
                }
            } else {
                if (B != (n - 1) / 2) {
                    ++B; 
                    ms.pb(i); 
                }
            }
        }        
    }
    for (int i = 1; i <= 2 * n; ++i) {
        if (used[i]) {
            ms.pb(i); 
            int t = ask(ms);
            if (t == 0) ans[i] = 'R'; 
            else ans[i] = 'B'; 
            ms.pop_back(); 
        }        
    }
//    freopen("TASK.out", "w", stdout); 
    cout << "! ";
    for (int i = 1; i <= 2 * n; ++i) cout << ans[i]; 
    cout << endl; 
}                                   

