int pos, ans[N + N];
int val, l, r, m;

int solve(int l, int r)
{
	if (l + 1 == r)
		return r;
	int m = (l + r) / 2;
	if (query(m) == val)
		return solve(m, r);
	else
		return solve(l,m);

}

