		x.pop_back();
	}
	x.clear();

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n - 1 && i >= pos)
			continue;
		if (ans[i] == 0 && x.size() < (n - 1) / 2)
			x.PB(i);
	}
	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n - 1 && i >= pos)
			continue;
		if (ans[i] == 1 && x.size() < (n - 1))
			x.PB(i);
	}

	for (int i = 1; i <= n + n; i++)
