typedef long long ll;
typedef long double ld;
typedef pair<ll, ll> ii;
typedef tuple<ll, ll, ll> iii;
typedef vector<ll> vi;
typedef vector<ii> vii;
typedef vector<iii> viii;
typedef vector<vi> vvi;
typedef vector<vii> vvii;
#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (int i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define PB push_back
#define MP make_pair
#define MT make_tuple
#define ALL(v) v.begin(), v.end()
#define rALL(v) v.rbegin(), v.rend()

const int MAX = 101;

int N;
int color[2*MAX];

string query(vi nums) {
    cout << "?";
    FORE(n, nums) cout << " " << (n+1);
    cout << endl;
    string ans;
    cin >> ans;
    return ans;
}

vi sequence(int n) {
    vi nums(N);
    REP (i, N) nums[i] = i+n;
    return nums;
}

void set_color(int n, string c, bool other) {
    if (other ^ c == "Blue") color[n] = 1;
    else color[n] = 2;
}

string solve() {
    string base = query(sequence(0));

    int left = 0, right = N;
    while (right - left > 1) {
        int mid = (left + right) / 2;
        if (query(sequence(mid)) == base) left = mid;
        else right = mid;
    }

    set_color(left, base, true);
    set_color(left+N, base, false);

    vi row1 = sequence(left+1);
    vi row2;
    REP (i, left) row2.PB(i);
    FOR (i, left+N+1, 2*N) row2.PB(i);
    row2.PB(0);

    REP (i, 2*N) {
        if (i == left || i == left + N) continue;
        else if (i < left || left + N < i) {
            row1[N-1] = i;
            set_color(i, query(row1), true);
        } else {
            row2[N-1] = i;
            set_color(i, query(row2), true);
        }
    }

    string ans = "! ";
    REP (i, 2*N) ans += (color[i] == 1 ? "R" : "B");
    return ans;
}

int main() {
    cin >> N;
    cout << solve() << endl;
}

