void bin_search(int st, int dr, int val) {

    if (st == dr) {
        if (ask(st) == val) {
            pos = max(pos, st);
            return;
        }
    }
    int mij = (st + dr) / 2;
    if (ask(mij) == val) {
        pos = max(pos, mij);
        bin_search(mij + 1, dr, val);
    } else {
        bin_search(st, mij - 1, val);
    }

}

