    if(crt=="Red"){
      ri=0; bi=N;
    }else{
      ri=N; bi=0;
    }
  }

  ll lb=min(ri,bi),ub=max(ri,bi);
  while(ub-lb>1){
    ll mid=(ub+lb)/2;
    vector<ll> qs;
    repl(j,mid,mid+N)qs.push_back(j);
    string crt=query(qs);
    if(crt=="Red"){
      ri=mid;
    }else{
      bi=mid;
    }
    lb=min(ri,bi); ub=max(ri,bi);
  }
  P r=P(lb+1,lb+N);

