    v.push_back(i);
    string crt=query(v);
    if(crt=="Red"){
      res[i]='R';
      if(rcnt<(N-1)/2){
        oth.push_back(i);
        rcnt++;
      }
    }else{
      res[i]='B';
      if(bcnt<(N-1)/2){
        oth.push_back(i);
        bcnt++;
      }
    }
  }

  repl(i,r.fi,r.se){
    vector<ll> v=oth;
    v.push_back(i);
    string crt=query(v);
    if(crt=="Red"){
      res[i]='R';
    }else{
      res[i]='B';
    }
  }

  answer(res);

  return 0;
}

