ll n, Ans[105];
vector<int> V;

ll ask()
{
    string ans;
    cout<<"? ";
    for (auto i : V)
        cout<<i<<" ";
    cout<<'\n';
    cout.flush();
    cin>>ans;
    if (ans == "-1")
        assert(false);
    return ans == "Blue";
}

int askCircular(int x)
{
    V.clear();
    for (int i=x; i<=x+n-1; i++)
        V.push_back(i);
    int ans = ask();
    return ans;
}

int askInterval(int l, int r, int x)
{
    V.clear();
    if (r<l)
    {
        for (int i = l; i <= 2*n; i++)
            V.push_back(i);
        for (int i = 1; i <= r; i++)
            V.push_back(i);
    }
    else
    {
        for (int i = l; i <= r; i++)
            V.push_back(i);
    }
    V.push_back(x);
    int ans = ask();
    return ans;
}

void askFinish(int x)
{
    int l = x;
    int r = x+n-2;
    for (int i=1; i<=2*n; i++)
    {
        if (!(l<=i && i<=r))
        {
            int ans = askInterval(l, r, i);
            Ans[i] = ans;
        }
    }

    l = x + n;
    r = x - 2;
    for (int i=1; i<=2*n; i++)
    {
        if (!(l<=i || i<=r) && Ans[i] == 0)
        {
            int ans = askInterval(l, r, i);
            Ans[i] = ans;
        }
    }

    cout<<"! ";
    for (int i=1; i<=2*n; i++)
    {
        if (Ans[i] == 0)
            cout<<"R";
        else
            cout<<"B";
    }
    cout.flush();
}

int main()
{
    //freopen("input.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    cin>>n;

    int last = -1;
    for (int i=1; i<=n; i++)
    {
        int ans = askCircular(i);
        if (last != -1 &&  ans != last)
        {
            askFinish(i);
            return 0;
        }
        last = ans;
    }
    assert(false);
    return 0;
}

