inline void go(int p,int x) {
    char ch=(x==1)?'R':'B';
    res[p]=ch;
}
int main()
{
    scanf("%d",&n);
    a=Q1(1,n);
    b=3-a;
    go(1,a);
    go(2,b);
    if (n==1) {
        printf("! ");
        puts(res+1);
        fflush(stdout);
        return 0;
    }
    int left=1,right=n;
    while (left+1<right) {
        int mid=(left+right)>>1;
        int c=Q1(mid,mid+n-1);
        if (a==c) left=mid;
        else right=mid;
    }
    for (int i=right;i<=left+n-1;++i) vec.push_back(i);
    for (int i=2;i<right;++i) {
        vec.push_back(i);
        go(i,Q2());
        vec.pop_back();
    }
    for (int i=left+n;i<=n+n;++i) {
        vec.push_back(i);
        go(i,Q2());
        vec.pop_back();
    }
    int c1=n/2,c2=n/2;
    vec.clear();
    for (int i=1;i<right;++i) {
        if (c1&&res[i]=='R') vec.push_back(i),--c1;
        if (c2&&res[i]=='B') vec.push_back(i),--c2;
    }
    for (int i=left+n;i<=n+n;++i) {
        if (c1&&res[i]=='R') vec.push_back(i),--c1;
        if (c2&&res[i]=='B') vec.push_back(i),--c2;
    }
    for (int i=right;i<=left+n-1;++i) {
        vec.push_back(i);
        go(i,Q2());
        vec.pop_back();
    }
    printf("! ");
    puts(res+1);
    fflush(stdout);
