	cin>>N;

	char ret = show(1,N);

	char C = ret;

	int ok = 1,ng = N+1;

	while(ng-ok>1){
		int mid = (ok+ng)/2;
		ret = show(mid,N);
		if(ret==C)ok = mid;
		else ng = mid;
	}

	string ans(2*N,'.');

	for(int i=1;i<=2*N;i++){
		if(i>=ok+1&&i<=ok+N-1)continue;
		ans[i-1] = show2(ok+1,N-1,i);
	}

	for(int i=0;i<2*N;i++){
		if(ans[i]!='.')continue;
		vector<int> t;
		t.push_back(i+1);
		int R=0,B=0;
		for(int j=0;j<2*N;j++){
			if(ans[j]=='R'){
				if(R<N/2){
					R++;
					t.push_back(j+1);
				}
			}
			if(ans[j]=='B'){
				if(B<N/2){
					B++;
					t.push_back(j+1);
				}
			}
		}
		ans[i] = show(t);
	}

	answer(ans);

	return 0;
}

