signed main() {
	INIT;

	VAR(int, n);

	std::string ans(n * 2, '~');

	V<int> a(n);
	std::iota(ALL(a), 0);

	std::string first = query(a);
	V<int> b;

	auto check = [&](int x) {
		V<int> c;
		REP(i, x) c.emplace_back(i);
		REP(i, n - x) c.emplace_back(i + n);
		return first == query(c);
	};

	int f0 = n, f1 = 0;
	while (f0 - f1 > 1) {
		int me = (f1 + f0) / 2;
		if (check(me)) f0 = me;
		else f1 = me;
	}

	a.resize(0);
	b.resize(0);
	std::set<int> used;
	REP(i, f0 - 1) a.emplace_back(i), used.insert(i);
	REP(i, n - f0) b.emplace_back(i + n), used.insert(i + n);

	REP(i, n * 2) {
		if (used.count(i)) continue;
		if (ans[i] != '~') continue;

		b.emplace_back(i);
		std::string res = query(a, b);
		ans[i] = res[0];
		b.pop_back();
	}

	int cnt[2] = {};
	a.resize(0);
	REP(i, n * 2) {
		if (ans[i] == 'R' && cnt[0] < n / 2) a.emplace_back(i), ++cnt[0];
		if (ans[i] == 'B' && cnt[1] < n / 2) a.emplace_back(i), ++cnt[1];
	}

	REP(i, n * 2) {
		if (ans[i] != '~') continue;
		a.emplace_back(i);
		std::string res = query(a);
		ans[i] = res[0];
		a.pop_back();
	}

	end(ans);

	return 0;
}

