int main(){
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	mt19937 mt(48);
	int n;
	cin >> n;
	vector<int> q;
	for(int i = 0; i < 2*n; i++) q.push_back(i);
	shuffle(q.begin(), q.end(), mt);

	auto ask_interval = [&](int i) -> int {
		vector<int> balls(n);
		for(int j = 0; j < n; j++) balls[j] = q[i + j];
		int v = ask(balls);
		return v;
	};

	int s = 0;
	int e = n;
	int vs = ask_interval(0);
	int ve = ask_interval(n);
	while(s + 1 < e){
		int m = (s + e) / 2;
		int vm = ask_interval(m);
		if(vm == vs){
			s = m;
		} else {
			e = m;
		}
	}
	vector<int> half1, half2;
	for(int j = e; j < e+n-1; j++){
		half1.push_back(q[j]);
		half2.push_back(q[(j+n) % (2*n)]);
	}
	vector<int> color(2*n);
	color[q[s]] = vs;
	color[q[s+n]] = ve;
	for(int x : half1){
		vector<int> c = half2;
		c.push_back(x);
		color[x] = ask(c);
	}
	for(int x : half2){
		vector<int> c = half1;
		c.push_back(x);
		color[x] = ask(c);
	}
	answer(color);
}

