void solve() {
	int n; cin >> n;
    int a = 0, b = n;
    vector<int> res1(n), res2(n);
    rep(i, n) {
        res1[i] = i + 1;
        res2[i] = i + n + 1;
    }
    string A = query(res1), B = query(res2);
    while(b - a > 1) {
        int mid = (a + b) / 2;
        vector<int> res(n);
        rep(i, n) {
            res[i] = i + mid + 1;
        }
        string C = query(res);
        if(A == C) a = mid;
        if(B == C) b = mid;
    }
    vector<char> ans(2 * n);
    ans[a] = (A == "Red" ? 'R' : 'B');
    ans[a + n] = (A == "Red" ? 'B' : 'R');
    vector<int> res(n);
    rep(i, n - 1) {
        res[i] = i + a + 1 + 1;
    }
    rep(i, 2 * n) {
        if(i >= a && i <= a + n) continue;
        auto hoge = res;
        hoge[n] = i;
        string X = query(hoge);
        if(X == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }
    int j = -1;
    rep(i, n - 1) {
        if(j == a - 1) j = a + n + 1;
        else ++j;
        res[i] = j + 1;
    }
    for(int i = a + 1; i <= a + n - 1; ++i) {
        auto hoge = res;
        hoge[n] = i;
        string X = query(hoge);
        if(X == "Red") {
            ans[i] = 'R';
        } else {
            ans[i] = 'B';
        }
    }
    cout << "! ";
    for(auto& x: ans) cout << x;
    cout << endl;
    fflush(stdout);
}

