        if(consec(mid) == init)
            left = mid + 1;
        else
        {
            right = mid - 1;
            ans = min(ans , mid);
        }
    }
    col[ans-1] = init; col[ans+n-1] = !init;
    for(int i=1 ; i<ans-1 ; i++)
        col[i] = f1(i , ans-1);
    for(int i=ans+n ; i<=2*n ; i++)
        col[i] = f1(i , ans-1);
    for(int i=ans ; i<ans+n-1 ; i++)
        col[i] = f2(i , ans-1);
    cout << "! ";
    for(int i=1 ; i<=2*n ; i++)
    {
        if(col[i])
            cout << "R";
        else cout << "B";
    }
    cout << "\n";
