int main() {
	int n; scanf("%d", &n);

	std::string ans(2 * n, '?');
	bool now = false;
	{
		std::vector<int> q(n);
		std::iota(begin(q), end(q), 1);
		now = query(q);
	}

	int tan = -1;
	std::vector<int> latte;
	for(int i = 1; i < n + 1; i++) {
		std::vector<int> q;
		for(int j = 0; j < n; j++) q.push_back(i + j + 1);
		bool ret = query(q);

		if(now != ret) {
			tan = i;
			for(int j = 0; j < n - 1; j++) latte.push_back(i + j + 1);

			for(int k = i; k < i + n - 1; k++) {
				std::vector<int> q;
				for(int j = 0; j < n; j++) {
					if(i + j == k) continue;

					q.push_back(i + j + 1);
				}
				q.push_back(i);

				auto ret = query(q);
				if(now == ret) {
					ans[k] = (now ? 'R' : 'B');
				} else {
					ans[k] = (now ? 'B' : 'R');
				}
			}

			ans[i - 1] = (now ? 'R' : 'B');
			ans[i + n - 1] = (now ? 'B' : 'R');
			break;
		}
		now = ret;
	}

	for(int i = 0; i < 2 * n; i++) {
		if(tan - 1 <= i and i < tan + n) continue;

		latte.push_back(i + 1);
		auto ret = query(latte);
		latte.pop_back();

		if(now == ret) {
			ans[i] = (now ? 'R' : 'B');
		} else {
			ans[i] = (now ? 'B' : 'R');
		}
	}

	cout << "! " << ans << endl;
	return 0;
}

