bool query(const vector<int>& v, int n)
{
    cout << '?';
    for(int i=0; i<n; ++i)
        cout << ' ' << (v[i] + 1);
    cout << endl;

    string s;
    cin >> s;
    return s == "Red";
}

int main()
{
    int n;
    cin >> n;

    vector<int> v(2*n);
    for(int i=0; i<2*n; ++i)
        v[i] = i;

    vector<bool> isRed(2*n, false);
    if(!query(v, n))
        reverse(v.begin(), v.end());

    int left = 0;
    int right = n;
    while(right - left > 1){
        int mid = (left + right + 1) / 2;
        vector<int> v2 = v;
        rotate(v2.begin(), v2.begin() + mid, v2.end());
        if(query(v2, n))
            left = mid;
        else
            right = mid;
    }
    rotate(v.begin(), v.begin() + left, v.end());
    isRed[v[0]] = true;

    for(int i=1; i<n; ++i){
        swap(v[i], v[n]);
        if(!query(v, n))
            isRed[v[n]] = true;
        swap(v[i], v[n]);
    }
    for(int i=n+1; i<2*n; ++i){
        swap(v[0], v[i]);
        if(query(v, n))
            isRed[v[0]] = true;
        swap(v[0], v[i]);
    }

    cout << "! ";
    for(int i=0; i<2*n; ++i){
        if(isRed[i])
            cout << 'R';
        else
            cout << 'B';
    }
    cout << endl;

    return 0;
}

