   for (int i = 1; i <= n; i ++) q1.pb (i);
   bool t = ask (q1);
   q1.clear ();
   while (L <= R) {
      int mid = L + R >> 1;
      q1.clear ();
      q2.clear ();
      for (int j = mid; j < mid + n; j ++) q1.pb (j);
      bool r1 = ask (q1);
