						dec=true;
					}
				}
				if(cnt[0]==n){
					ans[j]=1;
				}else if(cnt[1]==n){
					ans[j]=0;
				}else if(!dec){
					ans[j]=1-send_q();
					cnt[ans[j]]++;
					if(ans[j]==0){
						dep--;
					}else{
						dep++;
					}
				}
			}
			break;
		}
	}
	send_a();
	return 0;
}

