class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int ans = 0, N;
  vector<Int> B, R;
  Solver() {}
  void input() {
    cin >> N;
  }
  void solve() {
    set<Int> found;
    rep(tc, 210){
      if(int(R.size()) == N)break;
      cerr << "Red: ";
      FOR(r, R){
        cerr << r << " ";
      }
      cerr <<endl;
      cerr << "Blue: ";
      FOR(r, B){
        cerr << r << " ";
      }
      cerr <<endl;
      vi baseQ;
      rep(i, B.size()){
        baseQ.push_back(B[i]);
        baseQ.push_back(R[i]);
        if(Int(baseQ.size() + 1) == Int(N))break;
      }

      string lastResult;
      deque<Int> Q;
      rep(i, 2*N){
        if(found.count(i))continue;
        Q.push_back(i);
        if(Int(baseQ.size() + Q.size()) < N)continue;
        Int last = -1;
        if(Int(baseQ.size() + Q.size()) > N) {
          last = Q.front();
          Q.pop_front();
        }

        cout << "?";
        FOR(b, baseQ)cout << " " << b;
        FOR(q,Q)cout << " " << q;
        cout << endl;
        string result;
        cin >> result;
        if(lastResult == ""){
          lastResult = result;
          continue;
        }
        if(result != lastResult){
          if(result == "Blue"){
            found.insert(i);
            found.insert(last);
            B.push_back(i);
            R.push_back(last);
            goto NEXT;
          }
          if(result == "Red"){
            found.insert(i);
            found.insert(last);
            R.push_back(i);
            B.push_back(last);
            goto NEXT;
          }
        }
      }
      NEXT:;
    }
  }
  void output() {
    map<Int, char> M;
    FOR(r, R)M[r] = 'R';
    FOR(r, B)M[r] = 'B';
    cout << "! ";
    rep(i, N*2){
      cout << M[i];
    }
    cout <<endl;
  }
};

