int n,pos,c[N+N],ans[N+N];
vector<int> a;
bool last;

int main()
{
	srand(84684);
	cin >> n;
	for (int i = 1; i <= n + n; i++)
		a.PB(i);
	random_shuffle(all(a));
	a.PB(0);
	reverse(all(a));
	for (int i = 1; i <= n+1; i++)
	{
		vector<int> v;
		for (int j = 0; j < n; j++)
			v.PB(a[i+j]);
		int res = query(v);
		if (i != 1 && res != last)
		{
			pos = i;
			last = res;
			break;
		}
		last = res;
	}

	c[pos + n-1] = last;
	c[pos - 1] = !last;
	vector<int> x;
	for (int i = pos; i < pos + n - 1; i++)
		x.PB(a[i]);

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n && i >= pos - 1)
			continue;
		x.PB(a[i]);
		c[i] = query(x);
		x.pop_back();
	}
	x.clear();
	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n && i >= pos - 1)
			continue;
		if (c[i] == 0 && x.size() < (n - 1) / 2)
			x.PB(a[i]);
	}
	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n && i >= pos - 1)
			continue;
		if (c[i] && x.size() < (n - 1))
			x.PB(a[i]);
	}

	for (int i = 1; i <= n + n; i++)
	{
		if (i < pos + n-1 && i >= pos)
		{
			x.PB(a[i]);
			c[i] = query(x);
			x.pop_back();
		}
	}
	for (int i = 1; i <= n + n; i++)
		ans[a[i]] = c[i];
	cout << "! ";

	for (int i = 1; i <= n + n; i++)
		if (ans[i])
			cout << "R";
		else
			cout << "B";
	cout << endl;

	return 0;
}

