        int mid = (left + right) / 2;
        if(val == ask1(mid)){
            it = mid;
            left = mid + 1;
        }
        else right = mid - 1;
    }

    char sol[2*N];
    if(!val){
        sol[it] = 'B';
        sol[it + N] = 'R';
    }
