int main() {
  i64 N;
  cin >> N;

  vector<i64> blue(N);
  vector<i64> red(N);
  rep(i,0,N) blue[i] = i + 1;
  rep(i,0,N) red[i] = N + i + 1;

  vector<char> ans(2 * N);

  {
    auto s = query(blue);
    if(s == "Red") {
      swap(blue, red);
    }
  }

  i64 ok = N;
  i64 ng = 0;
  while(ok - ng > 1) {
    i64 mid = (ok + ng) /2;
    rep(i,0,mid) {
      swap(red[i], blue[i]);
    }
    if(query(blue) == "Red") {
      ok = mid;
    }
    else {
      ng = mid;
    }
    rep(i,0,mid) {
      swap(red[i], blue[i]);
    }
  }

  i64 B = ok - 1;

  ans[B] = 'R';
  ans[B + N] = 'B';

  swap(blue[B], red[B]);

  rep(i,0,N) {
    if(B == i) continue;
    swap(blue[i], red[B]);
    if(query(blue) == "Red") {
      ans[i] = 'B';
    }
    else {
      ans[i] = 'R';
    }
    swap(blue[i], red[B]);
  }

  rep(i,0,N) {
    if(B == i) continue;
    swap(blue[B], red[i]);
    if(query(red) == "Blue") {
      ans[i + N] = 'R';
    }
    else {
      ans[i + N] = 'B';
    }
    swap(blue[B], red[i]);
  }
  cout << "! ";
  rep(i,0,N * 2) {
    cout << ans[i];
  }
  cout << endl;
}

