int main(){
    ll n;
    cin >> n;

    vector<ll> tmp(n);
    REP(i, n){ tmp.at(i) = i; }
    ll col0 = ask(tmp);

    ll pos = binary_search(
        1, n,
        [&](ll mid) -> bool {
            vector<ll> tmp(n);
            REP(i, n){ tmp.at(i) = mid + i; }
            ll col = ask(tmp);
            return col != col0;
        },
        false
    );

    vector<ll> ans(2 * n, -1);
    ans.at(pos - 1) = col0;
    ans.at(pos + n - 1) = 1 - col0;

    REP(i, 2 * n){
        if(ans.at(i) != -1){
            continue;
        }
        vector<ll> tmp(n);
        tmp.at(0) = i;
        if(i < pos || i >= pos + n){
            REP(j, n - 1){
                tmp.at(j + 1) = pos + j;
            }
        }else{
            REP(j, n - 1){
                tmp.at(j + 1) = (pos + n + j) % (2 * n);
            }
        }
        ans.at(i) = ask(tmp);
    }

    cout << "! ";
    REP(i, 2 * n){
        if(ans.at(i) == 0){
            cout << 'R';
        }else{
            cout << 'B';
        }
    }
    cout << endl << flush;

    return 0;
}

