void solve(istream& input, ostream& output) {
	int N; cin >> N;
	vector<int> P(N*2);
	iota(all(P), 1);
	random_device seed_gen;
	mt19937 engine(seed_gen());
	shuffle(all(P), engine);
	bool r; cout << '?';
	rep(i, N) {
		cout << ' ' << P[i];
	}
	cout << endl;
	string in; cin >> in;
	r = in[0] == 'R';
	int pos = 0;
	reps(i, 1, 1e9) {
		cout << '?';
		reps(j, i, i+N) {
			cout << ' ' << P[j];
		}
		cout << endl;
		cin >> in;
		assert(in != "-1");
		if ((in[0] == 'R') != r) {
			pos = i;
			break;
		}
	}
	vector<int> R, B;
	if (r) {
		R.push_back(P[pos-1]);
		B.push_back(P[pos-1+N]);
	} else {
		B.push_back(P[pos-1]);
		R.push_back(P[pos-1+N]);
	}
	rep(i, pos-1) {
		cout << '?';
		cout << ' ' << P[i];
		reps(j, pos, pos+N-1) {
			cout << ' ' << P[j];
		}
		cout << endl;
		cin >> in;
		assert(in != "-1");
		if (in[0] == 'R') R.push_back(P[i]);
		if (in[0] == 'B') B.push_back(P[i]);
	}
	cout << pos << endl;
	reps(i, pos+N, 2*N) {
		cout << '?';
		cout << ' ' << P[i];
		reps(j, pos, pos+N-1) {
			cout << ' ' << P[j];
		}
		cout << endl;
		cin >> in;
		assert(in != "-1");
		if (in[0] == 'R') R.push_back(P[i]);
		if (in[0] == 'B') B.push_back(P[i]);
	}
	reps(i, pos, pos+N-1) {
		cout << '?';
		cout << ' ' << P[i];
		rep(j, N / 2) {
			cout << ' ' << R[j];
		}
		rep(j, N / 2) {
			cout << ' ' << B[j];
		}
		cout << endl;
		cin >> in;
		assert(in != "-1");
		if (in[0] == 'R') R.push_back(P[i]);
		if (in[0] == 'B') B.push_back(P[i]);
	}
	string res(2*N, ' ');
	cout << "! ";
	rep(i, N) {
		res[R[i]-1] = 'R';
	}
	rep(i, N) {
		res[B[i]-1] = 'B';
	}
	cout << res << endl;
}

