VI segment(int p)
{
	VI ans;

	for(int i = p; i < p+n; ++i)
		ans.pb(i);

	return ans;
}

int ask(VI v) //B = 0, R = 1
{
	cout << "? ";

	for(auto it:v)
		cout << it << " ";

	cout << endl;
	fflush(stdout);

	string ans;
