int32_t main()
{
	cin >> n;

	int pozycja = -1, jaki = -1;

	int last = ask(segment(1));

	for(int i = 2; i + n - 1 <= 2 * n; ++i)
	{
		int curr = ask(segment(i));

		if(last != curr)
		{
			pozycja = i-1;

			if(last)
				jaki = 1;
			else
				jaki = 0;

			ans[pozycja] = jaki;
			ans[pozycja+n] = (jaki^1);
			break;
		}

		last = curr;
	}

	VI rowno;

	for(int i = pozycja+1; i <= pozycja+n-1; ++i)
	{
		rowno.pb(i);
	}

	for(int i = 1; i <= 2*n; ++i)
	{
		if(i<pozycja || i>pozycja+n)
		{
			rowno.pb(i);
			ans[i] = ask(rowno);
			rowno.pop_back();
		}
	}

	VI pyk = rowno;
	pyk.pb(pozycja);
	pyk.pb(pozycja+n);

	for(int i = pozycja+1; i <= pozycja+n-1; ++i)
	{
		pyk.erase(remove(ALL(pyk), i), pyk.end());
		ans[i] = (ask(pyk)^1);
		pyk.pb(i);

	}

	cout << "! ";

	for(int i = 1; i <= 2*n; ++i)
	{
		if(ans[i])
			cout << "R";
		else
			cout << "B";
	}

	cout << endl;
	fflush(stdout);
}

