vector <int> getEqual(){
	vector <int> all;
	for(int i = 1; i <= n + n; ++i)
		all.push_back(i);
	random_shuffle(all.begin(), all.end());

	vector <int> Left, Right;
	for(int i = 0; i < n + n; ++i)
		if(i < n)	Left.push_back(all[i]);
		else	Right.push_back(all[i]);

	if(!ask(Left))
		swap(Left, Right);

	random_shuffle(Left.begin(), Left.end());
	random_shuffle(Right.begin(), Right.end());	

	vector <int> tmp = Left;
	while(true){
