void f(const set<int> &balance) {
	string res;
	rep(i, 2 * n) {
		if (balance.count(i) || ans[i] != 0)continue;
		cout << "?";
		for (int x : balance)cout << ' ' << x + 1;
		cout << ' ' << i + 1 << endl;
		cin >> res;
		if (res == "Red")ans[i] = 'R';
		else ans[i] = 'B';
	}
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n;

	string res;
	cout << '?';
	rep(i, n)cout << ' ' << i + 1;
	cout << endl;

	cin >> res;
	int lb = 0, ub = n;
	while (ub-lb>1) {
		int mid = (lb + ub) / 2;
		cout << '?';
		rep(i, n) {
			if (i < mid)cout << ' ' << i + n + 1;
			else cout << ' ' << i + 1;
		}
		cout << endl;
		string r;
		cin >> r;
		if (res == r)lb = mid;
		else ub = mid;
	}

	set<int> balance;
	rep(i, n) {
		if (i == lb)continue;
		if (i < lb)balance.insert(i + n);
		else balance.insert(i);
	}
	f(balance);

	set<int> balance2;
	int nr = 0, nb = 0;
	rep(i, 2 * n) {
		if (ans[i] == 'R' && nr < (n - 1) / 2) {
			balance2.insert(i);
			nr++;
		}
		else if (ans[i] == 'B' && nb < (n - 1) / 2) {
			balance2.insert(i);
			nb++;
		}
	}
	f(balance2);


	return 0;
}

