std::vector<int> get_segment(int s, int len, int i, int j) {
	std::vector<int> q;
	for(int k = s; k < s + len; k++) {
		if(i != j and k == i) continue;

		q.push_back(k + 1);
	}
	if(i != j) q.push_back(j + 1);
	return q;
}

char c(bool f) {
	return (f ? 'R' : 'B');
}

int main() {
	int n; scanf("%d", &n);

	// 1
	bool now = query(get_segment(0, n, 0, 0));

	// 7
	int L = 1, R = n + 1; // [L, R)
	while(std::abs(L - R) > 1) {
		int mid = (L + R) >> 1;

		auto ret = query(get_segment(mid, n, 0, 0));
		if(now == ret) L = mid;
		else R = mid;
	}

	// 1
	int bound = (query(get_segment(L, n, 0, 0)) != now ? L - 1 : L);
	// [bound, bound + n) != [bound + 1, bound + n + 1)
	// [bound, bound + n) == now

	// 2
	assert(query(get_segment(bound, n, 0, 0)) != query(get_segment(bound + 1, n, 0, 0)));

	std::string ans(2 * n, '?');
	ans[bound]	   = c(now);
	ans[bound + n] = c(!now);

	// 198
	for(int i = 0; i < 2 * n; i++) {
		if(i == bound or i == bound + n) continue;

		if(bound + 1 <= i and i < bound + n) {
			auto ret = query(get_segment(bound + 1, n, i, bound));

			ans[i] = (now == ret ? c(!now) : c(now));
		} else {
			auto ret = query(get_segment(bound + 1, n, bound + n, i));

			ans[i] = (now == ret ? c(now) : c(!now));
		}
	}

	cout << "! " << ans << endl;
	return 0;
}

