                //分岐点
                break;
            }
            ii++;
        }
        //N-ksum+ii-1ならfalseつまり最初少数派だったほう,N-ksum+iiならtrue
        int NNN = N - ksum + ii;
        int rNNN = N - NNN;
        cerr << NNN << " " << rNNN << endl;
        tasuu[NNN] = true;
        tasuu[N + NNN] = false;
        for (int idx = NNN + 1; idx < N + NNN; ++idx) {
            query2(NNN - 1, idx, rNNN);
        }

        for (int idx = 1; idx <= NNN - 1; ++idx) {
            query3(NNN, idx);
        }
        for (int idx = N + NNN + 1; idx <= 2 * N; ++idx) {
            query3(NNN, idx);
        }
        break;
    }
    cout << "! ";
    for (int i = 1; i <= 2 * N; ++i) {
        if (tasuu[i] == red)cout << "R";
        else cout << "B";
    }
    cout << endl;
    return 0;
}

