			ans[i]=0;
			ans[i+n]=1;
			for(int j=0;j<i;j++){
				for(int k=0;k<n-1;k++){
					query[k]=i+k+2;
				}
				query[n-1]=j+1;
				ans[j]=send_q();
				cnt[ans[j]]++;
			}
			for(int j=i+n+1;j<n*2;j++){
				for(int k=0;k<n-1;k++){
					query[k]=i+k+2;
				}
				query[n-1]=j+1;
				ans[j]=send_q();
				cnt[ans[j]]++;
			}
			cnt[0]++;
			cnt[1]++;
			for(int j=i+1;j<n;j++){
				int pos=0;
				for(int k=i+1;k<n;k++){
					if(j==k)continue;
					query[pos]=k+1;
				}
				query[n-2]=i+1;
				query[n-1]=i+n+1;
				if(cnt[0]==n){
					ans[j]=1;
				}else if(cnt[1]==n){
					ans[j]=0;
				}else{
					ans[j]=1-send_q();
					cnt[ans[j]]++;
				}
			}
			break;
		}
	}
	send_a();
	return 0;
}

