int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> n;

	if (n == 1) {
		ll res = query({0});
		cout << "! " << (res ? "BR" : "RB") << endl;
		return 0;
	}

	bool pref = queryc(0);

	ll lo = 0, hi = n;
	while (hi-lo > 1) {
		ll mid = (lo+hi)/2;
		if (queryc(mid) == pref) lo = mid;
		else hi = mid;
	}
	ll j = hi;


	vl balanced;
	balanced.resize(n-1);
	iota(all(balanced),j);

	vl res(2*n,-1);
	res[j-1] = pref;
	res[j+n-1] = !pref;
	FOR(i,0,2*n) if (i+1 < j || i >= j+n) {
		balanced.pb(i);
		res[i] = query(balanced);
		balanced.pop_back();
	}

	balanced.clear();
	vl need(2,n/2);
	FOR(i,0,2*n) if (res[i] != -1 && need[res[i]]) {
		balanced.pb(i), need[res[i]]--;
	}
	assert(sz(balanced) == n-1);

	FOR(i,j,j+n-1) {
		balanced.pb(i);
		res[i] = query(balanced);
		balanced.pop_back();
	}

	cout << "! ";
	FOR(i,0,2*n) cout << "RB"[res[i]];
	cout << endl;
}

