int N;
int M;
bool query(vector<int> v) {
	cout << '?';
	REP(i, 0, N) {
		cout << ' ' << v[i] % M + 1;
	}
	cout << endl;

	string t;
	cin >> t;
	return t == "Blue";
}

void answer(vector<int> v) {
	cout << "! ";
	for (int b : v) {
		cout << (b ? 'B' : 'R');
	}
	cout << endl;
}

void rec(vector<int>& ans, int l, int r, vector<int> fix) {
	if (l == r) return;
	vector<int> v = fix;
	REP(i, l + 1, r - 1) {
		v.push_back(i);
	}

	v.push_back(l);
	bool a = query(v);
	v.pop_back();
	v.push_back(r - 1);
	bool b = query(v);
	v.pop_back();

	if (a == b) {
		ans[l % M] = ans[(r - 1) % M] = !a;
	} else {
		ans[l % M] = a;
		ans[(r - 1) % M] = b;
	}
	fix.push_back(l);
	fix.push_back(r - 1);
	rec(ans, l + 1, r - 1, fix);
}

int main() {
	cin >> N;
	M = 2 * N;
	vector<int> ans(M, -1);
	vector<int> res;
	REP(i, 0, N) {
		vector<int> v;
		REP(k, i, N + i) {
			v.push_back(k);
		}
		res.push_back(query(v));
	}
	REP(i, 0, N) {
		res.push_back(!res[i]);
	}

	REP(i, 0, M) {
		if (res[0] != res[i]) {
			int a = i - 1;
			int b = i - 1 + N;
			ans[a] = res[0];
			ans[b] = res[i];

			vector<int> fix = { a, b };
			rec(ans, a + 1, a + N, fix);
			rec(ans, b + 1, b + N, fix);
			break;
		}
	}
	answer(ans);

	return 0;
}

