int main() {
    int n; cin >> n;

    auto askSegment = [&] (int start) {
        cout << "? ";
        for (int i = start; i <= start + n - 1; i += 1) {
            cout << i << " ";
        }
        cout << endl;
        string answer;
        cin >> answer;
        return answer;
    };

    auto askArray = [&] (vector<int> a) {
        cout << "? ";
        for(auto val : a)
            cout << val << " ";
        cout << endl;
        string answer;
        cin >> answer;
        return answer;
    };

    vector<string> res;

    for (int i = 1; i <= n + 1; i += 1) {
        res.push_back(askSegment(i));
    }

    int bingo = -1;

    for (int i = 0; i < n + 1; i += 1)
        if (i + 1 < n + 1 and res[i] != res[i + 1]) {
            bingo = i + 1;
        }

    assert(bingo >= 1);

    vector<int> rem;
    vector<string> sol(2 * n + 1);
    map<string, vector<int>> m;

    for (int i = 1; i <= 2 * n; i += 1)
        if (i < bingo + 1 or i > bingo + n - 1) {
            vector<int> a;
            for (int j = bingo + 1; j <= bingo + n - 1; j += 1) 
                a.push_back(j);
            a.push_back(i);

            sol[i] = askArray(a);
            m[sol[i]].push_back(i);
        } else {
            rem.push_back(i);
        }

    vector<int> dummy;

    for (int i = 0; i < n / 2; i += 1) {
        dummy.push_back(m["Red"][i]);
        dummy.push_back(m["Blue"][i]);
    }

    for (int i = bingo + 1; i <= bingo + n - 1; i += 1) {
        vector<int> a = dummy;
        a.push_back(i);

        sol[i] = askArray(a);
    }

    for (int i = 1; i <= 2 * n; i += 1)
        if (sol[i] == "Red")
            sol[i] = "R";
        else
            sol[i] = "B";

    cout << "! ";
    for (auto line : sol)
        cout << line;
    cout << endl;
}

