        }
        B[added] |= 1;
        D.push_back(added);
        bool curr = query(D);
        if (prev != curr) {
            B[removed] |= 2;
            B[added] |= 2;
            if (curr) A[removed] = -1, A[added] = +1;
            else      A[removed] = +1, A[added] = -1;
            break;
        }
        prev = curr;
    }
    int t = D.back();
    D.pop_back();
    B[t] &= ~1;
    for (int i = 0; i < 2 * N; i++) if (B[i] == 0) {
        D.push_back(B[i]);
        A[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    D.clear();
    int r = N / 2, b = N / 2;
    for (int i = 0; i < 2 * N; i++) {
        if (A[i] == +1 && r) D.push_back(i), r--;
        if (A[i] == -1 && b) D.push_back(i), b--;
    }
    for (int i = 0; i < 2 * N; i++) if (A[i] == 0) {
        D.push_back(i);
        A[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    cout << "! ";
    for (int i = 0; i < 2 * N; i++) {
        cout << (A[i] == +1 ? 'R' : 'B');
    }
    cout << '\n';
    return 0;
}

