string query1(int start, int n) {
    cout << "?";
    --start;
    if(start < n) {
        for(int i=start;i!=start+n;++i) cout << " " << i+1;
    } else {
        for(int i=start;i!=(start+n)%(2*n);i=(i+1)%(2*n)) cout << " " << i+1;
    }
    cout << endl;
    string ret;
    cin >> ret;
    return ret;
}

string query2(int start, int n, int target) {
    cout << "?";
    --start;
    if(start < n) {
        for(int i=start;i!=start+n-1;++i) cout << " " << i+1;
    } else {
        for(int i=start;i!=(start+n-1)%(2*n);i=(i+1)%(2*n)) cout << " " << i+1;
    }
    cout << " " << target << endl;
    string ret;
    cin >> ret;
    return ret;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> ans(2*n+1, "");
    int left = 1, right = n+1;
    string left_color = query1(1, n), right_color = query1(n+1, n);
    int query_cnt = 2;
    while(right-left > 1) {
        int mid = (left + right) / 2;
        if(query1(mid, n) == left_color) {
            left = mid;
        } else {
            right = mid;
        }
        ++query_cnt;
    }
    ans[left] = left_color;
    ans[left+n] = right_color;

    for(int i=left+1;i<left+n;++i) {
        ans[i] = query2(((left+n+1 == 2*n+1)?1:(left+n+1)), n, i);
        ++query_cnt;
    }
    for(int i=((left+n+1 == 2*n+1)?1:(left+n+1));i!=left;i=(i+1==2*n+1)?1:(i+1)) {
        ans[i] = query2(left+1, n, i);
        ++query_cnt;
    }

    assert(query_cnt <= 210);

    cout << "! ";
    for(int i=1;i<=2*n;++i){
        cout << ans[i][0];
    }
    cout << endl;
}

