#include <bits/stdc++.h>
using namespace std;

int N;

bool query(vector<int> vs) {
	assert((int)vs.size() == N);
	sort(vs.begin(), vs.end());
	cout << '?';
	for (int i = 0; i < N; i++) {
		cout << ' ' << vs[i] + 1;
	}
	cout << endl;
	string s;
	cin >> s;
	return s == "Red";
}

int main()
{
	cin >> N;
	vector<int> res(N * 2, -1);
	vector<bool> flag(N);
	for (int i = 0; i < N; i++) {
		vector<int> vs;
		for (int j = i; j < i + N; j++) {
			vs.push_back(j);
		}
		flag[i] = query(vs);
	}
	flag.push_back(!flag[0]);
	int pos = -1;
	for (int i = 0; i < N; i++) if (flag[i] != flag[i + 1]) {
		pos = i;
		res[i] = flag[i];
		res[i + N] = flag[i + 1];
	}
	for (int i = 0; i < N * 2; i++) if (res[i] == -1) {
		vector<int> vs;
		if (i < pos) {
			vs.push_back(i);
			for (int j = pos + 1; j < pos + N; j++) {
				vs.push_back(j);
			}
		}
		else if (pos < i && i < pos + N) {
			vs.push_back(i);
			for (int j = 0; j < N * 2; j++) if (j < pos || pos + N < j) {
				vs.push_back(j);
			}
		}
		else {
			vs.push_back(i);
			for (int j = pos + 1; j < pos + N; j++) {
				vs.push_back(j);
			}
		}
		res[i] = query(vs);
	}
	cout << '!' << ' ';
	for (int i = 0; i < N * 2; i++) {
		cout << (res[i] == 1 ? 'R' : 'B');
	}
	cout << endl;
	return 0;
}

