		if(l <= i && i <= r) continue;
		vector<int> toAsk;
		for(int j = l + 1; j <= r; ++j) toAsk.emplace_back(j);
		toAsk.emplace_back(i);
		answ[i] = I::Ask(toAsk);
	}
	l += n / 2, r += n / 2;
	for(int i = 0; i < n; ++i) {
		if(answ[i]) continue;
		vector<int> toAsk;
		for(int j = l + 1; j <= r; ++j) toAsk.emplace_back(j % n);
		toAsk.emplace_back(i);
		answ[i] = I::Ask(toAsk);
	}
	I::SubmitAnswer(answ);
}

