  if(n == 1){
    cout << "? 1" << endl;
    string s; cin >> s;
    cout << "! " << s[0] << endl;
    return 0;
  }
  vector<int> q(n); rep(i, n)q[i] = i + 1;
  string b = "Red";
  cout << "? " << q << endl;
  cin >> b;
  string s;
  string res = ""; rep(i, 2 * n)res += "n";
  int k = n;

  int ld = 0, rd = n;
  int r = 1;
  if(b == "Red")r = 1;
  else r = 0;
  int cnt = 1;

  while(rd - ld > 1){
    int md = (rd + ld) / 2;
    rep(i, n)q[i] = md + i + 1;
    cnt++;
    assert(cnt <= 210);
    cout << "? " << q << endl;
    string u; cin >> u;
    if(u == b)ld = md;
    else rd = md;
  }

  k = ld + 1;

  res[k-1] = (r == 1 ? 'R': 'B');
  res[k+n-1] = (r == 1 ? 'B': 'R');
  rep(i, n - 1)q[i] = k + 1 + i;
  for(int i = 0; i < 2 * n; i++){
    if(k - 1 <= i && i <= k + n - 1)continue;
    q.back() = i + 1;
    cnt++;
    assert(cnt <= 210);
    cout << "? " << q << endl;
    cin >> s;
    res[i] = s[0];
  }
  q.resize(0);
  rep(i, 2 * n){
    if(k - 1 <= i && i <= k + n - 1)continue;
    q.pb(i + 1);
  }
  q.pb(0);
