        cout<<i<<" ";
    cout<<'\n';
    cout.flush();
    cin>>ans;
    if (ans == "-1")
        assert(false);
    return ans == "Blue";
}

ll askllerval(ll l, ll r, ll x)
{
    if (r>2*n)
        r-=2*n;

    V.clear();
    if (r<l)
    {
        for (ll i = l; i <= 2*n; i++)
            V.push_back(i);
        for (ll i = 1; i <= r; i++)
            V.push_back(i);
    }
    else
    {
        for (ll i = l; i <= r; i++)
            V.push_back(i);
    }
    if (x!=-1)
        V.push_back(x);
    ll ans = ask();
    return ans;
}

void prllAns()
{
    cout<<"! ";
    for (ll i=1; i<=2*n; i++)
    {
        if (Ans[i] == -1)
            assert(false);

        if (Ans[i] == 0)
            cout<<"R";
        else
            cout<<"B";
    }
    cout.flush();
    exit(0);
}

void askOutOf(ll l, ll r)
{
    if (l<=r)
    {
        for (ll i=1; i<=2*n; i++)
        {
            if (!(l<=i && i<=r) && Ans[i] == -1)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }
    else
    {
        for (ll i=1; i<=2*n; i++)
        {
            if (r < i && i < l && Ans[i] == -1)
            {
                ll ans = askllerval(l, r, i);
                Ans[i] = ans;
            }
        }
    }

}

void askFinish(ll x)
{
    ll l = x;
    ll r = x+n-2;
    askOutOf(l, r);

    l = r+2;
    r = l+n-2;
    askOutOf(l, r);

    prllAns();
}

int main()
{
    //freopen("input.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    cin>>n;

    for (ll i=1; i<=2*n; i++)
        Ans[i] = -1;

    if (n==1)
    {
        V.push_back(1);
        Ans[1] = ask();
        V.clear();
        V.push_back(2);
        Ans[2] = ask();
        prllAns();
        return 0;
    }

    ll last = -1;
    for (ll i=1; i<=2*n; i++)
    {
        ll ans = askllerval(i, i+n-1, -1);
        if (last != -1 &&  ans != last)
        {
            askFinish(i);
            return 0;
        }
        last = ans;
    }
    assert(false);
    return 0;
}

