    cin >> n;
    bool resbefore = renzoku(0);
    ll same_left = -1;
    ll before = 0, after = n;
    while(after - before > 1){
        ll mid = (after + before) / 2;
        bool res = renzoku(mid);
        if(res == resbefore){
            before = mid;
        }else{
            after = mid;
        }
    }
    //before / after
