int main(void){
	cin >> n;
	int low = 0, high = n;
	const bool init = query(0);

	while(high - low > 1){
		const int mid = (low + high) / 2;
		if(query(mid))
			low = mid;
		else
			high = mid;
	}

	const int base_low = high;
	const int base_high = high + n - 2;
	string ans = string(2 * n, '?');

	vector<int> ball;
	rep(i, base_low, base_high + 1) ball.push_back(i);

	rep(i, 2 * n) {
		if(base_low <= i and i <= base_high) continue;
		ball.push_back(i);
		ans[i] = (output(ball) ? 'R' : 'B');
		ball.pop_back();
	}

	ball.clear();

	int red = 0, blue = 0;
	rep(i, 2 * n) {
		if(ans[i] == 'R' and red < (n - 1) / 2){
			ball.push_back(i);
			red++;
		}

