    if(n==1)
    {
        bool x=query(1,1);
        cout<<"! "<<C[x]<<' '<<C[x^1]<<'\n';
        cout.flush();
        return 0;
    }
    bool x=query(1,n);
    int p=1;
    for(int step=1<<8;step;step>>=1)
        if(p+step<=n+1)
            if(x==query(p+step,p+step+n-1)) p+=step;
    Sol[p]=C[x];
    Sol[p+n]=C[x^1];
    for(int i=1;i<=n+n;++i)
        if(i<p||i>p+n)
            Sol[i]=C[qquery(p+1,p+n-1,i)];
        else if(i>p&&i<p+n)
            Sol[i]=C[qqquery(1,p-1,p+n+1,n+n,i)];
    cout<<"! "<<(Sol+1)<<'\n';
    cout.flush();
    return 0;
