using namespace std;

int main(){
	ios_base::sync_with_stdio(false);
	default_random_engine engine;
	int n;
	cin >> n;
	vector<int> order(2 * n);
	for(int i = 0; i < 2 * n; ++i){ order[i] = i; }
	while(true){
		shuffle(order.begin(), order.end(), engine);
		cout << "?";
		for(int i = 0; i < n; ++i){ cout << " " << order[i] + 1; }
		cout << endl << flush;
		string result1;
		cin >> result1;
		cout << "?";
		for(int i = 0; i + 1 < n; ++i){ cout << " " << order[i] + 1; }
		cout << " " << order[n] + 1 << endl << flush;
		string result2;
		cin >> result2;
		if(result1 != result2){
			if(result1 == "Blue"){ swap(order[n - 1], order[n]); }
			break;
		}
	}
	vector<int> solution(2 * n, -1);
	solution[order[n - 1]] = 0; // Red
	solution[order[n]]     = 1; // Blue
	for(int i = n + 1; i < 2 * n; ++i){
		cout << "?";
		for(int j = 0; j + 1 < n; ++j){ cout << " " << order[j] + 1; }
		cout << " " << order[i] + 1 << endl << flush;
		string result;
		cin >> result;
		if(result == "Red"){
			solution[order[i]] = 0;
		}else{
			solution[order[i]] = 1;
		}
	}
	for(int i = n - 2; i >= 0; --i){
		cout << "?";
		for(int j = n + 1; j < 2 * n; ++j){ cout << " " << order[j] + 1; }
		cout << " " << order[i] + 1 << endl << flush;
		string result;
		cin >> result;
		if(result == "Red"){
			solution[order[i]] = 0;
		}else{
			solution[order[i]] = 1;
		}
	}
	for(const auto c : solution){
		cout << "RB"[c];
	}
	cout << endl;
	return 0;
}

