using namespace std;

int n, cnt;
char str[10];
int ans[210], a[210];
vector<int> s[2];

int main(){

    memset(a, -1, sizeof a);

    scanf("%d", &n);
    if(n == 1){
        printf("? 1\n");
        fflush(stdout);
        scanf("%s", str);
        printf("! %c %c\n", str[0], (str[0] == 'R') ? 'B': 'R');
        fflush(stdout);
        return 0;
    }

    for(int i = 1; i <= n; i++){
        printf("?");
        for(int j = 0; j < n; j++)
            printf(" %d", i+j);
        printf("\n"); fflush(stdout);

        scanf("%s", str); cnt++;
        ans[i] = (str[0] == 'R');

        if(i > 1 && ans[i] != ans[i-1]){
            //printf("found\n");
            a[i-1] = ans[i-1];
            a[i+n-1] = ans[i];
            s[ans[i-1]].push_back(i-1);
            s[ans[i]].push_back(i+n-1);

            //now solve the rest
            for(int j = 1; j <= 2*n; j++){
                if(j < i-1 || j > i+n-1){

                    printf("? %d", j);
                    for(int k = i; k < i+n-1; k++)
                        printf(" %d", k);
                    printf("\n"); fflush(stdout);

                    scanf("%s", str); cnt++;
                    a[j] = (str[0] == 'R');
                    s[a[j]].push_back(j);
                }
            }
            break;
        }
    }

    for(int i = 1; i <= 2*n; i++){
        if(a[i] == -1){
            printf("? %d", i);

            for(int j = 0; j < n/2; j++)
                printf(" %d %d", s[0][j], s[1][j]);
            printf("\n"); fflush(stdout);

            scanf("%s", str); cnt++;
            a[i] = (str[0] == 'R');
            s[a[i]].push_back(i);
        }
    }

    printf("! ");
    for(int i = 1; i <= 2*n; i++){
        if(a[i])
            printf("%c", 'R');
        else
            printf("%c", 'B');
    }
    printf("\n"); fflush(stdout);

    return 0;
}

