const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

bool isred(VI& pos) {
  static int cnter = 0;

  if(cnter > 210) exit(1);
  ++cnter;

  cout << "?";
  for(auto x : pos) cout << " " << x+1;
  cout << endl;

  string s;
  cin >> s;
  return s == "Red";
}

// xorshift
uint32_t xor64(void) {
  static uint64_t x = 88172645463325252ULL;
  x = x ^ (x << 13); x = x ^ (x >> 7);
  return x = x ^ (x << 17);
}

int main(int argc, char* argv[]){
  init_io(argc, argv);

  int N;
  cin >> N;

  int N2 = N * 2;

  // max query = 210
  vector<bool> ans(N2);
  while(true){
    set<int> poss;
    VI pos;
    REP(i,N-1){
      int j = xor64() % N2;
      if(poss.count(j)){
        --i;
        continue;
      }
      poss.insert(j);
      pos.PB(j);
    }

    int TRY = min(N2 - (N-1), 5);
    VI qs;
    set<int> qss;
    REP(i,TRY){
      int j = xor64() % N2;
      if(poss.count(j) || qss.count(j)){
        --i;
        continue;
      }
      qss.insert(j);
      qs.PB(j);
    }

    vector<bool> res(TRY);
    REP(i,TRY){
      pos.PB(qs[i]);
      res[i] = isred(pos);
      pos.pop_back();
    }

    int cnt_r = 0;
    REP(i,TRY) cnt_r += res[i];
    if(cnt_r == 0 || cnt_r == TRY) continue;

    VI reds, bs;
    REP(i,N2){
      if(poss.count(i)) continue;
      else if(qss.count(i)){
        auto ix = find(ALL(qs), i) - begin(qs);
        ans[i] = res[ix];
      }
      else{
        pos.PB(i);
        ans[i] = isred(pos);
        pos.pop_back();
      }
      if(ans[i]) reds.PB(i);
      else bs.PB(i);
    }

    VI tmp;
    REP(i,(N-1)/2) tmp.PB(reds[i]);
    REP(i,(N-1)/2) tmp.PB(bs[i]);

    for(auto i : pos){
      tmp.PB(i);
      ans[i] = isred(tmp);
      tmp.pop_back();
    }
    break;
  }

  cout << "! ";
  for(auto b : ans) cout << (b ? "R" : "B");
  cout << endl;

  return 0;
}

