char opposite(char color) {
  return color == 'B' ? 'R' : 'B';
}


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;
  if (N == 1) {
    cout << "? 1" << endl;
    string T;
    cin >> T;
    if (T[0] == 'B') cout << "BR" << endl;
    else cout << "RB" << endl;
    return 0;
  }
  string colors(N * 2, 'X');
  constexpr int blue = 1;
  constexpr int red = -1;

  cout << "?";
  for (int i = 0; i < N; ++i) {
    cout << " " << (i + 1);
  }
  cout << endl;
  string T;
  cin >> T;
  auto base_color = T[0];

  int left = 0;
  int right = N + 1;

  while (right - left > 1) {
    auto mid = (left + right) / 2;
    cout << "?";
    for (int j = 0; j < N; ++j) {
      cout << " " << (mid + j + 1);
    }
    cout << endl;
    string T;
    cin >> T;
    if (base_color != T[0]) {
      right = mid;
    } else {
      left = mid;
    }
  }

  auto base = right;

  int diff_color = base + N - 1;

  int target = base + N;

  --base;

  colors[base] = base_color;
  colors[diff_color] = opposite(base_color);

  assert(colors[target] == 'X');

  for (int swap = base + 1; swap < N + base; ++swap) {
    cout << "?";
    for (int j = 0; j < N; ++j) {
      if (base + j == swap) {
        cout << " " << (target + 1);
      } else {
        cout << " " << (base + j + 1);
      }
    }
    cout << endl;
    string T;
    cin >> T;
    if (base_color != T[0]) {
      cerr << (swap + 1) << " <- " << base_color << endl;
      cerr << (target + 1) << " <- " << opposite(base_color) << endl;
      colors[swap] = base_color;
      colors[target] = opposite(base_color);
      ++target;
    } else {
      cout << "?";
      for (int j = 0; j < N; ++j) {
        if (base + j == swap) {
          cout << " " << (diff_color + 1);
        } else {
          cout << " " << (base + j + 1);
        }
      }
      cout << endl;
      string T;
      cin >> T;
      if (base_color != T[0]) {
        cerr << (swap + 1) << " <- " << base_color << endl;
        cerr << (target + 1) << " <- " << base_color << endl;
        colors[swap] = colors[target] = base_color;
        ++target;
      } else {
        cerr << (swap + 1) << " <- " << opposite(base_color) << endl;
        colors[swap] = opposite(base_color);
      }
    }
    target %= colors.size();
  }

  for (; target != base; target = (target + 1) % colors.size()) {
    cout << "? " << (target + 1);
    for (int j = 1; j < N; ++j) {
      cout << " " << (base + j + 1);
    }
    cout << endl;
    string T;
    cin >> T;
    cerr << (target + 1) << " <- " << T[0] << endl;
    colors[target] = T[0];
  }

  cout << "! " << colors << endl;
}

