int main(){
	ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    srand(time(NULL));
    cin >> n;
    for(int i = 0 ; i < 2 * n ; ++i)
        p.push_back(i + 1);
    for(int i = 0 ; i < 1000 ; ++i)
        random_shuffle(p.begin(), p.end()); 
    for(int i = 0 ; i < (n + 1) / 2; ++i){
        bool res = ask(0);
        if(!res) reverse(p.begin(), p.end());
        int lo = 0 , hi = (int)p.size() - n - 2;
        int good = 0;
        while(lo <= hi){
            int mid = (lo + hi) >> 1;
            if(ask(mid) && !ask(mid + 1)){
                good = mid ;
                lo = mid + 1;
            }
            else hi = mid - 1;
        }
        assert(good + n < (int)p.size());
        red.push_back(p[good]);
        blue.push_back(p[good + n]);
        p.erase(p.begin() + good);
        p.erase(p.begin() + good + n - 1);
    }
    assert((int)p.size() == n - 1);
    for(int i = 1 ; i < (int)p.size() ; ++i){
        bool ans = ask2(p[i]);
        if(ans) red.push_back(p[i]);
        else blue.push_back(p[i]);
    }

    if(n > 1){
        if((int)red.size() == n) blue.push_back(p[0]);
        else red.push_back(p[0]);
    }
    for(int i = 0 ; i < n ; ++i){
        res[red[i]] = 'R';
        res[blue[i]] = 'B';
    }
    print();
    return 0;
}

