    if (idx == -1 && !ts.empty() && ts.back() != t) idx = ts.size() - 1;
    ts.emplace_back(t);
  }
  assert(idx != -1);
  vector<char> ans(n * 2, '?');
  ans[idx] = (ts[idx] == "Red" ? 'R' : 'B');
  ans[idx + n] = (ans[idx] == 'R' ? 'B' : 'R');
  FOR(j, idx + 1, idx + n - 1) {
    vector<int> a;
    FOR(k, idx, j) a.emplace_back(k);
    FOR(k, j + 1, idx + n + 1) a.emplace_back(k);
    string t = query(a);
    if (ans[idx] == 'R') {
      ans[j] = (t == "Red" ? 'B' : 'R');
    } else { // B
      ans[j] = (t == "Blue" ? 'R' : 'B');
    }
  }
  int r = 0, b = 0;
  FOR(j, idx, idx + n - 1) ++(ans[j] == 'R' ? r : b);
  if (r == b) {
    ans[idx + n - 1] = (ts[idx] == "Red" ? 'R' : 'B');
  } else {
    ans[idx + n - 1] = (r > b ? 'B' : 'R');
  }
  int red = 0, blue = 0;
  FOR(j, idx, idx + n + 1) ++(ans[j] == 'R' ? red : blue);
  vector<int> same;
  r = b = 0;
  FOR(j, idx, idx + n + 1) {
    if (ans[j] == 'R') {
      if (r < (n - 1) / 2) {
        same.emplace_back(j);
        ++r;
      }
    } else {
      if (b < (n - 1) / 2) {
        same.emplace_back(j);
        ++b;
      }
    }
  }
  FOR(j, idx, idx + n - 1) ++(ans[j] == 'R' ? r : b);
  for (int j = idx - 1; j >= 0; --j) {
    if (red == n) {
      ans[j] = 'B';
      ++blue;
    } else if (blue == n) {
      ans[j] = 'R';
      ++red;
    } else {
      if (r == b) {
        ans[j] = (ts[j] == "Red" ? 'R' : 'B');
      } else {
        same.emplace_back(j);
        ans[j] = (query(same) == "Red" ? 'R' : 'B');
        same.pop_back();
      }
    }
    --(ans[j + n - 1] == 'R' ? r : b);
    ++(ans[j] == 'R' ? r : b);
    ++(ans[j] == 'R' ? red : blue);
  }
  r = b = 0;
  FOR(j, idx + 2, idx + n + 1) ++(ans[j] == 'R' ? r : b);
  FOR(j, idx + 2, n * 2) {
    if (red == n) {
      ans[j + n - 1] = 'B';
      ++blue;
    } else if (blue == n) {
      ans[j + n - 1] = 'R';
      ++red;
    } else {
      if (r == b) {
        ans[j + n - 1] = (ts[j] == "Red" ? 'R' : 'B');
      } else {
        same.emplace_back(j + n - 1);
        ans[j + n - 1] = (query(same) == "Red" ? 'R' : 'B');
        same.pop_back();
      }
    }
    --(ans[j] == 'R' ? r : b);
    ++(ans[j + n - 1] == 'R' ? r : b);
    ++(ans[j + n - 1] == 'R' ? red : blue);
  }
  cout << "! ";
  REP(i, n * 2) {
    assert(ans[i] != '?');
    cout << ans[i];
  }
  cout << endl;
  return 0;
}

