int main()
{
    //freopen("a.in", "r", stdin);
    //freopen("a.out", "w", stdout);
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.precision(20);
    //ll TL = 10.95 * CLOCKS_PER_SEC;
    //clock_t time = clock();
    int n;
    cin >> n;
    if (n == 1) {
        vector<int> ans(n * 2, 0);
        rep(i, 0, n * 2) {
            ans[i] = ask({i});
        }
        answer(ans);
    }
    vector<int> segm(n + 1, 0);
    segm[0] = ask(get_range(0, 0 + n));
    segm[n] = -segm[0];
    int l = 0, r = n;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (segm[mid] == 0) {
            segm[mid] = ask(get_range(mid, mid + n));
        }
        if (segm[mid] != segm[l]) {
            r = mid;
        } else {
            l = mid;
        }
    }
    vector<int> ans(n * 2, 0);
    int L, R;
    if (segm[l] != segm[l + 1]) {
        if (segm[l] == 1 && segm[l + 1] == -1) {
            ans[l] = 1;
            ans[l + n] = -1;
        } else {
            ans[l] = -1;
            ans[l + n] = 1;
        }
        L = l; R = l + n;
    } else {
        assert(false);
    }
    vector<int> pos1, pos2;
    rep(i, 0, n * 2) {
        if (i < L || i > R) {
            pos1.push_back(i);
        } else if (i > L && i < R) {
            pos2.push_back(i);
        }
    }
    rep(i, 0, n * 2) {
        if (i == L || i == R) {
            continue;
        }
        if (i < L || i > R) {
            pos2.push_back(i);
            ans[i] = ask(pos2);
            pos2.pop_back();
        } else {
            pos1.push_back(i);
            ans[i] = ask(pos1);
            pos1.pop_back();
        }
    }
    answer(ans);
    return 0;
}

