int n;
int AskSegment(int l, int sz) {
	vector<int> toAsk;
	for(int i = l; i < l + sz; ++i) toAsk.emplace_back(i);
	return I::Ask(toAsk);
}
void solve() {
	I::init();
	n = I::GetN();
	int low = 0, high = n / 2;
	int lowVal = AskSegment(low, n / 2);
	int highVal = AskSegment(high, n / 2);
	assert(lowVal + highVal == 0);
	while(high - low > 1) {
		int mid = (low + high) / 2;
		if(AskSegment(mid, n / 2) == lowVal) {
			low = mid;
		} else {
			high = mid;
		}
	}
	vector<int> answ(n, 0);
	int l = low, r = low + n / 2 - 1;
	for(int i = 0; i < n; ++i) {
		if(l <= i && i <= r) continue;
		vector<int> toAsk;
		for(int j = l + 1; j <= r; ++j) toAsk.emplace_back(j);
		toAsk.emplace_back(i);
		answ[i] = I::Ask(toAsk);
	}
	l += n / 2, r += n / 2;
	for(int i = 0; i < n; ++i) {
		if(answ[i]) continue;
		vector<int> toAsk;
		for(int j = l + 1; j <= r; ++j) toAsk.emplace_back(j % n);
		toAsk.emplace_back(i);
		answ[i] = I::Ask(toAsk);
	}
	I::SubmitAnswer(answ);
}

int main() {
	//fast_io();
	solve();

	return 0;
}

