    ll n;
    cin >> n;

    if (false) {
        vl p = range(0, n);
        ll last = ask(p);
        ll index = 0;

        for (ll i = 1; i <= n; ++i) {
            vl pp = range(i, n);
            ll curr = ask(pp);
            if (curr == last) { continue; }
            index = i - 1;
            break;
        }
    }

    ll last;
    ll index;
    {
        ll l = 0;
        ll r = n;
        vl values(2);
        values[0] = ask(range(l, n));
        values[1] = ask(range(r, n));

        while (l + 1 < r) {
            ll mid = (l + r) / 2;
            ll value_mid = ask(range(mid, n));
            if (value_mid == values[0]) {
                l = mid;
            } else {
                r = mid;
            }
        }
        index = l;
        last = values[0];
    }

    vb colors(2 * n, false);
    colors[index] = last;
    colors[index + n] = 1 - last;

    for (ll i = 0; i < 2 * n; ++i) {
        if (i >= index && i <= index + n) { continue; }
        vl q = range(index + 1, n - 1);
        q.pb(i);
        colors[i] = ask(q);
    }

    for (ll i = 0; i < 2 * n; ++i) {
        if (i <= index || i >= index + n) { continue; }
        vl q;
        q.pb(i);
        for (ll xx : range(0, index)) { q.pb(xx); }
        for (ll xx : range(index + n + 1, (n - 1) - index)) { q.pb(xx); }
        colors[i] = ask(q);
    }


    ans(colors);
    print_time();
    return 0;
}

