}

void solve() {
  ll n; cin >> n;
  vector<ll> R(n), B(n);
  rep(i, n) R[i] = i, B[i] = n+i;
  if (query(R) == Blue) {
    swap(B, R);
  }
  set<ll> common;
  while (R.size() > 1) {
    assert(B.size() == R.size());
    assert(common.size() + B.size() == n);
    ll cnt = R.size() / 2;
    vector<ll> v(all(common));
    rep(i, cnt) v.pb(R[i]);
    rep(i, cnt, B.size()) v.pb(B[i]);
    if (query(v) == Red) {
      vector<ll> nR, nB;
      rep(i, cnt) {
        nR.pb(R[i]);
        nB.pb(B[i]);
      }
      rep(i, cnt, B.size()) common.insert(B[i]);
      R = nR, B = nB;
    }
    else {
      vector<ll> nR, nB;
      rep(i, cnt, R.size()) {
        nR.pb(R[i]);
        nB.pb(B[i]);
      }
      rep(i, cnt) common.insert(R[i]);
      R = nR, B = nB;
    }
  }
  assert(B.size() == 1);
  assert(R.size() == 1);
  assert(common.size() == n-1);

  vector<Color> ans(2*n, Unknown);
  ans[B[0]] = Blue;
  ans[R[0]] = Red;
  rep(i, 2*n) {
    if (ans[i] == Unknown && common.count(i) == 0) {
      vector<ll> v(all(common));
      v.pb(i);
      if (query(v) == Red) {
        ans[i] = Red;
      }
      else {
        ans[i] = Blue;
      }
    }
  }
  set<ll> ncommon;
  rep(i, 2*n) {
    if (common.count(i) == 0) {
      ncommon.insert(i);
    }
  }
  ncommon.erase(R[0]);
  ncommon.erase(B[0]);
  common = ncommon;
  // output(ans);
  rep(i, 2*n) {
    if (ans[i] == Unknown) {
      assert(common.count(i) == 0);
      vector<ll> v(all(common));
      v.pb(i);
      if (query(v) == Red) {
        ans[i] = Red;
      }
      else {
        ans[i] = Blue;
      }
    }
  }
  rep(i, 2*n) assert(ans[i] != Unknown);

  output(ans);
}

