using namespace std;
using Int = long long;
bool query(const deque<int> &A) {
    cout << "? ";
    for (auto a : A) cout << a + 1 << ' ';
    cout << endl;
    string T; cin >> T;
    if (T == "-1") exit(1);
    return T == "Red";
}
int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<int> A(2 * N);
    vector<int> B(2 * N);
    deque<int> D;
    for (int i = 0; i < N; i++) {
        int t = 0;
        for (;;) {
            t = rand() % (2 * N);
            if (B[t] == 0) break;
        }
        B[t] |= 1;
        D.push_back(t);
    }
    bool prev = query(D);
    for (;;) {
        int removed = D.front();
        D.pop_front();
        B[removed] &= ~1;
        int added = 0;
        for (;;) {
            added = rand() % (2 * N);
            if (B[added] == 0) break;
        }
        B[added] |= 1;
        D.push_back(added);
        bool curr = query(D);
        if (prev != curr) {
            B[removed] |= 2;
            B[added] |= 2;
            if (curr) A[removed] = -1, A[added] = +1;
            else      A[removed] = +1, A[added] = -1;
            break;
        }
        prev = curr;
    }
    int t = D.back();
    D.pop_back();
    B[t] &= ~1;
    for (int i = 0; i < 2 * N; i++) if (B[i] == 0) {
        D.push_back(i);
        A[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    D.clear();
    int r = N / 2, b = N / 2;
    for (int i = 0; i < 2 * N; i++) {
        if (A[i] == +1 && r) D.push_back(i), r--;
        if (A[i] == -1 && b) D.push_back(i), b--;
    }
    for (int i = 0; i < 2 * N; i++) if (A[i] == 0) {
        D.push_back(i);
        A[i] = query(D) ? +1 : -1;
        D.pop_back();
    }
    cout << "! ";
    for (int i = 0; i < 2 * N; i++) {
        cout << (A[i] == +1 ? 'R' : 'B');
    }
    cout << '\n';
    return 0;
}

