int main(){
    //cin.tie(0);
    //ios::sync_with_stdio(false);

    cin >> n;
    bool resbefore = renzoku(0);
    ll same_left = -1;
    ll before = 0, after = n;
    while(after - before > 1){
        ll mid = (after + before) / 2;
        bool res = renzoku(mid);
        if(res == resbefore){
            before = mid;
        }else{
            after = mid;
        }
    }
    //before / after
    if(resbefore){
        x[before] = 2;
        x[before+n] = 1;
        same_left = before + 1;
    }else{
        x[before] = 1;
        x[before+n] = 2;
        same_left = before + 1;
    }
    for(int i=same_left;i<=same_left + n - 2;i++){
        if(i >= 2 * n){
            insame[i - 2 * n] = true;
        }else{
            insame[i] = true;
        }
    }
    for(int i=0;i<2 * n;i++){
        if(insame[i])continue;
        if(x[i] != 0)continue;
        bool res = same_query(same_left, i);
        if(res){
            x[i] = 2;
        }else{
            x[i] = 1;
        }
    }
    vector<ll> red, blue;
    ll idx = 0;
    for(int i=0;i<2 * n;i++){
        if(x[i] == 1){
            blue.pb(i);
        }else if(x[i] == 2){
            red.pb(i);
        }
        if(blue.size() >= n / 2 && red.size() >= n / 2){
            for(int j=0;j<n/2;j++){
                y[idx++] = blue.back();
                blue.pop_back();
            }
            for(int j=0;j<n/2;j++){
                y[idx++] = red.back();
                red.pop_back();
            }
            break;
        }

    }
    for(int i=0;i<2*n;i++){
        if(insame[i]){
            bool res = last_query(i);
            if(res){
                x[i] = 2;
            }else{
                x[i] = 1;
            }
        }
    }
    answer();


    return 0;
}

