V rng(int l, int r) {
  int n = r - l + 1;
  V res(n);
  rep(i, n) res[i] = l + i;
  return res;
}


int main() {
  int n; cin >> n;

  auto f = [&] (int i) {
    cout << "? " << rng(i, i+n-1) << endl;
    string s; cin >> s;
    assert(s != "-1");
    if (s == "Red") return 0;
    else return 1;
  };

  int l = 1;
  int r = n+1;
  int xl = f(l);
  int xr = xl^1;

  while (r - l > 1) {
    int m = (l + r) >> 1;
    int xm = f(m);
    if (xl == xm) l = m;
    else r = m;
  }

  V ans(2*n+1, -1);
  ans[l] = xl;
  ans[l+n] = xr;

  rep2(i, 1, 2*n+1) {
    if (i == l || i == l+n) continue;
    if (i < l || n+l < i) cout << "? " << rng(l+1, l+n-1) << i << endl;
    else cout << "? " << rng(1, l-1) << rng(l+n+1, 2*n) << i << endl;
    string s; cin >> s;
    assert(s != "-1");
    int y = (s == "Red" ? 0 : 1);
    ans[i] = y;
  }

  cout << "! ";
  rep2(i, 1, 2*n+1) cout << (ans[i] == 0 ? 'R' : 'B');
  cout << endl;
  return 0;
}

