bool query(vector<int> q){
    cout<<"? ";
    for(const auto &x : q){
        cout<<x<<" ";
    }
    cout<<endl;
    string ans;
    cin>>ans;
    return ans=="Red";
}
vector<int> makevector(int l,int r){
    vector<int> ans(r-l+1);
    for(int i=0;i<ans.size();i++){
        ans[i]=i+l;
    }
    return ans;
}
void solve(){
    int n;
    cin>>n;
    vector<int> ans(2*n+1, -1);//1 - red, 0 - blue;
    vector<int> red, blue;
    int g,r;
    for(int i=2, prev = query(makevector(1,n));i<=n;i++){
        vector<int> q = makevector(i,n+i-1);
        if(prev!=query(q)){
            ans[i-1]=(prev==1);
            ans[n+i-1] = (prev==0);
            g=i, r=n+i-2;
            break;
        }
    }
    for(int i=1;i<=2*n;i++){
        if(i>=g && i<=r){
            continue;
        }
        vector<int> q = makevector(g,r);
        q.pb(i);
        ans[i] = query(q);
        if(ans[i]){
            red.pb(i);
        }
        else{
            blue.pb(i);
        }
    }
    vector<int> base;
    for(int i=0;i<n/2;i++){
        base.pb(red[i]);
        base.pb(blue[i]);
    }
    for(int i=g;i<=r;i++){
        base.pb(i);
        ans[i] = query(base);
        base.pop_back();
    }
    for(int i=1;i<=2*n;i++){
        cout<<(ans[i] ? "R" : "B");
    }
}
int main() {
    ios_base::sync_with_stdio(false);
    solve();
}

