char query_to_ans(string res){
    return res == "Red" ? 'R' : 'B';
}

vector<int> B, R;

string query_br(const vector<int> &B, const vector<int> &R, int n){
    cout << "?";
    for (const auto &b: B)
        cout << " " << b;
    for (const auto &r: R)
        cout << " " << r;
    cout << " " << n << endl;
    string res;
    cin >> res;

    return res;
}

int main(){
    int n;
    cin >> n;
    vector<char> ans(2 * n + 1, 'N');

    if (n == 1){
        ans[1] = query_to_ans(query(1, 2));
        ans[2] = query_to_ans(query(2, 3));
        cout << "! " << ans[1] << ans[2] << endl;
        return 0;
    }

    int l = 1, r = n + 1;
    string res_l = query(l, l + n);
    string res_r = query(r, r + n);
    while (r - l > 1){
        int mid = (r + l) / 2;
        string res_mid = query(mid, mid + n);
        if (res_mid != res_l)
            r = mid;
        else
            l = mid;
    }

    l++;
    r = l + n - 1;

    for (int i = 1; i <= 2 * n; i++){
        if (i == l){
            i = r - 1;
            continue;
        }
        if (ans[i] != 'N')
            continue;

        string res = query(l, r, i);
        ans[i] = query_to_ans(res);
    }

    for (int i = 1; i <= 2 * n; i++){
        if (ans[i] == 'B' and B.size() < n / 2)
            B.push_back(i);
        else if (ans[i] == 'R' and R.size() < n / 2)
            R.push_back(i);
    }

    for (int i = l; i < r; i++){
        string res = query_br(B, R, i);
        ans[i] = query_to_ans(res);
    }

    cout << "! ";
    for (int i = 1; i <= 2 * n; i++)
        cout << ans[i];
    cout << endl;
}

