ll gcd(ll a, ll b) {
  return b == 0 ? a : gcd(b, a%b);
}

ll mypow(ll x, ll n) {
  if(n == 0) return 1;
  if(n % 2 == 0) return mypow(x*x%MOD, n/2);
  return mypow(x*x%MOD, n/2) * x % MOD;
}

