char ans[400];

void answer(void) {
  printf("! %s\n", ans);
  fflush(stdout);
}

int main(void) {
  int N;
  scanf("%d", &N);
  char last = 0;
  vector<int> es;
  int ii = -1;
  REP(i, N+1) {
    vector<int> vs;
    REP(j, N) {
      vs.push_back(i+j);
    }
    query(vs);
    char res = buf[0];
    if(last == 0) {
      last = res;
    } else {
      if(last != res) {
        ans[i-1] = last;
        ans[i+N-1] = res;
        REP(j, N-1) {
          es.push_back(i+j);
        }
        ii = i;
        break;
      } else {
        continue;
      }
    }
  }
  REP(i, 2*N) {
    if(ans[i]) continue;
    if(ii <= i && ii < i+N-1) continue;
    es.push_back(i);
    query(es);
    es.pop_back();
    ans[i] = buf[0];
  }
  es.clear();
  {
    int rest = N / 2;
    REP(i, 2*N) {
      if(rest > 0 && ans[i] == 'R') {
        es.push_back(i);
        --rest;
      }
    }
    rest = N/2;
    REP(i, 2*N) {
      if(rest > 0 && ans[i] == 'B') {
        es.push_back(i);
        --rest;
      }
    }
  }
  REP(i, 2*N) {
    if(ans[i] == 0) {
      es.push_back(i);
      query(es);
      es.pop_back();
      ans[i] = buf[0];
    }
  }

  answer();

  return 0;
}

