template<class T>
class depth_first_search_iterator {
  public:
    stack<pair<T,T>> todo;
    function<bool(T)> notvisited;
    function<void(T)> mark_visited;
    function<set<T>(T)> neighbors;

    depth_first_search_iterator() {}

    depth_first_search_iterator(T start, function<bool(T)> notv, function<void(T)> mark_v, function<set<T>(T)> neigh) :
      notvisited(notv), mark_visited(mark_v), neighbors(neigh), end_(false), current(start), prev(start) {
          todo.push(make_pair(start, start)); operator++();
    }

    void operator++() {
        end_ = true;
        while (!todo.empty()) {
            current = todo.top().first; prev = todo.top().second; todo.pop();
            if (notvisited(current)) {
                mark_visited(current);
                for (const T x : neighbors(current)) {  todo.push(make_pair(x, current));   }
                end_ = false;
                break;
            }
        }
    }

    T operator*() {     return current;    }

    T previous() {  return prev;  }

    bool end() {  return end_;  }

  private:
    T current; // contains current node
    T prev;    // contains previous node
    bool end_;
};

template<class T>
class breadth_first_search_iterator {
  public:
    queue<pair<T,T>> todo;
    function<bool(T)> notvisited;
    function<void(T)> mark_visited;
    function<set<T>(T)> neighbors;

    breadth_first_search_iterator() {}

    breadth_first_search_iterator(T start, function<bool(T)> notv, function<void(T)> mark_v, function<set<T>(T)> neigh) :
      notvisited(notv), mark_visited(mark_v), neighbors(neigh), end_(false), current(start), prev(start) {
          todo.push(make_pair(start, start)); operator++();
    }

    void operator++() {
        end_ = true;
        while (!todo.empty()) {
            current = todo.front().first; prev = todo.front().second; todo.pop();
            if (notvisited(current)) {
                mark_visited(current);
                for (const T x : neighbors(current)) {  todo.push(make_pair(x, current));   }
                end_ = false;
                break;
            }
        }
    }

    T operator*() {     return current;    }

    T previous() {  return prev;  }

    bool end() {  return end_;  }

  private:
    T current;   // current node
    T prev;      // previous node
    bool end_;
};

template<class T>
class Graph {
    // allows only single connection between two vertices
    public:
      vector<T> vertices;
      vector<set<int>> neighbors;
      depth_first_search_iterator<int> dfs_iterator;
      breadth_first_search_iterator<int> bfs_iterator;
      vector<bool> visited;

      Graph() {}

      Graph(int n) {  for (int i = 0; i < n; ++i) {  AddVertex(0);  }   }

      void AddVertex(T val) {
          vertices.push_back(val);
          neighbors.push_back(set<int>());      }

      bool EdgeExists(int i, int j) {
          return (neighbors[i].find(j) != neighbors[i].end());
     }

      void AddEdge(int i, int j) {
          if (!EdgeExists(i,j)) {
            neighbors[i].insert(j);
            if (i != j) {         neighbors[j].insert(i);         } 
          }
      }

      T& operator[](int i) {      return vertices[i];      }

      void RemoveEdge(int i, int j) {
          if (EdgeExists(i,j)) {
            neighbors[i].erase(find(neighbors[i].begin(), neighbors[i].end(), j));
            neighbors[j].erase(find(neighbors[j].begin(), neighbors[j].end(), i));
          }
      }

      void dfs_init(int start) {
          visited = vector<bool>(vertices.size(), false);
          dfs_iterator = depth_first_search_iterator<int>(start, [this](int x){ return !visited[x]; }, [this](int x) { visited[x] = true;  },
            [this](int x) {  return neighbors[x];  } );
      }

      void bfs_init(int start) {
          visited = vector<bool>(vertices.size(), false);
          bfs_iterator = breadth_first_search_iterator<int>(start, [this](int x){ return !visited[x]; }, [this](int x) { visited[x] = true;  },
            [this](int x) {  return neighbors[x];  } );
      }

      void print_() {
          forr(i, 0, vertices.size()) {
              for (auto x : neighbors[i]) {
                  if (i <= x) {  cout << i << "-" << x << endl;  }                  
              }
          }
      }
};

template<class T>
pair<vector<T>, vector<int>> DijkstraUndirected(int N_vertices, map<pair<int,int>, T>& edges, int s, T infinity) {
    // input edges with weight of type T, return two arrays: first contains shortest distance from s, second (prev)
    // contains info on constructing path: start at vertex t, go to prev[t], then prev[prev[t]], until s, you get (shortest) path from t to s
    // infinity should be higher than all distances, and too high to prevent weird wraparound  effects in addition dist[u]+edges[]... below

    vector<T> dist(N_vertices, infinity);
    dist[s] = 0;
    vector<int> prev(N_vertices);
    set<pair<T,int>> Q;
    for (int i = 0; i < N_vertices; ++i) {  Q.insert(make_pair(dist[i], i));   }
    Graph<int> g(N_vertices);
    for (auto x : edges) {  g.AddEdge(x.first.first, x.first.second);  }

    while (!Q.empty()) {
        int u = Q.begin()->second;
        Q.erase(Q.begin());

        for (int v : g.neighbors[u]) {
                T one_way = 0, other_way = 0;
                if (edges.find(make_pair(u,v)) != edges.end() ) {   one_way = edges[make_pair(u,v)];   }
                if (edges.find(make_pair(v,u)) != edges.end() ) {   other_way = edges[make_pair(v,u)];   }
                T alt = dist[u] + one_way + other_way;   // since each edge is present in only one of those edges[u,v] & edges[v,u]
                   // if you need modification for directed graph, only first edges should be used
                   // CAREFUL!!!! edges should contain each edge only once!!! not twice for both directions
                if (alt < dist[v]) {
                    prev[v] = u;
                    Q.erase(make_pair(dist[v], v));
                    dist[v] = alt;
                    Q.insert(make_pair(dist[v], v));
                }
        }
    }

    return make_pair(dist, prev);
};

template<class T>
pair<vector<int>, vector<int>> DijkstraUndirectedGraph(Graph<T>& g, int s, int infinity = -1) {   // does dijsktra undirected on a graph, returns the same as above
   map<pair<int,int>, int> edges;
   int count = 0;
   for (int i = 0; i < g.vertices.size(); ++i) {
       for (auto w : g.neighbors[i]) {
           if ((edges.find(make_pair(i, w)) == edges.end()) && (edges.find(make_pair(w, i)) == edges.end())) {
               edges[make_pair(i, w)] = 1;
           }
           ++count;
       }
   }
   if (infinity == -1) {
     return DijkstraUndirected<int>(g.vertices.size(), edges, s, count+1);
   } else {
     return DijkstraUndirected<int>(g.vertices.size(), edges, s, infinity);
   }
};

        ll mm = 998244353;


template<class T>
T fastpower(T a, long long n) {  // n must be >= 1
  if (n % 2 == 0) {  
      T halfpower = fastpower<T>(a, n/2);
      return (halfpower*halfpower % mm);
  } else {
      if (n == 1) {  return a; } else {  
          T halfpower = fastpower<T>(a, n/2);
          return (((halfpower*halfpower) % mm)*a % mm);
      }
  }
};

