int eh[2*N];

void solve(){
  	cin >> n;
  	RE(i,2*n){
  		order.pb(i-1);
  	}
  	shuffle(all(order),rng);
  	bool lst = query(0);
  	RE(i,n){
  		bool nw = query(i);
  		if(nw == lst){
  			lst = nw;
  			continue;
  		}
  		ans[order[i+n-1]] = nw;
  		ans[order[i-1]] = lst;
  		for(int k = i;k < i+n-1;k++){
  			crucial.pb(order[k]);
  			eh[k] = 1;
  		}
  		for(int k = 0;k < 2*n;k++){
