		else if (r == n)
		{
			for (int j = i + 1; j < undefined.size(); j++)
			{
				color[undefined[j]] = 'B';
			}

			break;
		}
	}

	printf("! ");

	for (int i = 1; i <= 2 * n; i++)
	{
		printf("%c", color[i]);
	}

	printf("\n");
	fflush(stdout);

	return 0;
}

