    cout << pos << endl << flush;
}

char result()
{
    string color; CIN(color);
    return color[0];
}

ll get_sw(ll n, char leftcolor)
{
    ll left = 1LL;
    ll right = n;
    ll now = (left + right) / 2LL;
    ll change = n;

    for ( ; left <= right; now = (left + right) / 2LL) {
        query_successive(n, now);
        char color = result();
        if (leftcolor == color) {
            left = now + 1;
        }
        else {
            change = min(change, now);
            right = now - 1;
        }
    }

    return change - 1LL;
}

