char queryWithEvenRange(int pos, int rangePos)
{
    cout << "? " << (pos+1) << ' ';
    if (rangePos <= pos && pos < rangePos+N) {
        for (int i = 0; i < rangePos-1; ++i) {
            cout << (i+1) << ' ';
