const int MAXN = 105;

int n;
char s[MAXN];

char ask(vector<int> pos) {
    string message = "?";
    for(int x: pos)
        message += " " + to_string(x + 1);
    printf("%s\n", message.c_str());
    fflush(stdout);

    char tmp[10];
    scanf("%s", tmp);
    string res(tmp);
    if (res == "Red")
        return 'R';
    if (res == "Blue")
        return 'B';

    exit(0);
}

int main() {
    scanf("%d", &n);

    for(int i = 0; i < 2*n; ++i)
        s[i] = '?';
    s[2*n] = 0;

    // find balanced segment
    int balanceL = -1, balanceR = -1;

    char last = '?';
    for(int i = 0; i <= n; ++i) {
        vector<int> p;
        for(int j = 0; j < n; ++j)
            p.push_back(i + j);
        char res = ask(p);
        if (last != '?' && res != last) {
            balanceL = i;
            balanceR = i+n-2;
            break;
        } else
            last = res;
    }

//    printf("%d %d\n", balanceL, balanceR);

    // find color outside balanced segment
    for(int i = 0; i < 2*n; ++i) {
        if (i < balanceL || i > balanceR) {
            vector<int> p;
            for(int j = balanceL; j <= balanceR; ++j)
                p.push_back(j);
            p.push_back(i);
            s[i] = ask(p);
        }
    }

//    printf("%s\n", s);

    // find color inside balanced segment
    vector<int> balanceSet;
    int cntR = 0, cntB = 0;
    for(int i = 0; i < 2*n; ++i) {
        if (s[i] == 'R' && cntR < n/2) {
            balanceSet.push_back(i);
            ++cntR;
        }
        if (s[i] == 'B' && cntB < n/2) {
            balanceSet.push_back(i);
            ++cntB;
        }
    }

    for(int i = balanceL; i <= balanceR; ++i) {
        vector<int> p = balanceSet;
        p.push_back(i);
        s[i] = ask(p);
    }

    printf("! %s\n", s);
    fflush(stdout);

    return 0;
}

