    for (int i = 0; i < n; ++i)
        ans.app(s + i);
    return ans;                
}   

signed main() {
    cin >> n;
    int l = 1, r = n+1;
    while (l < r - 1) {
        int m = (l + r) >> 1;
        if (quer(sub(l)) == quer(sub(m)))
            l = m;
        else
            r = m;
    }                           

    vector <int> a;
    for (int i = 0; i < n - 1; ++i)
        a.app(r + i);

    vector <bool> used(2 * n + 1);
    for (int e : a)
        used[e] = 1;

    vector <char> ans(2 * n + 1);

    vector <int> fr, fb;
    for (int i = 1; i <= 2 * n; ++i) {
        if (!used[i]) {
            vector <int> t = a;
            t.app(i);
            if (quer(t) == "Red") {
                ans[i] = 'R';
                fr.app(i);  
            }   
            else {
                ans[i] = 'B';
                fb.app(i);
            }   
        }
    }   

    int m = n/2;
    a.clear();
    for (int i = 0; i < m; ++i)
        a.app(fr[i]);
    for (int i = 0; i < m; ++i)
        a.app(fb[i]);
    for (int i = 1; i <= 2 * n; ++i) {
        if (used[i]) {
            vector <int> t = a;
            t.app(i);
            if (quer(t) == "Red") {
                ans[i] = 'R';
            }   
            else {
                ans[i] = 'B';
            }   
        }   
    }   

    cout << "! ";
    for (int i = 1; i <= 2 * n; ++i)
        cout << ans[i];
    cout << endl;
}

