int f(vector<int> q) {
	cout << "?";
	for (auto qq : q)
		cout << " " << qq + 1;
	cout << endl << flush;
	string s;
	cin >> s;
	if (s == "Red")
		return 1;
	else if (s == "Blue")
		return -1;
	else
		return 0;
}

int main(int argc, char *argv[]) {
	int n;
	cin >> n;
	int b = 0, e = n;
	vector<int> q;
	for (int i = 0; i < n; i++)
		q.push_back(i);
	int c0 = f(q);
	while (b < e) {
		int m = (b + e) / 2;
		q.clear();
		for (int i = m; i < n + m; i++)
			q.push_back(i);
		int cm = f(q);
		if (cm == 1) {
			b = cm;
		}
		else {
			e = cm - 1;
		}
	}
	vector<int> res(2 * n, 0);
	res[b] = c0;
	res[b + n] = -c0;
	q.clear();
	for (int i = b + 1; i < b + n; i++) 
		q.push_back(i);
	for (int i = 0; i < 2 * n; i++) {
		if (res[i] == 0 && (i < b || i > b + n)) {
			q.push_back(i);
			res[i] = f(q);
			q.pop_back();
		}	
	}
	for (int i = b + 1; i < b + n; i++) {
		q.clear();
		for (int j = b; j <= b + n; j++) {
			if (i == j) continue;
			q.push_back(j);
		}
		res[i] = -f(q);
	}
	cout << "! ";
	for (int i = 0; i < 2 * n; i++) {
		if (res[i] == 1)
			cout << "R";
		else
			cout << "B";
	}
	cout << endl << flush;

}

