    return 'R';
}

char ask(vector<int> q){
    cout << '?';
    for(int i = 0;i < n;i++) cout << ' ' << q[i];
    cout << endl;
    string r;
    cin >> r;
    return r[0];
}

void solve(){
    int i,j;
    string str;
    cin >> n;
    vector<int> a(n),b(n);
    for(i = 0;i < n;i++){
        a[i] = 1+i;
        b[i] = n+1+i;
    }
    char s = ask(a),c;
    int l = 0,r = n,m;
    while(r-l > 1){
        m = (l+r)/2;
        for(int i = m;i < r;i++){
            swap(a[i],b[i]);
        }
        c = ask(a);
        if(c != s){
            l = m;
            s = c;
        }
        else{
            r = m;
        }
    }
    vector<char> ans(2*n+1);
    ans[a[l]] = s;
    ans[b[l]] = ci(s);
    for(int i = 0;i < n;i++){
        if(i == l) continue;
        swap(a[i],b[l]);
        if(ask(a) == s) ans[b[l]] = ci(s);
        else ans[b[l]] = s;
        swap(a[i],b[l]);
        swap(b[i],a[l]);
        if(ask(a) == s) ans[a[l]] = s;
        else ans[a[l]] = ci(s);
        swap(b[i],a[l]);
    }
    cout << "! ";
    for(i = 0;i < 2*n;i++) cout << ans[i+1];
    cout << endl;
}

int main(){
    solve();
}

