template <class T, class F>
T LowerBound(T i0, T i1, F f) {
    while (i0 < i1) {
        T i = (i0 + i1) / 2;
        if (f(i)) i1 = i; else i0 = i + 1;
    }
    return i0;
}

int main() {
    int n;
    cin >> n;

    vector<int> a(n), r(n * 2);

    auto f = [&]() -> int {
        cout << '?';
        for (int i = 0; i < n; i++) {
            cout << ' ' << a[i] + 1;
        }
        cout << endl;

        static string s;
        cin >> s;
        return s == "Blue";
    };

    for (int i = 0; i < n; i++) {
        a[i] = i + n;
    }
    int b = f();

    int j = LowerBound<int>(1, n, [&](int j) {
        for (int i = 0; i < n; i++) {
            a[i] = i + j;
        }
        return f() == b;
    }) - 1;

    r[j] = b ^ 1;
    r[j + n] = b;

    for (int i = 1; i < n; i++) {
        a[i] = i + j;
    }
    for (int i = 1; i < n; i++) {
        a[0] = (i + j + n) % (n * 2);
        r[a[0]] = f();
    }

    for (int i = 1; i < n; i++) {
        a[i] = (i + j + n) % (n * 2);
    }
    for (int i = 1; i < n; i++) {
        a[0] = i + j;
        r[a[0]] = f();
    }

    cout << "! ";
    for (int i = 0; i < n * 2; i++) {
        cout << "RB"[r[i]];
    }
    cout << endl;

    return 0;
}

