string solve(const int &N) {
    string s(2 * N + 1, ' ');
    int l = 1, r = N + 1;
    cout << "?";
    FOR(i, 1, N + 1) cout << " " << i;
    cout << endl;
    char first = input();
    while(l + 1 < r) {
        int mid = l + r >> 1;
        cout << "?";
        FOR(i, mid, mid + N) cout << " " << i;
        cout << endl;
        (input() == first ? l : r) = mid;
    }
    s[l] = first;
    s[l + N] = 'R' + 'B' - first;
    vector<int> x, y;
    FOR(i, 1, l) {
        x.push_back(i);
        y.push_back(i + N);
    }
    FOR(i, r, N + 1) {
        y.push_back(i);
        x.push_back(i + N);
    }
    int sumx = ('R' + 'B') * x.size() / 2;
    int sumy = sumx;
    for(int i : x) {
        if(i == x.back()) {
            s[i] = sumx;
            break;
        }
        cout << "? " << i;
        for(int j : y)
            cout << " " << j;
        cout << endl;
        s[i] = input();
        sumx -= s[i];
    }
    for(int i : y) {
        if(i == y.back()) {
            s[i] = sumy;
            break;
        }
        cout << "? " << i;
        for(int j : x)
            cout << " " << j;
        cout << endl;
        s[i] = input();
        sumy -= s[i];
    }
    return "!" + s;
}

