namespace XorShift {
    unsigned int x = 123456789;
    unsigned int y = 362436069;
    unsigned int z = 521288629;
    unsigned int w = 88675123;
    unsigned int t = 1;

    int rand() {
        t = x ^ (x << 11);
        x = y;
        y = z;
        z = w;
        w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
        return w & 0x7fffffff;
    }
}

inline int randint(int lower, int upper_inclusive) {
    int r32 = XorShift::rand();
    return lower + r32 % (upper_inclusive - lower + 1);
}

template <typename T>
void fisher_yates_inplace(vector<T>& a) {
    int n = a.size();
    for (int i=n-1; i>=0; --i) {
        int j = randint(0, i);
        swap(a[j], a[i]);
    }
}

