void solve(int N){
    vi a, b;
    int apicallcount=0, first, second, pix;

    set<int> unk;
    rep(i,N*2) unk.insert(i);
    map<int,int> deja;

    while (true) {
        a.resize(N*2); rep(i,N*2) a[i]=i;
        fisher_yates_inplace(a);
        b.assign(a.begin()+N, a.end());
        a.resize(N);
        first = ask(a); ++apicallcount;
        if (first == -1) return;
        swap(a[0], b[0]);
        second = ask(a); ++apicallcount;
        if (second == -1) return;
        if (first != second) {
            deja[a[0]] = second;
            deja[b[0]] = first;
            unk.erase(a[0]);
            unk.erase(b[0]);
            pix = 0;
            break;
        }
    }

    rep(i,N){
        if (i==pix) continue;
        swap(a[pix], b[i]);
        deja[a[pix]] = ask(a); apicallcount++;
        unk.erase(a[pix]);
    }

    int H=(N-1)/2, ac=0, bc=0, i=0;
    for (auto& p: deja){
        if (ac==H && bc==H) break;
        switch (p.second){
            case 'R':
                if (ac<H) {
                    a[i++] = p.first;
                    ++ac;
                }
                break;
            case 'B':
                if (bc<H) {
                    a[i++] = p.first;
                    ++bc;
                }
                break;
        }
    }
    assert(i==N-1);

    for (int n: unk){
        a[N-1] = n;
        deja[n] = ask(a); apicallcount++;
    }

    vi pat(N*2, '?');
    rep(i,2*N){
        pat[i] = deja[i];
    }
    ans(pat);
}

int main() {
    int N; cin >> N;
    solve(N);
    return 0;
}

