signed main()
{
  cin >> N;

  if(N == 1) {
    vv[queryCounter].push_back(1);
    color[1] = query();
    vv[queryCounter].push_back(2);
    color[2] = query();
    writeAns();
    return 0;
  }

  while(redIndex == -1 || blueIndex == -1) {
    memset(used, 0, sizeof(used));
    vv[queryCounter].push_back(1);
    used[1] = true;
    while(vv[queryCounter].size() != N) {
      int v = (xor128() % (2*N)) + 1;
      if(used[v]) continue;
      used[v] = true;
      vv[queryCounter].push_back(v);
    }
    int q = query();
    if(q == 1) {
      redIndex = queryCounter-1;
    } else {
      blueIndex = queryCounter-1;
    }
  }

  vector<int> RB; // ダブっている部分
  vector<int> rB; // ダブっていない部分(青)
  vector<int> rA; // ダブっていない部分(赤)
  int used2[2*MAX_N];
  memset(used2, 0, sizeof(used2));
  REP(n,N) {
    used2[vv[redIndex][n]] = 1;
  }
  REP(n,N) {
    if(used2[vv[blueIndex][n]] > 0) {
      RB.push_back(vv[blueIndex][n]);
      used2[vv[blueIndex][n]]++;
    } else {
      rB.push_back(vv[blueIndex][n]);
    }
  }
  REP(n,N) {
    if(used2[vv[redIndex][n]] != 2) {
      rA.push_back(vv[redIndex][n]);
    }
  }

  cerr << "rb" << endl;
  for(int d : RB) {
    cerr << d << " ";
  }
  cerr << endl;
  cerr << "b" << endl;
  for(int rd : rB) {
    cerr << rd << " ";
  }
  cerr << endl;
  cerr << "a" << endl;
  for(int rd : rA) {
    cerr << rd << " ";
  }
  cerr << endl;

  //基準となる配列を作成
  REP(n,N) {
    if(n < RB.size()) {
      vv[queryCounter].push_back(RB[n]);
    } else {
      vv[queryCounter].push_back(rB[n - RB.size()]);
    }  
  }

  // 一つずつAで置き換えて行く
  int baseIndex = -1;
  int vvQueryIndex = -1;
  REP(n,rA.size()) {
    vv[queryCounter][RB.size()+n] = rA[n];
    int color = query();
    if(color == -1) {
      vv[queryCounter] = vv[queryCounter-1];
      continue;
    } else { // 青から赤に変わった
      baseIndex = n + RB.size();
      vvQueryIndex = queryCounter-2;
      break;
    }
  }

  color[vv[queryCounter-1][baseIndex]] = 1;
  color[vv[queryCounter-2][baseIndex]] = -1;

  // cerr << "確定" << endl;
  // cerr << baseIndex << endl;
  // for(int v : vv[queryCounter-1]) {
  //   cerr << v << " ";
  // }
  // cerr << endl;

  bool baseVecUsed[2*MAX_N];
  memset(baseVecUsed, 0, sizeof(baseVecUsed));
  for(int v : vv[vvQueryIndex]) {
    baseVecUsed[v] = true;
  }

  // vvに含まれていない色を確定させて行く
  FOR(n,1,2*N+1) {
    if(color[n] == 0 && !baseVecUsed[n]) {
      vv[queryCounter] = vv[vvQueryIndex];
      vv[queryCounter][baseIndex] = n;
      color[n] = query();
    }
  }

  cerr << "OK" << endl;
  FOR(n,1,2*N+1) {
    cerr << color[n] << " ";
  }
  cerr << endl;

  int ccc = 0;
  int ci = 0;
  FOR(n,1,2*N+1) {
    if(color[n] == 1) {
      ccc = color[n];
      ci = n;
      break;
    }
  }

  REP(n,N) {
    vv[queryCounter] = vv[vvQueryIndex];
    int old = vv[queryCounter][n];
    vv[queryCounter][n] = ci;
    if(ccc == query()) {
      color[old] = -1;
    } else {
      color[old] = 1;
    }
  }

  writeAns();

  return 0;
}

