    vi common, a(n), b(n);
    rep(i,0,n) {
        a[i] = i;
        b[i] = n+i;
    }
    if(!query(a)) swap(a,b);
    while(sz(common)<n-1) {
        int k = sz(a);
        // debug(sz(common));
        // debug(k);
        assert(sz(b)==k);
        assert(k>1);
