        rep(i,j,k) aq[i-j]=a[i];
        vi combined = common;
        for(int x:bq) combined.push_back(x);
        for(int x:aq) combined.push_back(x);
        // for(int y:combined) debug(y);
        if(query(combined)) {
            for(int x:bq) common.push_back(x);
            vi bb(k-j);
            rep(i,j,k) bb[i-j] = b[i];
            a = aq;
            b = bb;
        }
        else {
            for(int x:aq) common.push_back(x);
