    if (k == 1) return false;

    string s1, s2;

    cout << "? ";
    for (int i = k; i <= k + n - 1; i++) cout << i << ' ';
    cout << endl;

    cin >> s1;

    cout << "? ";
    for (int i = k - 1; i <= k + n - 2; i++) cout << i << ' ';
    cout << endl;

    cin >> s2;

    return s1 != s2;    
}

bool is_red1(llong k) {
    string s;
    cout << "? " << k << ' ';
    for (auto e:sel) cout << e << ' ';
    cout << endl;

    cin >> s;

    return s == "Red";
}

bool is_red2(llong k) {
    llong cnt;
    string s;

