    for (auto itr = red.begin(); cnt < (n - 1) / 2; itr++) {
        cout << *itr << ' ';
        cnt++;
    }

    cnt = 0;
    for (auto itr = blue.begin(); cnt < (n - 1) / 2; itr++) {
        cout << *itr << ' ';
        cnt++;
    }
    cout << endl;

    cin >> s;

    return s == "Red";
}

