    cin >> n;

    llong valid = 2;
    llong invalid = 2 * n;

    while(invalid - valid > 1) {
        if (bs_query((valid + invalid) / 2)) {
            valid = (valid + invalid) / 2;
        }
        else {
            invalid = (valid + invalid) / 2;
        }
    }

    for (int i = valid; i < valid + n - 1; i++) {
        sel.insert(i);
    }

    for (int i = 1; i <= 2 * n; i++) {
