            else blue.insert(i);
        }
    }

    for (int i = 1; i <= 2 * n; i++) {
        if (sel.find(i) != sel.end()) {
            if (is_red2(i)) red.insert(i);
            else blue.insert(i);
        }
    }

    cout << "! ";
