			    if (a[j] == -1) {
					a[j] = 1;
					++sum1;
				}
			}
			break;
		}
		if (sum1 == (n + 1) / 2) {
		    for (int j = 0; j < 2 * n; ++j) {
			    if (a[j] == -1) {
					a[j] = 0;
					++sum0;
				}
			}
			break;
		}
	}
	vector<int> d;
	for (int i = 0; i < 2 * n; ++i) {
	   if (d.size() == (n - 1) / 2) break;
	   if (a[p[i]] == 0) d.pb(p[i]);
	}
	for (int i = 0; i < 2 * n; ++i) {
	   if (d.size() == (n - 1)) break;
	   if (a[p[i]] == 1) d.pb(p[i]);
	}

	for (int i = 0; i < 2 * n; ++i) {
	    if (a[p[i]] != 2) {
		    continue;
		}
		string ans = query(d, p[i]);
		if (ans == "Red") {
		   a[p[i]] = 1;
		   ++sum1;
		} else {
		   a[p[i]] = 0;
		   ++sum0;
		}
		if (sum0 == n) {
		    for (int j = 0; j < 2 * n; ++j) {
			    if (a[j] == -1 ||  a[j] == 2) a[j] = 1;
			}
			break;
		}
		if (sum1 == n) {
		    for (int j = 0; j < 2 * n; ++j) {
			    if (a[j] == -1 ||  a[j] == 2) a[j] = 0;
			}
			break;
		}
	}

	string ans = "! ";
	for (int i = 0; i < 2 * n; ++i) {
	   if (a[i] == 1) ans += 'R';
	   if (a[i] == 0) ans += 'B';
	}
	cout << ans << endl;	
    return 0;
}

