int main() {
    ios::sync_with_stdio(false);

    cin >> N;
    vector<bool> which(2 * N + 1, false);

    for (int i = 1; i <= N; i++)
        which[i] = true;

    bool initial = query(which);
    int low = 2, high = N + 1;

    while (low < high) {
        int mid = (low + high) / 2;

        which.assign(2 * N + 1, false);

        for (int i = mid; i < mid + N; i++)
            which[i] = true;

        bool result = query(which);

        if (result == initial)
            low = mid + 1;
        else
            high = mid;
    }

    int start = low, end = low + N - 1;
    which.assign(2 * N + 1, false);

    for (int i = start; i < end; i++)
        which[i] = true;

    vector<bool> answer(2 * N + 1, false);

    for (int i = 1; i <= 2 * N; i++)
        if (start <= i && i < end) {
            which[i] = false;
            which[start - 1] = which[end] = true;
            answer[i] = !query(which);
            which[start - 1] = which[end] = false;
            which[i] = true;
        } else {
            which[i] = true;
            answer[i] = query(which);
            which[i] = false;
        }

    cout << "! ";

    for (int i = 1; i <= 2 * N; i++)
        cout << (answer[i] ? 'R' : 'B');

    cout << endl;
}

