int main() {
  int N;
  cin >> N;

  if(N == 1) {
    auto x = ask({0});
    if(x) {
      cout << "! RB\n";
    } else {
      cout << "! BR\n";
    }
    return 0;
  }


  int pre = -1;
  vector< char > ans(2 * N);

  auto solve = [&](char L, int left, int right, char R) {
    // [left, right]
    if(left > right) right += 2 * N;

    for(int i = left; i <= right; i++) {
      vector< int > que;
      for(int j = left - 1; j <= right + 1; j++) {
        if(i == j) continue;
        que.emplace_back((j + 2 * N) % (2 * N));
      }
      auto ret = ask(que);

      if(ret) {
        ans[i % (2 * N)] = 'B';
      } else {
        ans[i % (2 * N)] = 'R';
      }
    }
  };


  vector< int > latte;
  for(int i = 0; i < N; i++) latte.emplace_back(i);
  pre = ask(latte);
  int ok = 0, ng = N;
  while(ng - ok > 1) {
    int mid = (ok + ng) / 2;
    vector< int > malta;
    for(int i = 0; i < N; i++) {
      malta.emplace_back((i + mid) % (2 * N));
    }
    if(pre == ask(malta)) ok = mid;
    else ng = mid;
  }


  int i = ok + 1;
  int ret = pre ^1;

  if(ret) {
    ans[i - 1] = 'B';
    ans[i + N - 1] = 'R';
    solve('B', i, i + N - 2, 'R');
    solve('R', i + N, i - 2, 'B');
  } else {
    ans[i - 1] = 'R';
    ans[i + N - 1] = 'B';
    solve('R', i, i + N - 2, 'B');
    solve('B', i + N, i - 2, 'R');
  }


  cout << "! ";
  for(auto &t : ans) cout << t;
  cout << endl;
}

