const int N=505;
char s[5];int a[N],col[N],st[N],cnt[2],top,n,las,now,ql,qr;
inline int ask(R int l,R int r){
	putchar('?'),putchar(' ');
	fp(i,l,r)printf("%d ",i);
	putchar('\n'),fflush(stdout);
	scanf("%s",s+1);return s[1]=='R';
