int main(){
	scanf("%d",&n);
	fp(i,1,n<<1)col[i]=-1;
	las=ask(1,n);
	fp(i,2,n+1){
		now=ask(i,i+n-1);
		if(now^las){
			col[i-1]=las,col[i+n-1]=now;
			fp(k,i,i+n-2)st[++top]=k;
			fp(k,1,i-2)col[k]=ask(k);
