#define D_BALL_MAX		200										// 最大ボール数

// 内部構造体 - 座標情報
typedef struct Ball {
	int miNo;													// 配列番号
	int miBNo;													// ボール
	char mcColor;												// 色
} Ball;

// 内部変数
static FILE *szpFpI;											// 入力
static Ball sz1Ball[D_BALL_MAX];								// ボール
static int siBCnt;												// ボール数
static int siBHCnt;												// ボール数(半分)

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
