		siRes = -1;
	}
#else
	printf("%s", pcpLine);
	fflush(stdout);
#endif

	return 0;
}

// 比較関数 - 配列番号昇順
int
fCmpFnc(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	Ball *lzpVal1 = (Ball *)pzpVal1;
	Ball *lzpVal2 = (Ball *)pzpVal2;

	// 配列番号昇順
	if (lzpVal1->miNo > lzpVal2->miNo) {
		return 1;
	}
	else if (lzpVal1->miNo < lzpVal2->miNo) {
		return -1;
	}

	return 0;
}

// 値 - 入れ替え
int
fSwap(
	int *pipVal1				// <IO> 値１
	, int *pipVal2				// <IO> 値２
)
{
	int liWork = *pipVal1;
	*pipVal1 = *pipVal2;
	*pipVal2 = liWork;

	return 0;
}

// 応答
char
fRes(
	int piSNo					// <I> 開始位置
)
{
	int i;

	// 質問
	char lc1Buf[1024], lc1Buf2[1024];
	sprintf(lc1Buf, "?");
	for (i = 0; i < siBHCnt; i++) {
		sprintf(lc1Buf2, " %d", sz1Ball[piSNo + i].miBNo);
		strcat(lc1Buf, lc1Buf2);
	}
	strcat(lc1Buf, "\n");
	fOutLine(lc1Buf);

	// 回答
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);

	return lc1Buf[0];
}

// ボール色 - セット
int
fSetColor(
	int piSNo					// <I> 開始位置
	, int piFNo					// <I> 確定色
)
{
	int i;

	// 反対側の確定色
	int liFNo2 = siBCnt - 1 - piFNo;

	// ボール色 - セット
	for (i = 0; i < siBHCnt; i++) {
		int liBNo = piSNo + i;
		if (liBNo == piFNo) {
			continue;
		}

		// ボール - 入れ替え
		fSwap(&sz1Ball[liBNo].miBNo, &sz1Ball[liFNo2].miBNo);

		// 色 - 取得
		char lcColor = fRes(piSNo);
		if (sz1Ball[piFNo].mcColor == lcColor) {
			sz1Ball[liBNo].mcColor = sz1Ball[liFNo2].mcColor;
		}
		else {
			sz1Ball[liBNo].mcColor = sz1Ball[piFNo].mcColor;
		}

		// ボール - 戻す
		fSwap(&sz1Ball[liBNo].miBNo, &sz1Ball[liFNo2].miBNo);
	}

	return 0;
}

// 実行メイン
int
fMain(
)
{
	int i;
	char lc1Buf[1024];

	// ボール数 - 取得
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
	sscanf(lc1Buf, "%d", &siBHCnt);
	siBCnt = siBHCnt * 2;

	// ボール - 初期値
	for (i = 0; i < siBCnt; i++) {
		sz1Ball[i].miNo = i;
		sz1Ball[i].miBNo = i + 1;
	}

	// 初期色
	char lcColor = fRes(0);

	// 確定色 - 検索
	int liFNo;
	for (i = 0; i < siBHCnt; i++) {

		// ボール - 入れ替え
		fSwap(&sz1Ball[i].miBNo, &sz1Ball[siBCnt - 1 - i].miBNo);

		// 色 - 取得
		char lcColor2 = fRes(0);
		if (lcColor == lcColor2) {
			continue;
		}

		// 確定色
		liFNo = i;
		sz1Ball[liFNo].mcColor = lcColor;
		sz1Ball[siBCnt - 1 - liFNo].mcColor = lcColor2;

		break;
	}

	// ボール色 - セット
	fSetColor(0, liFNo);
	fSetColor(siBHCnt, siBCnt - 1 - liFNo);

	// 解答
	qsort(sz1Ball, siBCnt, sizeof(Ball), fCmpFnc);
	lc1Buf[0] = '!';
	lc1Buf[1] = ' ';
	for (i = 0; i < siBCnt; i++) {
		lc1Buf[i + 2] = sz1Ball[i].mcColor;
	}
	lc1Buf[siBCnt + 2] = '\n';
	lc1Buf[siBCnt + 3] = '\0';
	fOutLine(lc1Buf);

	return 0;
}

