fun main(args: Array<String>) {
    val sc = FastScanner(System.`in`)

    val n = sc.nextInt()
    var a = 1
    var b = n + 1
    val col = ask(sc, a, n)
    val res = Array(2 * n) { false }
    while (b - a > 1) {
        val c = (b + a) / 2
        if (col != ask(sc, c, n)) b = c
        else a = c
    }

    var red = 0
    var blue = 0
    val t = mutableListOf<Int>()
    for (x in 1..2 * n) {
        if (x in a + 1 until a + n) continue

        val ans = ask(sc, x, a, n) == "Red"
        res[x - 1] = ans
        if (ans && red < n / 2) {
            red += 1
            t.add(x)
        }
        if (!ans && blue < n / 2) {
            blue += 1
            t.add(x)
        }
    }

    for (x in a + 1 until a + n) {
        val ans = ask(sc, x, n, t) == "Red"
        res[x - 1] = ans
    }

    println("! ${res.joinToString("") { if (it) "R" else "B" }}")


}

