public void solve() {
	int num = ni();
	boolean red = ask(0, num);
	int left = bisect(red ? 0 : num, !red ? 0 : num, num) + 1;
	boolean ans[] = new boolean[num * 2];
	for(int i = left + num;  i < left + num * 2; i ++) {
		ans[i % (num * 2)] = ask(left, num, i);
	}
	for(int i = left;  i < left + num; i ++) {
		ans[i % (num * 2)] = ask(left + num, num, i);
	}
	prt("! ");
	for(int i = 0; i < num * 2; i ++) {
		prt(ans[(i + 1) % (num * 2)] ? 'R' : 'B');
	}
	prtln();
}

boolean ask(int left, int num) {
	left %= num * 2;
	long a[] = new long[num];
	for(int i = 0; i < num; i ++) {
		a[i] = (i + left) % (num * 2) + 1;
	}
	prt("? ");
	prtln(a);
	flush();
	return ns().equals("Red");
}
boolean ask(int left, int num, int add) {
	left %= num * 2;
	long a[] = new long[num];
	for(int i = 0; i < num - 1; i ++) {
		a[i] = (i + left) % (num * 2) + 1;
	}
	a[num - 1] = (add - 1) % (num * 2) + 1;
	prt("? ");
	prtln(a);
	flush();
	return ns().equals("Red");
}

int bisect(int red, int blue, int num) {
	int ng = blue;
	int ok = red;
	while ((ng - ok + num * 2) % (num * 2) > 1) {
		int mid = ok < ng ? (ok + ng) / 2 : (ok + ng + num * 2) / 2;
		if(ask(mid, num)) {
			ok = mid;
			ng = (ok + num) % (num * 2);
		}else {
			ng = mid;
		}
	}
	return ok;
}

