    static class EMajorityOfBalls {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();

            int idx = 0;
            boolean prev = false;
            for (int i = 0; i <= n; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n; j++) {
                    a[j] = i + j + 1;
                }
                out.print("? ");
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                if (i > 0 && (prev ^ now)) {
                    idx = i;
                    break;
                }
                prev = now;
            }

            boolean[] ans = new boolean[2 * n];
            ans[idx - 1] = prev;
            ans[idx - 1 + n] = !prev;

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = idx + 1 + j;
                }
                a[n - 1] = (idx + n + i) % (2 * n) + 1;
                out.print("? ");
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[(idx + n + i) % (2 * n)] = now;
            }

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = (idx + n + j) % (2 * n) + 1;
                }
                a[n - 1] = (idx + i) % (2 * n) + 1;
                out.print("? ");
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[idx + i] = now;
            }

            out.print("! ");
            for (int i = 0; i < 2 * n; i++) {
                out.print(ans[i] ? "R" : "B");
            }
            out.printLine();
            out.flush();
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
