					}
				}
				for(int k = 1;k < n;k++){
					int[] a = new int[n];
					for(int j = 0;j < n;j++){
						a[j] = (i+n+j) % (2*n);
						if(j == k){
							a[j] = i;
						}
					}
					if(q(a)){
						color[(i+n+k) % (2*n)] = -1;
					}else{
						color[(i+n+k) % (2*n)] = 1;
					}
				}
			}
		}
		out.print("! ");
		for(int i = 0;i < 2*n;i++){
			out.print(color[i] == 1 ? 'R' : 'B');
		}
		out.println();
		out.flush();
	}

