        System.out.print("? "+(v+1)+" ");
        for(int i = s; i < s+n-1; i++){
            System.out.print((i+1)+" ");
        }
        System.out.println();
        String ret = ns();
        if (ret.equals("Red")) return 0;
        else return 1;
    }

