	private boolean getQuery(FastIO io) {
		String T = io.next();
		return T.charAt(0) == 'R';
	}
	private boolean sequenceQuery(FastIO io, int left, int N) {
		io.print("?");
		for (int i = left;i < left + N;++ i) {
			io.print(" " + (i + 1));
		}
		io.println();
		return getQuery(io);
	}

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * DISCO presents ディスカバリーチャンネルコードコンテスト2020 予選 E問題
		 * 考察メモ
		 * まず、差が1の区間が分かっていると嬉しい
		 * 後はその区間に対し、大きい方の1個を適当な1個と入れ替えることで1個ずつ特定できるため
		 * よって、後は差が1になる区間を高速に出したいが
		 * これは実は二分探索ができるよねって
		 * ・区間[0, N)と区間[l, l+N)の答えが同じ→少なくとも奥側に一つは境界値がある
		 * ・区間[0, N)と区間[l, l+N)の答えが違う→少なくとも手前側に一つは境界値がある
		 * これを利用すると一つ境界を探すことができて
		 * 次に、この境界を用いて答えを求めていくよ
		 * ここで、[l, l+N)がR, (l, l+N]がBであるものとするよ
		 * これはl番目の値がR, l+N番目の値がBであることが確定しているね
		 * また、(l, l+N)のBとRの個数は等しいね
		 * この時、(l, l+N)と他の一つを選ぶよ
		 * すると、他の一つのB, Rだけで答えが確定するので、残りが全部求まる
		 * それだけ情報があれば、そこからBとRを同数選んできて、それで(l, l+N)を確定させればいい
		 * 計算回数は2N+logNだね
		 */
		io.setAutoFlush(true);
		int N = io.nextInt();
		boolean isRight = sequenceQuery(io, 0, N);

		int min = 0, max = N, mid, halfDiff;
		while((halfDiff = max - min >> 1) != 0) {
			mid = min + halfDiff;
			if (isRight ^ sequenceQuery(io, mid, N)) max = mid;
			else min = mid;
		}
		boolean[] isRed = new boolean[2 * N];
		isRed[min] = isRight;
		isRed[min + N] = !isRight;
		for (int i = 0;i < 2 * N;++ i) {
			if (min <= i && i <= min + N) continue;
			io.print("? " + (i + 1));
			for (int j = min + 1;j < min + N;++ j) io.print(" " + (j + 1));
			io.println();
			isRed[i] = getQuery(io);
		}
		int[] querySet = new int[N - 1];
		int redCount = 0, blueCount = 0, count = 0;
		for (int i = 0;i < 2 * N;++ i) {
			if (min < i && i < min + N) continue;
			if (isRed[i]) {
				if (++ redCount > N / 2) continue;
				querySet[count++] = i + 1;
			} else {
				if (++ blueCount > N / 2) continue;
				querySet[count++] = i + 1;
			}
		}
		for (int i = min + 1;i < min + N;++ i) {
			io.print("? " + (i + 1) + " ");
			io.println(querySet);
			isRed[i] = getQuery(io);
		}
		io.print("! ");
		for (boolean i : isRed) io.print(i ? "R" : "B");
		io.println();

	}

