public class Main {

	void run() {
		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		String pre = "-1";
		String[] col = new String[2 * N];// 1(blue):-1(red)
		for (int i = 0; i < col.length; ++i)
			col[i] = "-1";
		ask(0, 0 + N, N);
		pre = sc.next();
		int l = 0, r = N;
		while (r - l > 1) {
			int middle = (r + l) / 2;
			ask(middle, middle + N, N);
			if (sc.next().equals(pre))
				l = middle;
			else
				r = middle;
		}
		if (pre.equals("Blue")) {
			col[(r + N - 1) % (2 * N)] = "Red";
			col[(l + 2 * N) % (2 * N)] = "Blue";
		} else {
			col[(r + N - 1) % (2 * N)] = "Blue";
			col[(l + 2 * N) % (2 * N)] = "Red";
		}
		for (int j = 0; j < 2 * N; ++j) {
			if (!col[j].equals("-1") || (r <= j && j < r + N - 1))
				continue;
			System.out.print("? ");
			for (int k = r; k < r + N - 1; ++k) {
				System.out.print((k % (2 * N) + 1) + " ");
			}
			System.out.println(j + 1);
			String U = sc.next();
			if (U.equals("Blue")) {
				col[j] = "Blue";
			} else {
				col[j] = "Red";
			}
		}
		ArrayList<Integer> lis = new ArrayList<>();
		int blue = 0, red = 0;
		for (int j = 0; j < 2 * N; ++j) {
			if (blue < N / 2 && col[j].equals("Blue")) {
				++blue;
				lis.add(j);
			} else if (red < N / 2 && col[j].equals("Red")) {
				++red;
				lis.add(j);
			}
		}
		for (int j = 0; j < 2 * N; ++j) {
			if (col[j].equals("-1")) {
				System.out.print("? ");
				for (int k = 0; k < lis.size(); ++k) {
					System.out.print((lis.get(k) + 1) + " ");
				}
				System.out.println(j + 1);
				String U = sc.next();
				if (U.equals("Blue")) {
					col[j] = "Blue";
				} else {
					col[j] = "Red";
				}
			}
		}
		System.out.print("! ");
		for (int i = 0; i < 2 * N; ++i) {
			System.out.print(col[i].equals("Red") ? "R" : "B");
		}
	}

	void ask(int l, int r, int N) {
		System.out.print("? ");
		for (int j = l; j < r; ++j) {
			System.out.print((j % (2 * N) + 1) + (j == r - 1 ? "\n" : " "));
		}
		return;
	}

	public static void main(String[] args) throws FileNotFoundException {
		new Main().run();
	}

