            this.in = in;
            this.out = out;

            init();

            int[] ps = new int[2 * n];
            for (int i = 0; i < 2 * n; i++) {
                ps[i] = i;
            }

            shuffle(ps, random);
            int res = query(ps);
            int[] qs = new int[n];
            int low = 0, high = n + 1;
            while (high - low > 1) {
                int mid = (low + high) / 2;
                for (int i = 0; i < n; i++) qs[i] = ps[i + mid];
                int res2 = query(qs);
                if (res == res2) {
                    low = mid;
                } else {
                    high = mid;
                }
            }

            for (int i = 0; i < n - 1; i++) qs[i + 1] = ps[i + high];

            for (int i = 0; i < ps.length; i++) {
                if (i < high || i >= high + n - 1) {
                    qs[0] = ps[i];
                    ans[qs[0]] = query(qs);
                }
            }

            int sum = 0;
            int len = 1;
            for (int t = 1; t >= 0; t--) {
                for (int i = 0; i < ps.length && len < n; i++) {
                    if (i < high || i >= high + n - 1) {
                        if (ans[ps[i]] == t && sum + ans[ps[i]] <= n / 2) {
                            qs[len++] = ps[i];
                            sum += ans[ps[i]];
                        }
                    }
                }
            }

            for (int i = 0; i < ps.length; i++) {
                if (!(i < high || i >= high + n - 1)) {
                    qs[0] = ps[i];
                    ans[qs[0]] = query(qs);
                }
            }

            answer();
        }

