        int right = n-1;
        int base = query(0);
        while(right-left>2){
            int mid = (left+right)/2;
            if (query(mid)==base){
                left = mid;
            }
            else{
                right = mid;
            }
        }
        int[] ans = new int[2*n];
        Arrays.fill(ans, -1);
        for(int i = 0; i <= left; i++){
            ans[i] = query2(i, right);
