/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        EMajorityOfBalls solver = new EMajorityOfBalls();
        solver.solve(1, in, out);
        out.close();
    }

    static class EMajorityOfBalls {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();

            int idx = 0;
            boolean prev = false;
            for (int i = 0; i <= n; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n; j++) {
                    a[j] = i + j + 1;
                }
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                if (i > 0 && (prev ^ now)) {
                    idx = i;
                    break;
                }
                prev = now;
            }

            boolean[] ans = new boolean[2 * n];
            ans[idx - 1] = prev;
            ans[idx - 1 + n] = !prev;

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = idx + 1 + j;
                }
                a[n - 1] = (idx + n + i) % (2 * n) + 1;
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[(idx + n + i) % (2 * n)] = !prev ^ (!prev != now);
            }

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = (idx + n + j) % (2 * n) + 1;
                }
                a[n - 1] = idx + i + 1;
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[(idx + n + i) % (2 * n)] = prev ^ (prev != now);
            }

            out.print("! ");
            for (int i = 0; i < n; i++) {
                out.print(ans[i] ? "R" : "B");
            }
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void print(int[] array) {
            for (int i = 0; i < array.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(array[i]);
            }
        }

        public void printLine(int[] array) {
            print(array);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.Random;
import java.io.IOException;
import java.io.Reader;
import java.io.InputStreamReader;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        EMajorityOfBalls solver = new EMajorityOfBalls();
        solver.solve(1, in, out);
        out.close();
    }

    static class EMajorityOfBalls {
        int qt = 0;
        boolean debug = false;
        Random random = new Random(9);
        MyInput in;
        PrintWriter out;
        int n;
        int[] test;
        int[] ans;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            n = in.nextInt();
            ans = new int[2 * n];
            Arrays.fill(ans, -1);

            this.in = in;
            this.out = out;

            init();

            int[] ps = new int[2 * n];
            for (int i = 0; i < 2 * n; i++) {
                ps[i] = i;
            }

            shuffle(ps, random);
            int res = query(ps);
            int[] qs = new int[n];
            int low = 0, high = n + 1;
            while (high - low > 1) {
                int mid = (low + high) / 2;
                for (int i = 0; i < n; i++) qs[i] = ps[i + mid];
                int res2 = query(qs);
                if (res == res2) {
                    low = mid;
                } else {
                    high = mid;
                }
            }

            for (int i = 0; i < n - 1; i++) qs[i + 1] = ps[i + high];

            for (int i = 0; i < ps.length; i++) {
                if (i < high || i >= high + n - 1) {
                    qs[0] = ps[i];
                    ans[qs[0]] = query(qs);
                }
            }

            for (int i = 0, j = 1; i < n - 1 && j < n; i++) {
                if (i < high || i >= high + n - 1) {
                    qs[j++] = ps[i];
                }
            }

            for (int i = 0; i < ps.length; i++) {
                if (!(i < high || i >= high + n - 1)) {
                    qs[0] = ps[i];
                    ans[qs[0]] = query(qs);
                }
            }

            answer();
        }

        int query(int[] q) {
            qt++;
            if (qt > 210) {
                throw new RuntimeException();
            }

            if (debug) {
                int c = 0;
                for (int i = 0; i < n; i++) {
                    c += test[q[i]];
                }
                return c > n / 2 ? 1 : 0;
            }
            out.print("?");
            for (int i = 0; i < n; i++) {
                out.print(" " + (q[i] + 1));
            }
            out.println();
            out.flush();
            return in.nextChars()[0] == 'B' ? 1 : 0;
        }

        void answer() {
            if (debug) {
                dump("query", qt);
                for (int i = 0; i < test.length; i++) {
                    if (ans[i] != test[i]) {
                        dump(test);
                        dump(ans);
                        dump("NG");
                        return;
                    }
                }
                dump("OK");
                return;
            }

            out.print("! ");
            for (int i = 0; i < 2 * n; i++) {
                out.print("RB".charAt(ans[i]));
            }
            out.println();
            out.flush();
        }

        void shuffle(int[] ps, Random random) {
            for (int i = 1; i < ps.length; i++) {
                int j = random.nextInt(i + 1);
                swap(ps, i, j);
            }
        }

        void init() {
            test = new int[n * 2];
