		int[] res = new int[2 * n];
		Arrays.fill(res, -1);
		int idx = -1;
		for (int i = 0; i < n; i++) {
			if (col[i] != col[i + 1]) {
				idx = i;
				res[i] = col[i];
				res[(i + n) % (2 * n)] = col[i] ^ 1;
				break;
			}
		}
		for (int i = 0; i < n - 1; i++) {
			out.print("?");
			for (int j = 1; j <= n - 1; j++) {
				out.print(" " + ((idx + j) % (2 * n) + 1));
			}
			out.print(" " + ((idx + n + i + 1) % (2 * n) + 1));
			out.println();
			out.flush();
			res[(idx + n + i + 1) % (2 * n)] = col(ir.next());
		}
		for (int i = 0; i < n - 1; i++) {
			out.print("?");
			for (int j = 1; j <= n - 1; j++) {
				out.print(" " + ((idx + n + j) % (2 * n) + 1));
			}
			out.print(" " + ((idx + i + 1) % (2 * n) + 1));
			out.println();
			out.flush();
			res[(idx + i + 1) % (2 * n)] = col(ir.next());
		}
		out.print("! ");
		for (int i = 0; i < 2 * n; i++) {
			out.print(res[i] == 0 ? "R" : "B");
		}
		out.println();
	}

	static int col(String s) {
		if (s.equals("Red"))
			return 0;
		else
