import java.io.UncheckedIOException;
import java.io.Closeable;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskE solver = new TaskE();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class TaskE {
        FastInput in;
        FastOutput out;
        int[] shuffle;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            this.in = in;
            this.out = out;

            shuffle = new int[n * 2 + 1];
            for (int i = 1; i <= 2 * n; i++) {
                shuffle[i] = i;
            }
            Randomized.randomizedArray(shuffle, 1, 2 * n + 1);
            IntList question = new IntList(n);
            boolean state;
            for (int i = 1; i <= n; i++) {
                question.add(i);
            }
            state = redMore(question);
            int red = 1;
            int blue = 2;
            int[] color = new int[2 * n + 1];
            int sep;

            int l = 1;
            int r = n;

            while (l < r) {
                sep = (l + r) >>> 1;
                question.clear();
                for (int j = 1; j <= 2 * n; j++) {
                    if (j <= n - sep || j > n && j <= n + sep) {
                        question.add(j);
                    }
                }
                if (state != redMore(question)) {
                    r = sep;
                } else {
                    l = sep + 1;
                }
            }

            sep = r;
            color[n - sep + 1] = state ? red : blue;
            color[n + sep] = 3 - color[n - sep + 1];
            question.clear();
            for (int j = 1; j <= 2 * n; j++) {
                if (j <= n - sep || j > n && j <= n + sep) {
                    question.add(j);
                }
            }

            for (int i = 1; i <= n - sep; i++) {
                replace(question, i, n - sep + 1);
                if (state != redMore(question)) {
                    color[i] = state ? red : blue;
                } else {
                    color[i] = state ? blue : red;
                }
                replace(question, n - sep + 1, i);
            }
            for (int i = n + sep + 1; i <= 2 * n; i++) {
                replace(question, n + sep, i);
                if (state == redMore(question)) {
                    color[i] = state ? red : blue;
                } else {
                    color[i] = state ? blue : red;
                }
                replace(question, i, n + sep);
            }

            for (int i = n - sep + 2; i <= n; i++) {
                replace(question, n + sep, i);
                if (state == redMore(question)) {
                    color[i] = state ? red : blue;
                } else {
                    color[i] = state ? blue : red;
                }
                replace(question, i, n + sep);
            }

            for (int i = n + 1; i < n + sep; i++) {
                replace(question, i, n - sep + 1);
                if (state != redMore(question)) {
                    color[i] = state ? red : blue;
                } else {
                    color[i] = state ? blue : red;
                }
                replace(question, n - sep + 1, i);
            }

            out.append("! ");
            int[] trueAns = new int[2 * n + 1];
            for (int i = 1; i <= 2 * n; i++) {
                trueAns[shuffle[i]] = color[i];
            }
            for (int i = 1; i <= 2 * n; i++) {
                out.append(trueAns[i] == red ? "R" : "B");
            }
            out.flush();
        }

        public void replace(IntList x, int a, int b) {
            x.set(x.indexOf(a), b);
        }

        public boolean redMore(IntList a) {
            out.append("? ");
            for (int i = 0; i < a.size(); i++) {
                out.append(shuffle[a.get(i)]).append(' ');
            }
            out.println();
            out.flush();
            return in.readString().equals("Red");
        }

    }

    static class Randomized {
        static Random random = new Random();

        public static void randomizedArray(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }

    static class FastInput {
        private final InputStream is;
        private StringBuilder defaultStringBuf = new StringBuilder(1 << 13);
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public String readString(StringBuilder builder) {
            skipBlank();

            while (next > 32) {
                builder.append((char) next);
                next = read();
            }

            return builder.toString();
        }

        public String readString() {
            defaultStringBuf.setLength(0);
            return readString(defaultStringBuf);
        }

    }

