/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        EMajorityOfBalls solver = new EMajorityOfBalls();
        solver.solve(1, in, out);
        out.close();
    }

    static class EMajorityOfBalls {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();

            int idx = 0;
            boolean prev = false;
            for (int i = 0; i <= n; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n; j++) {
                    a[j] = i + j + 1;
                }
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                if (i > 0 && (prev ^ now)) {
                    idx = i;
                    break;
                }
                prev = now;
            }

            boolean[] ans = new boolean[2 * n];
            ans[idx - 1] = prev;
            ans[idx - 1 + n] = !prev;

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = idx + 1 + j;
                }
                a[n - 1] = (idx + n + i) % (2 * n) + 1;
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[(idx + n + i) % (2 * n)] = !prev ^ (!prev != now);
            }

            for (int i = 0; i < n - 1; i++) {
                int[] a = new int[n];
                for (int j = 0; j < n - 1; j++) {
                    a[j] = (idx + n + j) % (2 * n) + 1;
                }
                a[n - 1] = idx + i + 1;
                out.printLine(a);
                out.flush();

                String s = in.readString();
                boolean now = s.equals("Red");
                ans[(idx + n + i) % (2 * n)] = prev ^ (prev != now);
            }

            out.print("! ");
            for (int i = 0; i < n; i++) {
                out.print(ans[i] ? "R" : "B");
            }
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void print(int[] array) {
            for (int i = 0; i < array.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(array[i]);
            }
        }

        public void printLine(int[] array) {
            print(array);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.*;

interface JudgeInterface {
  String putQuery(String query);
}

class ExternalJudge implements JudgeInterface {
  final Scanner scanner;

  ExternalJudge() {
    scanner = new Scanner(System.in);
  }

  public String putQuery(String query) {
    if (query != null) {
      System.out.println(query);
    }
    return scanner.nextLine();
  }
}

class Judge implements JudgeInterface {
  final char[] secrets;
  final int n;

  boolean first;
  int count;

  Judge(char[] secrets) {
    this.secrets = secrets;
    this.n = secrets.length / 2;
    this.first = true;
    this.count = 0;
  }

  public String putQuery(String query) {
    if (first) {
      first = false;
      return String.format("%d", secrets.length / 2);
    }
    Scanner s = new Scanner(query);
    char c = s.next().charAt(0);
    switch (c) {
      case '?':
        count++;
        if (count > 210) {
          throw new RuntimeException();
        }
        int countRed = 0;
        int countBlue = 0;
        for (int i = 0; i < n; i++) {
          int a = s.nextInt();
          if (secrets[a - 1] == 'R') {
            countRed++;
          } else {
            countBlue++;
          }
        }

        if (countRed > countBlue) {
          return "Red";
        } else {
          return "Blue";
        }
      case '!':
        char[] cs = s.next().toCharArray();
        boolean equals = true;
        for (int i = 0; i < 2 * n; i++) {
          if (cs[i] != secrets[i]) {
            equals = false;
          }
        }

        if (equals) {
          System.err.println("SUCCESS");
        } else {
          System.err.println("FAIL");
        }
        return null;
      default:
        throw new RuntimeException();
    }
  }
}

class JudgeWrapper {
  JudgeInterface judgeInterface;

  JudgeWrapper(JudgeInterface judgeInterface) {
    this.judgeInterface = judgeInterface;
  }

  String putQuery(String query) {
    System.err.println("Query: " + query);
    String judgeResponse = judgeInterface.putQuery(query);
    System.err.println("Judge: " + judgeResponse);
    return judgeResponse;
  }
}

class Solver {
  JudgeWrapper judgeWrapper;
  int n;

  Solver(JudgeWrapper judgeWrapper) {
    this.judgeWrapper = judgeWrapper;
  }

  private String createQuery(List<Integer> indexes) {
    StringBuffer sb = new StringBuffer();
    sb.append("?");
    for (int index : indexes) {
      sb.append(" ");
      sb.append(index);
    }
    return sb.toString();
  }

  private String createQuery(int headIndex) {
    List<Integer> indexes = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      indexes.add(headIndex + i);
    }
    return createQuery(indexes);
  }


  public void solve() {
    String judgeResponse = judgeWrapper.putQuery(null);

    n = Integer.parseInt(judgeResponse);
    String query = judgeWrapper.putQuery(createQuery(1));
    String headColor = query;
    int l = 1;
    int r = n + 1;
    while (r - l > 1) {
      int mid = (r + l) / 2;
      query = createQuery(mid);
      judgeResponse = judgeWrapper.putQuery(query);      
      if (judgeResponse.equals(headColor)) {
        l = mid;
      } else {
        r = mid;
      }
    }

    char[] answers = new char[2 * n + 1];
    if (headColor.equals("Red")) {
      answers[l] = 'R';
      answers[l + n] = 'B';
    } else {
      answers[l] = 'B';
      answers[l + n] = 'R';
    }

    for (int i = 1; i <= 2 * n; i++) {
      if (i == l || i == l + n) {
        continue;
      }

      List<Integer> indexes = new ArrayList<>();
      if (i < l || l + n < i) {
        for (int j = l + 1; j < l + n; j++) {
          indexes.add(j);
        }
        indexes.add(i);
      } else {
        for (int j = 1; j < l; j++) {
          indexes.add(j);
        }
        for (int j = l + n + 1; j <= 2 * n; j++) {
          indexes.add(j);
        }
        indexes.add(i);
      }

      query = createQuery(indexes);
      judgeResponse = judgeWrapper.putQuery(query);      
      if (judgeResponse.equals("Red")) {
        answers[i] = 'R';
      } else {
        answers[i] = 'B';
      }
    }

    String finalQuery = "! " + new String(answers, 1, 2 * n);
    System.err.println(finalQuery);
    System.out.println(finalQuery);
  }
}

class Main {
  public static void main(String[] args) {
//    JudgeInterface judgeInterface = new Judge("RRRBBBRRBBRRBB".toCharArray());
    JudgeInterface judgeInterface = new ExternalJudge();
    JudgeWrapper judgeWrapper = new JudgeWrapper(judgeInterface);
    Solver solver = new Solver(judgeWrapper);
    solver.solve();
  }
}

