    static class EMajorityOfBalls {
        InputReader in;
        OutputWriter out;
        int n;

        boolean ask_consec(int start) {
            out.print("?");
            for (int i = 0; i < n; i++) out.print(" " + (start + i));
            out.println();
            out.flush();
            return in.next().equals("Red");
        }

        public void solve(int testNumber, InputReader _in, OutputWriter _out) {
            in = _in;
            out = _out;
            n = in.nextInt();
