            boolean r1 = ask_consec(1);
            // lo is r1, hi is !r1;
            while (lo + 1 < hi) {
                int mid = (lo + hi) / 2;
                if (ask_consec(mid) == r1) lo = mid;
                else hi = mid;
            }
            char[] ret = new char[2 * n];
            for (int i = 1; i <= 2 * n; i++) {
                out.print("?");
