using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private int N;

    public void Solve()
    {
        N = int.Parse(Console.ReadLine());
        /* f(i) = [i,i+N)でどっちが多いか
         * f(i) != f(i+1) なら [i+1,i+N)の赤青の数は同じ
         * かつS[i] = f(i),S[i+N] = f(i+1)
         * f(i) != f(i+N)なので境目はどこかにある
         *　
         * にぶたん ①
         * if f(L) = f(M) L:=M
         * else R:=M
         * log N回 <= 9回
         *  
         * [i+1,i+N)とWを聞けばS[W]が確定する N-1回 ②
         * 
         * N+1個が赤青同数で確定しているのでN-1個の赤青同数のを構成して[i+1,i+N)を聞く ②で確定したの使えば楽かも
         * N-1回 ③
         */


        Color[] ans = new Color[N * 2];

        #region ①

        int l = 0, r = N;
        Color fL = F(l);
        Color fR = F(r);
        while (r - l > 1)
        {
            int m = (l + r) / 2;
            if (F(m) == fL)
            {
                l = m;
            }
            else
            {
                r = m;
            }
        }

        ans[l] = fL;
        ans[l + N] = fR;

        // [i+1 i+N) = [tL, tR)
        int tL = l + 1;
        int tR = l + N;

        int[] tmp = new int[N - 1];
        for (int i = 0; i < N - 1; i++)
        {
            tmp[i] = tL + i + 1;
        }

        string t = string.Join(" ", tmp);

        #endregion

        #region ②

        List<int> tmp2 = new List<int>();

        for (int i = 0; i < N * 2; i++)
        {
            if (ans[i] == Color.Unknown && (i < tL || tR <= i))
            {
                tmp2.Add(i + 1);
                ans[i] = Ask2(t, i + 1);
            }
        }

        string t2 = string.Join(" ", tmp2);

        #endregion

        #region ③

        for (int i = 0; i < N * 2; i++)
        {
            if (ans[i] == Color.Unknown)
            {
                ans[i] = Ask2(t2, i + 1);
            }
        }

        #endregion

        Console.WriteLine($"! {string.Join("", ans)}");
    }

    private Color F(int i)
    {
        var a = new int[N];
        for (int j = 0; j < N; j++)
        {
            a[j] = i + j + 1;
        }

        return Ask(string.Join(" ", a));
    }

    private Color Ask2(string t, int w)
    {
        Console.WriteLine($"? {t} {w}");
        return Anser();
    }


    private Color Ask(string a)
    {
        Console.WriteLine($"? {a}");
        return Anser();
    }

    private Color Anser()
    {
        string t = Console.ReadLine();
        if (t == "Red") return Color.R;
        if (t == "Blue") return Color.B;
        throw new Exception();
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

