internal partial class Solver {

    string Query(IEnumerable<int> A) {
        cout.WriteLine("? " + string.Join(" ", A.Select(x => x + 1)));
        cout.Flush();
        return ns();
    }

    public void Run() {
        var N = ni();
        char[] ans = new char[2 * N];
        if (N == 1) {
            for (int i = 0; i < 2 * N; i++) {
                ans[i] = Query(new[] { i })[0];
            }
        } else {
            var leftColor = Query(E.Range(0, N));
            int current = 0;
            for (int i = (1 << 10); i >= 1; i >>= 1) {
                var next = current + i;
                if (N <= next) continue;
                var color = Query(E.Range(next, N));
                if (color == leftColor) {
                    current = next;
                }
            }
            // current, current+1
            var common = E.Range(current + 1, N - 1).ToArray();
            for (int i = 0; i < 2 * N; i++) {
                if (common.Contains(i)) continue;
                var color = Query(common.Concat(new[] { i }));
                ans[i] = color[0];
            }

            var otherR = new List<int>();
            var otherB = new List<int>();

            for (int i = 0; i < 2 * N; i++) {
                if (ans[i] == 'R' && otherR.Count + 1 <= N / 2) {
                    otherR.Add(i);
                } else if (ans[i] == 'B' && otherB.Count + 1 <= N / 2) {
                    otherB.Add(i);
                }
            }
            common = otherR.Concat(otherB).ToArray();
            if (common.Length == N - 1) {
                for (int i = 0; i < 2 * N; i++) {
                    if (ans[i] != 0) continue;
                    if (common.Contains(i)) continue;
                    var color = Query(common.Concat(new[] { i }));
                    ans[i] = color[0];
                }
            }
        }
        var r = ans.Count(c => c == 'R');
        var b = ans.Count(c => c == 'B');

        if (r == N) {
            for (int i = 0; i < ans.Length; i++) {
                if (ans[i] == 0) ans[i] = 'B';
            }
        }
        if (b == N) {
            for (int i = 0; i < ans.Length; i++) {
                if (ans[i] == 0) ans[i] = 'R';
            }
        }

        cout.WriteLine("! " + new string(ans));
        cout.Flush();
    }
}

