		N = ri();
		int NN = N * 2;
		int[] q = new int[N];

		q = Enumerable.Range(0,N).ToArray();
		char[] ss = new char[NN];
		ss[0] = Query(q);
		if(ss[0] == 'R'){
			ss[N] = 'B';
		} else {
			ss[N] = 'R';
		}

		int l = 0;
		int r = N;
		while(r - l > 1){
			int c = (r + l) / 2;
			q = Enumerable.Range(c, N).ToArray();
			var ch = Query(q);
			if(ch == ss[l]){
				l = c;
			} else {
				r = c;
			}
		}

		char[] ans = new char[NN];
		for(int i=0;i<NN;i++) ans[i] = '?';


		for(int i=0;i<N-1;i++) q[i] = r + i;
		for(int i=0;i<NN;i++){
			if(i >= r && i < r + N - 1) continue;
			q[N - 1] = i;
			ans[i] = Query(q);
		}

		int cr = 0;
		int cb = 0;
		for(int i=0;i<NN;i++){
			if(i >= r && i < r + N - 1) continue;
			if(ans[i] == 'R'){
				cr++;
				if(cr <= (N - 1) / 2){
					q[cr + cb - 1] = i;
				}
			}
			if(ans[i] == 'B'){
				cb++;
				if(cb <= (N - 1) / 2){
					q[cr + cb - 1] = i;
				}
			}
		}

		for(int i=r;i<r+N-1;i++){
			q[N - 1] = i;
			ans[i] = Query(q);
		}

		Ans(ans);
	}

