namespace Program {
	public class Solver {
		Random rnd = new Random(0);
		public void Solve() {
			var n = int.Parse(Console.ReadLine());
			var l = 0; var r = n;
			var L = q(Enumerate(n, x => x));
			while (r - l > 1) {
				var m = (l + r) / 2;
				var res = q(Enumerate(n, x => x + m));
				if (res == L) l = m;
				else r = m;
			}
			var R = new List<int>();
			var B = new List<int>();
			Debug.WriteLine($"{l} {r}");
			for (int i = 0; i < 2 * n; i++) {
				var b = Enumerate(n - 1, x => l + 1 + x).ToList();
				if (!b.Contains(i)) {
					b.Add(i);
					var res = q(b.ToArray());
					if (res[0] == 'R') R.Add(i);
					else if (res[0] == 'B') B.Add(i);
				}
			}
			Debug.WriteLine(R.AsJoinedString());
			Debug.WriteLine(B.AsJoinedString());
			for (int i = 0; i < 2 * n; i++) {
				var b = Enumerate(n - 1, x => l + 1 + x).ToList();
				if (b.Contains(i)) {
					b = R.Take(n / 2).Concat(B.Take(n / 2)).ToList();
					b.Add(i);
					var res = q(b.ToArray());
					if (res[0] == 'R') R.Add(i);
					else if (res[0] == 'B') B.Add(i);
				}
			}
			var ans = new char[2 * n];
			foreach (var x in R) ans[x] = 'R';
			foreach (var x in B) ans[x] = 'B';
			Console.WriteLine($"! {ans.AsString()}");
			Console.Out.Flush();
		}
		string q(int[] a) {
			Console.WriteLine("? {0}", a.Select(x => x + 1).AsJoinedString());
			Console.Out.Flush();
			return Console.ReadLine();
		}
		const long INF = 1L << 60;
		static int[] dx = { -1, 0, 1, 0 };
		static int[] dy = { 0, 1, 0, -1 };
		static T[] Enumerate<T>(int n, Func<int, T> f) {
			var a = new T[n]; for (int i = 0; i < a.Length; ++i) a[i] = f(i); return a;
		}
		static T[][] Enumerate<T>(int n, int m, Func<int, int, T> f) {
			return Enumerate(n, x => Enumerate(m, y => f(x, y)));
		}
		static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
	}
