func Solve() {
  var N int
  NextInt(&N)
  Q := make([]int, N)
  for i := range Q { Q[i] = i + 1 }
  S := make([]string, N)
  A := make([]string, 2 * N + 1)
  for i := range A[1:] { A[i + 1] = "R" }
  n := N
  Query := func() string {
    for i, q := range Q { S[i] = strconv.Itoa(q) }
    Write("? " + strings.Join(S, " "))
    Output()
    return NextLine()
  }
  RB := Query()
  for ans := RB; ans == RB; ans = Query() {
    n++
    Q = append(Q[1:], n)
  }
  if RB == "Red" {
    A[n] = "B"
  } else {
    A[n - N] = "B"
  }
  for i := n; i != n - N - 1; i = (i + 1) % (2 * N) {
    Q[N - 1] = i + 1
    if Query() == "Blue" { A[i + 1] = "B" }
  }
  for i := n - N + 1; i < n; i++ { A[i] = "?" }
  r, b := 0, 0
  for i, a := range A {
    if a == "R" && r < N / 2 { Q[r] = i; r++ }
    if a == "B" && b < N / 2 { Q[N / 2 + b] = i; b++ }
  }
  for i := n - N + 1; i < n; i++ {
    Q[N - 1] = i
    A[i] = "R"
    if Query() == "Blue" { A[i] = "B" }
  }
  Write("! " + strings.Join(A, ""))
}

func main() {
  Solve()
  Output()
}

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt(A ...*int) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.Atoi(L[i])
  }
}
func NextIntVec(A *[]int) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]int, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.Atoi(l)
  }
}
func NextFloat(A ...*float64) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.ParseFloat(L[i], 64)
  }
}
func NextFloatVec(A *[]float64) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]float64, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}
func MaxInt(A ...int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}
func AbsInt(x int) int {
  if x < 0 { x = -x }
  return x
}

