		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	ans := make([]string, n<<1)
	question := make([]string, n+1)
	question[0] = "?"

	another := map[string]string{
		"Blue": "Red",
		"Red":  "Blue",
	}
	output := map[string]string{
		"Blue": "B",
		"Red":  "R",
	}

	n2 := n << 1
	l := 0
	r := n
	for i := 1; i <= n; i++ {
		question[i] = fmt.Sprint(i)
	}
	prev := ask(strings.Join(question, " "), scanner, writer)

	for l < r {
		m := (l + r) >> 1
		for i := 1; i <= n; i++ {
			question[i] = fmt.Sprint(i + m)
		}
		res := ask(strings.Join(question, " "), scanner, writer)
		if res == prev {
			l = m + 1
			continue
		}
		r = m
	}
	ans[(r+n-1)%n2] = output[another[prev]]
	ans[(r-1)%n2] = output[prev]
	for i := 1; i <= n; i++ {
		question[i] = fmt.Sprint(i + r)
	}
	for i := 1; i < n; i++ {
		question[n] = fmt.Sprint((r+n-1+i)%n2 + 1)
		ans[(r+n-1+i)%n2] = output[ask(strings.Join(question, " "), scanner, writer)]
	}
	for i := 0; i < n; i++ {
		question[i+1] = fmt.Sprint((r+n+i)%n2 + 1)
	}
	for i := 0; i < n-1; i++ {
		question[n] = fmt.Sprint((r+i)%n2 + 1)
		ans[(r+i)%n2] = output[ask(strings.Join(question, " "), scanner, writer)]
	}
	fmt.Fprintf(writer, "! %s\n", strings.Join(ans, ""))
	writer.Flush()
}

func ask(s string, scanner *bufio.Scanner, writer *bufio.Writer) string {
	fmt.Fprintln(writer, s)
	writer.Flush()
	return getNextString(scanner)
}

