func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	ans := make([]string, n<<1)
	question := make([]string, n+1)
	question[0] = "?"
	l := 0
	r := n
	for i := 1; i <= n; i++ {
		question[i] = fmt.Sprint(i)
	}
	fmt.Fprintln(writer, strings.Join(question, " "))
	writer.Flush()
	another := map[string]string{
		"Blue": "Red",
		"Red":  "Blue",
	}
	output := map[string]string{
		"Blue": "B",
		"Red":  "R",
	}
	prev := getNextString(scanner)

	for l < r {
		m := (l + r) >> 1
		for i := 1; i <= n; i++ {
			question[i] = fmt.Sprint(i + m)
		}
		fmt.Fprintln(writer, strings.Join(question, " "))
		writer.Flush()
		res := getNextString(scanner)
		if res == prev {
			l = m + 1
			continue
		}
		r = m
	}
	ans[r+n-1] = output[another[prev]]
	ans[r-1] = output[prev]
	for i := 1; i < n; i++ {
		question[n] = fmt.Sprint((r+n+i)%(n*2) + 1)
		fmt.Fprintln(writer, strings.Join(question, " "))
		writer.Flush()
		ans[(r+n+i)%(n*2)] = output[getNextString(scanner)]
	}
	for i := 0; i < n; i++ {
		question[i+1] = fmt.Sprint((r + n + i) % (n * 2))
	}
	for i := 0; i < n-1; i++ {
		question[n] = fmt.Sprint((r+i)%(n*2) + 1)
		fmt.Fprintln(writer, strings.Join(question, " "))
		writer.Flush()
		ans[(r+i)%(n*2)] = output[getNextString(scanner)]
	}
	fmt.Fprintf(writer, "! %s\n", strings.Join(ans, ""))
	writer.Flush()
}

