import (
  "bufio"
  "os"
  "strconv"
  "strings"
  "fmt"
)

func Solve() {
  var N int
  NextInt(&N)
  Q := make([]int, N)
  S := make([]string, N)
  A := make([]string, 2 * N + 1)
  for i := range A[1:] { A[i + 1] = "R" }
  Query := func() string {
    for i, q := range Q { S[i] = strconv.Itoa(q) }
    Write("? " + strings.Join(S, " "))
    Output()
    return NextLine()
  }
  for i := range Q { Q[i] = i + 1 }
  QA := make([]string, 2 * N + 1)
  QA[1] = Query()
  QA[N + 1] = "Red"
  if QA[1] == QA[N + 1] { QA[N + 1] = "Blue" }
  low, high := 1, N + 1
  for 1 < high - low {
    med := (high + low) / 2
    for i := range Q { Q[i] = i + med }
    QA[med] = Query()
    if QA[med] == QA[low] {
      low = med
    } else {
      high = med
    }
  }
  n := low + N
  if QA[high] == "Blue" {
    A[n] = "B"
  } else {
    A[n - N] = "B"
  }
  for i := range Q { Q[i] = i + high }
  for i := n % (2 * N); i != n - N - 1; i = (i + 1) % (2 * N) {
    Q[N - 1] = i + 1
    if Query() == "Blue" { A[i + 1] = "B" }
  }
  for i := n - N + 1; i < n; i++ { A[i] = "?" }
  r, b := 0, 0
  for i, a := range A {
    if a == "R" && r < N / 2 { Q[r] = i; r++ }
    if a == "B" && b < N / 2 { Q[N / 2 + b] = i; b++ }
  }
  for i := n - N + 1; i < n; i++ {
    Q[N - 1] = i
    A[i] = "R"
    if Query() == "Blue" { A[i] = "B" }
  }
  Write("! " + strings.Join(A, ""))
}

func main() {
  Solve()
  Output()
}

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt(A ...*int) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.Atoi(L[i])
  }
}
func NextIntVec(A *[]int) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]int, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.Atoi(l)
  }
}
func NextFloat(A ...*float64) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.ParseFloat(L[i], 64)
  }
}
func NextFloatVec(A *[]float64) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]float64, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
