func ask(a []int) bool {
	q := "?"
	for i := range a {
		q += fmt.Sprintf(" %d", a[i]+1)
	}
	pln(q)
	flush()

	resp := rs()
	switch resp {
	case "Red":
		return true
	case "Blue":
		return false
	default:
		panic("func ask: wrong response")
	}
}

func printAns(ans []string) {
	s := "! "
	for i := range ans {
		s += ans[i]
	}
	pln(s)
	flush()
}

func solve() {
	n := ri()

	iota := intsIota(n * 2)
	ans := make([]string, n*2)

	l, r := 0, n
	col := ask(iota[l : l+n])
	for r-l != 1 {
		m := l + (r-l)/2
		if ask(iota[m:m+n]) == col {
			l = m
		} else {
			r = m
		}
	}

	if ask(iota[l : l+n]) {
		ans[l], ans[l+n] = "R", "B"
	} else {
		ans[l], ans[l+n] = "B", "R"
	}

	for i := 0; i < l; i++ {
		arg := append(iota[r:l+n], i)
		if ask(arg) {
			ans[i] = "R"
		} else {
			ans[i] = "B"
		}
	}
	for i := r + n; i < n*2; i++ {
		arg := append(iota[r:l+n], i)
		if ask(arg) {
			ans[i] = "R"
		} else {
			ans[i] = "B"
		}
	}

	for i := r; i < l+n; i++ {
		arg := append(intsJoin(iota[0:l], iota[r+n:n*2]), i)
		if ask(arg) {
			ans[i] = "R"
		} else {
			ans[i] = "B"
		}
	}

	printAns(ans)
}

