func Solve() {
  var N int
  NextInt(&N)
  Q := make([]int, N)
  S := make([]string, N)
  A := make([]string, 2 * N + 1)
  for i := range A[1:] { A[i + 1] = "R" }
  Query := func() string {
    for i, q := range Q { S[i] = strconv.Itoa(q) }
    Write("? " + strings.Join(S, " "))
    Output()
    return NextLine()
  }
  for i := range Q { Q[i] = i + 1 }
  QA := make([]string, 2 * N + 1)
  Q[1] := Query()
  Q[N + 1] = "Red"
  if Q[1] == Q[N + 1] { Q[N + 1] = "Blue" }
  low, high := 1, N + 1
  for 1 < high - low {
    med := (high + low) / 2
    for i := range Q { Q[i] = i + med }
    Q[med] = Query()
    if Q[med] == Q[low] {
      low = med
    } else {
      high = med
    }
  }
  n := low + N
  if QA[high] == "Blue" {
    A[n] = "B"
  } else {
    A[n - N] = "B"
  }
  for i := range Q { Q[i] = i + high }
  for i := n % (2 * N); i != n - N - 1; i = (i + 1) % (2 * N) {
    Q[N - 1] = i + 1
    if Query() == "Blue" { A[i + 1] = "B" }
  }
  for i := n - N + 1; i < n; i++ { A[i] = "?" }
  r, b := 0, 0
  for i, a := range A {
    if a == "R" && r < N / 2 { Q[r] = i; r++ }
    if a == "B" && b < N / 2 { Q[N / 2 + b] = i; b++ }
  }
  for i := n - N + 1; i < n; i++ {
    Q[N - 1] = i
    A[i] = "R"
    if Query() == "Blue" { A[i] = "B" }
  }
  Write("! " + strings.Join(A, ""))
}

