var usi uint32 = 2463534242

func xorshift() uint32 {
	usi = usi ^ (usi << 13)
	usi = usi ^ (usi >> 17)
	usi = usi ^ (usi << 15)
	return usi
}

var sc = bufio.NewScanner(os.Stdin)

var numbers []int

func main() {
	sc.Split(bufio.ScanWords)
	log.SetFlags(log.Lshortfile)
	rand.Seed(time.Now().UnixNano())
	loop := rand.Intn(10)
	for i := 0; i < loop; i++ {
		xorshift()
	}

	N := nextInt()
	num := 2 * N
	color := make([]int, num+1)
	numbers = make([]int, num)
	for i := 0; i < num; i++ {
		numbers[i] = i + 1
	}
	for i := 0; i < 210; i++ {
		var ask string
		ask = "? "
		for i := 0; i < N; i++ {
			ask += strconv.Itoa(numbers[i])
			if i < N-1 {
				ask += " "
			}
		}
		fmt.Println(ask)
		ret := nextString()
		var c int
		if ret == "Red" {
			c = 1
		} else if ret == "Blue" {
			c = -1
		} else {
			panic("error")
		}
		for i := 0; i < N; i++ {
			color[numbers[i]] += c
		}
		shuffle()
	}
	log.Println(color)
	ans := "! "
	for i := 1; i < 2*N+1; i++ {
		if color[i] == 0 {
			color[i] = int(xorshift())%2 - 1
		}
		if color[i] > 0 {
			ans += "R"
		} else if color[i] < 0 {
			ans += "B"
		}
	}
	fmt.Println(ans)
}

func shuffle() {
	for i := len(numbers) - 1; i > 0; i-- {
		j := int(xorshift()) % (i + 1)
		numbers[i], numbers[j] = numbers[j], numbers[i]
	}

}

