var usi uint32 = 2463534242

func xorshift() uint32 {
	usi = usi ^ (usi << 13)
	usi = usi ^ (usi >> 17)
	usi = usi ^ (usi << 15)
	return usi
}

var sc = bufio.NewScanner(os.Stdin)

var numbers []int

func main() {
	sc.Split(bufio.ScanWords)
	log.SetFlags(log.Lshortfile)
	N := nextInt()
	num := 2 * N
	color := make([]int, num)
	numbers = make([]int, num)
	for i := 0; i < num; i++ {
		numbers[i] = i + 1
	}
	for i := 0; i < 20; i++ {
		asks := numbers[N:]
		var ask string
		ask = "? "
		for i := 0; i < N; i++ {
			ask += strconv.Itoa(asks[i])
			if i < N-1 {
				ask += " "
			}
		}
		fmt.Println(ask)
		ret := nextString()
		var c int
		if ret == "Red" {
			c = 1
		} else {
			c = -1
		}
		for i := 0; i < N; i++ {
			color[i] += c
		}
	}
	ans := "! "
	for i := 0; i < 2*N; i++ {
		if color[i] > 0 {
			ans += "R"
		} else {
			ans += "B"
		}
		if i < 2*N-1 {
			ans += " "
		}
	}
	fmt.Println(ans)
}

func shuffle() {
	for i := len(numbers) - 1; i > 0; i-- {
		j := int(xorshift()) % (i + 1)
		numbers[i], numbers[j] = numbers[j], numbers[i]
	}

}

func nextString() string {
	sc.Scan()
	return sc.Text()
}

func nextInt() int {
	sc.Scan()
	i, err := strconv.Atoi(sc.Text())
	if err != nil {
		panic(err)
	}
	return i
}

var dy = []int{0, 1, 0, -1}
var dx = []int{1, 0, -1, 0}
var MAX = math.MaxInt32

func pow(a, b int) int {
	return int(math.Pow(float64(a), float64(b)))
}

func lcm(a, b int) int {
	return a * b / gcd(a, b)
}
func gcd(a, b int) int {
	if a < b {
		a, b = b, a
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
func max(a ...int) int {
	r := a[0]
	for i := 0; i < len(a); i++ {
		if r < a[i] {
			r = a[i]
		}
	}
	return r
}
func min(a ...int) int {
	r := a[0]
	for i := 0; i < len(a); i++ {
		if r > a[i] {
			r = a[i]
		}
	}
	return r
}
func sum(a []int) (r int) {
	for i := range a {
		r += a[i]
	}
	return r
}
func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

type pair struct {
	a, b int
}

type pairs []pair

func (p pairs) Len() int {
	return len(p)
}
func (p pairs) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p pairs) Less(i, j int) bool {
	if p[i].a == p[j].a {
		return p[i].b < p[j].b
	}
	return p[i].a < p[j].a
}

