proc ask(v:seq[int]):int = # red: 0, blue: 1
  stdout.write("? ")
  var s = ""
  for i, t in v:
    stdout.write(t + 1)
    if i < v.len - 1:stdout.write(" ")
  echo("")
  let T = nextString()
  if T == "Red": return 0
  elif T == "Blue": return 1
  quit(-1)

proc main():void =
  let N = nextInt()
  var
    rs = newSeq[int]()
    bs = newSeq[int]()
  for i in 0..<N: rs.add(i)
  for i in 0..<N: bs.add(i + N)
  var idx = -1
  for i in 0..<N:
    var r = ask(rs)
    if i == 0 and r == 1:
      swap(rs, bs)
      r = 0
    if r == 1:
      idx = i - 1
      break
    swap(rs[i], bs[i])
  # rs: "blue" is majority
  # bs: "red" is majority
  # rs[i]: blue
  # bs[i]: red
  var ans = newSeqWith(N*2, -1)
  # foreach bs
  for i in 0..<N:
    swap(rs[idx], bs[i])
    if ask(rs) == 0:# red
      ans[rs[idx]] = 0
    else:
      ans[rs[idx]] = 1
    swap(rs[idx], bs[i])
  # foreach rs
  for i in 0..<N:
    swap(bs[idx], rs[i])
    if ask(bs) == 0:# red
      ans[bs[idx]] = 0
    else:
      ans[bs[idx]] = 1
  var s = "! "
  for i in 0..<ans.len:
    if ans[i] == 0: s &= "R"
    elif ans[i] == 1: s &= "B"
    else: quit(-1)
  echo s

main()

