def bisect(ng, ok, judge):
    while abs(ng-ok) > 1:
        m = (ng+ok)//2
        if judge(m):
            ok = m
        else:
            ng = m
    return ok

from random import shuffle

def solve(N):
    # detect change

    check = lambda i: query(range(i,i+N)) if i <= N else query(chain(range(i-N),range(i,2*N)))

    L = list(range(2*N))
    shuffle(L)
    x = L[-1]
    orig = check(x)
    for y in reversed(L[:-1]):
        if orig != check(y):
            break

    if y < x:
        x -= N*2


    while abs(x-y) > 1:
        mid = (x+y)//2
        r = check((mid)%(2*N))
        if r == orig:
            x = mid
        else:
            y = mid

    x %= 2*N

    res = [None]*(2*N)
    a,b = x, (x+N)%(2*N)
    res[a] = orig
    res[b] = not orig
    # [i+1, ... , i+N] is even
    n1 = list(range(a+1,b)) if a < b else list(chain(range(a+1,2*N),range(0,b)))
    # [0...i-1] + [i+N+2, ... 2*N] is even
    n2 = list(range(b+1,a)) if b < a else list(chain(range(b+1,2*N),range(0,a)))
    for i in n1:
        res[i] = query(n2+[i])
    for i in n2:
        res[i] = query(n1+[i])

    answer(res)


