def bisect(ng, ok, judge):
    while abs(ng-ok) > 1:
        m = (ng+ok)//2
        if judge(m):
            ok = m
        else:
            ng = m
    return ok

def solve(N):
    # detect change

    orig = query(range(N))
    for i in range(1,2*N):
        t = query(range(i,i+N)) if i <= N else query(chain(range(i-N),range(i,2*N)))
        if t != orig:
            break

    res = [None]*(2*N)
    a,b = i-1, (i+N-1)%(2*N)
    res[a] = orig
    res[b] = not orig
    # [i+1, ... , i+N] is even
    n1 = list(range(a+1,b)) if a < b else list(chain(range(a+1,2*N),range(0,b)))
    # [0...i-1] + [i+N+2, ... 2*N] is even
    n2 = list(range(b+1,a)) if b < a else list(chain(range(b+1,2*N),range(0,a)))
    for i in n1:
        res[i] = query(n2+[i])
    for i in n2:
        res[i] = query(n1+[i])

    answer(res)


