import sys


def pri(n, ar):
    print '?', ' '.join(map(lambda a: str((a % (n * 2) + 1)), ar))
    sys.stdout.flush()
    return raw_input()


def main():
    n = input()
    ans = [None] * (2 * n)
    now = pri(n, range(n))
    for start in range(1, 2 * n):
        nex = pri(n, range(start, start + n))
        if now != nex:
            if nex == 'Red':
                ans[start - 1] = 'B'
                ans[start + n - 1] = 'R'
            else:
                ans[start - 1] = 'R'
                ans[start + n - 1] = 'B'
            break
    aa = [start - 1, start + n - 1] * ((n - 1) / 2)
    for i in range(2 * n):
        if ans[i] is not None:
            continue
        if pri(n, aa + [i]) == 'Red':
            ans[i] = 'R'
        else:
            ans[i] = 'B'
    print '!' + ''.join(ans)


