def judge(x, question, T, N):
    sum = 0
    for n in question:
        sum += int(x[n])
    if T == "Red":
        if sum > N/2:
            return True
        else:
            return False
    elif T == 'Blue':
        if sum < N/2:
            return False
        else:
            return True

