class Interactive:
    def __init__(self):
        self.ques_cnt = 0
        self.create_data()

    def create_data(self):
        import random
        A = ['B']*N + ['R']*N
        random.shuffle(A)
        self.A = [None] + A

    def resp_ques(self, *args):
        self.ques_cnt += 1
        assert len(args) == N
        from collections import Counter
        A = self.A
        selected = [A[i] for i in args]
        counter = Counter(selected)
        resp = 'Red' if counter['R'] > counter['B'] else 'Blue'
        return resp

    def resp_ans(self, *args):
        if len(args) != 1 or not isinstance(args[0], str):
            raise ValueError('Answer must be a string')
        if list(args[0]) == self.A[1:]:
            print('AC!')
            print('num of questions:', self.ques_cnt)
        else:
            print('WA!')

