def ri():
    return int(input())

def rl():
    return list(input().split())

def rli():
    return list(map(int, input().split()))


def ask(la):
    out = "?"
    for a in la:
        out += " " + str(a+1)
    print(out, flush=True)
    c = input()
    return c

def answer(ans):
    out = "! "
    for a in ans:
        if a == 'Red':
            out += "R"
        else:
            out += "B"
    print(out, flush=True)
    return

def main():
    n = ri()
    ids = [i for i in range(2*n)]
    ans = [None for _ in range(2*n)]
    if n == 1:
        c = ask([0])
        if c == 'Red':
            ans[0] = 'Red'
            ans[1] = 'Blue'
        else:
            ans[0] = 'Blue'
            ans[1] = 'Red'
        answer(ans)
        return

    bef = None
    same = None
    for i in range(n):
        c = ask(ids[i:i+n])
        if bef != None and c != bef:
            # print("!!!!!!", bef, c)
            ans[i-1] = bef
            ans[i+n-1] = c
            same = ids[i:i+n-1]
            break
        bef = c
    # print(ans)
    for i in range(same[0]):
        if ans[i] is not None:
            continue
        ids = [i] + same
        c = ask(ids)
        ans[i] = c
    for i in range(same[-1]+1, 2*n):
        if ans[i] is not None:
            continue
        ids = same + [i]
        c = ask(ids)
        ans[i] = c
    # print(ans)
    half = (n-1) // 2
    cr = 0
    cb = 0
    same2 = []
    for i in range(2*n):
        if ans[i] is None:
            continue
        if ans[i] == "Red":
            if cr < half:
                same2.append(i)
                cr += 1
        else:
            if cb < half:
                same2.append(i)
                cb += 1
    for i in range(same[0], same[-1]+1):
        ids = [i] + same2 
        c = ask(ids)
        ans[i] = c
    answer(ans)
    return


if __name__ == '__main__':
    main()

