fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut colors = vec![None; 2 * n];
    let mut prefix = vec![];
    let mut suffix = vec![];
    for i in 0..n {
        prefix.push(i);
    }

    let mut print_count = 0;

    print_set(&prefix, &suffix);
    print_count += 1;

    let (first, second) = if sc.read::<String>().as_str() == RED {
        (RED, BLUE)
    } else {
        (BLUE, RED)
    };

    loop {
        assert!(prefix.pop().is_some());
        if suffix.is_empty() {
            suffix.push(2 * n - 1);
        } else {
            let s = suffix[0] - 1;
            suffix.insert(0, s);
        }

        print_set(&prefix, &suffix);
        print_count += 1;

        if sc.read::<String>().as_str() == second {
            break;
        }
    }

    colors[suffix[0]] = Some(second);
    let mut remain = vec![];
    for i in 0..(2 * n) {
        if prefix.contains(&i) || suffix.contains(&i) {
            continue;
        }
        remain.push(i);
    }

    while let Some(i) = remain.pop() {
        suffix[0] = i;
        print_set(&prefix, &suffix);
        print_count += 1;

        if sc.read::<String>().as_str() == RED {
            colors[i] = Some(RED);
        } else {
            colors[i] = Some(BLUE);
        }
    }

    let mut red = vec![];
    let mut blue = vec![];
    for i in 0..(2 * n) {
        if let Some(c) = colors[i] {
            if c == RED && red.len() * 2 + 1 < n {
                red.push(i);
            }
            if c == BLUE && blue.len() * 2 + 1 < n {
                blue.push(i);
            }
        }
    }

    assert_eq!(red.len() + blue.len() + 1, n);
    for i in 0..(2 * n) {
        if colors[i].is_none() {
            blue.push(i);
            print_set(&red, &blue);
            print_count += 1;

            if sc.read::<String>().as_str() == RED {
                colors[i] = Some(RED);
            } else {
                colors[i] = Some(BLUE);
            }
            assert_eq!(blue.pop(), Some(i));
        }
    }

    assert!(print_count <= 210);

    print!("! ");
    for i in 0..(2 * n) {
        if colors[i].unwrap() == RED {
            print!("R");
        } else {
            print!("B");
        }
    }
    println!();
}

fn print_set(prefix: &Vec<usize>, suffix: &Vec<usize>) {
    print!("?");
    for &p in prefix.iter() {
        print!(" {}", p + 1);
    }
    for &p in suffix.iter() {
        print!(" {}", p + 1);
    }
    println!();
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

