fn read_line() -> String {
    let mut ret = String::new();
    std::io::stdin().read_line(&mut ret).unwrap();
    ret.trim().to_owned()
}

fn reads<T: FromStr>() -> Vec<T>
where
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    let s = read_line();
    s.split_whitespace().map(|w| w.parse().unwrap()).collect()
}

fn query(q: &[usize]) -> bool {
    print!("?");
    for &q in q.iter() {
        print!(" {}", q + 1);
    }
    println!("");
    std::io::stdout().flush().unwrap();

    if true {
        let rep = read_line();
        if rep == "Red" {
            return true;
        } else if rep == "Blue" {
            return false;
        }
    } else {
        static S: &'static [u8] = b"RRBBRB";
        let mut sum = 0;
        for i in 0..q.len() {
            sum += if S[q[i]] == b'R' { 1 } else { -1 };
        }
        return sum > 0;
    }

    unreachable!()
}

fn query_(q: usize, n: usize) -> bool {
    let mut v = vec![];

    for i in 0..n {
        v.push((q + i) % (n * 2));
    }

    query(&v)
}

fn main() {
    let n = reads::<usize>()[0];
    let n2 = n * 2;

    let c0 = query_(0, n);

    let mut l = 0;
    let mut r = 0;

    while r - l > 1 {
        let m = (l + r) / 2;
        if query_(m, n) == c0 {
            l = m;
        } else {
            r = m;
        }
    }

    // println!("l: {}", l);

    // sum[l+1..l+1+n-1] == 0

    let mut zero = vec![];
    for i in 0..n - 1 {
        zero.push(l + 1 + i);
    }

    // println!("zero: {:?}", zero);

    let mut ans = vec![None; n2];

    for i in 0..n + 1 {
        let cur = (l + n + i) % n2;
        let mut q = zero.clone();
        q.push(cur);

        // println!("* {}", cur);
        ans[cur] = Some(query(&q));
    }

    // println!("{:?}", ans);

    let mut ll = 0;

    for i in 0.. {
        let start = (l + n + 1 + i) % n2;
        let mut sum = 0;
        for j in 0..n - 1 {
            sum += if ans[start + j].unwrap() { 1 } else { -1 };
        }
        if sum == 0 {
            ll = start;
            break;
        }
    }

    let mut zero = vec![];
    for i in 0..n - 1 {
        zero.push((ll + i) % n2);
    }

    for i in 0..n - 1 {
        let cur = (l + 1 + i) % n2;
        let mut q = zero.clone();
        q.push(cur);
        // println!("* {}", cur);
        ans[cur] = Some(query(&q));
    }

    // println!("{:?}", ans);

    print!("! ");

    for i in 0..n2 {
        print!("{}", if ans[i].unwrap() { 'R' } else { 'B' });
    }

    println!();
    std::io::stdout().flush().unwrap();
}

