fn is_true(prefix: &[usize], suffix: &[usize], ans: &[bool]) -> bool {
    assert_eq!((prefix.len() + suffix.len()) * 2, ans.len());
    let mut count = 0;
    for &i in prefix.iter() {
        if ans[i] {
            count += 1;
        }
    }
    for &i in suffix.iter() {
        if ans[i] {
            count += 1;
        }
    }
    count * 2 > prefix.len() + suffix.len()
}

fn solve<F: FnMut(&[usize], &[usize]) -> bool>(n: usize, mut is_red: F) -> Vec<bool> {
    let first = is_red(&(0..n).collect::<Vec<_>>(), &vec![]);
    let mut prefix = 0;
    let mut suffix = n;

    while suffix - prefix > 1 {
        let m = (suffix + prefix) / 2;
        if is_red(&(m..(m + n)).collect::<Vec<_>>(), &vec![]) == first {
            prefix = m;
        } else {
            suffix = m;
        }
    }

    let mut colors = vec![None; 2 * n];
    colors[prefix] = Some(first);
    colors[prefix + n] = Some(!first);
    let base = ((prefix + 1)..(prefix + n)).collect::<Vec<_>>();
    assert_eq!(base.len() + 1, n);
    for i in 0..(2 * n) {
        if base.contains(&i) {
            continue;
        }
        if colors[i].is_some() {
            continue;
        }
        colors[i] = Some(is_red(&base, &vec![i]));
    }

    let mut red = 0;
    let mut blue = 0;
    let mut base = vec![];
    for i in 0..(2 * n) {
        if let Some(is_red) = colors[i] {
            if is_red && red * 2 + 1 < n {
                red += 1;
                base.push(i);
            }
            if !is_red && blue * 2 + 1 < n {
                blue += 1;
                base.push(i);
            }
        }
    }

    assert_eq!(base.len() + 1, n);
    for i in 0..(2 * n) {
        if colors[i].is_none() {
            colors[i] = Some(is_red(&base, &vec![i]));
        }
    }
    colors.into_iter().map(|p| p.unwrap()).collect()
}

