use std::io::Write;

fn read() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().chars().collect()
}

fn query(b: &[usize]) -> bool {
    for i in 1..b.len() {
        for j in 0..i {
            assert!(b[i] != b[j]);
        }
    }
    let mut out = String::new();
    out.push('?');
    for b in b.iter() {
        out.push_str(&format!(" {}", *b));
    }
    println!("{}", out);
    std::io::stdout().flush().ok();
    let s = read();
    match s.chars().next().unwrap() {
        'R' => true,
        'B' => false,
        _ => unreachable!(),
    }
}

fn run() {
    let n: usize = read().parse().unwrap();
    let mut a: Vec<usize> = (1..(2 * n + 1)).collect();
    let mut y = 88172645463325252usize;
    for _ in 0..2000 {
        y = y ^ (y << 13);
        y = y ^ (y >> 7);
        y = y ^ (y << 17);
    }
    for i in 1..(2 * n) {
        y = y ^ (y << 13);
        y = y ^ (y >> 7);
        y = y ^ (y << 17);
        let p = y % (i + 1);
        if p != i {
            a.swap(i, p);
        }
    }
    for i in 0..n {
        let v = a[i];
        a.push(v);
    }
    let prev = query(&a[..n]);
    let mut ans = vec!['\n'; 2 * n + 1];
    let mut b = vec![];
    for i in 1.. {
        let v = query(&a[i..(i + n)]);
        if v != prev {
            if v {
                ans[a[i - 1]] = 'B';
                ans[a[i + n - 1]] = 'R';
            } else {
                ans[a[i - 1]] = 'R';
                ans[a[i + n - 1]] = 'B';
            }
            for j in i..(i + n - 1) {
                b.push(a[j]);
            }
            break;
        }
    }
    let b = b;
    for i in 0..(2 * n) {
        if b.contains(&a[i]) {
            continue;
        }
        let mut b = b.clone();
        b.push(a[i]);
        if query(&b) {
            ans[a[i]] = 'R';
        } else {
            ans[a[i]] = 'B';
        }
    }
    let mut b = vec![];
    let mut red = 0;
    let mut blue = 0;
    for i in 0..(2 * n) {
        if b.len() + 1 < n {
            if red < n / 2 && ans[a[i]] == 'R' {
                b.push(a[i]);
                red += 1;
            } else if blue < n / 2 && ans[a[i]] == 'B' {
                b.push(a[i]);
                blue += 1;
            }
        }
    }
    let b = b;
    for i in 0..(2 * n) {
        if ans[a[i]] == '\n' {
            let mut c = b.clone();
            c.push(a[i]);
            ans[a[i]] = if query(&c) {'R'} else {'B'};
        }
    }
    let mut out = String::new();
    out.push_str("! ");
    for &c in ans[1..].iter() {
        out.push(c);
    }
    println!("{}", out);
}

fn main() {
    run();
}

