fn range(l: usize, r: usize) -> Vec<usize> {
    let mut w = vec![];
    for i in l..r {
        w.push(i);
    }
    w
}

fn query_range(f: usize, n: usize) -> usize {
    query(range(f, f+n))
}

fn query(mut a: Vec<usize>) -> usize {
    let n = a.len();
    for i in 0..n {
        a[i] += 1;
    }
    println!("? {}", join!(a, " "));

    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    match s.trim_right() {
        "Red" => 0,
        "Blue" => 1,
        "-1"   => panic!("something is wrong"),
        _      => panic!("parse error"),
    }
}

fn answer(a: Vec<usize>) {
    let a = a.into_iter().map(|v| ifv!(v == 0, 'R', 'B')).collect::<Vec<_>>();
    println!("! {}", join!(a, ""));
}

