use std::io::BufRead;
fn do_query<R: BufRead>(parser: &mut Parser<R>, query: &Vec<usize>) -> Option<i64> {
    let mut s = String::new();
    s.push_str("? ");
    for &q in query {
        s.push_str(&format!("{} ", q + 1));
    }
    println!("{}", s);
    input! {
        parser = parser,
        q_res: String,
    }
    if q_res == "Red" {
        Some(0)
    } else if q_res == "Blue" {
        Some(1)
    } else {
        None
    }
}

fn main() {
    input! {
        new_stdin_parser = parser,
        n: usize,
    }
    let mut res = vec![None; 2 * n];
    let mut left = 0;
    let mut first_r = do_query(&mut parser, &(0..n).collect()).unwrap();
    for k in (0..7).rev() {
        let new_left = left + 1 << k;
        if new_left >= n {
            continue;
        }
        let q_res = do_query(&mut parser, &(new_left..new_left + n).collect()).unwrap();
        if q_res == first_r {
            left = new_left;
        }
    }
    let mut right = left + n;
    res[left] = Some(first_r);
    res[right] = Some(1 - first_r);
    for i in 0..2 * n {
        if i == left || i == right {
            continue;
        }
        let mut query = vec![];
        if left < i && i < right {
            for k in 0..left {
                query.push(k);
            }
            for k in right + 1..2 * n {
                query.push(k);
            }
            query.push(i);
        } else {
            for k in left + 1..right {
                query.push(k);
            }
            query.push(i);
        }
        let q_res = do_query(&mut parser, &query);
        if let Some(r) = q_res {
            res[i] = Some(r);
        } else {
            panic!();
        }
    }
    let mut res_s = String::new();
    res_s.push_str("! ");
    for i in 0..2 * n {
        if res[i].unwrap() == 0 {
            res_s.push('R');
        } else if res[i].unwrap() == 1 {
            res_s.push('B');
        }
    }
    println!("{}", res_s);
}

use std::io::Write;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut ans = vec!['.'; 2 * n];

    sc.write("?");
    for i in 1..=n {
        sc.write(" ");
        sc.write(i);
    }
    sc.write("\n");
    let left = sc.chars()[0];

    let mut l = 0;
    let mut r = n;
    while r - l > 1 {
        let m = (r + l) / 2;
        sc.write("?");
        for i in 0..n {
            sc.write(" ");
            sc.write(m + i + 1);
        }
        sc.write("\n");
        let result = sc.chars()[0];
        if result == left {
            l = m;
        } else {
            r = m;
        }
    }
    let right = if left == 'R' { 'B' } else { 'R' };

    ans[l] = left;
    ans[l + n] = right;
    for i in 0..(2 * n) {
        if l <= i && i <= l + n {
            continue;
        }
        sc.write("? ");
        sc.write(i + 1);
        for i in 1..n {
            sc.write(" ");
            sc.write(l + i + 1);
        }
        sc.write("\n");
        ans[i] = sc.chars()[0];
    }

    let mut red = vec![];
    let mut blue = vec![];
    for i in 0..(2 * n) {
        if ans[i] == 'R' && red.len() * 2 + 1 < n {
            red.push(i);
        }
        if ans[i] == 'B' && blue.len() * 2 + 1 < n {
            blue.push(i);
        }
    }
    assert_eq!(red.len(), n / 2);
    assert_eq!(blue.len(), n / 2);

    for i in 0..(2 * n) {
        if ans[i] != '.' {
            continue;
        }
        sc.write("? ");
        sc.write(i + 1);
        for &r in red.iter() {
            sc.write(" ");
            sc.write(r + 1);
        }
        for &r in blue.iter() {
            sc.write(" ");
            sc.write(r + 1);
        }
        sc.write("\n");
        ans[i] = sc.chars()[0];
    }

    sc.write("! ");
    for &ans in ans.iter() {
        sc.write(ans);
    }
    sc.write("\n");
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
        self.1.flush().unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

const RED: &'static str = "Red";
const BLUE: &'static str = "Blue";

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut colors = vec![None; 2 * n];
    let mut prefix = vec![];
    let mut suffix = vec![];
    for i in 0..n {
        prefix.push(i);
    }

    let mut print_count = 0;

    print_set(&prefix, &suffix);
    print_count += 1;

    let first = match sc.read::<String>().as_str() {
        RED => RED,
        BLUE => BLUE,
        _ => unreachable!(),
    };

    loop {
        let last = prefix.pop().unwrap();
        suffix.push(last + n);
        assert_eq!(prefix.len() + suffix.len(), n);
        print_set(&prefix, &suffix);
        print_count += 1;

        let response = sc.read::<String>();
        assert_ne!(response.as_str(), "-1");
        if response.as_str() != first {
            break;
        }
    }

    assert!(suffix.pop().is_some());
    let mut remain = vec![];
    for i in 0..(2 * n) {
        if prefix.contains(&i) || suffix.contains(&i) {
            continue;
        }
        remain.push(i);
    }

    while let Some(i) = remain.pop() {
        suffix.push(i);
        print_set(&prefix, &suffix);
        print_count += 1;

        colors[i] = match sc.read::<String>().as_str() {
            RED => Some(RED),
            BLUE => Some(BLUE),
            _ => unreachable!(),
        };
        assert_eq!(suffix.pop(), Some(i));
    }

    let mut red = vec![];
    let mut blue = vec![];
    for i in 0..(2 * n) {
        if let Some(c) = colors[i] {
            if c == RED && red.len() * 2 + 1 < n {
                red.push(i);
            }
            if c == BLUE && blue.len() * 2 + 1 < n {
                blue.push(i);
            }
        }
    }

    assert_eq!(red.len() + blue.len() + 1, n);
    for i in 0..(2 * n) {
        if colors[i].is_none() {
            blue.push(i);
            print_set(&red, &blue);
            print_count += 1;

            if sc.read::<String>().as_str() == RED {
                colors[i] = Some(RED);
            } else {
                colors[i] = Some(BLUE);
            }
            assert_eq!(blue.pop(), Some(i));
        }
    }

    assert!(print_count <= 210);
    assert_eq!(colors.iter().filter(|t| t.unwrap() == RED).count(), n);
    assert_eq!(colors.iter().filter(|t| t.unwrap() == BLUE).count(), n);

    print!("! ");
    for i in 0..(2 * n) {
        if colors[i].unwrap() == RED {
            print!("R");
        } else {
            print!("B");
        }
    }
    println!();
}

fn print_set(prefix: &Vec<usize>, suffix: &Vec<usize>) {
    print!("?");
    for &p in prefix.iter() {
        print!(" {}", p + 1);
    }
    for &p in suffix.iter() {
        print!(" {}", p + 1);
    }
    println!();
}

