const RED: &'static str = "Red";
const BLUE: &'static str = "Blue";

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut colors = vec![None; 2 * n];
    let mut prefix = vec![];
    let mut suffix = vec![];
    for i in 0..n {
        prefix.push(i);
    }
    print_set(&prefix, &suffix);
    let (first, second) = if sc.read::<String>().as_str() == RED {
        (RED, BLUE)
    } else {
        (BLUE, RED)
    };

    loop {
        assert!(prefix.pop().is_some());
        if suffix.is_empty() {
            suffix.push(2 * n - 1);
        } else {
            let s = suffix[0] - 1;
            suffix.insert(0, s);
        }

        print_set(&prefix, &suffix);

        if sc.read::<String>().as_str() == second {
            break;
        }
    }

    colors[suffix[0]] = Some(second);
    let mut remain = vec![];
    for i in 0..(2 * n) {
        if prefix.contains(&i) || suffix.contains(&i) {
            continue;
        }
        remain.push(i);
    }

    while let Some(i) = remain.pop() {
        suffix[0] = i;
        print_set(&prefix, &suffix);
        if sc.read::<String>().as_str() == RED {
            colors[i] = Some(RED);
        } else {
            colors[i] = Some(BLUE);
        }
    }

    let mut red = vec![];
    let mut blue = vec![];
    for i in 0..(2 * n) {
        if let Some(c) = colors[i] {
            if c == RED && red.len() * 2 + 1 < n {
                red.push(i);
            }
            if c == BLUE && blue.len() * 2 + 1 < n {
                blue.push(i);
            }
        }
    }

    assert_eq!(red.len() + blue.len() + 1, n);
    for i in 0..(2 * n) {
        if colors[i].is_none() {
            blue.push(i);
            print_set(&red, &blue);
            if sc.read::<String>().as_str() == RED {
                colors[i] = Some(RED);
            } else {
                colors[i] = Some(BLUE);
            }
            assert_eq!(blue.pop(), Some(i));
        }
    }

    print!("! ");
    for i in 0..(2 * n) {
        if colors[i].unwrap() == RED {
            print!("R");
        } else {
            print!("B");
        }
    }
    println!();
}

fn print_set(prefix: &Vec<usize>, suffix: &Vec<usize>) {
    print!("?");
    for &p in prefix.iter() {
        print!(" {}", p + 1);
    }
    for &p in suffix.iter() {
        print!(" {}", p + 1);
    }
    println!();
}

