    let mut i = 0;
    let mut zs = vec![];
    for i in 0..n + 1 {
        let mut query = vec![];
        for k in i..i + n {
            query.push(k % (2 * n));
        }
        let mut s = String::new();
        s.push_str("? ");
        for &q in &query {
            s.push_str(&format!("{} ", q + 1));
        }
        println!("{}", s);
        input! {
            parser = parser,
            q_res: String,
        }
        if q_res == "Red" {
            zs.push(0);
        } else if q_res == "Blue" {
            zs.push(1);
        } else {
            panic!();
        }
        if i >= 1 && zs[i] != zs[i - 1] {
            break;
        }
    }
    let mut left = None;
    let mut right = None;
    for i in 0..zs.len() - 1 {
        if zs[i] != zs[i + 1] {
            left = Some(i);
            right = Some(i + n);
            if zs[i] == 0 {
                res[i] = Some(0);
                res[i + n] = Some(1);
            } else {
                res[i] = Some(1);
                res[i + n] = Some(0);
            }
        }
    }
    let left = left.unwrap();
    let right = right.unwrap();
    for i in 0..2 * n {
        if i == left || i == right {
            continue;
        }
        let mut query = vec![];
        if left < i && i < right {
            for k in 0..left {
                query.push(k);
            }
            for k in right + 1..2 * n {
                query.push(k);
            }
            query.push(i);
        } else {
            for k in left + 1..right {
                query.push(k);
            }
            query.push(i);
        }
        let mut s = String::new();
        s.push_str("? ");
        for &q in &query {
            s.push_str(&format!("{} ", q + 1));
        }
        println!("{}", s);
        input! {
            parser = parser,
            q_res: String,
        }
        if q_res == "Red" {
            res[i] = Some(0);
        } else if q_res == "Blue" {
            res[i] = Some(1);
        } else {
            panic!();
        }
    }
    let mut res_s = String::new();
    res_s.push_str("! ");
    for i in 0..2 * n {
        if res[i].unwrap() == 0 {
            res_s.push('R');
        } else if res[i].unwrap() == 1 {
            res_s.push('B');
        }
    }
    println!("{}", res_s);
}

