fn inv(c: char) -> char {
    if c == 'R' {
        'B'
    } else {
        'R'
    }
}

fn main() {
    let n = read::<usize>();
    let ret0 = query(&(0..n).collect::<BTreeSet<_>>());
    let criterion = |x| query(&(x..x + n).collect::<BTreeSet<_>>()) == ret0;
    let (ok, _) = binary_search(0, n, criterion);
    let mut colors = vec!['U'; 2 * n]; // 0: unknown, 1: red: 2: blue
    colors[ok] = ret0;
    colors[ok + n] = inv(ret0);
    let mut query_base = BTreeSet::new();
    for i in ok + 1..ok + n {
        query_base.insert(i);
    }

    // coloring 0..ok
    for i in 0..ok {
        query_base.insert(i);
        colors[i] = query(&query_base);
        query_base.remove(&i);
    }
    // coloring ok + n + 1..2 * n
    for i in ok + n + 1..2 * n {
        query_base.insert(i);
        colors[i] = query(&query_base);
        query_base.remove(&i);
    }
    // coloring ok + 1..ok + n
    let mut query_base = BTreeSet::new();
    let mut r_count = 0;
    let mut b_count = 0;
    for i in 0..2 * n {
        if colors[i] == 'R' && r_count < n / 2 {
            query_base.insert(i);
            r_count += 1;
        } else if colors[i] == 'B' && b_count < n / 2 {
            query_base.insert(i);
            b_count += 1;
        }
    }
    assert!(query_base.len() == n - 1);

    for i in 0..2 * n {
        if colors[i] == 'U' {
            query_base.insert(i);
            colors[i] = query(&query_base);
            query_base.remove(&i);
        }
    }
    print!("! ");
    for ch in colors {
        print!("{}", ch);
    }
    println!("");
}

