    let mut rc = vec![0isize; 2 * n];
    for _ in 0..max_count {
        perm.sort_by_key(|idx| rc[*idx]);
        shuffle(&mut perm[0..n], &mut rnd);
        shuffle(&mut perm[n..2 * n], &mut rnd);
        let mut s = String::new();
        for i in n / 2..n / 2 + n {
