        if input.starts_with("-1") {
            break;
        }
        if input.starts_with("Red") {
            for i in 0..n {
                rc[perm[i]] += 1;
            }
            for i in n..2 * n {
                rc[perm[i]] -= 1;
            }
        }
        if input.starts_with("Blue") {
            for i in 0..n {
                rc[perm[i]] -= 1;
            }
            for i in n..2 * n {
                rc[perm[i]] += 1;
            }
