fn do_query<R: BufRead>(parser: &mut Parser<R>, query: &Vec<usize>) -> Option<i64> {
    let mut s = String::new();
    s.push_str("? ");
    for &q in query {
        s.push_str(&format!("{} ", q + 1));
    }
    println!("{}", s);
    input! {
        parser = parser,
        q_res: String,
    }
    if q_res == "Red" {
        Some(0)
    } else if q_res == "Blue" {
        Some(1)
    } else {
        None
    }
}

fn main() {
    input! {
        new_stdin_parser = parser,
        n: usize,
    }
    let mut res = vec![None; 2 * n];
    let mut left = 0;
    let mut first_r = do_query(&mut parser, &(0..n).collect()).unwrap();
    for k in (0..7).rev() {
        let new_left = left + (1 << k);
        if new_left >= n {
            continue;
        }
        let q_res = do_query(&mut parser, &(new_left..new_left + n).collect()).unwrap();
        if q_res == first_r {
            left = new_left;
        }
    }
    let mut right = left + n;
    res[left] = Some(first_r);
    res[right] = Some(1 - first_r);
    for i in 0..2 * n {
        if i == left || i == right {
            continue;
        }
        let mut query = vec![];
        if left < i && i < right {
            for k in 0..left {
                query.push(k);
            }
            for k in right + 1..2 * n {
                query.push(k);
            }
            query.push(i);
        } else {
            for k in left + 1..right {
                query.push(k);
            }
            query.push(i);
        }
        let q_res = do_query(&mut parser, &query);
        if let Some(r) = q_res {
            res[i] = Some(r);
        } else {
            panic!();
        }
    }
    let mut res_s = String::new();
    res_s.push_str("! ");
    for i in 0..2 * n {
        if res[i].unwrap() == 0 {
            res_s.push('R');
        } else if res[i].unwrap() == 1 {
            res_s.push('B');
        }
    }
    println!("{}", res_s);
}

