fn run() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());
    let n: usize = sc.read();
    let mut perm: Vec<usize> = (0..2 * n).collect();

    let max_count = 210;

    let mut rnd = XorShift::new();

    let mut rc = vec![0isize; 2 * n];
    for _ in 0..max_count {
        perm.sort_by_key(|idx| rc[*idx]);
        shuffle(&mut perm[0..n], &mut rnd);
        shuffle(&mut perm[n..2 * n], &mut rnd);
        for i in 0..n / 2 {
            perm.swap(i, n + i);
        }
        let mut s = String::new();
        for i in 0..n {
            s += &format!("{}", perm[i] + 1);
            if i != n - 1 {
                s += " ";
            }
        }
        println!("? {}", s);
        let input: String = sc.read();
        if input.starts_with("-1") {
            break;
        }
        if input.starts_with("Red") {
            for i in 0..n {
                rc[perm[i]] += 1;
            }
            for i in n..2 * n {
                rc[perm[i]] -= 1;
            }
        }
        if input.starts_with("Blue") {
            for i in 0..n {
                rc[perm[i]] -= 1;
            }
            for i in n..2 * n {
                rc[perm[i]] += 1;
            }
        }
    }
    let mut ps = Vec::new();
    for i in 0..2 * n {
        ps.push((rc[i], i));
    }
    ps.sort();
    let mut ans = vec!['R'; 2 * n];
    for i in 0..n {
        ans[ps[i].1] = 'B';
    }
    let mut ans_str = String::new();
    for i in 0..2 * n {
        ans_str += &format!("{}", ans[i]);
    }
    println!("! {}", ans_str);
}

fn shuffle(v: &mut [usize], rnd: &mut XorShift) {
    for i in (0..v.len()).rev() {
        let j = rnd.next_u32() as usize % (i + 1);
        v.swap(i as usize, j as usize);
    }
}

use std::num::Wrapping;

#[derive(Clone, Debug, Default)]
pub struct XorShift {
    x: Wrapping<u32>,
    y: Wrapping<u32>,
    z: Wrapping<u32>,
    w: Wrapping<u32>,
}

impl XorShift {
    /// Create object with default seed.
    pub fn new() -> XorShift {
        XorShift {
            x: Wrapping(123_456_789),
            y: Wrapping(362_436_069),
            z: Wrapping(521_288_629),
            w: Wrapping(88_675_123),
        }
    }

    /// Get next random u32 number.
    pub fn next_u32(&mut self) -> u32 {
        let x = self.x;
        let t = x ^ (x << 11);
        self.x = self.y;
        self.y = self.z;
        self.z = self.w;
        let v = self.w;
        self.w = v ^ (v >> 19) ^ (t ^ (t >> 8));
        self.w.0
    }
}

