fn query(q: &[usize]) -> bool {
    print!("?");
    for &q in q.iter() {
        print!(" {}", q + 1);
    }
    println!("");
    std::io::stdout().flush().unwrap();

    if true {
        let rep = read_line();
        if rep == "Red" {
            return true;
        } else if rep == "Blue" {
            return false;
        }
    } else {
        static S: &[u8] = b"RRBBRB";
        let mut sum = 0;
        for i in 0..q.len() {
            sum += if S[q[i]] == b'R' { 1 } else { -1 };
        }
        return sum > 0;
    }

    unreachable!()
}

fn query_(q: usize, n: usize) -> bool {
    let mut v = vec![];

    for i in 0..n {
        v.push((q + i) % (n * 2));
    }

    query(&v)
}

