fn run() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());
    let n: usize = sc.read();
    let mut perm: Vec<usize> = (0..2 * n).collect();

    let max_count = 210;

    let mut rnd = XorShift::new();

    let mut rc = vec![0isize; 2 * n];
    for _ in 0..max_count {
        shuffle(&mut perm, &mut rnd);
        let mut s = String::new();
        for i in 0..n {
            s += &format!("{}", perm[i] + 1);
            if i != n - 1 {
                s += " ";
            }
        }
        println!("? {}", s);
        let input: String = sc.read();
        if input.starts_with("-1") {
            break;
        }
        if input.starts_with("Red") {
            for i in 0..n {
                rc[perm[i]] += 1;
            }
            for i in n..2 * n {
                rc[perm[i]] -= 1;
            }
        }
        if input.starts_with("Blue") {
            for i in 0..n {
                rc[perm[i]] -= 1;
            }
            for i in n..2 * n {
                rc[perm[i]] += 1;
            }
        }
    }
    let mut ps = Vec::new();
    for i in 0..2 * n {
        ps.push((rc[i], i));
    }
    ps.sort();
    let mut ans = vec!['R'; 2 * n];
    for i in 0..n {
        ans[ps[i].1] = 'B';
    }
    let mut ans_str = String::new();
    for i in 0..2 * n {
        ans_str += &format!("{}", ans[i]);
    }
    println!("! {}", ans_str);
}

fn shuffle(v: &mut Vec<usize>, rnd: &mut XorShift) {
    for i in (0..v.len()).rev() {
        let j = rnd.next_u32() as usize % (i + 1);
        v.swap(i as usize, j as usize);
    }
}

