fn main() {
    read!(n = usize);
    let is_left_red = query_red(&(0..n).collect::<Vec<_>>());
    let mut l = 0;
    let mut r = n;
    while r - l > 1 {
        let mid = (l + r) / 2;
        if query_red(&(mid..mid+n).collect::<Vec<_>>()) == is_left_red {
            l = mid;
        } else {
            r = mid;
        }
    }
    let beg = l+1;
    let end = (l+1) + (n-1);

    let mut ans = vec![false; 2*n];
    let mut is: Vec<usize> = (beg..end).collect();
    for j in (0..beg).chain(end..2*n) {
        is.push(j);
        ans[j] = query_red(&is);
        is.pop();
    }
    let mut is: Vec<usize> = (0..beg-1).chain(end+1..2*n).collect();
    for j in beg..end {
        is.push(j);
        ans[j] = query_red(&is);
        is.pop();
    }
    println!("! {}", ans.into_iter().map(|a| if a { 'R' } else { 'B' }).cat());
}

