fn main() {
    read!(n = usize);
    let is_left_red = query_red(&(0..n).collect::<Vec<_>>());
    let mut l = 1;
    let mut r = n;
    while r - l > 1 {
        let mid = (l + r) / 2;
        if query_red(&(mid..mid+n).collect::<Vec<_>>()) == is_left_red {
            l = mid;
        } else {
            r = mid;
        }
    }
    dbg!(l);

    let mut is: Vec<usize> = (l..l+n-1).collect();
    let mut js = Vec::new();
    let mut red_count = 0;
    let mut blue_count = 0;
    let mut ans = vec![false; 2*n];
    for j in (0..2*n).filter(|&i| i < l || l+n-1 <= i) {
        is.push(j);
        ans[j] = query_red(&is);
        if ans[j] {
            if red_count < (n-1)/2 {
                js.push(j);
            }
            red_count += 1;
        } else {
            if blue_count < (n-1)/2 {
                js.push(j);
            }
            blue_count += 1;
        }
        is.pop();
    }
    let mut js: Vec<usize> = (0..l-1).chain(l+n..2*n).collect();
    for i in l..l+n-1 {
        js.push(i);
        ans[i] = query_red(&js);
        js.pop();
    }
    println!("! {}", ans.into_iter().map(|a| if a { 'R' } else { 'B' }).cat());
}
